"""session.py — lanes. Part of the harness namespace; loaded by sessionlib.load().

GENERATED BY MOVE, NOT BY REWRITE: every line below is verbatim from the
monolithic session.py it was split out of. Do not import this file directly —
it is executed into the session namespace by sessionlib/__init__.py.
"""

# Per-compilation-unit directive: each part is compiled on its own, so the
# monolith's single future import could not carry across the split.
from __future__ import annotations



def _supervise_key(did: str) -> str:
    """The sidecar filename stem to write this session's liveness under.

    The runtime's own session id once adoption has stamped it in — that is the key
    `_sidecar_evidence_by_csid` (the reaper's reader) looks under — and the durable id
    until then. Resolved fresh on every use because the watch starts BEFORE adoption, so
    the key genuinely changes part-way through a session."""
    try:
        fm, _ = parse_journal(journal_path(did).read_text(encoding="utf-8"))
        return (fm.get("claude-session-id") or "").strip() or did
    except Exception:
        return did


def _supervise_beat(did: str, pid: int | None = None) -> bool:
    """One supervision beat for the session journalled as `did`. Returns False when the
    session is over — journal gone or closed — and the watcher should stop.

    The sidecar is keyed by the journal's CURRENT `claude-session-id`, re-read every beat
    rather than captured once. The wrapper starts watching BEFORE the runtime has adopted
    the journal, so that key does not exist yet and appears part-way through the watch;
    re-reading is what lets the beat follow it. Until then the durable id keys the file,
    so evidence still flows without inventing a second liveness namespace that
    `_sidecar_evidence_by_csid` — the reaper's actual reader — would never look in.

    A transient read error returns True: failing to read a journal is not evidence that a
    session ended, and treating it as such would stop the heartbeat on a live session and
    hand it to the reaper."""
    try:
        p = journal_path(did)
        if not p.is_file():
            return False
        fm, _ = parse_journal(p.read_text(encoding="utf-8"))
        if fm.get("ended"):
            return False
        key = _supervise_key(did)
        live = SESSION_STATE_DIR / f"{key}.live"
        payload: dict = {}
        if live.is_file():
            payload = json.loads(live.read_text(encoding="utf-8"))
        payload.setdefault("session_id", did)
        payload.setdefault("machine", fm.get("machine", ""))
        payload.setdefault("started", fm.get("started", "") or _now_iso())
        payload["last_beat"] = _now_iso()
        # ADR-0082 D7: mark the beat's PROVENANCE. A supervised beat is process-alive,
        # not tool-active — coarser than a hook beat — and anything reasoning about
        # staleness needs to be able to tell which kind it is reading rather than
        # assuming the finer one (declare-what-a-check-assumes).
        payload["beat_source"] = "supervisor"
        # …and carry WHAT is being watched, so a later reader can resolve the silence
        # instead of only waiting it out. `beat_machine` is the pid's namespace: a pid
        # means nothing on the other machine, and comparing them across machines would
        # turn an unrelated live process into "this session is still running."
        if pid:
            payload["beat_pid"] = int(pid)
            payload["beat_machine"] = detect_machine() if CFG else ""
        _sidecar_write(key, "live", payload)
        return True
    except Exception:
        return True


def _supervise_loop(did: str, pid: int, interval: int = SUPERVISE_INTERVAL_SEC,
                    max_beats: int | None = None) -> str:
    """Beat for as long as `pid` lives. Returns why it stopped: 'exited' (the watched
    process is gone — the normal end), 'closed' (the journal was closed under us, e.g. a
    lane that landed), or 'max-beats' (the test bound)."""
    beats = 0
    while _process_alive(pid):
        if not _supervise_beat(did, pid):
            return "closed"
        beats += 1
        if max_beats is not None and beats >= max_beats:
            return "max-beats"
        time.sleep(interval)
    return "exited"


def _supervised_pid_state(ev: dict) -> str:
    """For a TIMER-beaten session: is the process the watcher was watching still there?

    `alive` / `gone` / `unknown`, and the third is not a hedge — it is the answer whenever
    the question cannot honestly be asked, which is the whole point of
    [`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes). Three
    ways it cannot be asked: the beat is a hook beat (activity-driven, no watched pid at
    all), the sidecar predates the pid being recorded, or it was written on the OTHER
    machine — where the number is a pid in someone else's namespace and probing it locally
    would let an unrelated process vouch for a session that is long dead.

    `unknown` costs a wait, never a wrong close: the caller falls back to a grace."""
    if (ev.get("beat_source") or "") != "supervisor":
        return "unknown"
    pid = ev.get("beat_pid")
    if not pid:
        return "unknown"
    here = detect_machine() if CFG else ""
    if not here or (ev.get("beat_machine") or "") != here:
        return "unknown"
    return "alive" if _process_alive(int(pid)) else "gone"


def _is_linked_worktree() -> bool:
    """True iff cwd is a LINKED git worktree (a `git worktree add` lane), not the main
    checkout. In a linked worktree the per-worktree git dir differs from the shared
    common dir; in the main checkout they coincide. Fail-safe: any git error → False
    (treat as the main checkout, i.e. don't take the lane path)."""
    # Both forced ABSOLUTE: `--git-common-dir` alone can be relative to git's cwd, and
    # Path.resolve() would then resolve it against the wrong (process) cwd. `--path-
    # format=absolute` (git 2.31+) makes the common dir absolute so the compare is sound.
    gd = sh(["git", "rev-parse", "--absolute-git-dir"], check=False)
    cd = sh(["git", "rev-parse", "--path-format=absolute", "--git-common-dir"], check=False)
    if gd.returncode != 0 or cd.returncode != 0:
        return False
    g, c = gd.stdout.strip(), cd.stdout.strip()
    if not g or not c:
        return False
    return Path(g).resolve() != Path(c).resolve()


def _on_worktree_lane() -> bool:
    """True iff this session runs inside a Claude Code native worktree lane (ADR-0060):
    on a `worktree-<name>` branch AND in a linked worktree. Terminal `poga` sessions
    land here — the lane is real git isolation, so `end` ff-advances the trunk to the
    lane's branch tip by plumbing, with no attribution and no shared-tree machinery."""
    return _current_branch().startswith("worktree-") and _is_linked_worktree()


def _journal_is_from_another_lane(jpath: Path) -> bool:
    """Was this journal found in a DIFFERENT lane than the one we are writing from?

    WI-0106's second path, and the whole difficulty is that "the journal is not in my
    checkout" is the WRONG test — it is true of the entirely legitimate case the land
    gate depends on. `poga work claim` anchors on the MAIN checkout by design (ADR-0073)
    and execs main's `session.py`, so a lane session's journal is routinely resolved from
    a process standing in main. Guarding on locality alone would refuse provenance for
    every front-door write, which is exactly what WI-0093 had just fixed.

    The distinction that actually separates them is which checkout the READER is in:

      * in MAIN, a lane's journal is the front door working as designed — local;
      * in a LANE, a journal belonging to a *different* lane means this session reached
        sideways into someone else's checkout and drew a record there. Its runtime was
        observed of the READER, not of the lane the record is about.

    Only the second is foreign. Never raises — an unanswerable question returns False,
    which claims nothing extra rather than marking a legitimate record suspect.

    Answered ENTIRELY from the process's cwd, and neither `ROOT` nor `_on_worktree_lane`
    is usable here. `ROOT` is resolved from the location of the `session.py` being
    executed, and the front door deliberately execs MAIN's copy from inside a lane, so
    `ROOT` is main on exactly the path this has to judge. `_on_worktree_lane` reads that
    same `ROOT` — which is why it answers "yes" for the whole test suite, since the suite
    itself runs inside a lane. Both would have marked every legitimate record foreign.
    (Both were tried; the tests caught both.)"""
    try:
        # `cwd=` is explicit and load-bearing: `sh` defaults to ROOT, so without it this
        # asks the question of the wrong repo entirely and gets an answer shaped like a
        # right one — the exact trap `_main_checkout`'s own docstring records.
        cwd = Path.cwd()
        here = sh(["git", "rev-parse", "--show-toplevel"], check=False, cwd=cwd)
        if here.returncode != 0 or not (here.stdout or "").strip():
            return False                      # cannot tell — claim nothing extra
        checkout = Path(here.stdout.strip()).resolve()
        main = _main_checkout(checkout)
        if main is None or checkout == main:
            return False                      # in main: the front door, by design
        return checkout not in jpath.resolve().parents
    except Exception:
        return False


def _lane_taken(root: Path, lane: str) -> bool:
    """Is lane `poga-N` in use? Worktree directory OR branch — a leftover branch means a
    crashed or un-landed lane and must never be silently reused.

    The Python twin of the `poga` wrapper's `lane_taken`. Deliberately the same two facts:
    if these two ever disagree the allocator hands out a lane the launcher then refuses,
    which is a worse failure than the one this file exists to fix."""
    if (root / ".claude" / "worktrees" / lane).exists():
        return True
    r = sh(["git", "-C", str(root), "show-ref", "--verify", "--quiet",
            f"refs/heads/worktree-{lane}"], check=False)
    return r.returncode == 0


def _lane_reserve(lane: str, identity: str, root: Path) -> bool:
    """Take the reservation on `lane`, exclusively. True iff this caller now holds it.

    DELIBERATELY NOT `_coord_try_acquire`, and the difference is the whole fix. That
    function reclaims a name it decides is already *ours* — correct for a claim or a
    number, where re-acquiring is a refresh — and `_coord_mine` matches on the ambient
    JOURNAL when the session id is shared. Two dispatched launches are exactly that case:
    `tmux new-session` hands the child the dispatcher's environment, so both inherit one
    `CLAUDE_CODE_SESSION_ID` and one journal, both are judged "mine", and both reclaim the
    same lane. Ten racers were measured all drawing `poga-2`.

    A lane reservation has no refresh semantics to preserve — a launcher that already holds
    one is not asking for it again, it is asking for a FREE one. So the only reclaim
    allowed here is of an EXPIRED record: exclusive create, or lose."""
    d = _coord_dir(LANE_ALLOC_KIND, create=True)
    if d is None:
        return True                      # no shared dir → fail-open, as everywhere else
    path = d / f"{lane}.json"
    # WI-0156: the reservation records whether this lane belongs to a DISPATCH, and it is
    # the only place that fact can be captured. `POGA_DISPATCH` rides in the environment
    # the spawning tab set, so it is readable HERE — inside the launched process drawing
    # its own lane — and nowhere the dispatcher can reach afterwards: the dispatch record
    # never learns which lane its item landed in, because the lane is drawn later, by the
    # child. Written at the draw rather than derived later, for the same reason the lane
    # name itself is drawn: a fact that must be true before the tab exists cannot be
    # reconstructed from what the tab does. Absent for a hand-launched lane, which is
    # exactly the distinction the cap needs.
    rec = _coord_record(identity, LANE_ALLOC_TTL_SECONDS, name=lane,
                        kind=LANE_ALLOC_KIND, root=str(root),
                        dispatch_id=os.environ.get("POGA_DISPATCH", "").strip(),
                        dispatch_item=os.environ.get("POGA_DISPATCH_ITEM", "").strip())
    payload = json.dumps(rec, ensure_ascii=False, indent=2) + "\n"
    try:
        fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(payload)
        return True
    except FileExistsError:
        pass
    except Exception:
        return True                      # unexpected fs error → fail-open
    holder = _coord_read(path)
    if holder is not None and not _coord_expired(holder):
        return False
    # Expired or unreadable. Reclaim, but re-arbitrate: the write itself is not exclusive,
    # so two racers could both decide the corpse is theirs. Re-read and keep only the
    # winner — whoever's payload is on disk after the dust settles.
    try:
        atomic_write(path, payload)
    except Exception:
        return False
    back = _coord_read(path)
    return bool(back) and back.get("created_at") == rec.get("created_at") \
        and back.get("session_id") == rec.get("session_id")


def cmd_lane_rollback(args: argparse.Namespace) -> None:
    """Undo a lane whose runtime never started (WI-0105).

    THE FAILURE, live during the WI-0033 Phase 3 drill (session ~129): `poga -r cx`
    created lane poga-5, its worktree and `.session-state/prep.json`, wrote the 81k
    session-context, then `exec codex` failed with *"Error: stdin is not a terminal"* and
    exit 1. Everything prep built stayed on disk with no agent behind it, and `poga` was
    gone — after `exec` succeeds there is no `poga` left to clean up.

    Two failure shapes, and only one of them can be caught in the moment. When `exec`
    cannot LAUNCH at all (a missing binary), `poga` runs this immediately under
    `shopt -s execfail`, which is the item's own prescription: *the launch path removes
    it when exec returns at all, since a successful exec never returns*. When the runtime
    starts and then dies, `poga`'s process is already replaced and nothing local
    survives to notice — so this verb is also the thing a later session runs, and its
    predicate is what makes that safe long after the fact.

    Releases the coordination reservation too. `alloc_lane` DRAWS the slot from the coord
    store (WI-0185), so a failed launch that only removed the worktree would leave the
    number reserved — a lane nobody can use and nothing will free until its TTL."""
    lane = args.lane
    root = ROOT
    lane_dir = Path(_lanes_root() or (root / ".claude" / "worktrees")) / lane
    branch = f"worktree-{lane}"
    safe, why = _launch_left_nothing(lane_dir, branch)
    if not safe:
        print(f"lane-rollback: REFUSED for {lane} — {why}.")
        print(f"  Nothing was removed. If its work is real, land it: "
              f"cd {lane_dir} && python3 session.py merge --continue")
        raise SystemExit(2)
    if getattr(args, "dry_run", False):
        print(f"lane-rollback: (dry-run) would remove worktree {lane_dir}, delete "
              f"branch {branch}, and release the {lane} reservation.")
        return
    reason = (getattr(args, "reason", None) or "runtime launch failed").strip()
    sh(["git", "-C", str(root), "worktree", "remove", "--force", str(lane_dir)],
       check=False)
    sh(["git", "-C", str(root), "worktree", "prune"], check=False)
    sh(["git", "-C", str(root), "branch", "-D", branch], check=False)
    # WI-0312: through the one exit, like every other route that ends a lane. No epoch is
    # passed and none is needed — the branch is deleted two lines up, so this lane is
    # provably gone and cannot be racing an occupant (`_lane_exit_owns`). The lane branch
    # is the identity even though nothing was ever checked out on it: it is what addresses
    # the reservation.
    with contextlib.suppress(Exception):
        _lane_exit_release(f"worktree-{lane}", kinds=(LANE_ALLOC_KIND,),
                           reason="teardown")
    print(f"lane-rollback: {lane} removed — worktree, branch {branch} and its "
          f"reservation are gone ({reason}). Nothing was lost: the predicate proved "
          f"the lane held no journal narrative, no unlanded commits and no live session.")


def _counter_lane_tips_max(c: _Counter) -> int:
    """Highest number committed on any sibling lane tip (refs/heads/worktree-*) — R5c
    defense in depth: a lapsed reservation whose file is committed-but-unlanded is
    invisible to the on-disk scan (the file is lane-local until land), so the tips are
    scanned directly and that number can never be re-issued."""
    mx = 0
    r = sh(["git", "for-each-ref", "--format=%(refname:short)", "refs/heads/worktree-*"],
           check=False)
    d = c.dirname()
    for ref in (r.stdout or "").split():
        t = sh(["git", "ls-tree", "--name-only", ref, f"{d}/"], check=False)
        for name in (t.stdout or "").split():
            n = _counter_num_in_path(c, name)
            if n is not None:
                mx = max(mx, n)
    return mx


def _adr_lane_tips_max() -> int:
    """Highest ADR number committed on any sibling lane tip (R5c)."""
    return _counter_lane_tips_max(_counter("adr"))


def _wi_lane_tips_max() -> int:
    """Highest WI number committed on any sibling lane tip (R5c)."""
    return _counter_lane_tips_max(_counter("wi"))


def _lane_added_lines(parent: str, rel: str) -> set[int] | None:
    """1-based line numbers in the WORKING-TREE copy of `rel` that are new since `parent`.

    `git diff` against the trunk tip rather than against the lane's own commits, so
    committed and uncommitted lane work answer the same way — a renumber run mid-session
    must see the paragraph written two minutes ago exactly as it sees one committed
    yesterday. None means "could not tell", and the caller then rewrites NOTHING in the
    file: an unreadable diff must never widen into permission to rewrite the whole thing."""
    # `--no-renames` for the same reason as `_counter_new_and_trunk`: a file git pairs
    # as a rename reports as modified rather than added, which would UNDERCOUNT the lines
    # this lane authored and quietly leave citations unfollowed.
    r = sh(["git", "diff", "-U0", "--no-color", "--no-renames", parent, "--", rel],
           check=False)
    if r.returncode != 0:
        return None
    out: set[int] = set()
    ln = 0
    for line in (r.stdout or "").splitlines():
        if line.startswith("@@"):
            m = re.search(r"\+(\d+)", line)
            if not m:
                return None
            ln = int(m.group(1))
        elif line.startswith("+++") or line.startswith("---"):
            continue
        elif line.startswith("+"):
            out.add(ln)
            ln += 1
    return out


def _lane_label(identity: str) -> str:
    """The human name for a lane — `federation lane 1`, never `poga-1`.

    Lane numbers are allocated PER REPO, lowest free slot, so every project's first lane
    is 1 and a wall of open tabs all read `poga-1` with nothing to tell them apart. the operator's
    ruling, session 127: a project-qualified `federation lane 1` is more useful than
    `poga-1` — what is missing is the project, not the numbering.

    Only the LABEL changes; the lane's own name does not. That name is an allocator
    identity with real machinery on it — the worktree directory, the branch
    `worktree-<lane>`, and the free-slot check that tests both — and lane names are
    deliberately RECYCLED, which is why the stranded-process detector keys on the
    directory's birth time rather than its name (session ~125, where a nine-day-old
    process and a live session both claimed `poga-1`). Renaming lanes would disturb all
    of that for a cosmetic gain; a label has nothing hanging off it.

    The system half is DERIVED from `architect_id` by stripping the ADR-0006 `-arch`
    suffix, never a hand-set display field — the same reasoning as `structural_name`: a
    free-text label invites the codename/abbreviation collapse ADR-0006 forbids. Falls
    back to the repo directory name when there is no config to read, so a repo mid-
    bootstrap still gets a useful tab rather than a bare number."""
    lane = (identity or "").replace("worktree-", "").strip()
    sysid = ""
    try:
        if CFG:
            sysid = (CFG.get("architect_id") or "").strip()
            if sysid.endswith("-arch"):
                sysid = sysid[: -len("-arch")]
    except Exception:
        sysid = ""
    if not sysid:
        with contextlib.suppress(Exception):
            sysid = ROOT.name
    m = re.search(r"(\d+)$", lane)
    if m:
        return f"{sysid} lane {m.group(1)}".strip()
    return f"{sysid} {lane}".strip() or lane or sysid


def lane_durable_session(lane: dict) -> str:
    """The durable session id of the session that last beat in this lane, or `""`.

    Read from the lane's OWN `.session-state`, because that is where the association
    actually lives: `lane_session_ids`' docstring records why the branch cannot answer
    this question — the branch diff goes EMPTY exactly once the lane is merged, which is
    most of the lanes a listing shows.

    LAST BEAT WINS. A lane slot is reused, so a long-lived worktree accumulates one
    sidecar per session that ever ran in it (measured: four of the fifteen lanes on this
    machine hold more than one). The label must name the session a reader could still
    attach to, not whichever one happens to sort first — naming a finished session as if
    it were the current occupant is the very confusion this item exists to end."""
    # `str()` because `_scan_lanes` puts a Path here while a hand-built lane dict (and
    # every fixture) puts a string. Taking the string shape on faith is what made the
    # first cut of this line raise on the one caller that matters.
    path = str(lane.get("path") or "").strip()
    if not path:
        # `Path("")` is `Path(".")`, which would read THIS process's own
        # `.session-state` and hand back the current session's id as though it were
        # the lane's — a confident wrong name, in the column this whole item exists to
        # make trustworthy. Absence is not identity
        # ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
        return ""
    with contextlib.suppress(Exception):
        ev = lane_session_evidence(Path(path) / ".session-state")
        if ev:
            def _beat(kv):
                # Compared as INSTANTS, not as strings. `_now_iso` writes a local
                # offset, so a string sort is wrong for one hour a year — at a DST
                # fall-back the older beat sorts higher and the label names a session
                # that is over. `_parse_iso` is what the rest of this file already
                # uses for exactly this comparison.
                return _parse_iso(kv[1].get("last_beat") or "") or datetime.min.replace(
                    tzinfo=timezone.utc)
            return max(ev.items(), key=_beat)[0]
    return ""


def lane_claim_index(claims: dict | None = None) -> dict:
    """`{durable-session-id: work-item-id}` — the lane->item join, built ONCE per render.

    The claim store is keyed by ITEM, so every consumer wanting the other direction has
    had to scan it; doing that once per listing rather than once per row is the whole
    reason this is a separate function.

    THE JOIN KEY IS THE JOURNAL, NEVER THE BRANCH. `poga work claim` anchors on the main
    checkout by design (ADR-0073), so `rec["branch"]` reads `main` for every front-door
    claim and a branch-keyed join silently matches nothing — the WI-0130 defect
    `_coord_short_holder` was built for, and the same reasoning that put a journal arm on
    `_coord_mine`. Verified on the live store while building this: all five held claims
    carried `branch: "main"` and five distinct journal ids."""
    out: dict = {}
    with contextlib.suppress(Exception):
        for wid, rec in sorted((claims if claims is not None
                                else _coord_list("claims")).items()):
            journal = (rec.get("journal") or "").strip()
            if not journal:
                continue
            # ONE SESSION MAY HOLD MORE THAN ONE CLAIM — nothing in `cmd_claim` forbids
            # it — and a label is one cell. The LOWEST id wins, chosen by sorting rather
            # than inherited from whatever order the store globbed in, so two renders of
            # the same state agree. `+N` says the cell is a summary rather than the whole
            # answer; `poga work claims` is the surface that lists them all.
            if journal in out:
                first = out[journal].split("+")[0]
                extra = out[journal].count("+") + 1
                out[journal] = f"{first}+{extra}"
            else:
                out[journal] = wid
    return out


def lane_identity(lane: dict, index: dict | None = None) -> str:
    """What a HUMAN calls this lane — `devbox·WI-0157`, never `poga-15` (WI-0157).

    A lane slot is an ADDRESS: freed on teardown, reissued to the next lane, and numbered
    per machine, so `poga-2` named three different sessions across two machines in one
    day. Every lane-facing surface nonetheless printed the slot as though it were a name,
    which is why a reader holding two of those surfaces an hour apart cannot tell whether
    they are looking at the same work. The slot keeps its job — it is what a reader types
    at `poga resume` and `recover-lanes --lane` — and stops doing the one it was never
    fit for.

    Three tiers, each the most durable thing actually on hand:

      * a session and a claim -> `devbox·WI-0157`, the two facts a person cares about;
      * a session, nothing claimed -> `devbox·d5b9`, the 4-char tail of the durable id,
        unique forever and already how every journal is named;
      * no session ever -> `_lane_label`, the project-qualified `federation lane 15`
        built for the operator's session ~127 ruling and until now wired to a single terminal
        title. A dormant slot has no session to name and inventing one would be worse
        than admitting it; what this tier must not do is present the raw slot as a name,
        and the project qualifier is exactly the ADR-0069 lesson applied to lanes.

    Deliberately NOT the session ordinal, for the same reason ADR-0069 D1 keeps it off a
    lane banner: it is assigned at land, so two live lanes transiently show the same one.
    That is the failure this function exists to stop, not one to import."""
    sid = lane_durable_session(lane)
    if not sid:
        return _lane_label(lane.get("name") or "")
    machine, tail = _durable_id_parts(sid)
    if not machine:
        return _lane_label(lane.get("name") or "")
    wid = (index if index is not None else lane_claim_index()).get(sid, "")
    return f"{machine}·{wid or tail}"


def lane_identities(lanes: list) -> dict:
    """`{lane-name: identity}` for a whole listing, reading the claim store once."""
    index = lane_claim_index()
    return {l.get("name", ""): lane_identity(l, index) for l in lanes}


def cmd_lane_identity(args) -> int:
    """`session.py lane-identity` — `<slot>\t<identity>` for every lane, one line each.

    EXISTS FOR `poga lanes`, which is bash. That renderer is a pure ref walk with no
    coordination-store read and no sidecar read, so it is the one lane surface where the
    durable identity is not already sitting in a variable — it had nothing to print but
    the slot. One shell-out here is cheaper than teaching the shell to parse two JSON
    stores, and it keeps ONE implementation of the label rule ([P16]): the shell asks the
    harness what a lane is called rather than deriving it a second time and drifting.

    Tab-separated and slot-first because this output is JOINED against rather than read:
    the slot is the key the caller already holds."""
    index = lane_claim_index()
    for l in sorted(_scan_lanes(), key=lambda x: x.get("name", "")):
        print(f"{l.get('name', '')}\t{lane_identity(l, index)}")
    return 0


def _ops_lane_tips_max() -> int:
    return _counter_lane_tips_max(_counter("ops"))


def _release_landed_numbers(tip: str, parent: str) -> list[str]:
    """Release the reservation behind every numbered file this land just carried onto the
    trunk. Returns the receipt lines to print. ADR-0119 D2.

    THE SET IS THE DIFF, NEVER THE SESSION. `_counter_new_and_trunk` already computes
    exactly the files entering the trunk under each counter's directory — the same scan
    `_counter_land_gate` refuses on moments earlier, so the gate and the release cannot
    disagree about which numbers this land is about. A release keyed on "records this
    session holds" would instead free a number whose ADR is still being written, which is
    the boundary WI-0237 drew and this must not cross.

    `force=True`, and that is the point rather than a shortcut. Ownership at this instant
    is unreliable by construction: the record may have been drawn through the main-anchored
    front door under a different key, by a session whose journal is already closed. The
    fact that authorises the release is not *"this is mine"* — it is *"the file carrying
    this number is on the trunk"*, which is a property of the ref, not of the holder. That
    is the same fact `_coord_reap`'s trunk-visible branch already frees on, arriving hours
    earlier and from the one place that knows immediately.

    Never raises: the land has already succeeded when this runs, and a reservation left
    behind is a nuisance the reaper collects — a raised exception here would strand a
    landed trunk mid-transaction, which is not a trade worth making."""
    freed: list[str] = []
    try:
        for c in _counters().values():
            scan = _counter_new_and_trunk(c, tip, parent)
            if scan is None:
                continue
            for n, _name in scan[0]:
                num = f"{n:04d}"
                if _coord_release(c.namespace, num, _coord_identity(), force=True,
                                  reason="landed"):
                    freed.append(f"{c.label} {num}")
    except Exception as e:                       # pragma: no cover - defensive
        return [f"numbers: release skipped — {e}; the reaper will collect them."]
    if not freed:
        return []
    return [f"numbers: released {', '.join(freed)} — the files carrying them are on the "
            f"trunk, so the reservations are spent."]


def _restore_trunk_views(parent: str) -> list[str]:
    """Put this lane's copy of every trunk-only view back to `parent`'s content, as one
    commit on the lane branch. Returns the receipt lines to print.

    ADR-0119 D5. `ROADMAP.md`, the compiled handoff and `STATUS.md` have a single writer —
    the trunk's own compile ([ADR-0105](adr/0105-roadmap-is-a-compiled-trunk-only-view.md) D4,
    [ADR-0056](0056-session-branch-gated-trunk.md)) — so a lane's copy of one is never
    content, it is a render of a tree that is behind. Carrying it into the rebase produces
    exactly two outcomes and both are defects: the trunk touched the same file and the lane
    is REFUSED on a file the trunk regenerates seconds later (WI-0262), or the trunk did
    not and the lane's stale render LANDS (WI-0260 — five real outcome bullets replaced by
    the empty placeholder, and only main having independently touched the file saved it).

    RESTORE, NEVER REMOVE. Deleting the views would be simpler and is wrong: the trunk
    would carry no `ROADMAP.md` between the CAS and the recompile, and `cmd_wi_render`
    splices into an existing file — the regeneration meant to heal it would find nothing to
    write into, so the human-facing view would be gone rather than stale. Taking the
    trunk's own bytes leaves the replayed commit a no-op against the tip it replays onto,
    which is the whole point.

    SAME TWO MEMBERSHIPS AS `_conflict_is_resolvable`, and for the same reason. A wholly
    generated view — the handoff, `STATUS.md` — is restored unconditionally: every byte is
    re-derived, so there is nothing a lane could have authored in one. `ROADMAP.md` is
    generated only in REGIONS, and is restored only when the lane's divergence is confined
    to them (`_strip_generated_regions` equal on both sides). A lane that edited `## Now`
    is left exactly as it is, to land or to be refused by name.

    That narrowing is not caution, it is the decision ADR-0105 already made and measured:
    taking the trunk side of the whole file *"would silently delete authored prose on every
    land, with no second copy to recover it from"* — the interim it rejected outright. A
    first cut of this function did take the whole file and was caught by the control
    `RoadmapResolveTest.test_a_lane_that_edited_the_hand_authored_now_still_refuses_by_name`
    exists to be: silently discarding prose is a worse failure than the stale render this
    is fixing, and the lane being out of contract (ADR-0105 D4 — lanes never write it) is
    an argument for telling someone, never for deleting it quietly.

    Idempotent, and it must be: it runs once per CAS attempt, against whatever tip that
    attempt read. A view already matching the trunk stages nothing and commits nothing, so
    a retry adds no empty commit. Never raises — a land is not failed by a view."""
    lines: list[str] = []
    restored: list[str] = []
    held: list[str] = []
    try:
        whole = _generated_view_names()
        for rel in _trunk_only_views():
            # A view the trunk does not carry cannot be restored FROM it. Skipping is the
            # honest answer: `git checkout <sha> -- <missing>` errors, and treating that
            # as "nothing to do" is the same thing without the noise.
            if sh(["git", "cat-file", "-e", f"{parent}:{rel}"], check=False).returncode != 0:
                continue
            if sh(["git", "diff", "--quiet", parent, "HEAD", "--", rel],
                  check=False).returncode == 0:
                continue                       # the lane already agrees with the trunk
            if Path(rel).name not in whole and not _lane_side_is_render_only(parent, rel):
                held.append(rel)
                continue
            if sh(["git", "checkout", parent, "--", rel], check=False).returncode == 0:
                restored.append(rel)
        for rel in held:
            lines.append(f"views:   {rel} left as the lane has it — it differs OUTSIDE its "
                         f"generated regions, so this lane authored prose and the land "
                         f"will not discard it (ADR-0105).")
        if not restored or not _has_staged_changes():
            return lines
        r = sh(["git", "commit", "-m",
                "chore(views): restore trunk-only views before landing (ADR-0119)"],
               check=False)
        if r.returncode != 0:                  # pragma: no cover - defensive
            return [f"views:   could not restore {', '.join(restored)} — "
                    f"{(r.stderr or r.stdout).strip()}; landing with the lane's copies."]
        lines.append(f"views:   restored {', '.join(restored)} to the trunk's copy — "
                     f"a lane does not author a compiled view (ADR-0105 D4).")
    except Exception as e:                     # pragma: no cover - defensive
        return [f"views:   restore skipped — {e}; landing with the lane's copies."]
    return lines


def _land_worktree_lane(focus, blocked, version: str, commit_msg: str | None = None,
                        push: bool = True, attempts: int | None = None,
                        resolve: str = "generated", renumber: bool = True) -> "LandOutcome":
    """Land a terminal worktree lane onto the trunk (ADR-0060 D2).

    The session is ALONE in its own linked worktree on a `worktree-<name>` branch, so
    it owns every changed file — no attribution, no private index, no scratch-gate on
    the shared tree. The flow, entirely by plumbing so nothing is checked out that
    another worktree holds:

      commit the lane's REAL files (journal + work; NOT the generated views — see
      run_compile / ADR-0060) -> rebase the branch onto the local trunk tip (this lane
      owns the branch, so a rebase here is safe) -> gate the rebased tip in a throwaway
      worktree -> compare-and-swap the trunk ref forward to that tip (never checking out
      the trunk — the main checkout holds it; never checking out the branch — this lane
      holds it).

    The trunk is the local `refs/heads/<trunk>`: it is the single source of truth for
    concurrent lanes on one machine, so the CAS is race-correct without depending on
    origin state (origin is a push backup). Loser of a CAS race rebases on the new tip
    and re-gates (ADR-0051 C3). Leaves the lane clean and merged; Claude then removes
    the worktree and the `WorktreeRemove` hook deletes the now-merged branch. Every
    failure leaves the work committed on the lane branch — `session.py merge` retries.
    The lane lands ONLY its real work (the closed journal + any files it changed); the
    generated handoff/STATUS are NEVER folded into the rebased close commit. Doing so was
    the session-83 view-amend defect: a CAS-losing lane re-rebasing onto the winner's trunk
    collided on those generated files. The views are derived and heal at the next session
    start (accept-lag), exactly like the ADR-0056 D2 branch model — so no generated file
    ever rides a lane's rebased history and the re-rebase carries only its distinct journal,
    which cannot conflict. (`version`/`focus`/`blocked` are accepted for signature
    stability with the branch/shared-tree land paths; a lane records them in its journal
    and STATUS reflects them at the next compile.)"""
    # WI-0349: ready to land, right here — the work is done and the verb has been
    # invoked. Everything after this point is the land, including the journal reap, the
    # close commit, every retry and re-gate, the queue wait and the publish. Marked in
    # the lander rather than at the call site because there are five call sites and a
    # forgotten mark is an unmeasured land.
    #
    # ADR-0148 D2: BEFORE the mark. A lane with no green verdict for its tree runs the
    # suite once here, in its own working tree — that is the session's build time, and
    # the receipt carries it as `build_seconds` rather than folding it into the land.
    trunk = _trunk()
    verdict_ok, accepted = _ensure_lane_verdict(trunk)
    if not verdict_ok:
        print("         branch left intact; nothing was committed or landed.")
        return LandOutcome(False, "gate")
    mark_ready_to_land()
    branch = _current_branch()
    # 0. ADR-0089 D2: ABSORB a surviving checkpoint rather than fast-forwarding it onto
    #    the trunk. Reachable when a lane is landed without ever being resumed (a resumed
    #    lane dissolves its own checkpoint at the first heartbeat). `--soft` puts its
    #    content back in the index, where step 1 commits it as part of the close — so the
    #    work lands and the `wip(checkpoint)` commit never reaches the trunk. Reported,
    #    not silent: a commit that disappears without a line in the record is the quiet
    #    history edit P2 exists to prevent.
    absorbed = _head_is_checkpoint() and _dissolve_lane_checkpoint()
    if absorbed:
        print("absorbed: a stop-checkpoint commit was folded into this close "
              "(ADR-0089 D2) — its work lands, the wip commit does not.")
    # 0b. WI-0110: close any journal in THIS LANE whose session is provably dead, NOW —
    #     this is the last moment the proof exists. A journal is tracked and travels to
    #     the trunk on land; its `.session-state/<csid>.ended|.gone` evidence is
    #     gitignored and per-worktree and does NOT. So a journal landed without being
    #     closed can never afterwards be PROVEN closeable from the trunk — the reaper
    #     matches by claude-session-id against `ROOT/.session-state`, which on main holds
    #     nothing for a session that lived in a lane — and it reads as an unstamped false
    #     close to every observer, forever. Worse, the very next step the banner
    #     recommends ("close it to free the worktree") destroys the evidence for good.
    #     Verified live on poga-3, session ~129: journal on main with `ended:` empty,
    #     zero sidecar files for its csid under the main checkout, both markers present
    #     under the lane. The board was showing this same shape six times across four
    #     systems — the fleet's single largest red.
    #
    #     Reuses the reaper unchanged (P16) rather than re-deriving "is it dead": same
    #     evidence rule, same grace, same phantom deletion. It is a no-op for the case
    #     `merge` exists to serve — a LIVE session landing mid-flight, whose own journal
    #     has a fresh beat and no exit marker (this session used `merge` twice while
    #     alive and stayed open both times).
    for sid, disposition in _reap_dead_journals(_claude_session_id()):
        print(f"closed:  {sid} — {disposition} (its liveness evidence lives in this "
              f"lane and would not have survived the land).")
    # 1. Commit the lane's real files (the closed journal + any work) as the close
    #    commit. The generated views are folded in per-iteration below, against whatever
    #    trunk tip this land actually advances — so they reflect every landed journal.
    sh(SWEEP_ADD)
    if _has_staged_changes():
        # WI-0280: `lane=branch` as well as the verb. A grant's scope has three axes
        # (D5) and this call used to name one, so a grant minted `--lane worktree-poga-1`
        # would stamp a land out of poga-5 with an `Authorized-By` line that truthfully
        # cited a record authorizing a different lane. That is exactly the unbacked
        # provenance claim the resolve exists to refuse. The branch IS the lane name the
        # operator types into `poga authorize --lane`, so the two sides already agree.
        # The `item` axis stays unnamed and is NOT covered here: this commit is the
        # lane's whole close, which may span several items, so there is no single id to
        # check it against — an item-scoped grant therefore still resolves for a land.
        sh(["git", "commit", "-m", commit_msg or f"chore(lane): work on {branch}"]
           + _grant_trailer_args(verb="land", lane=branch), check=False)
        print(f"committed: {commit_msg or 'lane work'}  (on {branch})")
    # ADR-0124 D1, superseding ADR-0114 D2 narrowly. The critical section is NO LONGER
    # rebase -> gate -> CAS. It is: check the trunk is where we validated against, merge,
    # publish. Everything expensive — the rebase, the renumber, the counter gate and the
    # whole suite — happens out here, where a second lane doing the same thing costs this
    # one nothing.
    #
    # WHAT MAKES IT SAFE is the check, not the shortening: inside the lock we refuse to
    # advance unless the trunk is still exactly the `parent` this candidate was validated
    # against, so the tree that lands is the tree that was gated, identically. When the
    # trunk HAS moved we write nothing, leave the lock, rebase and re-validate out here —
    # ADR-0114 D7 in full ("a lost CAS still re-runs the whole gate"), moved out of the
    # queue rather than repealed.
    #
    # Measured before this change, on the WI-0325 land: derive 271 s + gate 58 s inside
    # the lock, merge 0.060 s, push 1.7 s. Five lanes took about an hour to land ten
    # minutes of work.
    budget = _cas_budget(attempts)
    swapped = False
    for attempt in budget.attempts():
        stage_started = time.monotonic()
        # WI-0356: the shared trunk must be current with origin BEFORE this lane
        # rebases onto it. Replaces the bare fetch that used to be this line — the
        # fetch still happens inside, but its answer is now acted on instead of
        # discarded. This is the lander the defect was measured in: the trunk sat one
        # behind origin, lands kept stacking on it, and within the hour it was
        # diverged and unpushable.
        #
        # Per attempt, and BEFORE `parent` is read, so a fast-forward becomes the tip
        # this lane rebases onto. Checking after would leave the candidate built on
        # the stale tip, which is the bug with a reassuring line printed over it.
        refusal = _require_trunk_current_for_land(trunk)
        if refusal:
            print("         branch left intact; journal is closed, work is safe.")
            return LandOutcome(False, refusal)
        pr = sh(["git", "rev-parse", "--verify", "--quiet", f"refs/heads/{trunk}"], check=False)
        parent = pr.stdout.strip()
        if pr.returncode != 0 or not parent:
            print(f"land:    FAIL — cannot resolve the local {trunk} tip.")
            return LandOutcome(False, "trunk")
        # Rebase the lane branch onto the current trunk tip so the advance is a pure ff.
        #
        # UNLESS the lane already CONTAINS the trunk. A lane that merged the trunk in is
        # already a superset of it, so the trunk ref can advance to this tip by pure
        # fast-forward and the rebase has nothing left to do — except flatten the merge,
        # which is the ADR-0102 replay the lane merged precisely to avoid. Rebasing here
        # re-applies both sides of an already-resolved merge and reports conflicts on
        # files neither side has touched since. Found landing the ADR-0103/0106 promotion
        # reconciliation: a 216-commit lane carrying a genuine two-trunk merge was refused
        # by its own land verb, on seven paths the merge had already settled.
        # ADR-0119 D5: the lane may not author a trunk-only view, so it does not
        # carry one into the rebase. Runs against THIS attempt's `parent`, inside the
        # retry loop and before both the fast-forward branch and the rebase — a lost
        # CAS re-reads the tip, and a restore against the tip we no longer have is a
        # restore against the wrong content.
        for line in _restore_trunk_views(parent):
            print(line)
        if sh(["git", "merge-base", "--is-ancestor", parent, "HEAD"],
              check=False).returncode == 0:
            print(f"land:    lane already contains {trunk} — advancing by fast-forward, "
                  f"no rebase (the merge is preserved).")
            rb = None
        else:
            rb = sh(["git", "rebase", parent], check=False)
        if rb is not None and rb.returncode != 0:
            # WI-0109: a conflict used to be a dead end — "resolve it in this lane", which
            # means opening a session in a lane whose session may well be over. Try the
            # bounded policy first; it clears only a conflict confined to generated files,
            # which this land regenerates minutes later anyway.
            cleared, rlines = _resolve_rebase_conflict(resolve)
            for line in rlines:
                print(line)
            if not cleared:
                stuck = _unmerged_paths()
                sh(["git", "rebase", "--abort"], check=False)
                lane = ROOT.name
                print(f"land:    BLOCKED — rebase onto {trunk} conflicts"
                      + (f" on {', '.join(stuck)}" if stuck else "") + ".")
                print(f"         branch left intact; journal is closed, work is safe.")
                # Name a verb, never a place. The old advice was addressed to a session
                # that may not exist — the WI-0097 banner defect in a second costume.
                print(f"         This one needs a mind, not a policy: `poga resume {lane}` "
                      f"re-enters the lane to resolve it, then `session.py merge --continue`.")
                return LandOutcome(False, "conflict")
        # The lane must be AHEAD of the trunk — else there is nothing to land. Guard
        # against a no-op CAS that would rewrite the trunk's own tip.
        #
        # WI-0326: "level with the trunk" has TWO causes and they need different answers.
        # Either this lane genuinely carries nothing, or a previous attempt DID land and
        # died before its publication finished — in which case the trunk is advanced, the
        # main checkout may be stale and the push may be owed, and reporting "nothing to
        # land" (which `LandExitStatusTest` classifies as not a failure) hides a half
        # delivery. Measured: a crash at the sync stage left exactly that, with no receipt
        # written at all, and the retry said there was nothing to do.
        #
        # `_resume_owed_publication` distinguishes them by asking the world, and returns
        # None when nothing is owed — so the genuinely-empty lane falls through to the same
        # refusal it always got, and the half-delivered one is finished at the stage it
        # stopped, with no second suite run.
        if sh(["git", "rev-parse", "HEAD"], check=False).stdout.strip() == parent:
            finished = _resume_owed_publication(trunk, parent, version, focus, blocked,
                                                push, resolve, attempt)
            if finished is not None:
                # Reconstructed rather than passed through, because WI-0263's guard
                # requires every lander return to be a literal `LandOutcome` — a bare name
                # is exactly how an exit status went missing before.
                return LandOutcome(finished.landed, finished.reason)
            print(f"land:    lane '{branch}' has no commits ahead of {trunk} — "
                  f"nothing to land.")
            return LandOutcome(False, "nothing")
        # ADR-0060 (revised, session-83 drill): the lane lands ONLY its real work (journal
        # + files) — NEVER the generated views. Folding a freshly compiled handoff/STATUS
        # into the rebased close commit was a defect: a CAS-losing lane, on its re-rebase
        # onto the winner's trunk, collided on those generated files (both close commits had
        # rewritten them). The views are derived and heal at the next session start
        # (accept-lag), like the ADR-0056 D2 branch model — so nothing generated rides the
        # rebased history and the re-rebase carries only the lane's distinct journal, which
        # cannot conflict. `--focus`/`--blocked` for a lane session are recorded in the
        # journal and reflected in STATUS at the next compile, not folded in here.
        tip = sh(["git", "rev-parse", "HEAD"], check=False).stdout.strip()
        # WI-0169: remap colliding numbers FIRST, then gate. Automatic by default — a fix
        # that ends in "and then run X" leaves X as the remaining defect, and the land
        # already holds everything the remap needs: the colliding set, the trunk tip, a
        # working tree that matches the tip, and an allocator. `--no-renumber` restores
        # the refusal for anyone who wants to look before anything is rewritten.
        if renumber:
            newtip, rlines = _auto_renumber_collisions(tip, parent)
            for line in rlines:
                print(line)
            if newtip:
                tip = newtip
        # R5a: a NEW number of ANY registered counter must have been drawn, not picked.
        num_ok, num_msg = _all_counter_land_gates(tip, parent)
        if not num_ok:
            print(num_msg)
            print("         branch left intact; journal is closed, work is safe.")
            return LandOutcome(False, "counter")
        # ADR-0124 D1: the gate runs HERE, outside the queue. The comment this
        # replaces explained why the hold had to re-stamp itself before a five-minute
        # suite; there is no longer a five-minute anything under the lock to re-stamp
        # for. The heartbeat thread (ADR-0119 D3) still covers the seconds that are.
        #
        # WI-0294 / brief D1a: classify the lane's own diff against the trunk tip
        # BEFORE gating. 65 of the last 80 trunk commits touched only paths the
        # suite never reads — journals, items, comms, generated views — so four
        # lands in five queued behind a five-minute suite over a diff that could
        # not move its verdict. Anything touching the measured input set gates
        # exactly as before.
        #
        # ADR-0124 D3: `_gate_lane_candidate` is gone with the serial derive it
        # wrapped, so this is the same `_gate_unless_neutral` the other two landers
        # call, and the candidate `tip` is no longer rewritten under us.
        #
        # ADR-0148 D1: `_land_gate` replaces `_gate_unless_neutral`. The suite does not
        # run here: the lane's verdict was settled before the clock (`accepted`), a
        # bookkeeping diff needs none, and a `moved` retry lands on its clean rebase.
        # What runs is the cheap checks, in the candidate's scratch worktree.
        validate_started = time.monotonic()
        ok, report, gate_info = _land_gate(parent, tip,
                                           lambda skip, _t=tip: _gate_commit(_t, skip),
                                           accepted)
        validated = time.monotonic() - validate_started
        print(report)
        if not ok:
            if gate_info.get("trunk_check_refusal"):
                print("         branch left intact; journal is closed, work is safe.")
                _land_receipt("land-lane", "refused", 0.0, {}, 0.0, validated, attempt,
                              trunk, parent, tip, verdict=gate_info)
                return LandOutcome(False, "trunk-red")
            print(f"land:    BLOCKED — gate failed. Fix in this lane on '{branch}', then "
                  f"`session.py merge --continue`.\n"
                  f"         branch left intact; journal is closed, work is safe.")
            return LandOutcome(False, "gate")
        # ADR-0053 R3 conformance miner, folded in per phase2-followons — WARN only,
        # scoped to this lane's own new commits (parent..tip), never blocks the land.
        warn = _new_roledoc_violation(parent, tip)
        if warn:
            print(warn)

        # WI-0378: carries one bool out of the serialized section — "the push was
        # rejected, and it was rejected rather than unreachable". Empty means the push
        # succeeded, was not attempted, or `publish` never ran (a `moved` outcome).
        escalate: list[bool] = []

        def publish(stages, _tip=tip, _parent=parent):
            """Everything the serialized section does AFTER the ref moves.

            All of it mutates state shared across lanes — the numbers registry, the
            main checkout's working tree, the trunk's generated views, origin — so
            all of it stays inside the lock. the operator's ruling names the section "merge
            and push"; this is what publishing that merge consists of, and none of
            it is validation. Each stage is timed separately into the receipt,
            because "the lock was held 40 s" and "the recompile took 38 s of it" are
            different findings and a total cannot tell them apart."""
            # ADR-0119 D2: a drawn number becomes REAL at the land that carries its
            # file, and the same transaction releases the reservation. Here and not
            # earlier — this is the first instant the numbers are trunk-visible, so
            # anything before it would free a number whose file might still not land
            # (WI-0237's `(3) LIMIT`).
            #
            # `_store_autocommit` already does this for numbers written through the
            # store, which is why `wi-alloc` and `ops-alloc` looked covered. Nothing
            # writes an ADR through the store, so `adr-alloc` had no release on any
            # write path at all and sat until its 8-hour TTL lapsed — holding a number
            # that was spent the moment this ref moved.
            for line in _release_landed_numbers(_tip, _parent):
                print(line)
            # The trunk ref moved with no checkout — bring the MAIN checkout along, or
            # say why not (consultant F1, session 90). Fail-open: a sync hiccup never
            # fails a done land.
            started = time.monotonic()
            sync_report = _sync_main_checkout(trunk, _parent, _tip)
            stages["sync"] = round(time.monotonic() - started, 3)
            if sync_report:
                print(sync_report)
            # Regenerate the compiled views ON THE TRUNK, in the main checkout
            # (session ~102). This closes a silent gap: the land deliberately keeps
            # generated views OUT of the lane's rebased history (a CAS-losing lane
            # collided on them), deferring the refresh to "the next session start" —
            # but that heal is `run_compile` in `_complete_lazy_start`, which no-ops
            # on a lane (ADR-0056 D2). Once every session became a lane, BOTH paths
            # declined to compile and the views froze at the last main-checkout close.
            started = time.monotonic()
            recompile_report = _recompile_main_checkout(trunk, version, focus, blocked)
            stages["recompile"] = round(time.monotonic() - started, 3)
            if recompile_report:
                print(recompile_report)
            if not push:
                return
            po = _push_trunk(trunk)
            if po.seconds:
                stages["push"] = po.seconds
            if po.ok:
                if po.line:
                    print(po.line)
                return
            stages["push_owed"] = po.owed
            print(po.line)
            # WI-0355: a push that never REACHED origin must not buy a second trip down the
            # same dead route. `_integrate_trunk_with_remote`'s first act is a fetch from
            # the remote we just failed to talk to; on 2026-09-12 that cost 75.024s on top
            # of the push's own 75.013s and returned the OFFLINE line it was always going
            # to return. The land already succeeded and the work is on the local trunk, so
            # the honest move is to say the push is owed and stop, not to pay twice for the
            # same answer. Only a POSITIVELY identified network fault stops here — an
            # unclassified failure falls through to the integrate, so WI-0143's self-heal
            # survives a classifier that is incomplete.
            #
            # WI-0378: the escalation itself no longer happens HERE. It is recorded as
            # owed and run by the caller once this section has been released — see
            # `_escalate_to_integrate` below.
            escalate.append(po.unreachable)

        outcome, hold, stages = _serialized_advance(trunk, parent, tip, publish,
                                                    verb="land-lane")
        # ── OUTSIDE THE SECTION (WI-0378) ──────────────────────────────────────────
        # The integrate runs a full suite, and until this change it ran re-entrantly
        # inside the hold above (ADR-0114 D6 made the re-entry legal; ADR-0124 named it
        # as the one path that could still blow the budget and left it alone). Measured
        # on this machine's receipts, 2026-09-10 → 2026-09-17: it was 356.2s of 837.9s
        # of total gate hold — 42.5% from four events — and three of the four holds that
        # breached the 30s budget.
        #
        # ADR-0124 declined to move it because "releasing the lock mid-publication, with
        # the local trunk already advanced and origin not, is a worse shape than a slow
        # hold". That reasoning treats the intermediate state as something the release
        # CREATES. It does not: the rejected push created it, one line earlier, and
        # ADR-0134 D2/D3 shipped it as a named, reported, recoverable state with a verb
        # that clears it. Releasing costs nothing that is not already true; holding costs
        # every queued lane a second full suite.
        if outcome == "landed" and escalate and not escalate[0]:
            _escalate_to_integrate(trunk, stages, resolve)
        # ADR-0148 D5: the trunk verifies itself, in the background, one check at a
        # time and coalescing. Spawned, never awaited — it cannot slow this land.
        if outcome == "landed":
            gate_info["trunk_check"] = _trunk_check_spawn(trunk, tip)
        rec = _land_receipt("land-lane", outcome, hold, stages,
                            time.monotonic() - stage_started - validated, validated,
                            attempt, trunk, parent, tip, verdict=gate_info)
        print(_land_hold_line(rec))
        # WI-0326: the CAS succeeded and a publication stage then threw. The trunk IS
        # advanced, so this is not a failed land — it is a delivery that stopped partway,
        # and the honest move is to finish it here rather than to let the session close
        # over it. The resume re-reconciles against refs and origin, so it is correct even
        # if the stage that threw had in fact taken effect.
        if outcome == "landed" and stages.get("publish_error"):
            print(f"land:    the advance is made, but publishing raised "
                  f"{stages['publish_error']}")
            finished = _resume_owed_publication(trunk, tip, version, focus, blocked,
                                                push, resolve, attempt, force=True)
            if finished is not None and not finished.landed:
                return LandOutcome(finished.landed, finished.reason)
        if outcome == "landed":
            swapped = True
            print(f"landed:  lane '{branch}' → {trunk}"
                  + _land_publish_suffix(push, stages, trunk)
                  + "\n         lane is clean + merged; close it to free the worktree.")
            break
        print(f"land:    {_moved_or_lost_line(outcome, attempt, trunk, parent, budget)}")
    if not swapped:
        print(budget.exhausted_line(trunk))
        return LandOutcome(False, "contended")
    # No master: if this lane was dispatched, IT pulls the next queued item and spawns
    # it (WI-0032). Placed after the land is reported and irreversible, and fail-open
    # inside, so a dispatch problem can never turn a landed lane into a failed one.
    _dispatch_after_land()
    return LandOutcome(True)


def _reap_dead_journals(current_csid: str | None,
                        dry_run: bool = False) -> list[tuple[str, str]]:
    """Journal-native lease reaper (ADR-0051 — the orphan sweeper's systemic role, pulled
    forward from Phase 3; crash-class semantics amended by ADR-0054). Closes any OTHER
    open journal whose owning session is provably dead per the liveness sidecar (matched
    by claude-session-id): a clean-exit marker (as the latest signal) closes it at that
    time; a stale heartbeat with no later exit marker is treated as a crash — and closed
    at the last beat — only once the silence exceeds the grace that beat earns, because a
    beat that is merely HEARTBEAT_STALE_MIN old also describes a live session (idle-open,
    or — pre-ADR-0054 — mid-long-turn: the session-74 false reap). Within the grace, and
    with a FRESH heartbeat (live concurrent) or no sidecar (no evidence), the journal is
    left open — flown-not-landed.

    The grace is per-BEAT-KIND, not one number (`_crash_grace_min`): 48 h for an
    activity-driven hook beat, 2 h for a timer-driven supervisor beat whose silence is far
    less ambiguous. Better still, a supervisor beat names the process it watches, so on the
    same machine the silence is RESOLVED rather than waited out (`_supervised_pid_state`) —
    a dead subject closes the journal now, a live one protects it regardless of age. A reaped journal that never left the stub body and lived
    < REAP_PHANTOM_MAX_SEC is a phantom — DELETED, so it consumes no ordinal. Never
    touches the current session. Best-effort; never raises. Returns
    [(session-id, disposition)].

    `dry_run` reports the identical verdicts and writes nothing. It exists because the
    standalone `janitor` verb grew a `--dry-run` long before it could reach this function,
    and a preview flag that quietly closed journals anyway would be the worst kind of
    defect here — the one that looks like a preview."""
    reaped: list[tuple[str, str]] = []
    if _machine_close_would_hit_the_real_repo():
        return reaped                          # WI-0146 — never mutate real journals under test
    try:
        for p in _open_journal_paths():
            text = p.read_text(encoding="utf-8")
            fm, body = parse_journal(text)
            csid = fm.get("claude-session-id")
            if not csid or csid == current_csid:
                continue                      # the current session, or no liveness key
            ev = _sidecar_evidence_by_csid(csid)
            beat, ended = _parse_iso(ev["last_beat"]), _parse_iso(ev["ended_at"])
            gone = _parse_iso(ev["gone_at"])
            fresh = ev["beat_age_min"] is not None and ev["beat_age_min"] <= HEARTBEAT_STALE_MIN
            # Two kinds of DEATH EVIDENCE, and the later one wins: a clean-exit marker
            # (`.ended`, written by a runtime's own close binding) and an observed-exit
            # marker (`.gone`, ADR-0082 D7 — the wrapper's watcher saw the process
            # disappear). Both are *observations that the session is over*, which is why
            # neither needs the grace; the grace exists only for SILENCE, which is
            # ambiguous because a quiet session may merely be idle-open.
            death, death_at = None, None
            for cand, cand_at in ((ended, ev["ended_at"]), (gone, ev["gone_at"])):
                if cand is not None and (death is None or cand >= death):
                    death, death_at = cand, cand_at
            # The LATEST signal decides. LIVE only when a fresh heartbeat is the last thing
            # seen — i.e. it came at/after any death marker (a genuine resume). A death
            # signal that FOLLOWS the final heartbeat is definitive, however recent the beat.
            # A THIRD kind of evidence, for a timer beat: the watched process itself
            # (ADR-0082 D7 reconciled with ADR-0054). It outranks freshness — a beat
            # minutes old only says the WATCHER was alive minutes ago, and if its subject
            # is gone now, the session is over however recently it was seen breathing.
            pid_state = _supervised_pid_state(ev)
            if pid_state == "alive":
                continue                      # the watched process is still there — live
            if pid_state == "gone":
                # This IS the observation `.gone` records; the watcher simply did not
                # survive to write it. Close at the last moment the session was known
                # alive — the same instant the crash path uses — unless a marker landed
                # later, in which case the latest signal wins as it does everywhere here.
                ended_at = (death_at if (death is not None and beat is not None and death >= beat)
                            else (ev["last_beat"] or death_at))
                if not ended_at:
                    continue                  # nothing datable — leave it flown-not-landed
                reason = "process-gone"
            elif fresh and (death is None or (beat is not None and beat >= death)):
                continue                      # live (resumed past any death marker)
            elif death is not None and (beat is None or death >= beat):
                ended_at, reason = death_at, "exit-marker"   # an observed end is the last signal
            elif beat is not None and ev["beat_age_min"] > _crash_grace_min(ev):
                ended_at, reason = ev["last_beat"], "silent"  # silent past the grace THIS beat earns
            else:
                continue                      # in-grace or no evidence — flown-not-landed
            start_dt, end_dt = _parse_iso(fm.get("started", "")), _parse_iso(ended_at)
            secs = (end_dt - start_dt).total_seconds() if (start_dt and end_dt) else None
            if (_journal_is_unauthored(body) and secs is not None
                    and secs < REAP_PHANTOM_MAX_SEC):
                if not dry_run:
                    p.unlink()                # phantom — a non-event; ordinal reclaimed
                reaped.append((fm.get("session-id", p.stem), "phantom-deleted"))
            else:
                dur = format_duration(start_dt, end_dt) if (start_dt and end_dt) else "?"
                # WI-0137: stamp the death class as the title, but only over the birth
                # placeholder — a session that titled its own journal mid-flight said
                # something the reaper cannot improve on, and clobbering it would lose
                # the one piece of judgment in the file.
                stub = (fm.get("title") or "").strip() in ("", JOURNAL_STUB_TITLE)
                if not dry_run:
                    atomic_write(p, finalize_journal(
                        text, ended_at, dur,
                        title=machine_close_title(reason) if stub else None,
                        closed_by=f"reap ({MACHINE_CLOSE_REASONS[reason]})", path=p))
                reaped.append((fm.get("session-id", p.stem), "closed"))
    except Exception:
        pass
    return reaped


def lane_session_evidence(lane_dir) -> dict:
    """{session-id: liveness evidence} read from a lane's OWN `.session-state`.

    Must be called BEFORE the worktree is removed — the sidecar lives inside it, and the
    removal is what destroys the evidence. Returning the evidence rather than the
    directory is the point: an earlier cut of this passed the PATH down to the closer,
    which then ran after the removal and read an empty dir, so every close silently fell
    back to teardown time. The test that pinned "prefer the last beat" is what caught it.

    Keyed by SESSION-id (from the payload), not by the claude-session-id in the filename
    stem — those are different namespaces and the journal is addressed by the former."""
    out: dict = {}
    try:
        state = Path(lane_dir)
        if not state.is_dir():
            return out
        for suffix in ("live", "ended", "gone"):
            for f in sorted(state.glob(f"*.{suffix}")):
                try:
                    data = json.loads(f.read_text(encoding="utf-8"))
                except Exception:
                    continue
                sid = (data.get("session_id") or "").strip()
                if not sid:
                    continue
                ev = out.setdefault(sid, {})
                if suffix == "live":
                    ev["last_beat"] = data.get("last_beat") or data.get("started")
                elif suffix == "ended":
                    ev["ended_at"] = data.get("ended")
                else:
                    ev["gone_at"] = data.get("gone")
    except Exception:
        pass
    return out


def lane_session_ids(lane_dir, branch: str = "") -> tuple:
    """Every session-id that ran in `lane_dir`, from its own sidecar.

    The sidecar is the direct association and the branch is not. `_lane_journal_ids`
    answers `git diff {trunk}...{branch}`, a symmetric difference from the merge base —
    which is EMPTY the moment the branch is merged. That is precisely the state
    `cmd_worktree_remove` runs in on its success path, because `git branch -d` only
    succeeds on a MERGED branch: measured directly, the same lane yields `['J1']` before
    the merge and `[]` after it. So the ids WI-0123 reads "while the branch still exists"
    are reliably empty exactly when they are wanted, and the coordination release it feeds
    has been releasing nothing on the path that matters.

    `branch` is an optional FALLBACK for the unmerged case, where a crashed lane may have
    left no sidecar but its journal is still uniquely visible on the branch."""
    ids = tuple(lane_session_evidence(lane_dir).keys())
    if ids or not branch:
        return ids
    try:
        return tuple(_lane_journal_ids(branch))
    except Exception:
        return ()


def close_torn_down_lane_journals(session_ids, evidence, dry_run: bool = False):
    """Close a torn-down lane's still-open journals, using the teardown itself as proof.

    WI-0118. A lane keeps its liveness sidecar INSIDE its own worktree, so removing the
    worktree destroys the evidence the reaper reads — and the journal then falls through
    to the janitor's aged-out path and waits `JANITOR_AGED_DAYS` (7) to be closed with
    `duration: unknown`. That wait buys nothing: the worktree being gone is already a
    stronger proof than anything the sidecar could have said, because a session cannot
    still be running in a directory that no longer exists. The board had been
    computing and displaying exactly this the whole time while neither closer consulted it.

    The item flagged a likely blocker — a journal does not record which worktree it ran in,
    so the lane-to-journal association might need building first. It does not: the LANE
    BRANCH is the association, and `cmd_worktree_remove` already reads the branch's journal
    ids before deleting it (WI-0123, for the coordination holds). The link was already in
    hand one line away from where it was needed.

    Two honesty constraints, both load-bearing:

    * **The caller must have CONFIRMED the worktree is gone.** `git worktree remove`
      refuses a dirty or untracked lane by design (P9 — no work destroyed), and on that
      path the directory still exists and its session may well be alive. Closing on an
      *attempted* removal would manufacture a death. The proof is the absence, not the
      command.
    * **The end time comes from evidence CAPTURED BEFORE the removal**, which is why this
      takes an evidence mapping rather than a directory to read. An earlier cut passed the
      sidecar path down and read it here — after the worktree was gone — so every close
      silently fell back to teardown time while looking correct. Only when there is
      genuinely no beat does it fall back to that instant, which is a true upper bound
      rather than a measurement, and it is recorded as `duration: unknown` rather than
      dressed as one ([`no-fabricated-data`](habits/master.md#no-fabricated-data)).

    Returns [(session-id, outcome)] and never raises: this rides a fail-open hook.
    """
    closed: list[tuple[str, str]] = []
    try:
        for sid in session_ids:
            p = journal_path(sid)
            if not p.is_file():
                continue                  # lives only on an unmerged branch — not ours
            text = p.read_text(encoding="utf-8")
            fm, body = parse_journal(text)
            if not fm or (fm.get("ended") or "").strip():
                continue                  # already closed, by its own ritual or a reaper
            ev = (evidence or {}).get(sid) or {}
            # Prefer a real observed end, then the last beat, then the teardown instant.
            ended_at = (ev.get("ended_at") or ev.get("gone_at")
                        or ev.get("last_beat") or _now_iso())
            measured = bool(ev.get("ended_at") or ev.get("gone_at") or ev.get("last_beat"))
            start_dt, end_dt = _parse_iso(fm.get("started", "")), _parse_iso(ended_at)
            dur = (format_duration(start_dt, end_dt)
                   if (measured and start_dt and end_dt) else "unknown")
            stub = (fm.get("title") or "").strip() in ("", JOURNAL_STUB_TITLE)
            if not dry_run:
                atomic_write(p, finalize_journal(
                    text, ended_at, dur,
                    title=machine_close_title("lane-torn-down") if stub else None,
                    closed_by=f"worktree-remove ({MACHINE_CLOSE_REASONS['lane-torn-down']})",
                    path=p))
            closed.append((sid, "closed" if measured else "closed (duration unknown)"))
    except Exception:
        pass
    return closed


def _janitor_log(record: dict) -> None:
    """Append one sweep record. Best-effort — a log that cannot be written must never
    stop the sweep, and a sweep that happened is still better than one that did not."""
    try:
        SESSION_STATE_DIR.mkdir(exist_ok=True)
        with (SESSION_STATE_DIR / "janitor.jsonl").open("a", encoding="utf-8") as fh:
            fh.write(json.dumps(record, ensure_ascii=False) + "\n")
    except Exception:
        pass


def _janitor_sidecar_dirs() -> list[Path]:
    """Every `.session-state/` this repo is responsible for — THIS working tree's, and the
    MAIN checkout's when we are running in a lane (WI-0085).

    `.session-state/` is per-tree by design (it is what makes a lane invisible to its
    siblings), and `SESSION_STATE_DIR` is anchored on `ROOT`. So a lane's janitor swept the
    lane's own handful of files and never main's — while ADR-0059's detect-and-refuse
    steers essentially every session into a lane, making main's pile the one nobody was
    ever positioned to sweep. It reached **78** stale `.live` markers, oldest 2026-07-05,
    at the same time the sweep was reporting itself as having run.

    Same shape as `_auto_reap_lanes` being gated to the main checkout and thereby becoming
    dead code (session 90): a capability whose only caller is a surface nobody opens. The
    fix is the same — stop scoping the sweep to the surface, scope it to the repo.

    Deduped and existence-checked, so the main checkout is not swept twice when we ARE the
    main checkout. Never raises."""
    dirs: list[Path] = []
    seen: set[Path] = set()
    for d in (SESSION_STATE_DIR, _shared_work_root() / ".session-state"):
        try:
            r = d.resolve()
        except Exception:
            continue
        if r in seen or not d.is_dir():
            continue
        seen.add(r)
        dirs.append(d)
    return dirs


def _sibling_lane_sidecar_dirs() -> list[Path]:
    """Every OTHER lane's `.session-state/` — the stores no janitor is otherwise
    positioned to reach (WI-0270).

    `_janitor_sidecar_dirs` covers this tree and the main checkout, on the reasoning that
    each lane sweeps its own on its next start. That reasoning holds for every lane except
    the ones that matter here: a lane held unrecoverable does not start again, so it never
    runs the sweep that would release it. The residue and the thing preventing its removal
    were the same file.

    Used ONLY for the malformed-stem rule, with an age cutoff that can never fire — a lane
    has no business judging a sibling's real residue by this lane's clock. Never raises;
    an unreadable pool is simply not swept."""
    out: list[Path] = []
    try:
        root = _lanes_root()
        if not root or not root.is_dir():
            return out
        here = SESSION_STATE_DIR.resolve()
        for lane in sorted(root.iterdir()):
            d = lane / ".session-state"
            try:
                if d.is_dir() and d.resolve() != here:
                    out.append(d)
            except OSError:
                continue
    except Exception:
        pass
    return out


def _janitor_prune_sidecars(d: Path, open_csids: set[str], cutoff: float,
                            current_csid: str | None, dry_run: bool) -> int:
    """Drop dead per-session sidecar residue from one `.session-state/` dir; return the
    count pruned. A live session is protected twice over — by its journal being open, and
    by its `.live` marker's mtime being refreshed on every heartbeat — so the age cutoff
    alone would already spare it. Never raises."""
    n = 0
    try:
        for f in sorted(d.iterdir()):
            if not f.is_file():
                continue
            stem = ""
            for suf in JANITOR_SIDECAR_SUFFIXES:
                if f.name.endswith(suf):
                    stem = f.name[: -len(suf)]
                    break
            if not stem and f.name.startswith("wi-snapshot-") and f.name.endswith(".json"):
                stem = f.name[len("wi-snapshot-"):-len(".json")]
            if not stem:
                continue                       # not per-session residue (logs, prep, context)
            if stem == (current_csid or "") or stem in open_csids:
                continue                       # still load-bearing for a session in flight
            if f.name.endswith(LIVENESS_SUFFIXES) and not SIDECAR_STEM_RE.match(stem):
                # WI-0270: a stem that is neither a UUID nor a durable session id names
                # no session, so it is not evidence and no grace applies to it. The age
                # cutoff below is sized for real residue — "might still belong to someone"
                # — and spared exactly the files that could not. That is why three
                # `testsession.live` files survived every sweep and went on holding lanes:
                # their beats were always fresher than the cutoff, because a suite run
                # refreshed them. The write-side refusal stops new ones; this clears what
                # is already there, which the refusal by itself cannot do.
                n += 1
                if not dry_run:
                    # `missing_ok`: sibling stores are now reachable by more than one
                    # lane's janitor, so two can race on the same file. Losing that race
                    # is success — the file is gone — but an unhandled FileNotFoundError
                    # would abort the rest of this directory's sweep on the way out.
                    f.unlink(missing_ok=True)
                continue
            if f.stat().st_mtime >= cutoff:
                continue
            n += 1
            if not dry_run:
                f.unlink()
    except Exception:
        pass
    return n


def janitor_sweep(current_csid: str | None = None, dry_run: bool = False) -> dict:
    """Close aged evidence-less journals and drop dead sidecar residue. Never raises.

    Deliberately does NOT delete a phantom the way the reaper does. The reaper can prove a
    stub-bodied journal lived seconds; here there is no evidence at all, so 'this session
    did nothing' is an inference and deleting the record on it would destroy a narrative to
    tidy a list. Closing is reversible-in-effect (the text is untouched and the close is
    labelled); deleting is not.

    A closed-by-machine journal records `closed-by: janitor` and a duration of `unknown`,
    because with no evidence the end time genuinely is not known — stamping a computed
    duration between `started` and a bulk-commit timestamp would manufacture an 8-day
    session out of arithmetic ([`no-fabricated-data`](habits/master.md#no-fabricated-data))
    and trip the ADR-0053 insane-duration miner with our own fiction."""
    out = {"closed": [], "pruned": 0, "kept": 0, "dry_run": bool(dry_run)}
    if _machine_close_would_hit_the_real_repo():
        # WI-0146. Not an exception and not a log line: a sweep that touches nothing IS
        # the correct outcome here, and `refused` says which nothing it is, so a caller
        # (or a test) can tell "swept, found none" from "declined to sweep at all"
        # ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
        out["refused"] = "test suite running against the launch checkout"
        return out
    now = datetime.now(CFG["tz"]) if CFG else datetime.now()
    try:
        for p in _open_journal_paths():
            text = p.read_text(encoding="utf-8")
            fm, _body = parse_journal(text)
            csid = (fm.get("claude-session-id") or "").strip()
            if csid and csid == (current_csid or ""):
                continue                       # never the session doing the sweeping
            ev = _sidecar_evidence_by_csid(csid) if csid else None
            if ev and (ev["has_live"] or ev["has_ended"] or ev["has_gone"]):
                out["kept"] += 1
                continue                       # evidence exists — the REAPER's call, not ours
            last = _journal_last_activity(p, fm)
            last_dt = _parse_iso(last)
            if not last_dt:
                out["kept"] += 1
                continue                       # undatable — leave it rather than guess
            if (now - last_dt).total_seconds() < JANITOR_AGED_DAYS * 86400:
                out["kept"] += 1
                continue                       # young enough to still be a live long session
            out["closed"].append((fm.get("session-id", p.stem), last))
            if not dry_run:
                # WI-0137, same rule as the reaper: the placeholder title is replaced,
                # an authored one is left alone. The janitor's class is always the same
                # one — it exists precisely for the journals with no evidence left.
                stub = (fm.get("title") or "").strip() in ("", JOURNAL_STUB_TITLE)
                atomic_write(p, finalize_journal(
                    text, last, "unknown",
                    title=machine_close_title("no-evidence") if stub else None,
                    closed_by="janitor (no evidence, aged out)", path=p))
    except Exception:
        pass
    try:
        open_csids = set()
        for p in _open_journal_paths():
            fm, _ = parse_journal(p.read_text(encoding="utf-8"))
            cs = (fm.get("claude-session-id") or "").strip()
            if cs:
                open_csids.add(cs)
        cutoff = now.timestamp() - JANITOR_SIDECAR_KEEP_DAYS * 86400
        for d in _janitor_sidecar_dirs():
            out["pruned"] += _janitor_prune_sidecars(
                d, open_csids, cutoff, current_csid, dry_run)
        # WI-0270. Every OTHER lane's store, for malformed stems ONLY — `cutoff=0` means
        # nothing can age out, so the age rule cannot fire here and one lane's janitor
        # never prunes a sibling's real residue. Only files whose stem names no session
        # at all are removed.
        #
        # WHY THE SCOPE HAD TO GROW. `_janitor_sidecar_dirs` covers this tree and main, so
        # a lane self-cleans when it next starts — which is exactly what a STRANDED lane
        # never does. That is not an edge case, it is the whole population of the bug:
        # `poga-7` was held unrecoverable by a `testsession.live` in its own store, and
        # being held is what stopped it ever running the sweep that would have cleared it.
        # The residue outlived every mechanism positioned to reach it, which is the
        # WI-0085 shape again — a sweep scoped to the surface rather than to the repo.
        for d in _sibling_lane_sidecar_dirs():
            out["pruned"] += _janitor_prune_sidecars(
                d, open_csids, 0.0, current_csid, dry_run)
    except Exception:
        pass
    if not dry_run and (out["closed"] or out["pruned"]):
        _janitor_log({"at": _now_iso(), "closed": [s for s, _ in out["closed"]],
                      "pruned": out["pruned"]})
    return out


def _janitor_ignore_sidecar(dry_run: bool) -> list[str]:
    """Ensure `.session-state/` is gitignored and untracked in THIS repo (ADR-0091 D1).
    Idempotent and converging: appends the ignore line only when absent, untracks only
    what is tracked. Returns the pathspecs the janitor commit should carry (empty when
    the repo is already conformant — the steady state). This is the repo's own harness
    acting on its own tree; the standard section has always described the sidecar as
    gitignored, and members bootstrapped before that line existed never received it."""
    specs: list[str] = []
    try:
        gi = ROOT / ".gitignore"
        lines = gi.read_text(encoding="utf-8").splitlines() if gi.is_file() else []
        if not any(l.strip().rstrip("/") == ".session-state" for l in lines):
            if not dry_run:
                text = "\n".join(lines)
                if text and not text.endswith("\n"):
                    text += "\n"
                text += ("# Session liveness sidecar — per-tree scratch, never history "
                         "(ADR-0091 D1).\n.session-state/\n")
                atomic_write(gi, text)
            specs.append(".gitignore")
        tracked = sh(["git", "-C", str(ROOT), "ls-files", "--", ".session-state"],
                     check=False)
        if tracked.stdout.strip():
            if not dry_run:
                sh(["git", "-C", str(ROOT), "rm", "-r", "--cached", "-q", "--",
                    ".session-state"], check=False)
            specs.append(".session-state")
    except Exception:
        return []
    return specs


def _janitor_commit_harness_writes(dry_run: bool) -> dict:
    """Commit THIS repo's harness-written dirt — pathspec'd, never `add -A` (ADR-0091
    D2, the operator-approved precedent change). Runs only when no session is provably live
    here and the index is empty: a live session commits its own records at its own
    close, and a non-empty index means mid-flight state machinery must not touch. This
    is what makes a fleet-janitor close durable in git history on a parked member
    (WI-0117) instead of standing dirt nobody will ever sweep."""
    out = {"committed": [], "note": "", "dry_run": bool(dry_run)}
    try:
        if not (ROOT / ".git").exists():
            out["note"] = "not a git checkout"
            return out
        if _tree_has_live_session(ROOT.resolve()):
            out["note"] = "a session is live here — its records are its own to commit"
            return out
        if not _index_is_empty(ROOT):
            out["note"] = "the index is not empty — mid-flight state; not committing"
            return out
        mig = _janitor_ignore_sidecar(dry_run)
        r = sh(["git", "-C", str(ROOT), "status", "--porcelain"], check=False)
        if r.returncode != 0:
            out["note"] = "git would not report status"
            return out
        dirty = [l for l in (r.stdout or "").splitlines() if l.strip()]
        harness, _authored = _classify_dirt(dirty)
        specs = harness + [s for s in mig if s not in harness]
        if not specs:
            return out
        if dry_run:
            out["committed"] = specs
            return out
        ok, detail = _commit_harness_paths(
            ROOT, specs,
            "chore(janitor): commit harness-written session records (ADR-0091)")
        if ok:
            out["committed"] = specs
            _janitor_log({"at": _now_iso(), "harness_commit": specs})
        else:
            out["note"] = detail
    except Exception as exc:
        out["note"] = f"{type(exc).__name__}: {exc}"
    return out


def cmd_janitor(args: argparse.Namespace) -> None:
    """`session.py janitor [--dry-run]` — the scheduled/standalone entry point.

    Runs BOTH halves of session-record cleanup, because away from a session start nothing
    else will:

      1. the REAPER's evidence-based close (`_reap_dead_journals`) — a session whose
         sidecar proves it is over, closed at the moment that evidence names;
      2. the janitor's own sweep — evidence-LESS journals aged out, plus dead residue.

    Half 1 is here because the reaper's only other caller is `start`, so **a repo nobody
    opens never reaps**. That is not a corner case, it is the population: litter
    accumulates precisely in the repos nobody is working in, and those are exactly the
    repos the nightly fleet pass (`curate/adopt-runner.py` → `run_janitor_pass`) exists to
    reach. One member carried an open journal for 7.5 days with its own clean-exit marker sitting
    beside it the whole time — provably dead, swept nightly, and untouchable, because the
    one thing that reads that marker only ran at a session start that never came. The
    janitor met it every night and correctly stood down ("evidence exists — the REAPER's
    call, not ours"), which left the case owned by nobody: each half was individually
    right and the pair had a hole in it
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).

    **No predicate changes.** Same reaper, same evidence rules, same graces — it simply
    stops requiring someone to open a session first, so this verb now produces exactly
    what that repo's next session start would have produced. That equivalence is the
    whole safety argument, and it is why the fix is a caller rather than a new policy.

    Still ordered reaper-then-janitor, as at session start: the precise, evidence-based
    close gets first refusal, and the aged-out fallback only ever sees what it leaves."""
    if CFG is None:
        sys.exit(0)
    dry = bool(getattr(args, "dry_run", False))
    # Pass the live session id even though the evidence rules would also protect it: a
    # fresh heartbeat is what makes THIS session read as live, and identity is the cheaper
    # guarantee to reason about when the verb is run from inside a session it could reach.
    me = _claude_session_id() or None
    reaped = _reap_dead_journals(me, dry_run=dry)
    for sid, how in reaped:
        print(f"janitor: {'would reap' if dry else 'reaped'} {sid} ({how}) "
              f"— liveness evidence proves the session is over")
    res = janitor_sweep(me, dry_run=dry)
    tag = "would close" if res["dry_run"] else "closed"
    for sid, at in res["closed"]:
        print(f"janitor: {tag} {sid} at {at} (no liveness evidence, aged out)")
    verb = "would prune" if res["dry_run"] else "pruned"
    print(f"janitor: {verb} {res['pruned']} sidecar file(s); "
          f"{res['kept']} open journal(s) left alone.")
    # ADR-0091 D1/D2: the harness commits what the harness writes. After the sweep —
    # so a journal closed above is committed in the same pass — and only in a repo
    # with no live session and an empty index (the function holds both preconditions).
    hc = _janitor_commit_harness_writes(dry)
    ctag = "would commit" if dry else "committed"
    for p in hc["committed"]:
        print(f"janitor: {ctag} {p} (harness-written)")
    if hc["note"]:
        print(f"janitor: harness records not committed — {hc['note']}")
    sys.exit(0)


def cmd_supervise(args: argparse.Namespace) -> None:
    """ADR-0082 D7: heartbeat for the life of the runtime the wrapper launched.

    The Claude binding gets its liveness from `PreToolUse`/`Stop` hooks. A runtime with
    no hook surface has none, so its lane looks crashed from birth and the ADR-0054
    evidence model cannot work for it. This is the wrapper-side binding of the same
    obligation: watch a pid, beat while it lives.

    WHY A DETACHED WATCHER RATHER THAN SPAWN-AND-WAIT. `poga` hands the terminal to the
    agent with `exec`, which REPLACES the process image but KEEPS the pid — so a watcher
    started just before that exec can watch `$$` and be watching the agent itself, exactly
    and with no bookkeeping. Supervising by spawn-and-wait would instead put `poga`
    between the operator and the agent for the whole session, taking ownership of the
    terminal, signals and exit status; ADR-0082 D1 leaves Verify with the Architect, so
    the wrapper has no reason to outlive the agent and no business intercepting its
    signals.

    WHAT IT CANNOT DO, stated rather than implied: watching a pid tells you the process
    is GONE, never whether it went cleanly. So this writes no `.ended` marker and the
    clean-vs-crash discriminator is unchanged — a supervised runtime with no SessionEnd
    binding still has no clean-exit evidence, which is the honest reading of what a pid
    watch actually knows.

    What that costs has since been reduced. Each beat records the pid it is watching and
    the machine that pid means anything on, so a supervised session that goes silent is
    resolved by asking the OS rather than by waiting out a grace written for a completely
    different kind of beat; where the question cannot be asked, the fallback is
    `REAP_SUPERVISED_GRACE_MIN` (2 h), not the hook beat's 48 h.

    Resolution happens in the FOREGROUND, before detaching: the prep marker this reads is
    consumed by adoption moments later, so a child that read it after forking would race
    the very runtime it exists to watch. Fail-open throughout — a watcher that cannot
    start must never stop a session from starting."""
    if CFG is None:
        sys.exit(0)
    did = (getattr(args, "session_id", "") or "").strip() or _prep_session_id()
    if not did:
        print("supervise: nothing to watch — no --session-id and no prep marker.",
              file=sys.stderr)
        sys.exit(0)
    pid = int(getattr(args, "pid", 0) or 0)
    if pid <= 0 or not _process_alive(pid):
        print(f"supervise: pid {pid or '(none)'} is not running — not watching.",
              file=sys.stderr)
        sys.exit(0)
    if getattr(args, "detach", False):
        try:
            if os.fork() > 0:
                sys.exit(0)          # parent returns to poga immediately
            os.setsid()
            devnull = os.open(os.devnull, os.O_RDWR)
            for fd in (0, 1, 2):
                os.dup2(devnull, fd)
        except Exception:
            sys.exit(0)              # cannot detach → do not hold the terminal
    why = _supervise_loop(did, pid, int(getattr(args, "interval", SUPERVISE_INTERVAL_SEC)),
                          getattr(args, "max_beats", None))
    if why == "exited":
        _write_gone_marker(_supervise_key(did), pid)
    sys.exit(0)


def _worktree_branch_from_payload(hook: dict) -> str | None:
    """Derive the `worktree-<name>` branch a WorktreeRemove hook is about, from the
    hook payload. Prefers an explicit branch field; else derives it from the removed
    worktree path's basename (Claude Code names the branch `worktree-<dirname>`). Only
    returns names in the `worktree-` namespace — never a trunk or `session/` branch."""
    for k in ("branch", "worktree_branch", "worktreeBranch"):
        v = hook.get(k)
        if isinstance(v, str) and v.startswith("worktree-"):
            return v
    for k in ("worktree_path", "worktreePath", "path", "worktree", "worktree_dir"):
        v = hook.get(k)
        if isinstance(v, str) and v.strip():
            name = Path(v.rstrip("/")).name
            if name:
                return name if name.startswith("worktree-") else f"worktree-{name}"
    return None


def _worktree_path_from_payload(hook: dict) -> str | None:
    """The worktree DIRECTORY a WorktreeRemove hook is about. Claude Code hands removal
    to the hook when one is configured (its own strings: `No WorktreeRemove hook
    configured; falling back to git worktree remove for:` / `WorktreeRemove hook did not
    remove worktree, kept at:`), so the hook must do the removal itself — a hook that
    only prunes leaves the lane dir AND its lock behind, and the still-checked-out branch
    then refuses `git branch -d`."""
    for k in ("worktree_path", "worktreePath", "path", "worktree", "worktree_dir"):
        v = hook.get(k)
        if isinstance(v, str) and v.strip():
            return v.rstrip("/")
    return None


def cmd_worktree_remove(_args: argparse.Namespace) -> None:
    """WorktreeRemove hook (ADR-0060 D-teardown): when Claude removes a terminal lane's
    worktree, delete the now-merged `worktree-<name>` branch and prune the admin entry.
    Uses `git branch -d` (merged-only, refuses an unmerged branch), so a lane that
    landed is cleaned up and a lane that crashed BEFORE landing is left intact for the
    reaper / `poga lanes --clean` — its work is still committed on the branch. Reads the
    hook JSON on stdin; FAIL-OPEN (always exit 0 — never block a session's exit)."""
    try:
        hook = _read_hook_stdin()
        branch = _worktree_branch_from_payload(hook)
        # REMOVE THE WORKTREE FIRST — Claude delegates removal to a configured hook and
        # only falls back to `git worktree remove` when none exists, so a hook that skips
        # this actively disables the removal that would otherwise have happened. Never
        # `--force`: bare `remove` refuses a dirty/untracked lane, which is the outcome we
        # want (Claude logs it as kept, the reaper surfaces it, no work is destroyed — P9).
        # This must precede `git branch -d`: a branch checked out in a live worktree cannot
        # be deleted, which is why an unremoved lane also stranded its branch and, in turn,
        # its coordination holds.
        wt = _worktree_path_from_payload(hook)
        # WI-0118: capture the lane's journal ids and its sidecar path BEFORE the removal.
        # Both are about to become unreadable — the ids live only on the branch and the
        # sidecar lives only inside the worktree — and they are what lets the teardown
        # close its own sessions instead of leaving them to age out over 7 days.
        lane_state = Path(wt.rstrip("/")) / ".session-state" if wt else None
        # Read the association from the LANE'S OWN sidecar, not from the branch diff —
        # see `lane_session_ids`: the branch answer is empty once the branch is merged,
        # which is the state this hook succeeds in.
        pre_evidence = lane_session_evidence(lane_state) if lane_state else {}
        pre_journals = lane_session_ids(lane_state, branch) if lane_state else (
            tuple(_lane_journal_ids(branch)) if branch else ())
        if wt:
            sh(["git", "worktree", "remove", wt], check=False)
            # The PROOF is the absence, not the command. `remove` refuses a dirty or
            # untracked lane by design, and on that path the directory is still there and
            # its session may still be running — closing on an attempted removal would
            # manufacture a death.
            if pre_journals and not Path(wt.rstrip("/")).exists():
                for sid, outcome in close_torn_down_lane_journals(pre_journals, pre_evidence):
                    print(f"worktree-remove: closed journal {sid} — {outcome}")
            # A pad-launched lane also has a generated pad beside the
            # operator's own. A pad outliving its lane is a launch surface aimed at a
            # deleted worktree — the orphan class this hook exists to prevent, one
            # level out. No-op for an ordinary member (no `pad_dir` declared).
            with contextlib.suppress(Exception):
                remove_lane_pad(Path(wt.rstrip("/")).name)
        # Prune stale worktree admin entries (also clears the lock of an already-gone dir).
        sh(["git", "worktree", "prune"], check=False)
        if not branch:
            sys.exit(0)
        trunk = _trunk() if CFG else "main"
        if branch in (trunk, f"origin/{trunk}") or not branch.startswith("worktree-"):
            sys.exit(0)
        if not _ref_exists(f"refs/heads/{branch}"):
            sys.exit(0)
        # WI-0123: read the lane's journal ids while the branch still exists — they are
        # the only link to the records it took through the main-anchored front door, and
        # the delete below destroys the one place they can be read from.
        # WI-0123's ids, now sourced where they can actually be read (see above). The
        # branch read stays as the fallback for a lane whose sidecar did not survive.
        lane_journals = pre_journals or tuple(_lane_journal_ids(branch))
        d = sh(["git", "branch", "-d", branch], check=False)
        if d.returncode == 0:
            # C4/C5: free the landed lane's claims now — by branch AND by journal.
            # WI-0298 / D6: ONE lane exit, and it is VERIFIED. The teardown sweep it
            # replaced freed only `COORD_KINDS`, so the dispatch slot survived every
            # teardown and the capacity it held stayed invisible to the next wave — and
            # WI-0312 then wired the other four routes to this same call. The verify half is
            # `a-close-is-the-banner-not-the-sentence`: the receipt that a teardown ran is
            # the store being empty of this lane's records, never the line we print.
            #
            # WI-0312: the epoch comes from the LANE's journals, never from this process's
            # own. `cmd_worktree_remove` is a hook running in the MAIN checkout's session,
            # so "when did my session end" is a question about the wrong session entirely —
            # and a teardown carrying the hook's clock would treat every record the lane
            # wrote as newer than its own occupancy and free nothing.
            ok, left = _lane_exit_verify(branch, journals=tuple(lane_journals),
                                         reason="teardown",
                                         epoch=_lane_exit_epoch(tuple(lane_journals)))
            print(f"worktree-remove: deleted merged lane branch {branch}")
            if not ok:
                names = ", ".join(f"{k}/{n}" for k, n in left)
                print(f"worktree-remove: WARNING — {branch} was torn down but these "
                      f"coordination records survived it: {names}. The next session in "
                      f"that lane will queue behind them as a foreign holder "
                      f"(WI-0298). Free them with `python3 session.py coord`.")
        else:
            # Unmerged -> the lane never landed. Leave it; its work is safe on the branch.
            print(f"worktree-remove: kept {branch} (not merged into {trunk}) — "
                  f"land it with `session.py merge --continue` from the lane, or `poga lanes --clean`.")
    except Exception:
        pass
    sys.exit(0)


def _lane_pad(lane: str) -> Path | None:
    """Where lane `<lane>`'s generated pad lives: a sibling of the operator's own pad,
    suffixed with the lane name (`architect` -> `architect-poga-1`). A sibling, so it
    is outside the repo like the pad it mirrors — the ADR-0027 §1 invariant."""
    pad = _main_pad()
    return None if pad is None else pad.parent / f"{pad.name}-{lane}"


def _lane_root(lane: str) -> Path | None:
    main = _main_checkout()
    return None if main is None else main / ".claude" / "worktrees" / lane


def build_lane_pad(lane: str) -> Path:
    """Materialize (or refresh) the launch pad for lane `<lane>`; return its path.

    Three files, and each is load-bearing:

      CLAUDE.md          -> symlink to THAT LANE's role doc, so the session comes up as
                            the Architect rather than the runtime persona.
      .claude/settings.json
                         -> the lane's own tracked settings with the harness prefix
                            REWRITTEN to reach the lane's `session.py`. This cannot be a
                            symlink: `session.py` resolves the repo it operates on from
                            its own file location, so hooks pointing at the main
                            checkout's copy would write every lane's journal, handoff and
                            commits into the MAIN checkout — the exact collision lanes
                            exist to prevent.
      .claude/settings.local.json
                         -> symlink to the operator's real one, so an
                            approval given in any lane is already granted everywhere and
                            nothing is re-approved per lane.
    """
    # Distinguish the preconditions: these messages are the entire diagnostic surface
    # for an operator whose `poga` just refused, so one catch-all blaming `pad_dir`
    # would send them editing a config that was already correct.
    if not _pad_dir_rel():
        raise RuntimeError("not a resident-runtime member: no `pad_dir` in session.config.json")
    pad, root, main_pad = _lane_pad(lane), _lane_root(lane), _main_pad()
    if pad is None or root is None or main_pad is None:
        raise RuntimeError("cannot locate the main checkout — is this a git repository?")
    if not root.is_dir():
        raise RuntimeError(f"lane worktree {root} does not exist — create the lane first")
    settings_rel = _settings_rel()
    if not settings_rel:
        raise RuntimeError(
            "no IN-REPO Architect settings declared: set `settings_path` to a "
            "repo-relative path (a pad-relative `../…` names the main pad, which a "
            "lane cannot share — its hooks must reach the lane's own harness)")
    src = root / settings_rel
    if not src.is_file():
        raise RuntimeError(f"{src} not found — seed the Architect settings in-repo first")

    # The RAW repo-relative role doc — CFG["role_doc"] is ROOT-joined and would point
    # at the main checkout's copy, which is the bug this whole path exists to avoid.
    role_doc = (CFG or {}).get("role_doc_rel") or "CLAUDE.md"
    pad.mkdir(parents=True, exist_ok=True)
    (pad / ".claude").mkdir(exist_ok=True)
    _relink(pad / "CLAUDE.md", root / role_doc)

    # Retarget the harness prefix: `../example-app` (pad -> main checkout) becomes
    # `../../example-app/.claude/worktrees/<lane>` (lane pad -> lane worktree), computed
    # rather than string-patched so it is right for any layout.
    old = _harness_dir_rel()
    new = os.path.relpath(root, pad)
    text = src.read_text(encoding="utf-8")
    if old != ".":
        text = text.replace(f"{PAD_ANCHOR}{old}/", f"{PAD_ANCHOR}{new}/")
    else:
        text = text.replace(PAD_ANCHOR, f"{PAD_ANCHOR}{new}/")
    atomic_write(pad / ".claude" / "settings.json", text)

    # The operator's permission file is a REAL file at one location; pads only link at
    # it. Created empty if absent so the link is never dangling.
    local = main_pad / ".claude" / "settings.local.json"
    if not local.exists():
        local.parent.mkdir(parents=True, exist_ok=True)
        atomic_write(local, "{}\n")
    _relink(pad / ".claude" / "settings.local.json", local)
    return pad


def remove_lane_pad(lane: str) -> Path | None:
    """Delete lane `<lane>`'s generated pad. Returns the path if one was removed.

    Refuses anything that is not the exact generated name beside the operator's own pad
    — a pad is disposable, the pad it mirrors is NOT, and this runs from teardown paths
    where a wrong answer deletes the Architect's real launch surface (P9)."""
    pad, main_pad = _lane_pad(lane), _main_pad()
    if pad is None or main_pad is None or not pad.is_dir():
        return None
    if pad.resolve() == main_pad.resolve() or pad.name == main_pad.name:
        return None
    shutil.rmtree(pad, ignore_errors=True)
    return pad


def cmd_lane_pad(args: argparse.Namespace) -> None:
    """Materialize / remove a lane's launch pad (for a member whose Architect launches
    from outside its repo). `poga` calls this; it prints
    the pad path on stdout so the wrapper can `cd` into it."""
    try:
        if args.remove:
            gone = remove_lane_pad(args.lane)
            print(f"lane-pad: removed {gone}" if gone else "lane-pad: nothing to remove")
            return
        print(build_lane_pad(args.lane))
    except RuntimeError as e:
        print(f"lane-pad: {e}", file=sys.stderr)
        sys.exit(2)


def _lanes_root() -> Path | None:
    """The `.claude/worktrees/` directory that holds the terminal poga lanes, anchored at
    the MAIN checkout. Computed from the shared common git dir (`<main>/.git`) so it
    resolves to the same pool whether the reaper runs from the main checkout or from
    inside a lane. Returns None if git cannot report the common dir."""
    r = sh(["git", "rev-parse", "--path-format=absolute", "--git-common-dir"], check=False)
    if r.returncode != 0 or not r.stdout.strip():
        return None
    return Path(r.stdout.strip()).resolve().parent / ".claude" / "worktrees"


def _registered_lanes(lanes_root: Path) -> dict:
    """Map lane-dir-name -> {path, branch, locked, lock_pid} for every git-registered
    worktree living under `lanes_root`, parsed from `git worktree list --porcelain`."""
    out: dict = {}
    r = sh(["git", "worktree", "list", "--porcelain"], check=False)
    if r.returncode != 0:
        return out
    cur: dict = {}

    def flush() -> None:
        p = cur.get("worktree")
        if not p:
            return
        path = Path(p).resolve()
        try:
            path.relative_to(lanes_root)
        except ValueError:
            return
        out[path.name] = {"path": path, "branch": cur.get("branch"),
                          "locked": cur.get("locked", False), "lock_pid": cur.get("lock_pid")}

    for line in r.stdout.splitlines():
        if not line.strip():
            flush()
            cur = {}
            continue
        if line.startswith("worktree "):
            cur["worktree"] = line[len("worktree "):].strip()
        elif line.startswith("branch "):
            ref = line[len("branch "):].strip()
            cur["branch"] = ref[len("refs/heads/"):] if ref.startswith("refs/heads/") else ref
        elif line == "locked" or line.startswith("locked "):
            cur["locked"] = True
            m = _LOCK_PID_RE.search(line)
            if m:
                cur["lock_pid"] = int(m.group(1))
    flush()
    return out


def _lane_branch_for(name: str, registered: dict) -> str | None:
    """The branch associated with lane dir `name`. Registered worktrees carry it in the
    worktree registry; unregistered residue is probed across the two known lane-naming
    schemes — poga's `worktree-<name>` and Claude Code's native `claude/<name>` — plus a
    bare `<name>`. Returns the first branch ref that exists, else None (no branch to
    lose: the dir is pure residue)."""
    reg = registered.get(name)
    if reg and reg.get("branch"):
        return reg["branch"]
    for cand in (f"worktree-{name}", f"claude/{name}", name):
        if _ref_exists(f"refs/heads/{cand}"):
            return cand
    return None


def _lane_commits_ahead_count(branch: str) -> str:
    """How many commits this lane holds that the trunk does NOT have, BY CONTENT.

    WI-0147, display half. `rev-list --count trunk..branch` counts by SHA reachability, so
    a lane whose work was recovered and landed elsewhere keeps reporting "2 commit(s) not
    on main" over commits whose patches are already there. The operator then either redoes
    landed work or learns to ignore the number — both bad. Returns a string because every
    call site prints it, and "?" is a real answer distinct from "0"."""
    if not branch:
        return "0"
    r = sh(["git", "cherry", _trunk(), branch], check=False)
    if r.returncode != 0:
        return "?"
    return str(sum(1 for ln in (r.stdout or "").splitlines() if ln.startswith("+")))


def _lane_work_is_on_trunk(branch: str, trunk: str) -> bool:
    """Is every commit on `branch` already on `trunk` — by CONTENT, not by SHA?

    WI-0147. `merge-base --is-ancestor` answers "is this branch reachable from the trunk",
    which is a different question and the wrong one after a rebase, a squash, or a
    cherry-pick recovery. A lane whose work was recovered into another lane and landed
    there has different SHAs carrying identical patches: its work IS on the trunk, and the
    old check called it `unmerged` forever. That is not merely a cosmetic mislabel — a lane
    that cannot be reaped keeps consuming the DISPATCH CAP, which is precisely what made
    D-4d41da spawn zero lanes on 2026-08-22.

    `git cherry` marks each commit `-` when an equivalent patch exists on the upstream and
    `+` when it does not, which is the content question asked directly. Fail-safe: any
    error, or output we cannot parse, returns False — the direction that keeps a lane
    rather than deleting one.
    """
    if sh(["git", "merge-base", "--is-ancestor", branch, trunk],
          check=False).returncode == 0:
        return True                                   # cheap path: genuinely reachable
    r = sh(["git", "cherry", trunk, branch], check=False)
    if r.returncode != 0:
        return False
    lines = [l for l in (r.stdout or "").splitlines() if l.strip()]
    if not lines:
        return True                                   # nothing on the branch at all
    return all(l.startswith("-") for l in lines)


def _scan_lanes() -> list[dict]:
    """Classify every terminal poga lane under `.claude/worktrees/` for the crash-safety
    reaper (ADR-0060 Q5). Each result carries {name, path, branch, status, registered,
    is_self, live_by}. `status`:

      - 'live'     — this session, or a registered+locked lane whose session pid is alive
                     on this machine, or a lane whose ADR-0054 heartbeat sidecar is
                     beating. NEVER touched. `live_by` names WHICH of the three said so
                     ('self' / 'worktree-lock' / 'heartbeat'), '' when not live — they are
                     three different kinds of evidence with three different coverages, and
                     a consumer that cannot tell them apart cannot state what its own
                     answer assumes
                     ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
      - 'reap'     — an orphan whose branch is merged into the trunk, or that has no
                     branch at all (pure directory residue). Safe to delete: no unlanded
                     work is lost.
      - 'young'    — would be 'reap', but the lane is inside the birth window and may
                     still be starting up (WI-0257). Held back by every sweep that
                     classifies THROUGH HERE — which is all of them: `_auto_reap_lanes`,
                     `reap-lanes`, `discard-phantom-lanes`. Named in the report rather
                     than dropped, and it ages into 'reap' on its own.
                     (`poga lanes --clean` is the one lane sweep that does NOT come
                     through this function — it re-derives merged-ness in bash and calls
                     `git branch -d`. It needs no age term: a lane being born HAS a
                     worktree, and git refuses to delete a branch checked out in one.
                     Probed 2026-09-05: `git branch -d` on a fresh `git worktree add -b`
                     branch exits 1, "cannot delete branch ... used by worktree at ...".
                     `-d` not `-D`, so an unmerged branch is refused too.)
      - 'unmerged' — an orphan carrying a branch NOT merged into the trunk. Surfaced
                     loudly; NEVER auto-reaped (never auto-discard, never auto-merge).

    'dirty' is the fifth: a 'reap' lane whose worktree holds uncommitted work (WI-0082)."""
    lanes_root = _lanes_root()
    if lanes_root is None or not lanes_root.is_dir():
        return []
    registered = _registered_lanes(lanes_root)
    self_path = None
    r = sh(["git", "rev-parse", "--show-toplevel"], check=False)
    if r.returncode == 0 and r.stdout.strip():
        self_path = Path(r.stdout.strip()).resolve()
    trunk = _trunk()

    names = set(registered)
    for child in lanes_root.iterdir():
        if child.is_dir():
            names.add(child.name)

    out: list[dict] = []
    for name in sorted(names):
        reg = registered.get(name)
        path = reg["path"] if reg else (lanes_root / name).resolve()
        is_self = self_path is not None and path == self_path
        # How long since anything happened in this lane's directory. The BIRTH-RACE guard
        # (session 90): a lane created seconds ago has not locked yet AND its branch is
        # trivially merged (it was just cut from the trunk), so it classifies 'reap' — a
        # sweep that ignored age would delete a sibling that is still starting up. An
        # active lane keeps touching its own dir, so it reads young and is skipped; an
        # abandoned one stops and ages into reapability. None = unreadable, treated as
        # young (cautious).
        try:
            age_min = (time.time() - path.stat().st_mtime) / 60.0
        except OSError:
            age_min = None
        live = is_self
        live_by = "self" if is_self else ""
        if not live and reg and reg.get("locked"):
            pid = reg.get("lock_pid")
            # Locked with a dead pid = the crash class (orphan). Locked with no parseable
            # pid = treat as live (cautious): refuse to reap what we can't prove is dead.
            live = pid is None or _pid_alive(pid)
            live_by = "worktree-lock" if live else ""
        if not live and _tree_has_live_session(path):
            # WI-0258. The worktree lock is CLAUDE'S evidence, not the substrate's: only
            # the native `claude --worktree` path takes one, and it is Claude that takes
            # it, not `poga`. The other two lane-creation paths — the off-repo launch
            # pad and any runtime with no worktree flag of its own (ADR-0082 D4: codex,
            # antigravity) — both go through `create_lane_worktree` and then
            # exec a runtime that never locks anything. Keying liveness on the lock alone
            # therefore reported those lanes free FOR THE WHOLE LIFE OF THE SESSION
            # sitting in them, which `lane-enterable` then answered as "yes, enter" — the
            # one thing the lane model cannot survive, on a path that is deliberately
            # supported rather than hypothetical (ADR-0041 multi-runtime membership).
            #
            # The ADR-0054 heartbeat is the runtime-AGNOSTIC evidence, and it already
            # exists for exactly these lanes: `poga`'s `prep_and_supervise` starts
            # `session.py supervise --detach` before it execs, and `_supervise_loop` beats
            # first and sleeps after, so the sidecar appears within a second or two of the
            # lane rather than one `SUPERVISE_INTERVAL_SEC` later.
            #
            # Read through `_tree_has_live_session` rather than re-implemented here (P16),
            # which also inherits its erring direction: an unreadable sidecar dir answers
            # True, i.e. "someone may be in there," which is the direction that declines to
            # reap and declines to enter. Widening `live` can only ever hold a lane BACK —
            # the reaper skips it, `recover-lanes` holds it with a reason, `lane-enterable`
            # refuses it — so no consumer of this function loses a safety property here.
            live = True
            live_by = "heartbeat"
        branch = _lane_branch_for(name, registered)
        # WI-0082: `merged` answers a question about COMMITS. It was being consumed as an
        # answer about WORK, and the working tree was never consulted at all — so a lane
        # whose branch was an ancestor of the trunk classified `reap` while holding
        # uncommitted edits, and the automatic sweep force-removed them. Probed only for a
        # REGISTERED worktree: pure directory residue is not a git worktree, `status` has
        # nothing to say about it, and it stays reapable exactly as before.
        dirty = bool(reg is not None and not live and _lane_is_dirty(path))
        if live:
            status = "live"
        elif branch is None:
            status = "reap"
        else:
            merged = _lane_work_is_on_trunk(branch, trunk)
            status = "reap" if merged else "unmerged"
        # Uncommitted work outranks a clean merge verdict, and never the reverse: an
        # `unmerged` lane is already protected, so this only ever holds back a lane the
        # old rule would have swept.
        if status == "reap" and dirty:
            status = "dirty"
        # WI-0257: the BIRTH-RACE guard, applied HERE so every consumer inherits it —
        # which is what `_auto_reap_lanes`'s docstring has claimed since session 90 while
        # the code applied it in the auto path alone. `cmd_reap_lanes` therefore ran with
        # NO age term at all, and a lane in its birth window is *maximally* reapable: the
        # directory exists, the branch is freshly cut from the trunk so trivially merged,
        # the tree is clean because nothing has run yet, and the child has not taken its
        # lock, so it is not live. Every predicate answers "safe" and every one of them is
        # reading a lane that is still being born.
        #
        # A SEPARATE STATUS, never a silent drop from 'reap'. Erasing the lane from the
        # report would be WI-0082's defect wearing a safer coat — an operator seeing a
        # lane simply absent cannot tell "reaped" from "spared" from "never seen"
        # ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
        if status == "reap" and _lane_too_young({"age_min": age_min}):
            status = "young"
        out.append({"name": name, "path": path, "branch": branch, "status": status,
                    "dirty": dirty,
                    "registered": reg is not None, "is_self": is_self,
                    "live_by": live_by,
                    "age_min": age_min,
                    # WI-0038 half two. Carried so the reaper can act on the lock rather
                    # than merely losing to it: a lane only reaches 'reap' while locked if
                    # its lock pid was PROVED dead just above (no pid, or a live pid, both
                    # classify 'live'), so a lock seen down there is always a corpse's.
                    "locked": bool(reg and reg.get("locked")),
                    "lock_pid": reg.get("lock_pid") if reg else None})
    return out


# ── WI-0172: the lane that is alive, quiet, and holding work nobody can reach ──────────
#
# There is no fourth STATUS here, deliberately. `_scan_lanes` answers "may a verb touch
# this lane", and for an idle-live lane the answer is still no — the session that owns it
# is running, and landing work out from under a quiet session is the exact harm the
# ADR-0054 grace exists to prevent (the session-74 false reap). Folding this into `dead`,
# or inventing a status that some future sweep might act on, would trade a reporting bug
# for a data-loss bug.
#
# What was missing was never a verdict. It was a ROW. The predicate has live / dead /
# unknown and this lane is genuinely `live`, so every surface correctly said nothing:
# `reap-lanes` printed "protected", `recover-lanes` printed "nothing stranded", and the
# startup banner dropped it from the output altogether. Three correct answers, and the
# work stayed unreachable for as long as the window stayed open — which is unbounded.
# It was found only because a peer session went looking at the branch by hand.
#
# So: the lane keeps its status, no verb gains a new power, and the invisibility — which
# is the actual harm — is what gets removed
# ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes): the
# fix for a missing answer is a distinct answer, never a silent drop).


def _lane_last_beat_age_min(path: Path) -> float | None:
    """Minutes since the FRESHEST heartbeat any session ever wrote in lane `path`, or
    None when the lane holds no readable beat at all.

    The freshest, not the oldest: a lane is reused across sessions and holds one sidecar
    per session that ever ran there, so "how long has this lane been quiet" is answered by
    the most recent beat in it — an old sidecar from a session that finished months ago
    says nothing about the session sitting there now.

    Read through `_sidecar_evidence_by_csid` rather than parsed here (P16): the rules for
    what counts as a beat, and how its age is computed, must not fork between the reaper
    and this. `.ended` / `.gone` markers are deliberately NOT consulted — this measures
    silence, not death, and the death question already has `_lane_death_verdict`.

    None means "no measurement exists", which is a different thing from "silent a long
    time" and is reported as such by every caller rather than being rounded into it.
    Never raises: an unreadable sidecar returns None, so the advisory degrades to a row
    that states it has no duration instead of a row asserting a duration it cannot see."""
    try:
        state = path / ".session-state"
        if not state.is_dir():
            return None
        ages = []
        for f in sorted(state.glob("*.live")):
            age = _sidecar_evidence_by_csid(f.stem, state_dir=state)["beat_age_min"]
            if age is not None:
                ages.append(age)
        return min(ages) if ages else None
    except Exception:
        return None


def _idle_live_lanes(lanes: list[dict]) -> list[dict]:
    """The WI-0172 advisory set: lanes that are LIVE, silent past
    `LANE_IDLE_ADVISORY_MIN`, and holding commits the trunk does not have.

    Returns the `_scan_lanes` dicts with two fields added — `silent_min` (float, or None
    when no beat is readable) and `ahead` (the commit count as a string, including
    `_lane_commits_ahead_count`'s own "?"). Rows to print; nothing here acts, and no
    caller of this may act on the result without re-arguing the safety case above.

    ORDERED CHEAPEST-FIRST, and that ordering is the P19 term: the git question — two
    subprocesses per lane — is asked only of a lane that has already passed three free
    tests. In the common case (every live lane is beating) the loop costs one `glob` per
    lane and no git at all, which is what makes it affordable on the startup path.

    WHICH LANES CAN EVEN REACH THE GIT CALL is worth stating, because it is narrower than
    "live": a lane is `live` by one of three evidences, and two of them exclude themselves
    here. `self` is this session — its own unlanded work is work in progress, not a
    stranding, the same exclusion `_stranded_lane_lines` already makes. `heartbeat` means
    a beat inside HEARTBEAT_STALE_MIN (15m), which cannot also be silence past 120m —
    except in the one case `_tree_has_live_session` errs True on an unreadable sidecar,
    where declining to advise is the right direction (do not narrate a lane you cannot
    read). That leaves `worktree-lock`: a live pid with a stopped heartbeat, which is
    precisely the observed state — poga-2, its pid alive, last beat twelve minutes after
    launch, two commits, still unreachable hours later."""
    trunk = _trunk()
    out: list[dict] = []
    for l in lanes:
        if l.get("status") != "live" or l.get("is_self"):
            continue
        if (l.get("live_by") or "") in ("self", "heartbeat"):
            continue
        branch = l.get("branch")
        if not branch or not l.get("path"):
            continue
        age = _lane_last_beat_age_min(Path(str(l["path"])))
        if age is not None and age <= LANE_IDLE_ADVISORY_MIN:
            continue
        if _lane_work_is_on_trunk(branch, trunk):
            continue
        out.append({**l, "silent_min": age, "ahead": _lane_commits_ahead_count(branch)})
    return out


def _idle_live_lane_note(l: dict, index: dict | None = None) -> str:
    """The one sentence every surface prints about an idle-live lane (P16).

    WI-0157 put the lane's DURABLE identity in front and demoted the slot to the bracket
    beside it. `index` is the caller's `lane_claim_index()` when it is rendering more
    than one row, so a listing reads the claim store once rather than once per lane.

    Three surfaces report this state and they must not drift into describing it
    differently — an operator who reads `reap-lanes`, `recover-lanes` and the startup
    banner in the same minute is holding three views of one lane, and WI-0140 is the
    record of what it costs when those views use different vocabulary for the same fact.

    The silence term says `no heartbeat ever recorded` rather than a number when there is
    no beat to measure. A lock-live lane whose sidecar was never written is the same harm
    — work held where nothing can reach it — but "silent 0.0h" would be a fabricated
    measurement, and a report that invents its own evidence is worse than one that admits
    the gap ([`capture-the-probe`](habits/master.md#capture-the-probe))."""
    silent = (f"silent {l['silent_min'] / 60:.1f}h"
              if l.get("silent_min") is not None else "no heartbeat ever recorded")
    return (f"{lane_identity(l, index)} [{l['name']}] — "
            f"LIVE ({l.get('live_by') or 'unknown evidence'}) but {silent}: "
            f"{l['ahead']} commit(s) not on {_trunk()}, branch {l['branch']}")


def _idle_live_lane_advice() -> list[str]:
    """The routing half of the advisory — what a reader can actually DO about these lanes.

    Every line here is executable by the person reading it, which is the ADR-0099 D3 / RC2
    rule this file has been corrected against twice already (WI-0122's instruction to a
    session that no longer existed; WI-0158's `git -C <lane>` the runtime guard refuses).
    A session is sitting in each of these lanes, so the routes are: ask it, or wait it out.
    There is deliberately no command here that lands the lane from outside — that would be
    the land this whole design refuses to perform under a live session, and WI-0141 /
    WI-0099 own the larger question of a verb that asks the owning session's consent.

    ONE block with a `<lane>` placeholder, not one per row — the shape the four other
    held-back blocks in `cmd_reap_lanes` already use. Repeating six lines per lane would
    bury the rows themselves, which are the part that carries the new information."""
    return [
        "    A session is in each of these right now, so nothing here will touch them —",
        "    that is the safety property, not a failure. The work is its OWNER's to land:",
        "    From inside it:  cd <lane> && python3 session.py merge   (the sanctioned",
        "                     cross-lane form, and the only route while the session lives)",
        "    Once it closes:  python3 session.py recover-lanes --lane <name>   — lands it",
        "                     as soon as that session is provably over.",
        "    Until then the row above is the whole report, deliberately.",
    ]


def _gate_worktree_residue() -> list[Path]:
    """Registered scratch worktrees left behind by gate runs that died before cleanup
    (WI-0063), old enough that no live run could own them.

    **Driven from `git worktree list`, never from a filesystem glob, and that is the whole
    safety argument.** `session.py` is byte-identical fleet substrate, so `fed-gate-`
    directories from every member sit in the SAME temp directory —
    one was observed appearing there mid-cleanup on 2026-07-30. A sweeper that globbed the
    prefix would delete another repo's in-flight gate run and fail its land. `git worktree
    list` answers only for the repo it is run in, so a foreign gate is not merely skipped,
    it is never visible in the first place.

    The age guard covers the remaining case — a concurrent land *in this repo* — since our
    own live gate worktree is minutes old at most. Unknown age reads as young: refuse to
    reap what cannot be proved stale, the same rule `_lane_too_young` applies.

    Never raises; returns [] on any git or filesystem error."""
    out: list[Path] = []
    try:
        r = sh(["git", "worktree", "list", "--porcelain"], check=False)
        if r.returncode != 0:
            return []
        repo = ROOT.resolve()
        cutoff = time.time() - GATE_REAP_MIN_AGE_MIN * 60
        for block in (r.stdout or "").split("\n\n"):
            line = next((l for l in block.splitlines()
                         if l.startswith("worktree ")), None)
            if not line:
                continue
            path = Path(line[len("worktree "):].strip())
            # The scratch tree is `<tmp>/fed-gate-XXXX/wt`; match on the PARENT so a
            # user's own directory that merely starts with the prefix is not caught.
            if not path.parent.name.startswith(GATE_WORKTREE_PREFIX) or path.name != "wt":
                continue
            inside_repo = True
            try:
                path.resolve().relative_to(repo)
            except ValueError:
                inside_repo = False
            if inside_repo:
                continue                     # a real worktree in the repo — never residue
            try:
                if path.exists() and path.parent.stat().st_mtime >= cutoff:
                    continue                 # young enough that a live gate may own it
            except OSError:
                continue                     # unknown age reads as young
            out.append(path)
    except Exception:
        return []
    return out


def _reap_gate_worktrees() -> list[str]:
    """Remove the gate residue `_gate_worktree_residue` found. Returns report lines.

    `--force` is correct HERE and would be wrong one class over. A gate worktree is a
    detached checkout of a candidate commit that nothing ever authors into — the normal
    cleanup path already removes it with `--force`, and its only "dirt" is build output
    the run itself produced. That is the opposite of a LANE, where `--force` is what turned
    every classification mistake into destroyed work (WI-0082) and was removed for exactly
    that reason. Same flag, different class; the distinction is what makes it safe."""
    lines: list[str] = []
    for wt in _gate_worktree_residue():
        r = sh(["git", "worktree", "remove", "--force", str(wt)], check=False)
        if r.returncode == 0:
            lines.append(f"  freed leaked gate worktree {wt.parent.name}")
            with contextlib.suppress(Exception):
                shutil.rmtree(wt.parent, ignore_errors=True)
        else:
            lines.append(f"  gate worktree remove FAILED for {wt}: "
                         f"{(r.stderr or r.stdout).strip()}")
    if lines:
        sh(["git", "worktree", "prune"], check=False)
    return lines


def _checkpoint_lane_work(session_id: str) -> str | None:
    """ADR-0089 D1: commit a lane's uncommitted work as an identifiable checkpoint.
    Returns the subject on success, None when there was nothing to do or anything failed.

    Only ever called from a worktree lane. FAIL-OPEN and quiet: this rides the SessionEnd
    path, whose whole contract is that it cannot delay or break an exit
    ([ADR-0054](adr/0054-heartbeat-on-tool-use-and-crash-reap-grace.md)) — a checkpoint
    that cannot be written must lose to the exit, every time.

    `add -A` is correct here and not merely convenient: one member's loss included files
    that had never been `git add`ed, so a checkpoint that staged only tracked changes
    would preserve exactly the wrong half. The lane's `.gitignore` still applies, so
    `.session-state/` and other ignored state stay out. `SWEEP_ADD` also drops Python
    bytecode where that `.gitignore` forgets to (WI-0461): a checkpoint is squashed into
    the close, so bytecode staged here would reach the trunk.
    """
    try:
        if not _lane_is_dirty(ROOT):
            return None
        subject = f"{CHECKPOINT_PREFIX} session {session_id} stopped with uncommitted work"
        if sh(SWEEP_ADD, check=False).returncode != 0:
            return None
        body = ("Written by `session.py record-end` (ADR-0089 D1) because this session\n"
                "stopped without landing. This is NOT a close: no `ended` stamp, no\n"
                "journal body, and the session still reads as flown-not-landed.\n"
                "\n"
                "It dissolves on resume (`git reset --soft HEAD^`, restoring the working\n"
                "tree exactly as it was) and is squashed into the close if the lane is\n"
                "landed without ever being resumed.")
        r = sh(["git", "commit", "-q", "-m", subject, "-m", body], check=False)
        return subject if r.returncode == 0 else None
    except Exception:
        return None


def _dissolve_lane_checkpoint() -> bool:
    """ADR-0089 D2: undo a checkpoint when its session resumes, leaving the working tree
    byte-for-byte as the operator left it.

    `--soft` ONLY. It moves the branch ref and leaves both the index and the working tree
    untouched, which is the entire point — the operator's uncommitted state comes back
    uncommitted. (`reset --hard`/`--keep` stay denied by the destructive-git guard; this
    is deliberately the one reset shape that cannot lose work.)

    Refuses when the checkpoint is the branch's ONLY commit — there is no parent to reset
    to, and a lane whose whole history is one checkpoint is a case for a human to look at
    rather than for the substrate to unpick. Fail-open throughout.
    """
    try:
        if not _on_worktree_lane() or not _head_is_checkpoint():
            return False
        if sh(["git", "rev-parse", "--verify", "-q", "HEAD^"], check=False).returncode != 0:
            return False
        return sh(["git", "reset", "--soft", "HEAD^"], check=False).returncode == 0
    except Exception:
        return False


def _stranded_lane_lines() -> list[str]:
    """ADR-0089 D3: orientation lines naming lanes that hold work the trunk does not.

    Two classes, reported separately because the resolution differs and folding them into
    one count would hide that ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)):
    `unmerged` — commits not on the trunk, resolved by landing; `dirty` — uncommitted
    files in the worktree, resolved by committing them first. A lane can be both, and is
    reported as unmerged since that is the outer of the two.

    Reports only; resolving stranded work stays a human call (P9). Excludes this session's
    own lane — a live session's dirty tree is work in progress, not a stranding. Silent
    when there is nothing to say, and fail-open: a start must never break on this.

    A LANE WITH A LIVE SESSION IN IT IS NOT STRANDED (session ~129). The exclusion above
    was `is_self` only, so it covered the session reading the banner and nothing else —
    every OTHER session running concurrently was reported to it as stranded litter.
    Under parallel lanes that is the common case, not the edge one: a sibling writes its
    journal at first heartbeat and holds it uncommitted for the whole session, so it is
    `dirty` from the moment it starts until the moment it lands. Session ~129 found
    every lane start raising this false alarm. Reported live was
    poga-6, whose heartbeat was twenty seconds old.

    Live lanes are still NAMED, on their own `active:` line — the alarm was false, the
    information is not ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes):
    the fix is a distinct answer, never a silent drop). `_tree_has_live_session` is the
    same evidence rule used to decide whether the trunk views may be rewritten, reused
    rather than re-derived (P16); it errs toward "live" on an unreadable sidecar, which
    here means erring toward *not* crying stranded, the harmless direction.
    """
    try:
        if _lanes_root() is None:
            return []
        lanes = [l for l in _scan_lanes() if not l["is_self"]]
    except Exception:
        return []
    # Bound BEFORE the filtering below rebinds `lanes` twice: the WI-0172 advisory is the
    # one reader here that cares about lanes the `live` split removes.
    _scan_lanes_self_excluded = list(lanes)
    live = [l for l in lanes if _tree_has_live_session(Path(l["path"]))]
    lanes = [l for l in lanes if l not in live]
    unmerged = [l for l in lanes if l["status"] == "unmerged"]
    dirty = [l for l in lanes if l["status"] == "dirty"]
    # A dead lane whose ONLY uncommitted file is an empty session stub is holding
    # NOTHING (session ~129). `_lane_holds_only_phantom_debris` proves the body never
    # left the stub form, which is the same evidence on which the reaper already deletes
    # a phantom journal outright as a non-event. Reported on its own line rather than
    # under "resume or discard is your call" — there is nothing to resume, and calling it
    # stranded work is what made an empty lane look like an obligation.
    phantom, dirty = ([l for l in dirty if _lane_holds_only_phantom_debris(l)],
                      [l for l in dirty if not _lane_holds_only_phantom_debris(l)])
    # WI-0172, and this surface is where the invisibility was TOTAL. A pid-live but
    # heartbeat-silent lane is not `unmerged` and not `dirty` (its status is `live`), and
    # `_tree_has_live_session` is false for it (that reads the heartbeat, which stopped),
    # so it fell out of `live` too and appeared on no line at all — not even the `active:`
    # one. The banner is the list a session actually reads, so a state that no verb will
    # act on has to at least arrive here.
    idle_live = _idle_live_lanes(_scan_lanes_self_excluded)
    # WI-0157: every line below names a lane by its DURABLE identity and carries the slot
    # in brackets, because the slot is the address the routing half tells a reader to
    # type. One read of the claim store serves the whole banner.
    # LAZY on purpose: `lane_claim_index` reaches the coordination store through
    # `_git_common_dir`, which spawns a subprocess (~31ms measured). The early return
    # below is the common case on a healthy machine, and it must not pay for a join it
    # never uses.
    _ix: list = []
    def _id(l):
        if not _ix:
            _ix.append(lane_claim_index())
        return f"{lane_identity(l, _ix[0])} [{l['name']}]"
    if not unmerged and not dirty and not phantom and not idle_live:
        return ([f"active:  {len(live)} lane(s) with a live session — "
                 f"{', '.join(_id(l) for l in live)}."] if live else [])
    lines = []
    if live:
        lines.append(f"active:  {len(live)} lane(s) with a live session (not stranded) — "
                     f"{', '.join(_id(l) for l in live)}.")
    for l in idle_live:
        if not _ix:
            _ix.append(lane_claim_index())
        lines.append(f"idle:    {_idle_live_lane_note(l, _ix[0])}. Its own session must land it; "
                     f"`recover-lanes --lane {l['name']}` once that session is over.")
    for l in unmerged:
        lines.append(f"stranded: {_id(l)} — commits NOT on {_trunk()} (branch {l['branch']}). "
                     f"Land it: cd {l['path']} && python3 session.py merge")
    for l in dirty:
        # WI-0158 / ADR-0099 D4. This line used to end *"Inspect: git -C {path} status"* —
        # refused by the RUNTIME's worktree-isolation guard in the reading lane, which denies
        # a git call
        # aimed at another working tree whatever the syntax used to reach it. It was also
        # inconsistent with its own neighbour two lines up, which has printed the
        # sanctioned cross-lane form (`cd <lane> && python3 session.py <verb>`) for the
        # unmerged case all along: the same function knew the rule and broke it one line
        # later, which is why RC2 needs a lint and not a memo.
        #
        # No read-only verb answers "what is uncommitted in that lane" from outside it —
        # `lane-enterable` reports a lane's STATUS but not its contents, `recover-lanes`
        # acts only on `unmerged` lanes and so never sees this one, and `main-status`
        # answers about the main checkout. So the route is the one `cmd_reap_lanes`
        # already sanctions for the identical case: ENTER the lane. `poga resume` is gated
        # by `lane-enterable`, so a lane that must not be entered refuses with its reason
        # rather than being silently shared by two sessions.
        lines.append(f"stranded: {_id(l)} — UNCOMMITTED files in the worktree. "
                     f"Inspect: poga resume {l['name']}. Entering the lane is the "
                     f"sanctioned route; there is no read-only lane-inspect verb.")
    for l in phantom:
        lines.append(f"empty:   {_id(l)} — an abandoned lane holding only an empty "
                     f"session stub. Nothing to recover; discard when convenient.")
    if unmerged or dirty:
        lines.append("stranded: resume or discard is your call — nothing here is swept "
                     "automatically (ADR-0089 D3).")
    return lines


def _lane_holds_only_phantom_debris(lane: dict) -> bool:
    """True iff `lane`'s uncommitted files are nothing but empty session stubs.

    A session writes its journal at its first heartbeat and holds it uncommitted until
    it closes ([ADR-0055](adr/0055-lazy-session-start.md)). A session that opened and
    did nothing therefore leaves a lane that is permanently `dirty` over a file whose
    body never left `### What happened\\n\\n- Session opened.` — and because the file is
    UNTRACKED IN A LANE, the reaper never sees it: it walks the journals it can reach,
    and a lane's uncommitted file is not one of them. So the one piece of debris the
    reaper is explicitly allowed to delete as a non-event is the one piece it structurally
    cannot reach, and it nags at every start instead (poga-5, session ~129 — an abandoned
    `codex` lane, `.gone` marker, stub body, reported as stranded work for hours).

    Conservative by construction, in the direction that cannot lose work: ANY untracked
    or modified path that is not a stub journal, and ANY journal whose body carries real
    narrative, disqualifies the lane and it stays `stranded`. Reuses
    `_journal_is_unauthored` — the same predicate the reaper's phantom rule and the close
    guard use (P16) — rather than a second definition of "empty" that could disagree with
    it. That call was `_is_stub_body` until WI-0377: byte-exactness is defeated by the
    single line `_journal_note` files under `### Notes filed`, so any lane whose session
    opened in a checkout holding authored work was disqualified by the harness's own
    bookkeeping and stayed reported forever.
    """
    try:
        # `-uall` is load-bearing: bare `--porcelain` COLLAPSES a wholly-untracked
        # directory to one `?? sessions/` entry, which is not a file and would fail the
        # is-it-a-stub-journal test — so a genuinely empty lane stayed reported whenever
        # its journal dir was itself new. Ask for every path, then judge each one.
        r = sh(["git", "-C", str(lane["path"]), "status", "--porcelain", "-uall"],
               check=False)
        if r.returncode != 0:
            return False                       # can't tell → not phantom → stays reported
        entries = [ln[3:].strip() for ln in (r.stdout or "").splitlines() if ln.strip()]
        if not entries:
            return False
        for rel in entries:
            p = Path(lane["path"]) / rel
            jdir = layout_of(CFG_RAW, "journal_dir")
            if not (rel.startswith(jdir) and rel.endswith(".md")) or not p.is_file():
                return False
            _fm, body = parse_journal(p.read_text(encoding="utf-8"))
            if not _journal_is_unauthored(body):
                return False
        return True
    except Exception:
        return False                           # unknown is never "safe to ignore"


def _lane_commits_are_only_phantom_debris(lane: dict) -> bool:
    """True iff every commit `lane` holds ahead of the trunk touches nothing but empty
    session stubs — the COMMITTED sibling of `_lane_holds_only_phantom_debris`.

    The uncommitted form above catches a lane that opened and died. It misses the one
    that opened, died, and got **checkpointed on the way out**: the `Stop` hook's
    `wip(checkpoint): session … stopped with uncommitted work` commit turns exactly the
    same nothing into an UNMERGED branch, which reads as stranded work forever. Both of
    the federation's remaining orphans were this (session ~134): `poga-8` from 08-08 and
    `poga-1` from a later day, each holding one commit whose entire content is a journal whose
    body never left `- Session opened.`

    That is why the reaper's own advice for these lanes was `git branch -D` — a force
    branch delete, which `check-bash` denies as destructive, correctly. The way out of a
    guard that is right to refuse is never an exception to it: it is a verb whose
    PREDICATE carries the safety argument, so the destructive act is only reachable
    where it is provably a non-event.

    Conservative in the direction that cannot lose work, like its sibling: any commit
    touching any path that is not a journal, or any journal whose body at the branch tip
    carries real narrative, disqualifies the lane — as does any git error, since an
    unreadable history must never read as "safe to delete"."""
    try:
        branch = lane.get("branch")
        if not branch:
            return False
        # `-C` the LANE, always. Without it these run against the process cwd, which in
        # the federation happens to share an object store with the lane and so gives the
        # right answer for the wrong reason — the identical cwd-relative defect this
        # session fixed in `_main_checkout`, reintroduced ten minutes later. A question
        # about a lane must be asked AT that lane.
        g = ["git", "-C", str(lane["path"])]
        # WI-0147: ask which commits are ahead BY CONTENT, not by SHA reachability.
        # `git cherry` marks `-` where an equivalent patch already exists on the trunk and
        # `+` where it does not. A lane whose work was recovered into another lane and
        # landed there carries different SHAs for identical patches; walking `trunk..branch`
        # counts those as work still held, so the lane reads "holds real work" forever and
        # no verb will retire it. It then keeps consuming the DISPATCH CAP — the exact
        # mechanism that made D-4d41da spawn zero lanes on 2026-08-22.
        r = sh(g + ["cherry", f"refs/heads/{_trunk()}", f"refs/heads/{branch}"], check=False)
        if r.returncode != 0:
            return False
        shas = [ln.split()[1] for ln in (r.stdout or "").splitlines()
                if ln.startswith("+") and len(ln.split()) > 1]
        if not shas:
            return False                        # nothing ahead — not this function's case
        jdir = layout_of(CFG_RAW, "journal_dir")
        touched: set[str] = set()
        saw_debris = False
        for sha in shas:
            f = sh(g + ["show", "--pretty=", "--name-only", sha], check=False)
            if f.returncode != 0:
                return False
            for rel in (f.stdout or "").splitlines():
                rel = rel.strip()
                if not rel:
                    continue
                # `.session-state/` is the harness's own liveness sidecar — heartbeats,
                # `.live`, `.ended`. It is gitignored BY DESIGN and carries no authored
                # content ever. Where a member tracks it (one has no ignore entry;
                # another committed the files before adding one), every session
                # commits heartbeat bumps, and a stop-checkpoint turns that into an
                # unmerged branch that reads as stranded WORK. One member's entire red lane was
                # one `.live` and one `.ended` file. Treating it as debris is not a
                # loosening: a commit touching only these paths cannot contain anything
                # a human wrote. The tracking itself is still a defect (WI-0113) — this
                # stops it manufacturing a red lane per session in the meantime.
                if rel.startswith(".session-state/"):
                    saw_debris = True
                    continue
                if not (rel.startswith(jdir) and rel.endswith(".md")):
                    return False                # touched something that is not a journal
                touched.add(rel)
        if not touched and not saw_debris:
            return False
        for rel in touched:
            # The body AT THE BRANCH TIP is what matters — an intermediate revision of a
            # journal that later gained narrative must not read as a stub.
            b = sh(g + ["show", f"refs/heads/{branch}:{rel}"], check=False)
            if b.returncode != 0:
                return False
            _fm, body = parse_journal(b.stdout)
            if not _journal_is_unauthored(body):
                return False
        return True
    except Exception:
        return False                            # unknown is never "safe to delete"


def _lane_journals_are_superseded_on_trunk(lane: dict) -> bool:
    """True iff every journal the lane's unmerged commits touch is ALREADY CLOSED on the
    trunk — same session-id, carrying an `ended` stamp.

    The third litter shape, and the least obvious. A lane can hold a journal that is not
    a stub — real narrative, so the phantom predicate rightly refuses it — while the
    trunk already carries the FINISHED version of that same session, stamped and longer.
    The lane's copy is an intermediate snapshot that was superseded and never cleaned up.
    Read from the lane it looks exactly like unlanded work; read from the trunk there is
    nothing missing at all.

    A member's poga-5 was this (session ~134) and it cost a wrong write before it produced the
    insight: the board's FALSE CLOSE led to opening the lane, finding 145 lines of real
    narrative, and committing it as a rescue — without first asking whether the trunk
    already had it. It did, stamped, with six hours of duration on it. The check that
    would have prevented the write is the same one that makes deletion provably safe,
    which is why it belongs in code rather than in a resolution to be more careful
    ([`probe-live-state-before-acting-on-a-report`]).

    Fail-closed throughout: a journal missing from the trunk, one present but still open,
    a commit touching any non-journal path, or any git error, all disqualify the lane."""
    try:
        branch = lane.get("branch")
        if not branch:
            return False
        g = ["git", "-C", str(lane["path"])]
        rng = f"refs/heads/{_trunk()}..refs/heads/{branch}"
        r = sh(g + ["log", "--format=%H", rng], check=False)
        if r.returncode != 0:
            return False
        shas = [s for s in (r.stdout or "").split() if s]
        if not shas:
            return False
        jdir = layout_of(CFG_RAW, "journal_dir")
        touched: set[str] = set()
        for sha in shas:
            f = sh(g + ["show", "--pretty=", "--name-only", sha], check=False)
            if f.returncode != 0:
                return False
            for rel in (f.stdout or "").splitlines():
                rel = rel.strip()
                if not rel:
                    continue
                if not (rel.startswith(jdir) and rel.endswith(".md")):
                    return False
                touched.add(rel)
        if not touched:
            return False
        for rel in touched:
            t = sh(g + ["show", f"refs/heads/{_trunk()}:{rel}"], check=False)
            if t.returncode != 0:
                return False                    # not on the trunk at all — real work
            fm, _body = parse_journal(t.stdout)
            if not (fm.get("ended") or "").strip():
                return False                    # on the trunk but still open
        return True
    except Exception:
        return False


def _lane_adds_nothing_the_trunk_lacks(lane: dict) -> bool:
    """True iff every path `lane` touches ahead of the trunk is either a GENERATED view or
    already byte-identical on the trunk — so deleting the branch discards no content.

    The third phantom shape, and the one the other two cannot see. Both of them ask what a
    lane's commits CONTAIN (an empty stub, a superseded journal). This one asks what they
    CONTRIBUTE, which is a different question with a different answer for a lane whose real
    work reached the trunk by another route. Session ~174's `poga-4` was exactly that: its
    24 substantive commits were cherry-picked into a sibling lane and landed from there, and
    what stayed behind was nine `recompile views and stamp STATUS` commits plus two commits
    that wrote work-item files whose bytes the trunk already had. Nothing empty, nothing
    superseded, nothing worth keeping — and no predicate could say so, so the substrate's
    own advice was `git branch -D`, which `check-bash` denies as destructive, correctly.
    The way out of a guard that is right to refuse is a verb whose PREDICATE carries the
    safety argument (WI-0141).

    THREE VERDICTS PER PATH, and the middle one is why this is not a tree comparison:

      * a generated view          -> ignored. `_recompile_main_checkout` rewrites these from
                                     the journals at every land, so a stale copy on a branch
                                     is not content, it is a snapshot of an older render.
      * absent on BOTH sides      -> ignored. A commit that deleted a file the trunk also no
                                     longer has (usually because the trunk RENAMED it) has
                                     nothing left to contribute.
      * present on both, and equal -> ignored. Present on one side only, or differing ->
                                     the lane holds something, and the answer is False.

    Conservative in the only direction that cannot lose work, like its siblings: any git
    error, any unreadable path, any difference at all disqualifies the lane. A history that
    cannot be read must never read as safe to delete."""
    try:
        branch = lane.get("branch")
        if not branch:
            return False
        # `-C` the LANE. A question about a lane is asked at that lane — and for a
        # branch-only orphan `path` is deliberately the repo root, which shares the object
        # store and so answers about the same refs.
        g = ["git", "-C", str(lane["path"])]
        trunk = _trunk()
        # BY CONTENT, not by sha reachability, for `_lane_commits_are_only_phantom_debris`'s
        # reason: a lane whose patches landed from a SIBLING carries different shas for
        # identical work, and `trunk..branch` would call all of it unlanded forever. That is
        # precisely this predicate's own motivating case.
        r = sh(g + ["cherry", f"refs/heads/{trunk}", f"refs/heads/{branch}"], check=False)
        if r.returncode != 0:
            return False
        shas = [ln.split()[1] for ln in (r.stdout or "").splitlines()
                if ln.startswith("+") and len(ln.split()) > 1]
        if not shas:
            return False                        # nothing ahead — not this function's case
        views = _generated_view_names()
        touched: set[str] = set()
        for sha in shas:
            f = sh(g + ["show", "--pretty=", "--name-only", sha], check=False)
            if f.returncode != 0:
                return False
            for rel in (f.stdout or "").splitlines():
                rel = rel.strip()
                if rel:
                    touched.add(rel)
        if not touched:
            return False                        # commits touching nothing: not this case
        for rel in sorted(touched):
            if rel.rsplit("/", 1)[-1] in views:
                continue
            a = sh(g + ["show", f"refs/heads/{branch}:{rel}"], check=False)
            b = sh(g + ["show", f"refs/heads/{trunk}:{rel}"], check=False)
            if a.returncode != 0 and b.returncode != 0:
                continue                        # gone from both — nothing to contribute
            if a.returncode != 0 or b.returncode != 0:
                return False                    # one side has it: that IS content
            if a.stdout != b.stdout:
                return False
        return True
    except Exception:
        return False


def cmd_discard_phantom_lanes(args: argparse.Namespace) -> None:
    """Delete lanes that provably hold nothing — and refuse everything else by name.

    The reaper sweeps MERGED lanes (their work is on the trunk, so removal is safe by
    construction) and deliberately leaves unmerged ones alone (ADR-0089 D3: nothing
    stranded is swept automatically). A committed phantom falls between those: it is
    unmerged, so the reaper will not touch it, and it holds nothing, so no one ever wants
    to land it. It therefore accumulates — reported at every single session start, by a
    substrate whose own advice is a command its own guard denies.

    This verb exists so that the destructive act is reachable ONLY where
    `_lane_commits_are_only_phantom_debris` proves it is a non-event. It is deliberately
    NOT folded into `reap-lanes`: reaping a merged branch and force-deleting an unmerged
    one are different risk classes, and an operator running the routine sweep should never
    silently get the second one.

    A lane inside the birth window is refused outright (WI-0257), ahead of every predicate.
    It used to be missed rather than refused — a newborn has no commits ahead and a clean
    tree, so all four phantom predicates answered False and it fell out of both lists
    unmentioned. Correct outcome, no reasoning behind it, and nothing said."""
    if _lanes_root() is None:
        print("discard-phantom-lanes: no lanes directory — nothing to do.")
        return
    # `is_self` and a live heartbeat are BOTH excluded: this verb force-deletes a branch,
    # so the one thing it must never reach is a lane someone is working in. Same evidence
    # rule as the stranded reporter (P16), and it errs toward "live" on an unreadable
    # sidecar — here that means erring toward not deleting, the harmless direction.
    lanes = [l for l in _scan_lanes()
             if not l["is_self"] and not _tree_has_live_session(Path(l["path"]))]
    # BRANCH-ONLY ORPHANS. A lane whose worktree is already gone leaves its branch
    # behind, and `_scan_lanes` walks worktrees — so the residue that OUTLIVES a teardown
    # is exactly the residue this verb could not see. One member carried two (session ~134),
    # each a `worktree-poga-N` branch holding one stub-journal commit and no directory.
    # Synthesised with the lane's own path so the predicate's `git -C` still resolves;
    # the repo root is the right place to ask about a branch whose tree no longer exists.
    seen = {l["branch"] for l in lanes}
    checked_out = set()
    wt = sh(["git", "-C", str(ROOT), "worktree", "list", "--porcelain"], check=False)
    for ln in (wt.stdout or "").splitlines():
        if ln.startswith("branch "):
            checked_out.add(ln.split("/", 2)[-1].strip())
    br = sh(["git", "-C", str(ROOT), "for-each-ref", "--format=%(refname:short)",
             "refs/heads/"], check=False)
    for ref in (br.stdout or "").split():
        if not ref.startswith("worktree-") or ref in seen or ref in checked_out:
            continue
        # MERGED branch-only leftovers are safe by the reaper's own argument — the work
        # is on the trunk — but the reaper walks WORKTREES, so a branch whose delete
        # failed once (see the `-d`-against-lane-HEAD defect) is left behind by every
        # subsequent sweep, because by then there is no worktree to find it by. Classify
        # it as merged rather than calling it unmerged and refusing it with advice to
        # land work that has already landed.
        merged = sh(["git", "-C", str(ROOT), "merge-base", "--is-ancestor",
                     f"refs/heads/{ref}", f"refs/heads/{_trunk()}"],
                    check=False).returncode == 0
        lanes.append({"name": ref.replace("worktree-", ""), "branch": ref,
                      "path": str(ROOT), "status": "merged" if merged else "unmerged",
                      "is_self": False, "branch_only": True, "merged": merged})
    # BOTH phantom shapes, because they are one class wearing two costumes: the lane that
    # died with its stub journal uncommitted (session ~129's poga-5, which the reaper is
    # explicitly allowed to delete and structurally cannot reach), and the one whose stub
    # got swept onto the branch by a stop-checkpoint (session ~134's poga-1 / poga-8).
    # Covering only the second would leave the first nagging at every start — the exact
    # complaint that started this.
    cands, refused, newborn = [], [], []
    for l in lanes:
        # WI-0257, and it outranks even `merged`: a lane in its birth window has a branch
        # freshly cut from the trunk, so `merged` is exactly what it reads as. This verb
        # never reached one only because all four phantom predicates happen to answer
        # False on a lane with no commits ahead and a clean tree — a true accident rather
        # than a safety argument, and the sibling of the WI-0238 shape (a stale liveness
        # read consumed as live state). Refused BY NAME, like every other refusal here.
        if l["status"] == "young":
            newborn.append(l)
        elif l.get("merged"):
            cands.append(l)                     # work is on the trunk; only the ref is left
        elif (_lane_commits_are_only_phantom_debris(l)
              or _lane_holds_only_phantom_debris(l)
              or _lane_journals_are_superseded_on_trunk(l)
              or _lane_adds_nothing_the_trunk_lacks(l)):
            cands.append(l)
        elif l["status"] == "unmerged":
            refused.append(l)
    for l in newborn:
        age = l.get("age_min")
        seen = f"{age:.0f}m since last activity" if age is not None else "age unreadable"
        print(f"refused: {l['name']} — inside the {LANE_REAP_MIN_AGE_MIN}m birth window "
              f"({seen}); it may still be starting up. Re-check once it ages.")
    for l in refused:
        print(f"refused: {l['name']} — holds real work, or its history could not be read. "
              f"Land it: cd {l['path']} && python3 session.py merge")
    if not cands:
        print("discard-phantom-lanes: nothing to discard — no lane holds only empty "
              "stubs, superseded journals, or content the trunk already has.")
        return
    for l in cands:
        # Name WHICH shape was found. "Committed a stub" and "never committed anything"
        # are different histories, and a receipt that describes the wrong one is the
        # defect this session already fixed once in the store receipt.
        why = ("already merged into the trunk; only the branch ref is left"
               if l.get("merged")
               else "commits touch only empty session stubs"
               if _lane_commits_are_only_phantom_debris(l)
               else "every journal on it is already CLOSED on the trunk — this is a "
                    "superseded snapshot, not unlanded work"
               if _lane_journals_are_superseded_on_trunk(l)
               else "every path it touches is a generated view or already byte-identical "
                    "on the trunk — its work reached the trunk by another route"
               if _lane_adds_nothing_the_trunk_lacks(l)
               else "holds only an uncommitted empty session stub")
        print(f"phantom: {l['name']} (branch {l['branch']}) — {why}; nothing to recover.")
    if getattr(args, "dry_run", False):
        print(f"would discard {len(cands)} lane(s); write nothing.")
        return
    for l in cands:
        # A branch-only orphan's `path` is the repo root, not a worktree — removing it
        # would be removing the main checkout. Never let the cleanup reach the thing it
        # is standing in.
        if not l.get("branch_only"):
            _unlock_if_owner_is_dead(l["path"])
            wt = sh(["git", "-C", str(ROOT), "worktree", "remove", "--force",
                     str(l["path"])], check=False)
            if wt.returncode != 0:
                print(f"note: could not remove worktree {l['path']} — "
                      f"{(wt.stderr or '').strip()[:120]}", file=sys.stderr)
        br = sh(["git", "branch", "-D", l["branch"]], check=False)
        if br.returncode != 0:
            print(f"note: could not delete branch {l['branch']} — "
                  f"{(br.stderr or '').strip()[:120]}", file=sys.stderr)
            continue
        print(f"discarded: {l['name']} (branch {l['branch']}).")
    sh(["git", "worktree", "prune"], check=False)


# ── Retiring a park ref (WI-0141) ────────────────────────────────────────────────
# The two ref namespaces a PARK lives in, and the only two `retire-parked` will ever
# delete from:
#
#   `parked/<trunk>-<sha>` — written by `_park_unpushed_trunk` when `integrate` refuses
#                            and pushes the un-integrable tip somewhere additive rather
#                            than leaving the work on one disk.
#   `landed/<id>`          — the by-hand equivalent the destructive-git deny message
#                            prescribes when a land cannot push: commit in-lane, push the
#                            branch additively, strand nothing.
#
# Deliberately NOT a delete-any-ref verb. A lane branch is `discard-phantom-lanes`'s
# subject and has four predicates of its own; the trunk is nobody's; and a verb that
# would delete an arbitrary ref on a good predicate is the same blind force-delete the
# P9 guard exists to stop, wearing a sanctioned name.
PARK_NAMESPACES = ("parked/", "landed/")

# How many park refs the START BANNER will look at. The verb itself is uncapped — an
# operator who asked for the survey wants all of it — but the banner runs at every session
# open ([P19](principles/master.md#p19--cap-what-can-run-away)).
#
# MEASURED, NOT PICKED, and the measuring is what changed the design. On a machine under
# heavy load: `cherry` costs ~327 ms/ref because it computes patch-ids, `merge-base --is-ancestor`
# ~35 ms/ref because it walks reachability — ten to one. The first draft ran the full
# content predicate here behind a cap of 25 and measured ~4.7 SECONDS of session-open time;
# a cap that bounds the count and not the time is not a cap on the thing that hurts. So the
# banner now buys only the cheap half and says which half it skipped (below), which puts
# the worst case at cap × ~35 ms ≈ 0.4 s under a load this machine has never exceeded.
PARK_REPORT_CAP = 12


def _retire_trunk_ref() -> tuple[str, str]:
    """Which trunk `retire-parked` measures against, and how to say so out loud.

    `origin/<trunk>`, FETCHED FIRST, whenever a remote exists — never the local trunk
    while there is a remote one. A park ref exists precisely because the work was not
    safe on one disk, so "is this ref safe to delete" is really "is this content
    somewhere that survives this machine," and only the remote trunk answers that. A
    local trunk that has the content but has not pushed it reads here as NOT landed and
    the refusal says so: that is the right answer, not a false negative — retiring the
    ref then would delete the only published copy.

    Returns ('', '') when no trunk can be resolved at all, which every caller treats as
    a refusal. A fetch that FAILS is not fatal: the last-fetched remote state is still a
    trunk, it is merely older, and older can only make this verb refuse more. Named in
    the line rather than folded into the clean answer
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes))."""
    trunk = _trunk()
    if sh(["git", "remote"], check=False).stdout.split():
        f = sh(["git", "fetch", "--quiet", "origin"], check=False)
        remote = f"refs/remotes/origin/{trunk}"
        if _ref_exists(remote):
            stale = ("" if f.returncode == 0 else
                     " — FETCH FAILED, so this is the last-fetched state and may be "
                     "behind; that can only make this verb refuse, never retire")
            return remote, f"origin/{trunk}{stale}"
    local = f"refs/heads/{trunk}"
    if _ref_exists(local):
        return local, (f"the LOCAL {trunk} — no remote trunk to measure against, so "
                       f"'landed' here means landed on this disk only")
    return "", ""


def _park_ref_sides(branch: str) -> dict[str, str]:
    """The refs that actually exist for `branch`, keyed 'local' / 'origin'.

    Both are asked separately and both must pass. A park ref commonly exists on ONE side
    only — the live federation instances are all origin-only, pushed from a lane that
    kept no local copy — and where both exist their tips can differ, so a predicate that
    checked whichever it found first would be answering about a ref it is not deleting.
    """
    sides = {}
    if _ref_exists(f"refs/heads/{branch}"):
        sides["local"] = f"refs/heads/{branch}"
    if _ref_exists(f"refs/remotes/origin/{branch}"):
        sides["origin"] = f"refs/remotes/origin/{branch}"
    return sides


def _park_ref_verdicts(branch: str, trunk_ref: str,
                       subjects: bool = True) -> tuple[list[dict], bool]:
    """Per-commit verdicts for every side of `branch`, and whether ALL of it is landed.

    `subjects=False` skips the per-commit `log -1` that fills in each commit's message.
    The verdict is identical either way — the subject is for the human reading a receipt,
    and a caller that only needs the boolean should not pay for prose nobody prints.
    MEASURED, not assumed: the subject lookups are essentially the whole cost. With them,
    one ref eight commits ahead takes ~187ms and the start banner's worst case at its cap
    was ~4.7 SECONDS on the session-open path; without them the same ref is ~31ms. The cap
    alone did not make the banner cheap, which is what writing "capped" in its docstring
    had quietly claimed
    ([`a-timing-claim-is-measured-never-read`](habits/master.md#a-timing-claim-is-measured-never-read)).

    THE PREDICATE IS CONTENT-BASED, NOT ANCESTRY-BASED, and WI-0141 had to learn why
    twice. Its second instance is the clean one: a lane pushed its work to
    `landed/20260817T1200Z-runner-9378`, the trunk absorbed that work through an ordinary
    `pull --rebase`, and every commit came out the far side with a NEW SHA. Ask
    `merge-base --is-ancestor` and the answer is no; ask whether the content is on the
    trunk and the answer is yes for all seventeen. A verb built on ancestry would refuse
    to retire a fully-landed ref forever, and one that fell back to "looks merged" would
    delete on a guess. `git cherry` asks the content question directly — `-` where an
    equivalent patch exists upstream, `+` where it does not — which is the judgement a
    human cannot make by eye and the whole reason this is a verb rather than advice.

    Three verdicts, and the middle one is what earns the verb:

      * `ancestor`           — the side is reachable from the trunk; nothing ahead at all.
      * `content-equivalent` — ahead by SHA, but this commit's patch is already upstream.
      * `UNLANDED`           — ahead, and the trunk has nothing equivalent. Real work.

    Fail-safe in the one direction that cannot lose work, like every sibling predicate in
    this file: an unreadable history, a `cherry` that errors, a line that will not parse —
    all report `UNREADABLE` and falsify the verdict. A history that cannot be read must
    never read as safe to delete."""
    rows: list[dict] = []
    sides = _park_ref_sides(branch)
    if not sides:
        return [], False
    landed = True
    for side, ref in sorted(sides.items()):
        if sh(["git", "merge-base", "--is-ancestor", ref, trunk_ref],
              check=False).returncode == 0:
            rows.append({"side": side, "sha": "", "subject": "", "verdict": "ancestor",
                         "note": "every commit on it is reachable from the trunk"})
            continue
        r = sh(["git", "cherry", trunk_ref, ref], check=False)
        if r.returncode != 0:
            rows.append({"side": side, "sha": "", "subject": "", "verdict": "UNREADABLE",
                         "note": (r.stderr or r.stdout).strip()[:120]})
            landed = False
            continue
        lines = [ln.split() for ln in (r.stdout or "").splitlines() if ln.strip()]
        if not lines:
            rows.append({"side": side, "sha": "", "subject": "", "verdict": "ancestor",
                         "note": "nothing ahead of the trunk"})
            continue
        for parts in lines:
            if len(parts) < 2:
                rows.append({"side": side, "sha": "", "subject": "",
                             "verdict": "UNREADABLE",
                             "note": f"unparseable cherry line: {' '.join(parts)[:60]}"})
                landed = False
                continue
            mark, sha = parts[0], parts[1]
            subject = (sh(["git", "log", "-1", "--format=%s", sha],
                          check=False).stdout.strip() if subjects else "")
            ok = mark == "-"
            landed = landed and ok
            rows.append({"side": side, "sha": sha[:12], "subject": subject[:72],
                         "verdict": "content-equivalent" if ok else "UNLANDED",
                         "note": ""})
    return rows, landed


def _park_refs() -> list[str]:
    """Every ref in the park namespaces, local and on origin, as short branch names."""
    out: set[str] = set()
    r = sh(["git", "for-each-ref", "--format=%(refname)",
            "refs/heads/", "refs/remotes/origin/"], check=False)
    for ln in (r.stdout or "").splitlines():
        ln = ln.strip()
        for prefix in ("refs/heads/", "refs/remotes/origin/"):
            if ln.startswith(prefix):
                name = ln[len(prefix):]
                if name and name != "HEAD" and name.startswith(PARK_NAMESPACES):
                    out.add(name)
                break
    return sorted(out)


def _branch_checked_out_at(branch: str) -> str | None:
    """The worktree path `branch` is checked out in, or None.

    A ref someone is standing on is never retired, whatever the predicate says — asked
    here rather than left to git's own refusal because the MESSAGE matters: the operator
    should be told which tree holds it, not handed a delete that already succeeded on the
    remote side and then failed locally."""
    r = sh(["git", "worktree", "list", "--porcelain"], check=False)
    path = None
    for ln in (r.stdout or "").splitlines():
        if ln.startswith("worktree "):
            path = ln.split(" ", 1)[1].strip()
        elif ln.startswith("branch "):
            if ln.split(" ", 1)[1].strip() == f"refs/heads/{branch}":
                return path
    return None


def _retire_refusal(branch: str) -> str | None:
    """The STRUCTURAL refusals — the ones that hold whatever the history says."""
    if branch in (_trunk(), f"origin/{_trunk()}", "HEAD"):
        return "that is the trunk"
    if not branch.startswith(PARK_NAMESPACES):
        return ("not a park ref — this verb retires only "
                + " / ".join(n + "*" for n in PARK_NAMESPACES)
                + ". A lane branch is `python3 session.py discard-phantom-lanes`'s "
                  "subject, which carries its own four predicates")
    if not _park_ref_sides(branch):
        return "no such ref, locally or on origin"
    held = _branch_checked_out_at(branch)
    if held:
        return f"checked out at {held} — a ref someone is standing on is never retired"
    return None


def _park_ref_is_ancestor_everywhere(branch: str, trunk_ref: str) -> bool:
    """The CHEAP half of the retirement question: is every side of `branch` reachable from
    the trunk? True only when at least one side exists and all of them pass."""
    sides = _park_ref_sides(branch)
    return bool(sides) and all(
        sh(["git", "merge-base", "--is-ancestor", ref, trunk_ref],
           check=False).returncode == 0
        for ref in sides.values())


def _retirable_park_lines() -> list[str]:
    """Start-banner line: that park refs exist, and how many are retirable on the cheap
    test alone.

    IT BUYS THE CHEAP HALF AND SAYS SO. The full predicate is content-based and therefore
    costs a patch-id computation per ref (~327 ms/ref measured, against ~35 ms for the
    ancestry test); paying that at every session open is not worth it for a housekeeping
    line, and capping the ref COUNT does not bound the TIME. So the banner runs
    `merge-base --is-ancestor` only, and reports the refs it could not settle as a distinct
    unchecked group rather than folding them into either answer
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)). The
    verb is where the real answer lives, and it is one line away.

    NOT SILENT WHEN NOTHING IS CHEAPLY RETIRABLE — only when there are no park refs at all.
    A leftover the banner declined to price is still a leftover, and going quiet about it
    would rebuild the exact stale signal WI-0141 exists to remove. NO FETCH: a stale
    `origin/<trunk>` can only shrink the count, and the verb fetches for itself. Fail-open:
    a start must never break on housekeeping."""
    try:
        all_refs = _park_refs()
        if not all_refs:
            return []
        refs = all_refs[:PARK_REPORT_CAP]
        trunk_ref = f"refs/remotes/origin/{_trunk()}"
        if not _ref_exists(trunk_ref):
            trunk_ref = f"refs/heads/{_trunk()}"
            if not _ref_exists(trunk_ref):
                return []
        ready = [b for b in refs if _park_ref_is_ancestor_everywhere(b, trunk_ref)]
        rest = len(all_refs) - len(ready)
        line = f"parked:  {len(all_refs)} park ref(s) left over"
        if ready:
            line += (f"; {len(ready)} provably retirable "
                     f"({', '.join(ready[:3])}"
                     + (f", +{len(ready) - 3} more" if len(ready) > 3 else "") + ")")
        if rest:
            line += (f"; {rest} NOT checked here — the content test is not free at "
                     f"session open, so the verb answers for those")
        return [line + ". Retire: python3 session.py retire-parked"]
    except Exception:
        return []


def cmd_retire_parked(args: argparse.Namespace) -> None:
    """Retire a park ref — delete it locally AND on origin — only where every commit on
    it is provably already on the trunk. WI-0141.

    THE GAP THIS CLOSES IS NOT A MISSING PERMISSION, IT IS A MISSING PREDICATE. Twice
    now, a lane parked its work additively because a push was refused, the work reached
    the trunk by another route, operator explicitly authorised deleting the leftover ref, and
    the `confirm-destructive-ops` guard denied it anyway — correctly, both times. The
    guard cannot tell a ref whose content has landed from one holding the only copy of
    somebody's work, and neither can a human by eye once a rebase has rewritten every
    SHA. So the safety argument moves OUT of the human's assertion and INTO the verb's
    predicate: `_park_ref_verdicts` answers the content question per commit, the verb
    prints what it verified, and the delete is reachable only where that answer is
    unanimous. This is the denied-hand-run-becomes-a-substrate-verb pattern its sibling
    `discard-phantom-lanes` already runs, applied to the ref case the lane predicates
    deliberately do not cover (a lane holding parked work is work).

    NO CONFIRMATION PROMPT, and that is the point rather than an omission. A prompt would
    ask a human to assert exactly the thing they cannot check — the assertion this verb
    exists to replace. What it does instead is show its working: the per-commit verdict
    is printed before the delete on the success path and instead of it on the refusal
    path, so the receipt says what was verified rather than merely that something was
    ([`capture-the-probe`](habits/master.md#capture-the-probe)).

    Three shapes:
      * no argument  — SURVEY every park ref and delete nothing.
      * `<branch>`   — retire that one, or refuse it with its own verdict list.
      * `--all`      — retire every ref whose verdict is unanimous; refuse the rest BY
                       NAME, never silently skipped.
    """
    trunk_ref, trunk_why = _retire_trunk_ref()
    if not trunk_ref:
        print(f"retire-parked: cannot resolve a {_trunk()} to measure against — "
              f"refusing to delete anything.", file=sys.stderr)
        raise SystemExit(2)
    tip = sh(["git", "rev-parse", "--short", trunk_ref], check=False).stdout.strip()
    print(f"retire-parked: measuring against {trunk_why} at {tip or '?'}.")

    named = (getattr(args, "branch", None) or "").strip()
    sweep = bool(getattr(args, "all", False))
    if named:
        targets = [named]
    else:
        targets = _park_refs()
        if not targets:
            print("retire-parked: no park refs — nothing under "
                  + " or ".join(n + "*" for n in PARK_NAMESPACES) + ".")
            return

    retirable, refused = [], []
    for branch in targets:
        why = _retire_refusal(branch)
        if why:
            refused.append((branch, why, []))
            continue
        rows, landed = _park_ref_verdicts(branch, trunk_ref)
        if landed:
            retirable.append((branch, "", rows))
        else:
            bad = sum(1 for r in rows if r["verdict"] not in ("ancestor",
                                                              "content-equivalent"))
            refused.append((branch, f"{bad} commit(s) the trunk does not have, or a "
                                    f"history that could not be read", rows))

    # THE SURVEY COLLAPSES, THE ACT DOES NOT. A receipt for a delete must carry the
    # whole per-commit verdict it acted on — that is the probe, and a summary of a probe
    # is not one ([`capture-the-probe`](habits/master.md#capture-the-probe)). A survey
    # deletes nothing and spans every park ref at once, so 45 lines of
    # `content-equivalent` there buys nothing and buries the one ref that is NOT. So the
    # clean rows fold into a count in survey mode only, and `--verbose` unfolds them;
    # anything that is not clean prints in full on every path, always.
    collapse = not named and not sweep and not getattr(args, "verbose", False)
    for branch, why, rows in refused + retirable:
        print(f"  {branch}")
        clean = [r for r in rows if r["verdict"] == "content-equivalent"]
        for r in rows:
            if collapse and r["verdict"] == "content-equivalent":
                continue
            where = f"{r['sha']}  {r['subject']}" if r["sha"] else r["note"]
            print(f"    {r['side']:<7} {r['verdict']:<19} {where}")
        if collapse and clean:
            print(f"    {clean[0]['side']:<7} {'content-equivalent':<19} "
                  f"{len(clean)} commit(s) — patches already on the trunk under other "
                  f"SHAs (--verbose lists them)")
        if why:
            print(f"    REFUSED — {why}.")

    if not retirable:
        print("retire-parked: nothing retired — every ref named above holds something "
              "the trunk lacks, or could not be read.")
        if named:
            raise SystemExit(2)
        return
    if not named and not sweep:
        print(f"retire-parked: survey only — {len(retirable)} ref(s) are retirable. "
              f"Name one, or pass --all, to act.")
        return
    if getattr(args, "dry_run", False):
        print(f"would retire {len(retirable)} ref(s); write nothing.")
        return

    failed = []
    for branch, _why, _rows in retirable:
        sides = _park_ref_sides(branch)
        gone = []
        for side in sorted(sides):
            if side == "local":
                r = sh(["git", "branch", "-D", branch], check=False)
            else:
                r = sh(["git", "push", "origin", "--delete", branch], check=False)
            if r.returncode == 0:
                gone.append(side)
            else:
                failed.append(f"{branch} ({side})")
                print(f"note: could not retire {branch} on {side} — "
                      f"{(r.stderr or r.stdout).strip()[:140]}", file=sys.stderr)
        if gone:
            print(f"retired: {branch} ({' + '.join(gone)}) — its content is on the trunk.")
    # A DELETE THAT DID NOT HAPPEN MUST NOT EXIT 0, and this is here because the live
    # exercise produced it rather than because it was foreseen: the first `--all` over the
    # federation's own seven refs hit an SSH timeout part-way, four refs went and three did
    # not, and the verb still exited 0 with the failures on stderr — which a caller that
    # checks status reads as "the namespace is clear." Distinct code from the refusal
    # (2), because "the predicate said no" and "the predicate said yes and the network
    # dropped" are different facts and the retry for them is different too.
    if failed:
        print(f"retire-parked: {len(failed)} delete(s) DID NOT HAPPEN — "
              f"{', '.join(failed)}. The refs are untouched; re-run when the cause above "
              f"is cleared.", file=sys.stderr)
        raise SystemExit(1)


def _lane_processes() -> list[dict]:
    """Every live `--worktree <lane>` process: `{pid, lane, age_sec, cmd, cwd}`.

    `cwd` is the repo the process actually belongs to (see `_process_cwd`) and is None
    where that could not be read. It is resolved HERE, at enumeration, so that
    `_classify_lane_processes` stays pure logic over these dicts — the classifier is the
    thing that decides whether a process may be killed, and it should be exercisable
    without a live process to point it at.

    Resolution is capped at `LANE_PROC_CWD_CAP` processes ([P19](principles/master.md#p19--cap-what-can-run-away))
    because this runs on the startup path; beyond the cap `cwd` stays None, which the
    classifier reads as unprovable — the safe direction, and reported rather than silent.

    Read-only; never raises. Returns [] where `ps` is unavailable or unparseable, which
    the caller reports as "not checked" rather than as "none found".

    UNDER THE GATE, [] — for the same reason and with the same meaning (ADR-0119 D4). The
    machine's process table is the one input guaranteed to differ between the gate run and
    the trunk the gate is deciding about, and WI-0271 traced this call reached from
    `cmd_reap_lanes` in five separate lane tests during a real land."""
    if _under_gate():
        return []
    out: list[dict] = []
    try:
        r = subprocess.run(["ps", "-axo", "pid=,etime=,command="],
                           capture_output=True, text=True, check=False)
        if r.returncode != 0:
            return []
        for line in (r.stdout or "").splitlines():
            parts = line.strip().split(None, 2)
            if len(parts) < 3 or not parts[0].isdigit():
                continue
            pid, etime, cmd = int(parts[0]), parts[1], parts[2]
            m = LANE_PROC_RE.search(cmd)
            if not m or "grep" in cmd.split()[0]:
                continue
            age = _parse_etime(etime)
            if age is None:
                continue
            out.append({"pid": pid, "lane": m.group(1), "age_sec": age, "cmd": cmd,
                        "cwd": None})
        for proc in out[:LANE_PROC_CWD_CAP]:
            proc["cwd"] = _process_cwd(proc["pid"])
    except Exception:
        return []
    return out


def _lane_trunk_distance() -> dict | None:
    """How far this lane's HEAD sits behind the newest known trunk, and the commits both
    sides were measured at. `None` when we are not on a lane.

    **ADR-0108 D3.** A lane is otherwise structurally blind to this. `git_sync` derives
    every behind/ahead number from `@{u}` (`_git_diagnose`), and a lane branch
    (`worktree-poga-N`) has no upstream — so it returns `no upstream tracking` before any
    distance is computed, and every lane takes that path, always. The number the banner
    was assumed to be reporting was never calculated at all.

    Measured against `_trunk_tip()` rather than the local trunk ref, so the answer is
    against the newest trunk this machine knows about (it prefers `origin/<trunk>` when
    that is ahead) — the same reference a land builds its candidate on.

    Three outcomes, never two ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)):
    readable with a count, readable-but-unmeasurable, and not-a-lane. "I could not ask"
    must never render as "you are current"."""
    if not _on_worktree_lane():
        return None
    trunk = _trunk()
    # WHAT DATES THIS ANSWER (WI-0283). `_trunk_tip()` PREFERS `origin/<trunk>` when it
    # is ahead, so the measurement rests on a remote-tracking ref either way: either it
    # returns one, or it returns the local trunk BECAUSE origin looked no newer — and
    # that second reading is the one a stale ref fakes. Nothing on this path fetches, so
    # the ref's own date has to travel with the number.
    remote = _remote_provenance(f"origin/{trunk}")
    tip = _trunk_tip()
    head = sh(["git", "rev-parse", "HEAD"], check=False)
    head_sha = head.stdout.strip() if head.returncode == 0 else None
    if not tip or not head_sha:
        return {"readable": False, "trunk": trunk, "tip": tip, "head": head_sha,
                "behind": None, "remote": remote}
    r = sh(["git", "rev-list", "--count", f"HEAD..{tip}"], check=False)
    count = (r.stdout or "").strip()
    if r.returncode != 0 or not count.isdigit():
        return {"readable": False, "trunk": trunk, "tip": tip, "head": head_sha,
                "behind": None, "remote": remote}
    return {"readable": True, "trunk": trunk, "tip": tip, "head": head_sha,
            "behind": int(count), "remote": remote}


def _lane_trunk_distance_lines() -> list[str]:
    """The ADR-0108 D3 orientation line. Silent when the lane is current — the common
    case, and the same silence `_main_checkout_lines` keeps when main is clean."""
    d = _lane_trunk_distance()
    if d is None:
        return []
    if not d["readable"]:
        return [f"trunk:   NOT CHECKED — could not measure this lane's distance from "
                f"{d['trunk']}. Reads from this tree may be stale and nothing here can "
                f"say by how much."]
    p = d.get("remote") or {}
    # STALE means: there IS a remote-tracking ref, and nothing has confirmed it against
    # the remote recently. When no such ref exists at all (a local-only trunk) the local
    # ref is genuinely the whole truth and there is nothing to qualify.
    stale = bool(p.get("readable")) and not p.get("fresh")
    if not d["behind"]:
        if not stale:
            return []
        # THE FALSE ALL-CLEAR, AND THE ONE THIS FUNCTION'S DOCSTRING ALREADY FORBADE.
        # Silence here is read as "you are current". A zero measured against a ref
        # nobody refreshed only ever meant "level with what this machine last saw",
        # and with concurrent lanes that ref moves when a SIBLING pushes, not when we look.
        return [f"trunk:   this lane is level with {d['trunk']} (at {d['tip'][:7]}) — but "
                f"only with what this machine last saw: {_remote_clause_of(p)}. "
                f"Nothing here has asked the remote, so 'level' is not 'current'."]
    line = (f"trunk:   this lane (at {d['head'][:7]}) is {d['behind']} commit(s) behind "
            f"{d['trunk']} (at {d['tip'][:7]}) — anything read from THIS tree is that far "
            f"stale (ADR-0108). `python3 session.py merge` lands on the newest trunk; it "
            f"does not pull under you.")
    # The COUNT is dated too, and understates when the ref is behind the real remote.
    if stale:
        line += f" Distance measured {_remote_clause_of(p)}."
    return [line]


def _lane_birth(path: Path) -> tuple[float | None, str]:
    """`(epoch, source)` for when the lane at `path` was created, or `(None, "unavailable")`.

    The `predates` proof needs a birth time, and the obvious source — `st_birthtime` — is
    a **macOS/BSD field that Linux does not expose to Python** (the kernel has it via
    `statx`; `os.stat_result` does not carry it). Shipping only that would have made this
    detector quietly weaker on any Linux member: not broken, not warned about, just never
    firing for the harder half of the class.

    So there is a fallback, and it is better than a guess — **git's own registration
    record**. `git worktree add` creates `<common>/worktrees/<name>/gitdir` at the moment
    the worktree is registered, and ordinary work in the lane never rewrites it (commits
    touch `HEAD`, not this). Verified on the live pool: both lanes' `gitdir` mtimes match
    their directories' birth times to the second.

    It is also the *more correct* signal in the case that matters. A lane branch can be
    **reused** — `poga` re-adds a worktree onto an existing `worktree-<name>` branch — so
    anything derived from the branch (its reflog, its first commit) would report the
    ORIGINAL lane's age and defeat the recycled-name detection this proof exists for.
    Registration time is per-incarnation.

    What is deliberately NOT here is `mtime` on the lane directory itself: a lane's own
    activity keeps that fresh, so it would prove the opposite of what it appears to prove.
    Where neither source resolves the proof is UNAVAILABLE and the caller says so, rather
    than reporting "nothing stranded"
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).

    **`st_birthtime` is not immutable, and the caller relies on which way that breaks.**
    On macOS, setting an mtime older than the creation date drags the birth time down with
    it — so a restore, an `rsync -t`, or any backup tool can move this value. That is
    survivable only because of the direction: the predicate is
    `process_start < birth - grace`, so an earlier birth makes it HARDER to satisfy, and
    the failure mode is a stranded process we decline to kill rather than a live one we do.
    The `git-registration` fallback (Linux's only source, WI-0468) is an mtime a restore
    can rewrite the same way, and the same direction argument covers it — which is why
    there is still no `st_mtime`-of-the-directory fallback after it: that one moves LATER
    with ordinary lane activity, the unsafe direction. Pinned for both sources by `test_a_dragged_birth_time_fails_in_the_SAFE_direction`, which is what found
    the mutability in the first place — it was written asserting the opposite."""
    b = _fs_birthtime(path)
    if b is not None:
        return b, "st_birthtime"
    with contextlib.suppress(Exception):
        common = _git_common_dir()
        if common is not None:
            gd = common / "worktrees" / path.name / "gitdir"
            if gd.is_file():
                return gd.stat().st_mtime, "git-registration"
    return None, "unavailable"


def _classify_lane_processes() -> tuple[list[dict], list[dict]]:
    """`(proven, unprovable)` over every live lane process.

    **PROVEN** — safe to act on. Two proofs, and nothing else counts:

      `lane-gone`   — the named lane directory does not exist, so there is no tree for it
                      to be working in.
      `predates`    — the directory exists but the process started more than
                      `LANE_PROCESS_BIRTH_GRACE_MIN` before that directory was BORN, so it
                      belongs to an earlier incarnation of a recycled lane name.

    **Both proofs are asked only of OUR OWN processes.** A lane process is attributed to a
    repo by its working directory, never by its lane name (WI-0135): `--worktree poga-2`
    says which lane, and every member has a `poga-2`. Before this gate the global `ps` scan
    was joined against *this* repo's `lanes_root`, so another member's live session read as
    `lane-gone` here — its directory is genuinely absent from this pool — and
    `reap-lanes --processes` would SIGKILL it. That is not hypothetical: it killed the
    session that was running the command (federation session 145, 2026-08-15), and a
    session killed mid-tool-call leaves a `tool_use` with no `tool_result`, which makes it
    permanently unresumable. So the blast radius was another member's work AND that
    session's ability to be re-entered.

    A process whose cwd is outside our pool is therefore **not our subject at all** — it is
    dropped, not reported. Reporting it would put every member's lanes in every other
    member's banner, which is noise that trains the reader to skim exactly the block that
    matters.

    **UNPROVABLE** — a question that could not be asked. Two causes, kept distinct because
    they are different ignorances and the operator's next move differs:

      `repo-unknown`  — cwd could not be read, so we cannot say whether this process is
                        ours. Note this outranks the lane checks: an unattributable process
                        is never `lane-gone`, however absent the directory looks from here.
      `birth-unknown` — the lane is ours and exists, but `_lane_birth` resolved no creation
                        time, so the `predates` question cannot be asked.

    Returned SEPARATELY and never mixed in: the proven list is what `_reap_lane_processes`
    terminates, and one un-asked question landing in it would kill a live session. This is
    [`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes) enforced
    by the type rather than by remembering — "I could not tell" gets its own return value,
    so a caller has to decide what to do with it instead of receiving it as "fine".

    Everything else is left alone by design. Two live-looking processes naming one lane is
    a real and ordinary state (a resumed session), and *ambiguous* must not be folded in
    with *proven*. Never raises."""
    lanes_root = _lanes_root()
    if lanes_root is None:
        return [], []
    now = time.time()
    grace = LANE_PROCESS_BIRTH_GRACE_MIN * 60
    proven: list[dict] = []
    unprovable: list[dict] = []
    for proc in _lane_processes():
        d = lanes_root / proc["lane"]
        try:
            cwd = proc.get("cwd")
            if cwd is None:
                unprovable.append({**proc, "reason": "unprovable",
                                   "unprovable_cause": "repo-unknown"})
                continue
            if not _path_within(cwd, lanes_root):
                continue                       # another repo's lane — not ours to judge
            if not _path_within(cwd, d):
                # In our pool but not in the lane its argv names — a recycled or hand-moved
                # cwd. Ambiguous, so it takes the same exit as any un-asked question.
                unprovable.append({**proc, "reason": "unprovable",
                                   "unprovable_cause": "repo-unknown"})
                continue
            if not d.is_dir():
                proven.append({**proc, "reason": "lane-gone"})
                continue
            birth, source = _lane_birth(d)
            if birth is None:
                unprovable.append({**proc, "reason": "unprovable", "birth_source": source,
                                   "unprovable_cause": "birth-unknown"})
                continue
            if (now - proc["age_sec"]) < birth - grace:
                proven.append({**proc, "reason": "predates", "birth_source": source})
        except OSError:
            continue                           # unreadable proves nothing
    return proven, unprovable


def _stranded_lane_processes() -> list[dict]:
    """The PROVABLY stranded processes — the list that is safe to act on. See
    `_classify_lane_processes` for the two proofs and for what is deliberately excluded."""
    return _classify_lane_processes()[0]


def _reap_lane_processes() -> list[str]:
    """Terminate the provably-stranded lane processes; return report lines.

    **Every line here is a post-check, never a self-report.** The first cut of this
    function printed `terminated pid N` on the strength of `os.kill` not raising — which
    proves only that the signal was DELIVERED. Exercised live in session ~125 against a
    real four-day-old stranded process, it printed `terminated` and the process was still
    running afterwards. That is exactly
    [`a-close-is-the-banner-not-the-sentence`](habits/master.md#a-close-is-the-banner-not-the-sentence):
    the receipt has to be the outcome its own code produced, not the sentence describing
    the attempt — and it slipped into a sweep whose entire purpose is to stop lying about
    residue.

    SIGTERM first so a session gets to run whatever exit handling it has, then SIGKILL if
    it is still there after the grace. Escalating rather than reporting-and-leaving is
    deliberate: the safety of this operation comes from the PREDICATE (the process is
    provably stranded — its tree is gone, or belongs to someone else now), not from the
    strength of the signal, and a stranded process that ignores SIGTERM is precisely the
    case that otherwise lands back on the operator. A process that survives both is
    reported as SURVIVED, never as terminated."""
    lines: list[str] = []
    for p in _stranded_lane_processes():
        pid, tag = p["pid"], (f"({p['lane']}, {p['reason']}, up "
                              f"{p['age_sec'] // 3600}h{p['age_sec'] % 3600 // 60:02d}m)")
        try:
            os.kill(pid, signal.SIGTERM)
        except ProcessLookupError:
            lines.append(f"  pid {pid} already gone")
            continue
        except PermissionError:
            lines.append(f"  pid {pid} NOT signalled — permission denied "
                         f"(another user's process?); left alone")
            continue
        except Exception as e:
            lines.append(f"  pid {pid} NOT signalled — {type(e).__name__}")
            continue
        deadline = time.time() + PROC_SIGNAL_GRACE_SEC
        while _pid_alive(pid) and time.time() < deadline:
            time.sleep(0.1)
        if not _pid_alive(pid):
            lines.append(f"  terminated pid {pid} {tag}")
            continue
        with contextlib.suppress(Exception):
            os.kill(pid, signal.SIGKILL)
        deadline = time.time() + PROC_SIGNAL_GRACE_SEC
        while _pid_alive(pid) and time.time() < deadline:
            time.sleep(0.1)
        if _pid_alive(pid):
            lines.append(f"  pid {pid} SURVIVED both SIGTERM and SIGKILL {tag} — "
                         f"still running; it needs a human")
        else:
            lines.append(f"  killed pid {pid} {tag} (ignored SIGTERM)")
    return lines


def _lane_is_dirty(path: Path) -> bool:
    """True if `path` (a lane worktree) holds uncommitted work — modified tracked files
    OR untracked ones. `--porcelain` reports both, and both matter: one member's loss was
    uncommitted edits, some of which had never been `git add`ed at all, so a probe
    that only saw modified-tracked files would have called that lane clean.

    **Unreadable reads as DIRTY.** If git cannot answer, we do not get to assume the tree
    is empty — that assumption is the entire defect this function exists to close
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes): a
    question we could not ask must not produce the same answer as a question answered
    'no'). Erring dirty costs a lane that lingers until a human looks; erring clean costs
    the work.
    """
    r = sh(["git", "-C", str(path), "status", "--porcelain"], check=False)
    if r.returncode != 0:
        return True
    return bool((r.stdout or "").strip())


def _lane_too_young(lane: dict) -> bool:
    """True if `lane` has been active too recently for ANY sweep to reap it. Unknown age
    reads as young: refuse to reap what we cannot prove is stale.

    WI-0257 retired the carve-out this used to carry — *"the loud, explicit `reap-lanes`
    command is not subject to this, a human asking for the sweep has already looked."*
    The premise was false in both halves. Nothing shows a lane's birth time (there is no
    read-only lane-inspect verb, by design), so the human has not looked at the one
    property this decides on; and `poga` spawns lanes CONCURRENTLY, so running the sweep
    while a dispatcher is spawning is not a rare coincidence, it IS the race. The cost is
    asymmetric in the usual direction: holding a young lane back costs an orphan that
    lingers up to an hour and is named in the report, while reaping one force-removes a
    sibling that is still starting up. `reap-lanes --include-young` is the explicit
    opt-out for an operator who actually watched the lane die.

    Applied in `_scan_lanes` (the 'young' status), so both sweeps inherit it structurally
    rather than each one remembering to ask — which is the whole shape of the defect."""
    age = lane.get("age_min")
    return age is None or age < LANE_REAP_MIN_AGE_MIN


def _reap_lane(lane: dict, lanes_root: Path) -> tuple[bool, list[str]]:
    """Reap one 'reap'-status lane: free the worktree (or delete the residual dir),
    delete its merged branch, and prune stale worktree admin entries.

    Returns `(ok, lines)`. **`ok` is the whole point of this signature** (WI-0038): it
    used to return lines only, so the caller had nothing to count but the number of lanes
    it had *attempted* — and printed that as the number reaped. Two runs with opposite
    outcomes produced byte-identical summaries (session ~102 and again ~111), which is a
    report that cannot express its own failure. `ok` is False if ANY step failed, so a
    partial reap can never round up to success.

    Refuses any path not under `lanes_root` — belt-and-braces so a path-parsing slip can
    never delete outside the lane pool.
    """
    acts: list[str] = []
    ok = True
    path = lane["path"]
    try:
        path.relative_to(lanes_root)
    except ValueError:
        return False, [f"  SKIP {lane['name']}: {path} is not under {lanes_root} — refusing to touch."]
    if lane["registered"]:
        # WI-0038 half two: git refuses to remove a LOCKED worktree even with --force, so
        # a crashed session's lane stayed un-reapable forever and needed a human running
        # `git worktree unlock` by hand — every time, on a lane nothing was using. Only
        # reachable when `_scan_lanes` already proved the lock's pid dead (a live or
        # unparseable pid classifies the lane 'live' and never arrives here), so this
        # unlocks corpses only, never a running session's lane.
        if lane.get("locked"):
            u = sh(["git", "worktree", "unlock", str(path)], check=False)
            acts.append(f"  unlocked {path.name} (lock held by dead pid "
                        f"{lane.get('lock_pid')})" if u.returncode == 0
                        else f"  unlock FAILED for {path.name}: {(u.stderr or u.stdout).strip()}")
            ok = ok and u.returncode == 0
        # WI-0082: NO `--force`. `--force` is precisely the flag that overrides git's
        # refusal to remove a worktree holding uncommitted changes, so it converted every
        # classification mistake into destroyed work. The sibling teardown path (the
        # WorktreeRemove hook, `cmd_worktree_remove`) already omitted it deliberately and
        # its docstring delegated the leftover to "the reaper" — which then force-removed
        # it. Two paths, opposite policies, the safe one citing the unsafe one as its net.
        #
        # Bare `remove` makes git the LAST line of defence rather than the first casualty:
        # `_scan_lanes` should already have held a dirty lane back as `dirty`, and if it
        # ever fails to, this refuses, `ok` goes False, and the lane is REPORTED instead of
        # emptied. Fail-safe in the direction that keeps work. Reaping a lane git refuses
        # to remove is a destructive act and therefore a human one
        # ([`confirm-destructive-ops`](habits/master.md#confirm-destructive-ops)/P9) — the
        # loud command names the lane and the operator runs `--force` themselves.
        r = sh(["git", "worktree", "remove", str(path)], check=False)
        acts.append(f"  freed worktree {path.name}" if r.returncode == 0
                    else f"  worktree remove FAILED for {path.name}: {(r.stderr or r.stdout).strip()}")
        ok = ok and r.returncode == 0
    elif path.exists():
        shutil.rmtree(path, ignore_errors=True)
        acts.append(f"  removed residual dir {path.name}")
    # Sweep the lane's generated pad too. The reaper is the crash path, and a
    # crashed resident-runtime lane strands BOTH a worktree and a pad; leaving the pad
    # would leave a launchable Architect surface pointing into a deleted worktree.
    with contextlib.suppress(Exception):
        if remove_lane_pad(lane["name"]):
            acts.append(f"  removed lane pad for {lane['name']}")
    branch = lane["branch"]
    if branch and _ref_exists(f"refs/heads/{branch}"):
        # `git branch -d` asks "is this merged into MY CURRENT HEAD?" — and run from a
        # lane, that HEAD is the lane's own branch, not the trunk. So a lane that had
        # just landed cleanly failed to reap with *"not fully merged"*, and the advice
        # git prints for it is `-D`, which our own guard denies. The merged-ness question
        # is about the TRUNK; ask it about the trunk explicitly, then delete.
        #
        # Third instance in one session of one shape: a resolver answering about wherever the
        # process happens to be standing rather than about the thing being asked
        # (`_main_checkout`, then `_lane_commits_are_only_phantom_debris`, now this).
        merged = sh(["git", "merge-base", "--is-ancestor",
                     f"refs/heads/{branch}", f"refs/heads/{_trunk()}"],
                    check=False).returncode == 0
        if not merged:
            acts.append(f"  branch delete SKIPPED for {branch}: not an ancestor of "
                        f"{_trunk()} — work is NOT landed, so it is not the reaper's to "
                        f"delete")
            ok = False
        else:
            d = sh(["git", "branch", "-D", branch], check=False)
            acts.append(f"  deleted merged branch {branch}" if d.returncode == 0
                        else f"  branch delete FAILED for {branch}: "
                             f"{(d.stderr or d.stdout).strip()}")
            ok = ok and d.returncode == 0
    sh(["git", "worktree", "prune"], check=False)
    return ok, acts


def _lane_journal_ids(branch: str, unstamped_only: bool = False) -> list[str]:
    """Session-ids of journals committed on `branch` beyond the trunk. An unlanded lane's
    journal exists ONLY on its branch, so the trunk cannot see it either way.

    `unstamped_only` narrows to journals whose `ended:` is blank (R2a, the poga-5
    close-honesty gap — a session that claimed a close its `end` never performed was
    perfectly silent from the trunk). The full set is what lane teardown needs to free
    that lane's front-door coordination records (WI-0123), which are keyed by journal and
    so cannot be found from the branch name alone.

    Fail-open: any git or parse hiccup just yields fewer names, never an exception."""
    out: list[str] = []
    try:
        r = sh(["git", "diff", "--name-only", "--diff-filter=A",
                f"{_trunk()}...{branch}", "--", "sessions/journal/"], check=False)
        for name in (r.stdout or "").split():
            show = sh(["git", "show", f"{branch}:{name}"], check=False)
            if show.returncode != 0:
                continue
            try:
                fm, _body = parse_journal(show.stdout)
            except Exception:
                continue
            if unstamped_only and fm.get("ended"):
                continue
            out.append(fm.get("session-id") or Path(name).stem)
    except Exception:
        pass
    return out


def _lane_unstamped_journals(branch: str) -> list[str]:
    """The unstamped subset — see `_lane_journal_ids`. Kept as a named call because
    "present but UNSTAMPED" is its own diagnostic across the reaper and the banners."""
    return _lane_journal_ids(branch, unstamped_only=True)


def _lane_sidecar_unstamped_journals(path: Path) -> list[tuple[str, dict]]:
    """`(session-id, evidence)` for every open journal belonging to a session that ran in
    the lane at `path` — resolved from THAT LANE'S sidecar, not from a branch diff.

    **Why a second resolver rather than a fix to the first** (WI-0136). `_lane_journal_ids`
    answers "which journals did this branch ADD beyond the trunk", which is the right
    question for an UNMERGED lane and is empty *by construction* for a merged one — the
    branch tip is an ancestor of the trunk, so `trunk...branch` names nothing. Merged lanes
    are exactly the set `reap-lanes` removes, so on the teardown path that resolver can
    only ever answer "none". The two questions genuinely differ and collapsing them would
    break the unmerged case to serve this one.

    The sidecar can answer where the diff cannot: `<lane>/.session-state/<csid>.live` names
    every session that ever beat in this lane, and a journal carries its `claude-session-id`.

    **This is time-critical, which is the whole reason it exists.** The sidecar lives INSIDE
    the lane, so removing the worktree destroys the only evidence that could ever close
    those journals honestly — converting a journal that is closeable right now into one
    whose end time nobody may invent
    ([`a-close-is-the-banner-not-the-sentence`](habits/master.md#a-close-is-the-banner-not-the-sentence)).
    Reaping first and asking later is not recoverable.

    Evidence is the same dict `_sidecar_evidence_by_csid` returns, so the caller can tell a
    clean exit (closeable at a real recorded time) from a crash (not). Never raises."""
    out: list[tuple[str, dict]] = []
    try:
        state = path / ".session-state"
        if not state.is_dir():
            return out
        csids = {p.stem for p in state.glob("*.live")}
        if not csids:
            return out
        for jp in _open_journal_paths():
            fm, _body = parse_journal(jp.read_text(encoding="utf-8"))
            csid = (fm.get("claude-session-id") or "").strip()
            if csid and csid in csids:
                out.append((fm.get("session-id") or jp.stem,
                            _sidecar_evidence_by_csid(csid, state_dir=state)))
    except Exception:
        pass
    return out


def _auto_reap_lanes() -> None:
    """Session-start crash-safety sweep of orphaned terminal poga lanes (ADR-0060 Q5),
    the auto-wired counterpart to the standalone `reap-lanes` command.

    Runs at the first heartbeat's lazy-start materialization, alongside the journal reap
    and SILENTLY (like `_reap_dead_journals` on that path) — background hygiene, not a
    user-facing event: it reaps only what is provably safe (a merged-branch orphan or pure
    dir residue — no unlanded work lost), and the standalone `reap-lanes` remains the loud,
    surfaced path for unmerged lanes.

    **This used to be gated to the MAIN checkout, which quietly made it dead code**
    (session 90). The gate stood in for a real hazard — a just-born sibling lane has not
    locked yet and its freshly-cut branch is trivially merged, so a naive sweep would
    delete a lane that is still starting up. But ADR-0059's detect-and-refuse (session 88)
    steers every session into a `poga` lane, so the only surface allowed to sweep became
    the one nobody opens: `worktree-poga-3` sat merged and reapable for a full day with
    the reaper "running" at every start. The birth race is now handled where it belongs —
    by LANE_REAP_MIN_AGE_MIN in `_scan_lanes`, which excludes a young lane structurally
    rather than by excluding a whole surface — so any session can sweep.

    **That sentence was aspirational for four months** (WI-0257). `_scan_lanes` only
    RECORDED `age_min`; the exclusion lived in this function's own filter, so the loud
    `reap-lanes` path — and `discard-phantom-lanes` — inherited none of it. The age term
    now really is in the classification, which is why there is no age test left here to
    read: a status of 'reap' already means old enough. Duplicating the check at the
    consumer is precisely how the two paths drifted apart, so it is not duplicated back.

    Concurrent sweeps are safe without a lease: each git op is individually atomic, the
    sweep is idempotent, a loser just reports a failure line, and on this path the lines
    are discarded. Fail-open — a reaper hiccup must never break the start it rides."""
    try:
        lanes_root = _lanes_root()
        if lanes_root is None:
            return
        # Drop admin entries whose directory is gone before classifying, so pure residue
        # doesn't linger as a registered-but-absent worktree (consultant F2).
        sh(["git", "worktree", "prune"], check=False)
        for lane in _scan_lanes():
            if lane["status"] == "reap":        # 'reap' now implies old enough (WI-0257)
                _reap_lane(lane, lanes_root)
        sweep_orphan_pads()          # pads whose lane vanished by any route
        _reap_gate_worktrees()       # WI-0063: scratch trees from gates that died mid-run
        # WI-0078: AFTER the lane sweep, so a branch this pass just deleted is already
        # gone when the reconcile looks. Route-independent by design — it also frees the
        # holds of a lane torn down by hand, which is the documented route whenever a live
        # sibling must be preserved.
        _coord_release_dead_lanes()
    except Exception:
        pass


def _lane_death_verdict(path: Path) -> tuple[str, str]:
    """Is the session that owned this lane provably over? `(verdict, reason)` where
    verdict is `dead` / `live` / `unknown`.

    Three answers, not two, and the third is the load-bearing one
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)): a
    lane whose sidecar was never written, or was swept, cannot be judged at all, and
    folding that into `dead` is how an automatic recovery would land work out from under
    a session that is merely quiet. `unknown` is reported and left alone.

    Evidence, per session that ever beat in this lane, using the same rules the reaper
    applies to its own journals (P16 — `_sidecar_evidence_by_csid` + `_crash_grace_min`):
      - a `.ended` marker (the runtime's own clean-exit binding) or a `.gone` marker (the
        wrapper's watcher SAW the process go) — dead, no grace needed;
      - a supervisor beat whose watched pid is gone on this machine — dead;
      - silence past this beat-kind's grace — dead;
      - anything fresher — LIVE, and one live session vetoes the whole lane.

    A lane's `.ended` marker with no stamped journal is precisely the operator's dropped-session
    case: the runtime fired SessionEnd, so the exit is real and clean, but `session.py end`
    never ran, so the journal reads as a false close forever
    ([`a-close-is-the-banner-not-the-sentence`](habits/master.md#a-close-is-the-banner-not-the-sentence))."""
    state = path / ".session-state"
    if not state.is_dir():
        return ("unknown", "no .session-state in the lane — nothing to judge from")
    try:
        csids = sorted({p.stem for p in state.glob("*.live")})
    except OSError as exc:
        return ("unknown", f"lane sidecar unreadable ({exc})")
    if not csids:
        return ("unknown", "no session ever recorded a heartbeat in this lane")
    reasons: list[str] = []
    for csid in csids:
        ev = _sidecar_evidence_by_csid(csid, state_dir=state)
        if ev["has_ended"]:
            reasons.append(f"{csid[:8]} exited cleanly at {ev['ended_at'] or '?'}")
            continue
        if ev["has_gone"]:
            reasons.append(f"{csid[:8]} observed gone at {ev['gone_at'] or '?'}")
            continue
        if _supervised_pid_state(ev) == "alive":
            return ("live", f"{csid[:8]} is a supervised session whose pid is still alive")
        age = ev["beat_age_min"]
        if age is None:
            return ("unknown", f"{csid[:8]} has a sidecar with no readable heartbeat")
        grace = _crash_grace_min(ev)
        if age <= grace:
            return ("live", f"{csid[:8]} beat {age / 60:.1f}h ago — inside its "
                            f"{grace / 60:.0f}h grace; not provably dead")
        reasons.append(f"{csid[:8]} silent {age / 60:.1f}h — past its {grace / 60:.0f}h grace")
    return ("dead", "; ".join(reasons))


def _lane_entry_verdict(l: dict) -> tuple[str, str]:
    """May a new session open inside lane `l`? `(verdict, reason)`, verdict one of
    `occupied` / `too-young` / `free` (WI-0258).

    ONE decision with two renderings — the bare listing and the named form both call this,
    so they cannot drift into disagreeing about the same lane (P16). That is the same
    argument that put the gate in `session.py` rather than in `poga` in the first place;
    it applies just as well one level down, and the previous shape had the liveness test
    written out twice already.

    Reads every optional field with `.get()`, deliberately: `_scan_lanes`' own output
    always carries them, but several tests hand this function a hand-built partial lane,
    and a `KeyError` there would be an entry gate that crashes rather than answers —
    strictly worse than any verdict it could have returned. `path` is the one field that
    is genuinely required, and a lane without it is not a partial answer but no answer at
    all, so it refuses rather than defaulting.

    `too-young` is the third state this verb previously lacked. It is NOT a weaker
    `occupied`: it says the evidence has not had time to appear, so the honest answer is
    "ask again," and it clears on its own within `LANE_ENTER_MIN_AGE_SEC`."""
    if l.get("status") == "live":
        if l.get("is_self"):
            return "occupied", "this session is already in it"
        # Name the EVIDENCE, not just the verdict. A lane refused on a heartbeat and a lane
        # refused on a worktree lock are refused for genuinely different reasons — the
        # first covers a runtime with no lock at all — and an operator who cannot tell
        # which one answered cannot judge whether to believe it
        # ([`capture-the-probe`](habits/master.md#capture-the-probe)).
        probe = {"worktree-lock": "its worktree lock is held by a live pid",
                 "heartbeat": "its session heartbeat is still beating"}.get(
                     l.get("live_by") or "", "a session is in this worktree now")
        return "occupied", f"OCCUPIED: {probe}, and two sessions cannot share one worktree"
    if not l.get("path"):
        return "too-young", "cannot tell — this lane has no path to look at"
    birth, source = _lane_birth(Path(l["path"]))
    if birth is None:
        return ("too-young",
                f"cannot tell — this lane's creation time is unreadable ({source}), so "
                f"there is no way to know whether a session is still starting up in it")
    age = time.time() - birth
    if age < LANE_ENTER_MIN_AGE_SEC:
        return ("too-young",
                f"this lane is {age:.0f}s old and its liveness evidence can take up to "
                f"{LANE_ENTER_MIN_AGE_SEC}s to appear, so 'nobody is in it' is not yet a "
                f"fact — retry in {max(1, int(LANE_ENTER_MIN_AGE_SEC - age))}s")
    return "free", l.get("status") or ""


def cmd_lane_enterable(args: argparse.Namespace) -> None:
    """`session.py lane-enterable [<lane>]` — may a NEW session open inside an EXISTING
    lane? Exit 0 yes, 1 no, 2 cannot-tell-yet (with the reason on stdout). Bare, it lists
    every lane and its answer.

    THREE ANSWERS, NOT TWO (WI-0258). The verb used to answer only from `status == "live"`,
    which folded "I cannot tell yet" into "checked, and it's free" — the exact collapse
    [`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes) names.
    A lane whose liveness evidence has not appeared YET is not a free lane; it is an
    unanswered question, and the honest output is a third state that says so. Exit 2 rather
    than 1 so a caller can distinguish "occupied — do not retry" from "too young — ask
    again in a moment"; `poga resume` treats every non-zero as a refusal and prints the
    reason, so nothing downstream had to change to get this right.

    WHY AGE IS THE MISSING TERM, and why it points the OPPOSITE way from the reaper's.
    `LANE_REAP_MIN_AGE_MIN` exists so a newborn lane is not DELETED before it locks; this
    exists so a newborn lane is not ENTERED before it locks. Same race, opposite verbs, and
    the sizes are unrelated — see `LANE_ENTER_MIN_AGE_SEC` for the measurement.

    The birth time comes from `_lane_birth`, whose documented `st_birthtime` mutability
    hazard breaks the OTHER way here and is therefore stated rather than inherited: a
    dragged-EARLIER birth makes a lane read older, which for the reaper makes its proof
    harder to satisfy (safe) and for this gate makes entry easier to allow (unsafe). It is
    tolerable only because the two cannot coincide in practice — dragging requires a
    restore or an `rsync -t` landing inside the same 30 seconds as the lane's creation.
    The fallback source (`git-registration`, the `gitdir` mtime — the ONLY source on
    Linux, WI-0468) has no birth-drags-with-mtime coupling, but it IS an mtime, so the
    same restore can rewrite it directly; the same "cannot coincide with creation"
    argument is what covers it. An UNRESOLVABLE birth is treated as young, i.e. refused: unknown is never
    "safe to enter" here, which is the same rule `_unlock_if_owner_is_dead` already applies
    to unknown lock ownership.

    The gate behind `poga resume` (WI-0122). Two sessions sharing one worktree is the one
    thing the lane model cannot survive — they would share an index, a branch and a
    journal directory — so the refusal is the whole point of the verb, and it lives here
    rather than in bash because `_scan_lanes` already owns "is a session live in this
    lane" and a second implementation in the launcher would be free to disagree with the
    reaper about the same lane (P16).

    Note the asymmetry with `recover-lanes`, which is deliberate and not an oversight:
    recovery LANDS a lane, so it demands positive proof of death; resume only OPENS one,
    so it needs merely the absence of a live holder. A lane whose owner is unprovable is
    refused by the first and allowed by the second — and that is the right way round,
    because entering a lane whose session is long gone is exactly the walked-away case
    this exists to rescue.

    **That asymmetry survives WI-0258, but the sentence that used to close it did not.**
    It read: the cost of being wrong is a refusal from the runtime's own lock rather than
    a bad land. The runtime's own lock is precisely the evidence that does not exist yet
    during the birth window — and, on the two non-Claude lane paths, never exists at all —
    so the backstop was empty in exactly the cases the gate was wrong. The asymmetry is
    kept because it is right about an ABANDONED lane (old, no evidence → enter, and the
    15-minute `HEARTBEAT_STALE_MIN` is what lets a walked-away lane become enterable
    again). It is qualified by the birth floor because it was never an argument about a
    NEWBORN one, where there is no past session to be permissive toward."""
    lanes = _scan_lanes()
    if not lanes:
        print("no lanes exist under .claude/worktrees/.")
        raise SystemExit(1)
    wanted = getattr(args, "lane", None)
    if not wanted:
        # WI-0140: state the question before the answers. `recover-lanes` asks whether a
        # session is provably OVER; this asks only whether one is sitting here NOW. The
        # two disagree by design about a lane whose owner walked away — refused there,
        # allowed here — and printed as bare verdicts that read as the substrate
        # contradicting itself two minutes apart.
        print("`lane-enterable` asks: is a session IN this lane right now? It only opens "
              "a lane, so absence of a holder is enough — it does not ask, and cannot "
              "answer, whether a past session is provably over (`recover-lanes` does). A "
              "lane too young for its liveness evidence to have appeared yet answers "
              "WAIT, which is neither of those: nobody is in it that we can see, and we "
              "cannot yet tell that nobody is.")
        for l in sorted(lanes, key=lambda x: x["name"]):
            verdict, why = _lane_entry_verdict(l)
            if verdict == "occupied":
                print(f"{l['name']:<10} NO   — {why}")
            elif verdict == "too-young":
                print(f"{l['name']:<10} WAIT — {why}")
            else:
                ahead = _lane_commits_ahead_count(l["branch"])
                extra = f", {ahead} commit(s) not on {_trunk()}" if ahead not in ("", "0") else ""
                print(f"{l['name']:<10} yes  — {l['status']}{extra}")
        return
    match = [l for l in lanes if l["name"] == wanted]
    if not match:
        print(f"no lane named '{wanted}' — see `session.py lane-enterable`.")
        raise SystemExit(1)
    l = match[0]
    verdict, why = _lane_entry_verdict(l)
    if verdict == "occupied":
        print(f"{wanted}: NO — {why}.")
        raise SystemExit(1)
    if verdict == "too-young":
        print(f"{wanted}: WAIT — {why}.")
        raise SystemExit(2)
    print(f"{wanted}: yes — {l['path']}")


def _drive_lane_merge(path: Path) -> subprocess.CompletedProcess:
    """Run the LANE'S OWN `session.py merge`, in the lane. The single seam through which
    recovery touches a stranded lane.

    Not `git -C`, and not an in-process call: the land is a sequence of operations that
    must all resolve against that worktree — its journal, its gitignored sidecar, its
    branch, its `session.config.json` — and re-pointing them one flag at a time is exactly
    how a second, subtly-different land path gets built by accident (P16). Invoking the
    lane's own entry point means recovery inherits every safety property of a normal land
    rather than a weaker copy: the WI-0110 journal close, the ADR-0089 D2 checkpoint
    absorb, the counter land-gates, the merge gate, and the CAS."""
    # `--continue` IS LOAD-BEARING (WI-0288 R2). `merge` closes by default now, and the
    # session in this lane is provably DEAD — nobody is there to agree to the close and
    # no dispatch stands in for them, so a closing `merge` would be refused by the
    # ADR-0113 gate and recovery would quietly stop landing anything, in the one code
    # path whose whole purpose is that stranded work is not lost. Recovery lands the
    # work and leaves the record alone: a journal is closed by the reaper on its own
    # liveness evidence, which is the only actor entitled to close a session it can
    # prove is over.
    return subprocess.run([sys.executable, "session.py", "merge", "--continue"],
                          cwd=str(path), capture_output=True, text=True)


def cmd_recover_lanes(args: argparse.Namespace) -> None:
    """`session.py recover-lanes [--dry-run] [--lane NAME]` — land the work stranded in
    lanes whose session is provably over (WI-0122).

    THE GAP THIS CLOSES. `reap-lanes` deliberately refuses an unmerged lane and prints
    *"cd into the lane and run `session.py merge`"*. That instruction can only be carried
    out by a session INSIDE the lane — and the whole reason the lane is stranded is that
    its session is gone. So the recovery step was addressed to someone who no longer
    exists, and the work sat on a branch nobody would ever land: several such lanes across
    several systems, the fleet's largest red.

    WHAT IT DOES NOT DO IS RE-IMPLEMENT LANDING. It is a CALLER (the WI-0115 shape — the
    defect was between two mechanisms, not inside either): for each provably-dead lane it
    invokes that lane's OWN `session.py merge` with the lane as cwd, which is the same
    entry point a live session uses. That path already closes any journal whose session is
    provably dead (WI-0110), absorbs a stop-checkpoint (ADR-0089 D2), rebases onto the
    trunk, runs the gate, and CAS-advances — so recovery inherits every safety property of
    a normal land instead of a second, weaker copy of it (P16). A lane that cannot land
    cleanly is left EXACTLY as it was, with the blocker named.

    THE SAFETY ARGUMENT IS THE DEATH TEST, and it is deliberately conservative:
    `_scan_lanes` must classify the lane `unmerged` (never `live` — this session and any
    locked lane with a live pid are excluded there), AND its own sidecar must prove the
    session over (`_lane_death_verdict`). Both must agree. `live` and `unknown` are held
    back and printed with their reason — the check says which of the three it found, never
    folding "could not tell" into "nothing to do."

    This is the recovery path for BOTH ways a session stops being there: one that was
    walked away from and never returned to (silence past the grace), and one the runtime
    dropped (an `.ended`/`.gone` marker with no stamped journal). Neither is a corruption
    to be triaged by hand; both are now a verb."""
    lanes = _scan_lanes()
    if args.lane:
        lanes = [l for l in lanes if l["name"] == args.lane]
        if not lanes:
            raise SystemExit(f"recover-lanes: no lane named '{args.lane}'.")
    # WI-0172, and it goes ABOVE the early return because the early return is where the
    # defect was observed. `recover-lanes --lane poga-2` answered "nothing stranded — no
    # unmerged orphan lanes" over a lane holding two commits: correct, since `stranded` is
    # the `unmerged` set and that lane classified `live`, and unreadable as anything but
    # "there is nothing here". A verb whose whole subject is unlanded work must not print
    # a clean bill over unlanded work it can see, even when acting on it is exactly what
    # it must refuse to do.
    # WI-0157: one read of the claim store for the whole render, not one per row.
    _lane_index = lane_claim_index()
    idle_live = _idle_live_lanes(lanes)
    if idle_live:
        print("advisory — these lanes are LIVE, so this verb will not act on them, and it "
              "will not start to: landing under a live session is the harm it is built "
              "around. Named because nothing else names them.")
        for l in idle_live:
            print(f"advisory: {_idle_live_lane_note(l, _lane_index)}")
        for line in _idle_live_lane_advice():
            print(line)
        print("")

    stranded = [l for l in lanes if l["status"] == "unmerged"]
    if not stranded:
        # NAME THE DENOMINATOR (WI-0140's lesson, applied to the empty case). "Nothing
        # stranded" is a claim about the `unmerged` set alone, and saying so is what keeps
        # it from being read as a claim about unlanded work in general — which it is not,
        # and visibly is not whenever the advisory above just printed.
        print("recover-lanes: nothing stranded — no unmerged orphan lanes"
              + (f", though {len(idle_live)} live lane(s) hold unlanded commits (above)."
                 if idle_live else "."))
        return

    held: list[tuple[dict, str, str]] = []
    actionable: list[tuple[dict, str]] = []
    for l in stranded:
        verdict, reason = _lane_death_verdict(l["path"])
        if verdict == "dead":
            actionable.append((l, reason))
        else:
            held.append((l, verdict, reason))

    # WI-0140: NAME THE QUESTION, because the answer alone reads as a contradiction.
    # `recover-lanes` and `lane-enterable` ask genuinely different things — is this session
    # PROVABLY OVER (recovery writes, so it demands proof of death) versus is anyone SITTING
    # HERE NOW (resume only opens, so absence of a holder is enough) — and until now both
    # rendered their answer as the bare word "live". Two minutes apart on lane poga-2 the
    # substrate told one operator that a lane was LIVE and that it was enterable, with
    # nothing on either surface to say the two verbs had been asked different questions.
    # Unifying the predicates was the wrong repair: it would make one verb wrong. Naming
    # them is the right one, so each verb states its question and neither reuses the
    # other's vocabulary.
    if held:
        print("held — `recover-lanes` asks: is the session PROVABLY OVER? It lands work, "
              "so it needs proof of death, and absence of proof is not proof.")
    for l, verdict, reason in held:
        # Deliberately NOT the word "live": that is `lane-enterable`'s vocabulary for a
        # different question. These two tags split the one thing that matters here —
        # whether there is positive evidence of life, or simply no evidence at all.
        tag = "SIGNS OF LIFE" if verdict == "live" else "NO EVIDENCE"
        # WI-0157: the durable identity leads, the slot follows in brackets as the
        # ADDRESS the routing line below tells the reader to type.
        print(f"held:     {lane_identity(l, _lane_index):<22} [{l['name']}] [{tag}] {reason}")
        print(f"          branch {l['branch']} left exactly as it was.")
        # THE ROUTING HALF, and the reason this item was not merely cosmetic. In the
        # observed incident recovery refused and that read as a dead end, while `resume`
        # was open the whole time and was how the lane actually got landed. The claim is
        # provable rather than probed: `stranded` is exactly the lanes whose `_scan_lanes`
        # status is `unmerged`, and `lane-enterable` never refuses an `unmerged` lane as
        # OCCUPIED. WI-0258 added its one other refusal — a lane too young for its
        # liveness evidence to have appeared — which cannot apply to anything reaching
        # this line: a lane is only `stranded` here after `_lane_death_verdict` has looked
        # at its sidecar, and a lane whose birth window has not closed has no session that
        # could have gone quiet. So the route named below stays true by construction, and
        # the wording says "nothing is sitting in it" rather than "it is enterable" —
        # which is the claim actually established.
        print(f"          nothing is sitting in this lane, though — `poga resume "
              f"{l['name'].replace('poga-', '')}` enters it and `session.py merge --continue` lands "
              f"it from inside.")

    for l, reason in actionable:
        ahead = _lane_commits_ahead_count(l["branch"])
        print("")
        print(f"recover:  {lane_identity(l, _lane_index)} [{l['name']}] — branch "
              f"{l['branch']}, {ahead} commit(s) not on {_trunk()}")
        print(f"          dead: {reason}")
        if l["dirty"]:
            print("          note: uncommitted edits in the lane — the land commits them "
                  "as part of the close rather than discarding them.")
        if args.dry_run:
            print("          dry-run — would run `session.py merge` in the lane.")
            continue
        # WI-0312: read the lane's journal ids BEFORE the land, from the lane's own
        # sidecar. They are what the exit below binds ownership and its epoch to, and
        # after the land the branch answer is empty — a merged branch has no journal in
        # its diff (see `lane_session_ids`).
        pre_journals = tuple(lane_session_ids(Path(str(l["path"])) / ".session-state",
                                              l["branch"]))
        proc = _drive_lane_merge(l["path"])
        body = (proc.stdout or "") + (proc.stderr or "")
        for line in body.splitlines():
            if line.strip():
                print(f"          | {line}")
        # The land path reports its own blockers precisely ("rebase conflicts", "gate
        # failed", "no commits ahead") and leaves the branch intact on every one of them.
        # Re-deriving a verdict here would be a second opinion free to disagree with the
        # only one that acted, so the exit code and its own words are the receipt
        # ([`a-close-is-the-banner-not-the-sentence`](habits/master.md#a-close-is-the-banner-not-the-sentence)).
        landed = proc.returncode == 0 and "land:    BLOCKED" not in body
        print(f"          => {'RECOVERED — work is on the trunk' if landed else 'BLOCKED — left intact, nothing lost'}")
        if landed:
            # WI-0312 — recovery's own lane exit, and it needs one precisely BECAUSE of
            # the `--continue` in `_drive_lane_merge`. That flag is load-bearing (nobody
            # is alive in this lane to agree to a close, so a closing `merge` would be
            # refused) but it also means the land runs the one path that does NOT end a
            # session, and the dead lane went on holding its claims, its attention record
            # and its dispatch slot until some later reaper pass happened to notice the
            # branch was gone. Recovery has already PROVEN this session over — that proof
            # is what let it write at all — so it is entitled to free what that session
            # held, and it frees it through the same exit every other route uses rather
            # than growing a fourth way out.
            #
            # This releases HOLDS and nothing else. The journal stays exactly as the
            # reaper will find it: recovery deliberately does not close a session it
            # cannot prove closed, and a cleanup that could reopen or stamp a journal
            # could fabricate the close this whole design refuses to fabricate.
            ok, left = _lane_exit_verify(l["branch"], journals=pre_journals,
                                         reason="teardown",
                                         epoch=_lane_exit_epoch(pre_journals))
            if not ok:
                names = ", ".join(f"{k}/{n}" for k, n in left)
                print(f"          note: these coordination records survived the exit: "
                      f"{names} — re-runnable, and `reap-lanes` sweeps them once the "
                      f"branch is gone.")

    print("")
    verb = "would recover" if args.dry_run else "actioned"
    # NAME THE SET THIS COUNTED OVER (WI-0140). The old line read `0 held (live or
    # unprovable)` as a claim about lanes in general, while `poga resume` in the same
    # minute named nine lanes as held by a live session. Both were true and the pair was
    # unreadable: this verb only ever considers UNMERGED lanes — a lane with nothing
    # stranded on it is not "not held", it was never a candidate. A count whose
    # denominator is invisible is a count that will be misread, so the denominator is
    # printed.
    print(f"recover-lanes: of {len(stranded)} unmerged lane(s) — {verb} "
          f"{len(actionable)} provably over, {len(held)} held for lack of proof. "
          f"Lanes with nothing stranded were not candidates and are not counted here; "
          f"`poga resume` answers the different question of which lanes are free to "
          f"enter.")


def cmd_reap_lanes(args: argparse.Namespace) -> None:
    """`session.py reap-lanes` — crash-safety reaper for orphaned terminal poga lanes
    (ADR-0060 Q5). A `poga` session that dies mid-run leaves an orphaned worktree dir +
    branch behind that no clean `WorktreeRemove` swept. This sweep finds them and, per
    lane:
      - MERGED branch (or no branch — pure dir residue): reaps it — frees the worktree,
        deletes the merged branch, prunes the admin entry. No unlanded work is lost.
      - UNMERGED branch: surfaces it LOUDLY and leaves it fully intact. Never
        auto-discards, never auto-merges — landing is `session.py merge` from the lane,
        and discarding is `discard-phantom-lanes`, which acts only where its predicate
        proves nothing unlanded is lost (WI-0099). This docstring used to name
        `git branch -D`, which `check-bash` denies: advice the substrate itself refuses.
    Live lanes (this session, and any registered+locked lane whose pid is alive) are
    protected. This is the loud, surfaced path (it prints unmerged orphans for a human
    call); `_auto_reap_lanes` runs the SAFE subset silently at each main-checkout session
    start (ADR-0060 Q5, now wired). `--dry-run` reports without acting."""
    lanes = _scan_lanes()
    # The pad sweep runs BEFORE the lane scan is consulted and independently of it: an
    # orphan pad can outlive the lane pool itself (its worktree removed by a route neither
    # teardown path saw), so gating it on "are there lanes?" would leave exactly the case
    # it exists to catch. What it is NOT independent of is `--dry-run`.
    #
    # WI-0291: this call used to sit ABOVE the guard its two neighbours below already
    # shared, so `reap-lanes --dry-run` — whose `--help` reads "Report only; reap nothing"
    # — deleted pads for real and said `removed orphaned lane pad X`, past tense and
    # accurate. `--dry-run` is what an operator reaches for precisely when they do not yet
    # trust the sweep, so a flag that mutates anyway discredits the one affordance that is
    # supposed to be free. The dry branch REPORTS the same set rather than skipping it:
    # silence would leave the dry run's report incomplete, which is a second lie about the
    # same pads, and both branches read that set from one predicate (`orphan_pads`) so the
    # two answers cannot drift. `_auto_reap_lanes` still calls the sweep unconditionally —
    # it has no dry-run mode and never had this defect.
    # WI-0063 / WI-0078: both are lane-pool litter with no owner, and both are reported
    # DISTINCTLY from lane reaping — a gate worktree is not a lane and a freed claim is
    # not a removed directory, so folding them into the lane counts would make the summary
    # line mean three different things
    # ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
    if not args.dry_run:
        for gone in sweep_orphan_pads():
            print(f"reap-lanes: removed orphaned lane pad {gone}")
        for line in _reap_gate_worktrees():
            print(f"reap-lanes:{line}")
        for kind, name in _coord_release_dead_lanes():
            print(f"reap-lanes:  released {kind}/{name} — its holding lane no longer exists")
    else:
        for pad in orphan_pads():
            print(f"reap-lanes: would remove orphaned lane pad {pad.name}")
        residue = _gate_worktree_residue()
        if residue:
            print(f"reap-lanes: would free {len(residue)} leaked gate worktree(s): "
                  + ", ".join(p.parent.name for p in residue))
    # Stranded PROCESSES are always REPORTED and only terminated when asked. A process is
    # the one thing here whose removal cannot be undone by re-running anything, so it does
    # not ride the same automatic path as a directory or a claim
    # ([`confirm-destructive-ops`](habits/master.md#confirm-destructive-ops)/P9).
    stranded = _stranded_lane_processes()
    if stranded:
        print("")
        print("⚠ STRANDED LANE PROCESSES — alive, holding nothing reachable:")
        for p in stranded:
            print(f"  ! pid {p['pid']:<7} {p['lane']:<10} up "
                  f"{p['age_sec'] // 86400}d{p['age_sec'] % 86400 // 3600:02d}h   "
                  f"({p['reason']})")
        if getattr(args, "processes", False) and not args.dry_run:
            for line in _reap_lane_processes():
                print(f"reap-lanes:{line}")
        else:
            print("    Terminate them: `python3 session.py reap-lanes --processes`.")
    if not lanes:
        print("reap-lanes: no lanes found under .claude/worktrees/.")
        return
    lanes_root = _lanes_root()
    live = [l for l in lanes if l["status"] == "live"]
    reapable = [l for l in lanes if l["status"] == "reap"]
    unmerged = [l for l in lanes if l["status"] == "unmerged"]
    dirty = [l for l in lanes if l["status"] == "dirty"]
    # WI-0257. `young` is a lane that would be reapable but is inside the birth window.
    # `--include-young` folds it back in for an operator who watched the lane die and does
    # not want to wait the window out — an opt-OUT of the safe default, never a step the
    # default obliges anyone to take.
    young = [l for l in lanes if l["status"] == "young"]
    if getattr(args, "include_young", False) and young:
        print(f"reap-lanes: --include-young — {len(young)} lane(s) inside the "
              f"{LANE_REAP_MIN_AGE_MIN}m birth window folded into the sweep: "
              + ", ".join(l["name"] for l in young))
        reapable, young = reapable + young, []

    # WI-0136: a merged lane is safe to remove as far as its WORK goes — that is what
    # "merged" means — but its `.session-state` is not work and is not on the branch. If it
    # still holds the only exit marker for an open journal, removing the worktree turns a
    # journal that can be closed at a real recorded time into one that can never be closed
    # at all, because inventing an end time for a session is the precise record-integrity
    # harm the close ritual exists to prevent. So the lane is HELD, exactly like the dirty
    # case and for the same reason: the reap is not undoable and the evidence is.
    held_journal: list[tuple[dict, list]] = []
    _reapable: list[dict] = []
    for l in reapable:
        js = _lane_sidecar_unstamped_journals(Path(l["path"]))
        (held_journal.append((l, js)) if js else _reapable.append(l))
    reapable = _reapable

    for l in live:
        tag = "this session" if l["is_self"] else "live session"
        print(f"live:     {l['name']} ({tag}) — protected.")

    # WI-0172. "protected" was the whole report for a lane whose session is alive but has
    # been at a prompt for hours holding unlanded commits — a true sentence that reads as
    # "nothing here", because protection is the only thing it mentions. The lane stays
    # protected; what it stops doing is passing for a non-event.
    idle_live = _idle_live_lanes(lanes)
    if idle_live:
        print("")
        print("⚠ LIVE LANES HOLDING UNLANDED WORK — long idle; protected, and NOT reachable:")
        # One read of the claim store for the whole block. Inside the loop it was a glob
        # and a JSON parse of every claim file PER ROW — the reason `_idle_live_lane_note`
        # takes the index as a parameter at all.
        _lane_index = lane_claim_index()
        for l in idle_live:
            print(f"  ! {_idle_live_lane_note(l, _lane_index)}")
        print(f"    Silent longer than {LANE_IDLE_ADVISORY_MIN}m, holding commits the trunk does "
              f"not have. A beat")
        print("    proves LIFE; silence proves nothing — so these are reported and never "
              "acted on,")
        print("    however long the silence runs.")
        for line in _idle_live_lane_advice():
            print(line)

    # WI-0082: held back for a REASON, and the reason is printed. Silence here would be
    # the original defect wearing a safer coat — an operator seeing a lane simply absent
    # from the report cannot tell "reaped" from "spared" from "never seen"
    # ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
    if dirty:
        print("")
        print("⚠ LANES HELD BACK — uncommitted work in the worktree; nothing was removed:")
        for l in dirty:
            where = f"branch {l['branch']}" if l["branch"] else "no branch"
            print(f"  ! {l['name']}   {where}   ({l['path']})")
        print("    The branch may well be merged — that says nothing about the working tree,")
        print("    which is why these are not swept.")
        # ADR-0099 D3 / R3's interim rule. The three lines here used to be the
        # cleanest specimen of the brief's RC2: every one of them was addressed to a
        # reader who cannot run it. `git -C <lane> status` is refused by the isolation
        # guard from a lane; `git worktree remove --force` is refused by the
        # destructive-git guard; and "cd into the lane and re-run this" is the WI-0122
        # instruction addressed to a session that does not exist. Until WI-0099's
        # discard verb lands, the honest advice is the sanctioned form plus the park-
        # and-file fallback — never a command the reader must escalate to a human.
        print("    To keep the work:    cd <lane> && python3 session.py merge   (the")
        print("                         sanctioned cross-lane form — the RUNTIME's")
        print("                         worktree guard, not this harness, refuses")
        print("                         `git -C <lane>`; this form it allows)")
        print("    To inspect it:       poga resume <lane>   (there is no read-only")
        print("                         lane-inspect verb; entering it is the sanctioned route)")
        print("    If its session is gone:  python3 session.py recover-lanes --lane <name>")
        print("    To discard it:       python3 session.py discard-phantom-lanes   (WI-0099;")
        print("                         it deletes ONLY where the predicate proves nothing")
        print("                         is lost, and names by lane what it refuses and why)")

    if held_journal:
        print("")
        print("⚠ LANES HELD BACK — merged, but holding the only proof of when a session ended:")
        for l, js in held_journal:
            print(f"  ! {l['name']}   ({l['path']})")
            for sid, ev in js:
                if ev.get("has_ended"):
                    print(f"      journal {sid}: UNSTAMPED — the lane's own exit marker "
                          f"records {ev.get('ended_at') or '?'}, so it is closeable NOW.")
                else:
                    print(f"      journal {sid}: UNSTAMPED and the lane holds no exit "
                          f"marker — no honest end time exists for it yet.")
        print("    The work is landed; the .session-state is not, and removing the worktree")
        print("    deletes it. A journal closed from that marker is a fact; one closed after")
        print("    it is gone would be an invented timestamp, so these are not swept.")
        print("    To clear:  `poga resume <lane>` — its first heartbeat closes the journal at")
        print("               the recorded exit time. Re-run this after and the lane reaps.")

    if young:
        print("")
        print("⚠ LANES HELD BACK — inside the birth window; may still be starting up:")
        for l in young:
            age = l.get("age_min")
            seen = (f"{age:.0f}m since last activity" if age is not None
                    else "age unreadable")
            print(f"  ! {l['name']}   {seen}   ({l['path']})")
        print(f"    A lane younger than {LANE_REAP_MIN_AGE_MIN}m looks MAXIMALLY reapable and")
        print("    may simply not have locked yet: freshly cut branch (so trivially merged),")
        print("    clean tree (so not dirty), no lock (so not live). Unreadable age counts as")
        print("    young — refuse to reap what cannot be proved stale.")
        print("    Leave it:  re-run later; it ages into the sweep on its own.")
        print("    Force it:  `--include-young`, if you watched this lane's session die.")

    if unmerged:
        print("")
        print("⚠ UNMERGED ORPHAN LANES — work is NOT on the trunk; left fully intact:")
        for l in unmerged:
            print(f"  ! {l['name']}   branch {l['branch']}   ({l['path']})")
            # R2a: say when a lane's journal never got its end stamp — a close claim
            # without the stamp was false (the poga-5 close-honesty gap).
            for sid in _lane_unstamped_journals(l["branch"] or ""):
                print(f"      journal {sid}: present but UNSTAMPED — `session.py end` "
                      f"never ran, so any close this session reported was false.")
        # WI-0122: the old text here said "cd into the lane and run `session.py merge`",
        # which is only executable by a session INSIDE the lane — and a lane is stranded
        # precisely because its session is gone. The instruction was addressed to someone
        # who no longer exists, so it was never carried out and the work sat forever.
        print("    To land them:  `python3 session.py recover-lanes` — lands every one "
              "whose session is provably over, and says why for the rest.")
        # WI-0099. This line used to print `git branch -D <branch>` — which `check-bash`
        # DENIES as a destructive force-delete, correctly, since it cannot tell an empty
        # stub from the only copy of someone's work. So the substrate's own advice was a
        # command the substrate then refused, and the only way anyone ever carried it out
        # was by handing it to operator ([`never-route-your-own-work-through-the-user`]). The
        # replacement is the verb whose PREDICATE carries the safety argument: it deletes
        # where deleting is provably a non-event and refuses everything else BY NAME,
        # which is a better answer than the old line even when it declines.
        print("    To discard:    `python3 session.py discard-phantom-lanes` — deletes only")
        print("                   lanes it can PROVE hold nothing unlanded (empty stubs, or")
        print("                   commits already on the trunk by content); refuses the rest")
        print("                   by name. A lane holding real work is meant to be landed,")
        print("                   not discarded — there is deliberately no verb for that.")

    if not reapable:
        if not unmerged and not dirty and not held_journal and not young:
            # WI-0172: qualified rather than bare. "Nothing to reap" is a claim about the
            # REAPABLE set, and it is still true with an advisory row above it — but a
            # reader who takes it as "nothing here" has just been handed the defect this
            # item is about, one line after it was fixed.
            print("reap-lanes: nothing to reap — no orphaned lanes"
                  + (f"; {len(idle_live)} live lane(s) hold unlanded commits (above), and "
                     f"this verb does not touch those." if idle_live else "."))
        return

    if args.dry_run:
        print("")
        print("would reap (merged branch / dir residue):")
        for l in reapable:
            what = f"branch {l['branch']}" if l["branch"] else "no branch — dir residue"
            print(f"  - {l['name']}   ({what})")
        print(f"reap-lanes: dry-run — {len(reapable)} reapable, {len(unmerged)} unmerged kept, "
              f"{len(held_journal)} held on an unstamped journal, {len(young)} held as too "
              f"young, {len(live)} live protected. Re-run without --dry-run to reap.")
        return

    print("")
    print(f"attempting {len(reapable)} orphaned lane(s):")
    failed = []
    for l in reapable:
        print(f"- {l['name']}:")
        ok, lines = _reap_lane(l, lanes_root)
        for line in lines:
            print(line)
        if not ok:
            failed.append(l["name"])
    # WI-0038: count what SUCCEEDED, and name the failures. The old line printed
    # `reaped {len(reapable)}` — the attempt count — so a run where every operation failed
    # and a run where every operation worked printed the same sentence, and an operator
    # reading only the total believed the pool was clean while lanes and branches remained.
    # `declare-what-a-check-assumes`: "tried and could not" gets its own output.
    print(f"reap-lanes: reaped {len(reapable) - len(failed)} of {len(reapable)}; "
          f"kept {len(unmerged)} unmerged; held {len(held_journal)} on an unstamped "
          f"journal; held {len(young)} as too young; {len(live)} live protected.")
    if failed:
        print(f"reap-lanes: FAILED to reap {len(failed)}: {', '.join(failed)} — see the "
              f"per-lane lines above. These are still present.")


#: Subtrees, ANYWHERE under the repo, whose whole contents decide what runs. `.claude/`
#: is the hook and instruction surface — `settings.json` alone carries 42 command entries,
#: and agents, skills and commands under it are read as instructions. `.git/hooks/` is
#: arbitrary execution on the next commit. `.github/workflows/` runs on a CI runner
#: holding whatever secrets CI has. The editor dirs run tasks and debug configurations.
BRIEF_DENIED_DIRS = frozenset({".claude", ".git", ".github", ".vscode", ".idea"})

#: Suffixes something interprets or loads as code. Deliberately NOT `.json`/`.yaml` at
#: large: `dev-environments.json` is a legitimate auto-apply target, and denying JSON
#: wholesale would cost the only delivery this pipeline has ever legitimately made.
#: `.claude/settings.json` is refused for WHERE it lives; the two behaviour-shaping data
#: files operator named are refused BY NAME — see `BRIEF_DENIED_RELPATHS`.
BRIEF_DENIED_SUFFIXES = frozenset({
    ".py", ".pyw", ".pyc", ".pyo", ".pth", ".sh", ".bash", ".zsh", ".ksh", ".fish",
    ".command", ".expect", ".pl", ".rb", ".js", ".mjs", ".cjs", ".ts", ".php", ".lua",
    ".ps1", ".psm1", ".bat", ".cmd", ".applescript", ".scpt", ".osa",
    ".so", ".dylib", ".dll", ".plist",
})

#: Named files, at an EXACT path relative to the repo root, that decide what runs without
#: being code and without living under a denied subtree — so the suffix, name and
#: executable-bit rules are all blind to them (WI-0370 / B16, the live residue of
#: WI-0348). the operator's ruling from the OPS-0007 pack: deny these two now; whether auto-apply
#: should become default-deny with an allowlist is a SEPARATE question and is not
#: answered here.
#:
#: `session.config.json` carries this repo's `settings_extras` — the permission rules and
#: the SessionStart hook COMMANDS that `.claude/settings.json` is generated from. Denying
#: the rendered file while leaving its source reachable guards the copy and not the
#: original, which is the whole defect over again one file upstream.
#:
#: `deploy/registry.json` names every system the deploy runner ships, and from where. It
#: decides what code lands on which machine, which is the same power as a hook with a
#: longer fuse.
#:
#: Keys are relative POSIX paths, lower-cased to match the rest of this guard — on a
#: case-insensitive filesystem `Session.Config.json` IS the same file, and on a
#: case-sensitive one refusing a near-miss costs a surfaced brief, not a wrong write.
BRIEF_DENIED_RELPATHS = {
    "session.config.json":
        "`session.config.json` carries the permissions and SessionStart hook commands "
        "`.claude/settings.json` is generated from",
    "deploy/registry.json":
        "`deploy/registry.json` decides which system is deployed to which machine",
    # WI-0381. The one entry here whose hazard is not "something acts on this file" but
    # "this file decides what LEAVES the repo". Nothing runs the public-cut manifest; it
    # names the files copied into a PUBLIC repository, so a brief that widens it unattended
    # widens what becomes public. Same mailbox, same unattended apply, opposite direction —
    # which is why it gets its own phrase rather than borrowing the execution one.
    "curate/public_cut_manifest.json":
        "it decides what LEAVES this repo — `curate/public_cut_manifest.json` is the "
        "public-cut boundary, and a brief that widens it unattended widens what "
        "becomes public",
}

#: Files that are RUN but carry no suffix to recognise them by — an extension check is
#: blind to every one of these.
BRIEF_DENIED_NAMES = frozenset({
    "makefile", "gnumakefile", "justfile", "rakefile", "dockerfile", "containerfile",
    ".envrc", ".pre-commit-config.yaml", "conftest.py", ".bashrc", ".zshrc",
    ".bash_profile", ".zprofile", ".profile", ".inputrc",
})

def _brief_code_reason(p, root):
    """Why `p` decides what code runs, in a phrase — or None if it is ordinary data.

    WI-0348. Containment to ROOT is not a safe blast radius, because the repo CONTAINS the
    file that decides what commands run. Demonstrated 2026-09-11 (OPS-0007 first run,
    throwaway repo, live tree untouched): an ordinary role-doc-bumping brief carrying a
    second op aimed at `.claude/settings.json` planned `apply`, and the planned file held a
    SessionStart hook running an attacker-chosen command. That is arbitrary command
    execution, unattended, from a GITIGNORED mailbox peer systems and an external
    consultant write into.

    The class, not the three instances it was reported as. The work item named `.claude/`,
    `.py` and `.sh`; sweeping the tracked tree for the actual property — "something runs
    this file's contents" — turns up siblings an extension denylist is blind to. `poga` and
    `err` sit at the repo root with mode 100755 and NO suffix, `bootstrap-kit/git-hooks/`
    ships `pre-commit` and `pre-push` to every member, and `Makefile`-shaped runners are
    named rather than suffixed. So the executable BIT is checked directly, alongside the
    suffix and subtree rules, and each rule names itself in the refusal.

    FIVE RULES, each naming itself: an exact relative path (`BRIEF_DENIED_RELPATHS`), a
    denied subtree, a run-by-name file, an interpreted suffix, and the executable bit.
    The first was added by WI-0370 for the files that change BEHAVIOUR without being code
    — `session.config.json` and `deploy/registry.json` — which the "something runs this
    file" line drawn here was, by construction, blind to.

    RELATIVE TO ROOT, never the absolute path: a lane's own ROOT is
    `<repo>/.claude/worktrees/poga-N`, so a segment scan over the absolute path matches
    `.claude` for EVERY file and denies the entire worktree."""
    try:
        rel_parts = p.relative_to(root).parts
    except ValueError:  # pragma: no cover — containment already refused this
        return "outside the repo"
    named = BRIEF_DENIED_RELPATHS.get("/".join(rel_parts).lower())
    if named:
        # First, so the refusal names THIS file rather than a broader rule that happens
        # to also catch it. `_brief_code_reason`'s contract is that each rule says which
        # one fired; a path denied for being itself must not report as a subtree.
        return named
    for seg in rel_parts[:-1]:
        if seg.lower() in BRIEF_DENIED_DIRS:
            return f"it is under `{seg}/`"
    if p.name.lower() in BRIEF_DENIED_NAMES:
        return f"`{p.name}` is run as a build or shell file"
    if p.suffix.lower() in BRIEF_DENIED_SUFFIXES:
        return f"`{p.suffix}` is executed or interpreted"
    try:
        if p.is_file() and (p.stat().st_mode & 0o111):
            return "it is marked executable"
    except OSError:
        pass
    return None


def _brief_dest(rel, op):
    """A brief-named path, resolved against ROOT and REFUSED if it leaves the repo OR if
    it is a file that decides what code runs.

    An `Apply: auto` brief is applied unattended at session start, so the set of files it
    can reach is a security boundary and not a tidiness rule. `..` in a path field would
    let a brief that arrived in a gitignored mailbox write anywhere the session can — and
    the mailbox is the one input to this pipeline that did not come from the repo.

    Containment was the first half and is not sufficient on its own: `.claude/settings.json`
    is TRACKED, in-repo, and holds the hooks that execute at session start and around every
    tool use (WI-0348). The second half is `_brief_code_reason`.

    THE GUARD LIVES HERE, at the one chokepoint all three brief-supplied path fields
    already pass through — `target-file`, `changelog-prepend`'s `File:`, and `create-file`'s
    `Path:` — so any future op that builds a path inherits it without having to remember
    to. Placing it per-op would repeat the exact shape of the defect 121f143e fixed, where
    one of three siblings did not call the guard."""
    p = (ROOT / rel).resolve()
    root = ROOT.resolve()
    if p != root and root not in p.parents:
        raise SurfaceBrief(f"{op}: path escapes the repo: {rel}")
    why = _brief_code_reason(p, root)
    if why is not None:
        raise SurfaceBrief(
            f"{op}: refuses a path that decides what code runs, or what leaves this "
            f"repo — {why}: {rel}. "
            f"An `Apply: auto` brief is applied unattended; this one surfaces for a "
            f"human to read instead.")
    return p


class SurfaceBrief(Exception):
    """Raised to route a brief to the surface path with a human-readable reason. Not an
    error — a classification. A malformed or ambiguous brief is surfaced, never
    half-applied."""


def evaluate_brief(brief_path):
    """Classify + plan one brief. Returns a Plan; never writes. Applies only if the
    brief is `apply: auto`, its base version matches, and every op verifies against an
    in-memory copy (whole-brief atomicity)."""
    text = brief_path.read_text(encoding="utf-8")
    header, body = parse_frontmatter(text)
    plan = Plan(brief_path, header.get("edit-id", brief_path.stem))
    try:
        apply_mode = header.get("apply", "").strip().lower()
        if apply_mode != "auto":
            raise SurfaceBrief(
                "Apply: manual (or no `apply: auto` header)" if apply_mode in ("", "manual")
                else f"unrecognised apply mode: {apply_mode!r}")
        missing = [k for k in REQUIRED_BRIEF_HEADER if not header.get(k)]
        if missing:
            raise SurfaceBrief(f"header missing required field(s): {', '.join(missing)}")
        # THROUGH `_brief_dest` — the third site of this class, swept after fixing
        # `create-file` rather than waiting to be shown it separately. `target-file`
        # cannot invent a file: it needs one that exists and carries a matching
        # `**Version:**` line. That is not narrow enough to be safe, because EVERY OTHER
        # MEMBER'S ROLE DOC is exactly such a file in a sibling directory — so an
        # unguarded join let a brief in this Architect's gitignored mailbox edit another
        # system's role doc unattended, in a repo it has no authority over.
        target = _brief_dest(header["target-file"], "target-file")
        if not target.is_file():
            raise SurfaceBrief(f"target-file does not exist: {header['target-file']}")
        target_text = target.read_text(encoding="utf-8")
        cur = current_version(target_text)
        expected = header["expected-base-version"]
        proposed = header["proposed-new-version"]
        plan.proposed_version = proposed
        if cur is None:
            raise SurfaceBrief("target-file has no single `**Version:**` line — cannot verify base")
        if _norm_version(cur) != _norm_version(expected):
            raise SurfaceBrief(f"version drift: target is v{cur}, brief expects v{_norm_version(expected)}")
        # `originals` is what each touched file held BEFORE this brief. It exists because
        # `changelog-prepend` can now edit a file that already exists (ADR-0123), so
        # "in `copies` but not the target" stopped meaning "created by this brief" — the
        # distinction the no-op check and the `+N new file(s)` reason both ride on.
        copies = {target: target_text}
        originals = {target: target_text}
        op_count = 0
        for op_type, section_lines in split_op_sections(body):
            fields, blocks = extract_fields_and_blocks(section_lines)
            op_count += 1
            if op_type == "replace":
                if "before" not in blocks or "after" not in blocks:
                    raise SurfaceBrief("replace: needs both ~~~before and ~~~after blocks")
                copies[target] = apply_replace(copies[target], blocks["before"], blocks["after"])
            elif op_type == "version-bump":
                copies[target] = apply_version_bump(copies[target], expected, proposed)
            elif op_type == "changelog-prepend":
                if "after" not in fields:
                    raise SurfaceBrief("changelog-prepend: needs an `After:` anchor line")
                if "content" not in blocks:
                    raise SurfaceBrief("changelog-prepend: needs a ~~~content block")
                # OPTIONAL `File:` — the changelog need not live in the target file
                # (ADR-0123). Without it the op is exactly what it was: prepend into the
                # brief's one `target-file`, which is what every member's brief does and
                # what every existing brief on disk means.
                #
                # WHY THE OP AND NOT THE HEADER. `target-file` is the file whose
                # `**Version:**` line gates the whole brief — the base-version check, the
                # bump, and the did-it-move verify all key on it. A changelog sibling
                # carries no version line, so it can never be a second `target-file`; it
                # is one op's destination, and that is the grain the field belongs at.
                # Without this, a split member's every role-doc brief regresses to
                # `Apply: manual`, against ADR-0049.
                dest = target
                if fields.get("file"):
                    dest = _brief_dest(fields["file"], "changelog-prepend")
                    if not dest.is_file():
                        raise SurfaceBrief(
                            f"changelog-prepend: File: does not exist: {fields['file']}")
                    if dest not in copies:
                        copies[dest] = originals[dest] = dest.read_text(encoding="utf-8")
                copies[dest] = apply_changelog_prepend(copies[dest], fields["after"], blocks["content"])
            elif op_type == "create-file":
                if "path" not in fields:
                    raise SurfaceBrief("create-file: needs a `Path:` line")
                if "content" not in blocks:
                    raise SurfaceBrief("create-file: needs a ~~~content block")
                # THROUGH `_brief_dest`, not a bare join. This op chooses its own
                # destination, which makes it the one that most needs the containment
                # check — and it was the sibling that did not call it. Measured
                # 2026-09-11 (OPS-0007 sitting): `../escape.md`, `docs/../../escape2.md`
                # and an ABSOLUTE `/tmp/...` path each planned `apply`, the last escaping
                # without containing `..` at all because joining an absolute path
                # discards ROOT entirely.
                newp = _brief_dest(fields["path"], "create-file")
                if newp.exists() or newp in copies:
                    raise SurfaceBrief(f"create-file: path already exists: {fields['path']}")
                content = blocks["content"]
                copies[newp] = content if content.endswith("\n") else content + "\n"
            else:
                raise SurfaceBrief(f"unknown operation: `## op: {op_type}`")
        after_ver = current_version(copies[target])
        if _norm_version(after_ver or "") != _norm_version(proposed):
            raise SurfaceBrief(
                f"version not moved to proposed v{_norm_version(proposed)} "
                f"(target ends at v{after_ver}) — a version-bump op is required")
        created = [p for p in copies if p not in originals]
        edited = [p for p in copies if p in originals and copies[p] != originals[p]]
        if not created and not edited:
            raise SurfaceBrief("brief is a no-op (nothing would change)")
        plan.action = "apply"
        plan.touched = copies
        plan.reason = (
            f"{op_count} op(s); {header['target-file']} v{_norm_version(expected)} -> "
            f"v{_norm_version(proposed)}"
            + (f"; +{len(created)} new file(s)" if created else "")
            + (f"; also edits {', '.join(sorted(q.name for q in edited if q != target))}"
               if len(edited) > 1 else ""))
    except SurfaceBrief as s:
        plan.action = "surface"
        plan.reason = str(s)
    return plan


def file_applied_brief(plan, applied_dir, stamp):
    """Move pending/<id>.md -> applied/<id>.md, stamping applied metadata in frontmatter."""
    text = plan.brief_path.read_text(encoding="utf-8")
    stamp_lines = (f"applied: {stamp}\napplied-at-version: "
                   f"{_norm_version(plan.proposed_version)}\nstate: applied\n")
    if text.startswith("---"):
        end = text.find("\n---", 3)
        if end != -1:
            text = text[: end + 1] + stamp_lines + text[end + 1:]
    applied_dir.mkdir(parents=True, exist_ok=True)
    dest = applied_dir / plan.brief_path.name
    atomic_write(dest, text)
    plan.brief_path.unlink()
    return dest


def pending_briefs(pending):
    if not inbox_visible(pending):
        return []
    return sorted(p for p in pending.glob("*.md") if p.name != "index.md")


def cmd_apply_briefs(args: argparse.Namespace) -> None:
    """Auto-adopt conforming briefs; surface the rest. Fails open — never bricks startup."""
    mode = "status" if getattr(args, "status", False) else \
           "dry-run" if getattr(args, "dry_run", False) else "apply"
    if mode == "apply" and _cloud_start_quiet():
        mode = "dry-run"   # WI-0484: a cloud container's start writes nothing tracked
    try:
        _apply_run(mode)
    except Exception:  # fail open — never brick startup
        print("Apply: errored; applied nothing. Surfacing for manual handling:", file=sys.stderr)
        import traceback
        traceback.print_exc()
        print("Apply: apply-briefs errored — applied nothing (see stderr); handle the inbox manually.")


def _dispatch_dir(create: bool = False) -> Path | None:
    """`<git-common-dir>/poga-coord/dispatch` — the dispatch records. Deliberately NOT a
    COORD_KINDS member: a dispatch plan is not a hold, so it must survive the TTL reaper
    and `_lane_exit_release` at lane teardown (the lane that dies is often the one
    that just landed an item the queue still needs)."""
    common = _git_common_dir()
    if common is None:
        return None
    d = common / COORD_DIRNAME / DISPATCH_DIRNAME
    if create:
        try:
            d.mkdir(parents=True, exist_ok=True)
        except Exception:
            return None
    return d


def _dispatch_read(did: str) -> dict | None:
    d = _dispatch_dir()
    if d is None:
        return None
    return _coord_read(d / f"{did}.json")


def _dispatch_write(rec: dict) -> bool:
    d = _dispatch_dir(create=True)
    if d is None:
        return False
    try:
        atomic_write(d / f"{rec['dispatch_id']}.json",
                     json.dumps(rec, ensure_ascii=False, indent=2) + "\n")
        return True
    except Exception:
        return False


def _dispatch_snapshot() -> tuple[str | None, dict]:
    """This session's pinned ordinal→id snapshot, as (snapshot_id, mapping).

    (None, {}) when no snapshot has been pinned — a DISTINCT answer from "pinned and
    empty" (`declare-what-a-check-assumes`). Resolving "items 1-10" against a list this
    session never saw would silently dispatch a different ten items than the ones the
    operator read."""
    sid = os.environ.get("CLAUDE_CODE_SESSION_ID", "app")
    try:
        raw = json.loads((ROOT / ".session-state" / f"wi-snapshot-{sid}.json")
                         .read_text(encoding="utf-8"))
    except Exception:
        return None, {}
    mapping = raw.get("mapping")
    if not isinstance(mapping, dict) or not mapping:
        return None, {}
    return raw.get("snapshot_id"), mapping


def _dispatch_parse_range(spec: str) -> list[str]:
    """Parse `1-10`, `1,3,5`, `1-3,7`, or explicit `WI-0047` tokens into an ordered,
    de-duplicated token list. Ordinals stay strings here; they resolve later against the
    snapshot, so an unresolvable one can be named rather than guessed."""
    out: list[str] = []
    for chunk in spec.replace(" ", "").split(","):
        if not chunk:
            continue
        m = re.fullmatch(r"(\d+)-(\d+)", chunk)
        if m:
            lo, hi = int(m.group(1)), int(m.group(2))
            if lo > hi:
                lo, hi = hi, lo
            out.extend(str(i) for i in range(lo, hi + 1))
        else:
            out.append(chunk.upper() if chunk.lower().startswith("wi-") else chunk)
    seen, uniq = set(), []
    for t in out:
        if t not in seen:
            seen.add(t)
            uniq.append(t)
    return uniq


def _dispatch_resolve(tokens: list[str], mapping: dict
                      ) -> tuple[list[str], list[str], dict[str, str]]:
    """(resolved WI ids, unresolvable tokens, why each is unresolvable).

    An ordinal not in the snapshot and an id not in the store are both UNRESOLVABLE and
    named — never silently dropped, which would turn "do 1-10" into "do the eight of them
    I could find".

    WI-0239 adds the third element. Unresolvable still means unresolvable — this tree
    cannot read the body, so it cannot brief a lane on it — but "no such item" and "a lane
    that has not landed is holding it" are different facts with different remedies, and
    reporting the second as the first sends the operator to fix a range that is correct.
    """
    known = {it["id"] for it in _wi_parse()}
    ids, bad = [], []
    for t in tokens:
        wid = mapping.get(t, t if t in known else None)
        if wid is None or wid not in known:
            bad.append(t)
        elif wid not in ids:
            ids.append(wid)
    # Only WI-shaped tokens can be probed; an unmapped ORDINAL is a fact about the pinned
    # snapshot, not about the store, and `_wi_absent_cause` correctly says nothing.
    return ids, bad, _wi_absent_cause(bad)


def _wi_declared_paths(item: dict) -> tuple[set[str], list[str]]:
    """An item's declared independence list: (paths it touches, tokens that are not paths).

    WI-0376 clause 1. `dispatch` had no overlap check of any kind — a wave was bounded by
    `blocked-by` and the cap and by nothing else, which is why four `deploy/runner.py`
    items were planned into a single wave of five and why the waves in the OPS-0007 pack
    are composed BY HAND from the files each item names. This is the parse that retires
    that hand-composition.

    THE READING IS LITERAL, for `_wi_readiness`'s reason: which files an item "really"
    touches is a judgment call, and a judgment call in code is unpredictable, unarguable
    and different every time the model behind it changes. A `FILES:` line an author wrote
    on purpose is a declaration — contestable, and fixable by editing one line.

    Two returns, never one, because "declared nothing" and "declared something I could not
    read" are different facts and the plan surface prints them differently
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
    WI-0350's real declaration is `FILES: deploy/runner.py, the registry schema.` — one
    path and one prose fragment naming something real that is not a path. Counting the
    fragment as a path would invent a file; dropping it silently would report the item as
    fully assessed when a third of its declaration was discarded unread.

    The declaration WRAPS: two of the four real ones run onto a second line. It is read to
    the first blank line or to the next uppercase marker, whichever comes first, so a
    `FILES:` immediately followed by `SEQUENCING:` cannot swallow its neighbour."""
    body = item.get("notes") or ""
    paths: set[str] = set()
    prose: list[str] = []
    lines = body.splitlines()
    for i, line in enumerate(lines):
        m = WI_FILES_RE.match(line)
        if not m:
            continue
        chunk = [m.group(1)]
        for nxt in lines[i + 1:]:
            if not nxt.strip() or re.match(r"^[^\S\r\n]*(?:[-*][^\S\r\n]+)?[A-Z][A-Z -]{2,}:",
                                           nxt):
                break
            chunk.append(nxt)
        for raw in " ".join(chunk).split(","):
            tok = raw.strip().rstrip(".").strip()
            if not tok:
                continue
            # A trailing parenthetical is the author annotating the entry, not naming a
            # second thing. Strip it before the word test, or every annotated path in the
            # store reads as unparseable prose and its item reports as partly assessed.
            ann = WI_ANNOTATED_PATH_RE.match(tok)
            head = ann.group(1).rstrip(".") if ann else tok
            (paths.add(head) if WI_PATHISH_RE.match(head) else prose.append(tok))
    return paths, prose


def _wi_path_collisions(a: set[str], b: set[str]) -> set[str]:
    """The declared entries two items genuinely share.

    A directory entry (`adr/`) collides with anything beneath it, which is the whole point
    of being allowed to declare one — WI-0382 says `adr/` precisely because it will touch
    files inside it that it cannot enumerate in advance. Symmetric, so the answer does not
    depend on which item the caller happened to look at first.

    WHAT AN EMPTY ANSWER DOES NOT MEAN. This bounds DECLARED overlap, never actual
    overlap, and the gap is not a rounding error: a change to one function's signature
    drags in every sibling that calls it, and no pre-flight list predicts which those are —
    measured on an earlier wave whose ten pairwise file-set intersections were all empty
    and whose lanes collided anyway. So "no collision" is "nothing DECLARED collides", one
    real check stronger than the nothing that was here before and well short of a
    guarantee. The plan surface is careful to say only that, which is also why the
    unassessed set is printed rather than passed over
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes))."""
    hits: set[str] = set()
    for x in a:
        for y in b:
            if x == y:
                hits.add(x)
            elif x.endswith("/") and y.startswith(x):
                hits.add(x)
            elif y.endswith("/") and x.startswith(y):
                hits.add(y)
    return hits


def _wi_unlanded_builders() -> dict[str, list[str]]:
    """Work-item id → the branches holding COMMITTED work for it that is not on the trunk.

    WI-0376 clause 3: built-but-held and unstarted are different states, and a plan that
    conflates them re-dispatches finished work — a second lane opens, redoes what is
    already written on a branch nobody landed, and the two then collide.

    Status cannot answer this. `held` means a human parked the item, never that its code
    exists; and this repo has recorded both halves of the divergence — an item reading
    `done` whose fix never left its lane, and a landed fix whose item was never flipped.
    The only honest evidence is the commits themselves.

    `git cherry` rather than `trunk..branch`, for the WI-0147 reason: a lane whose work was
    recovered into a sibling and landed there carries DIFFERENT SHAs for identical
    patches, so reachability reports it as unlanded forever and the item could never be
    dispatched again. `+` means no equivalent patch is on the trunk.

    ASSUMES the item id appears in the commit message, which is this repo's convention and
    not an invariant — an item built under a branch whose commits never name it reads as
    unstarted here. That is the direction that fails safe: it plans a lane that may
    duplicate work, which is today's behaviour, rather than refusing to dispatch an item
    whose evidence was never written down. Fail-open for the same reason — a probe that
    cannot run must not take the dispatch down with it."""
    out: dict[str, list[str]] = {}
    try:
        trunk = _trunk()
        r = sh(["git", "for-each-ref", "--format=%(refname:short)", "refs/heads/"],
               check=False)
        if r.returncode != 0:
            return {}
        for branch in [b.strip() for b in (r.stdout or "").splitlines() if b.strip()]:
            if branch == trunk:
                continue
            ch = sh(["git", "cherry", f"refs/heads/{trunk}", f"refs/heads/{branch}"],
                    check=False)
            if ch.returncode != 0:
                continue
            shas = [ln.split()[1] for ln in (ch.stdout or "").splitlines()
                    if ln.startswith("+") and len(ln.split()) > 1]
            if not shas:
                continue
            log = sh(["git", "log", "--no-walk", "--format=%s%n%b", *shas], check=False)
            if log.returncode != 0:
                continue
            for wid in sorted(set(WI_ID_IN_TEXT_RE.findall(log.stdout or ""))):
                out.setdefault(wid, []).append(branch)
    except Exception:
        return {}
    return out


def _dispatch_order(ids: list[str]) -> tuple[list[str], dict[str, list[str]], dict[str, str]]:
    """Topologically order the selected ids on `blocked-by`.

    Returns (ordered, held, skipped):
      ordered — runnable now or once an in-range blocker lands, in dependency order
      held    — id → live blockers that are NOT in this range (can't run in this dispatch)
      skipped — id → why (already terminal, or already claimed by a live lane)

    A blocker that is done/superseded does not block. A cycle lands in `held` rather
    than being broken arbitrarily — an arbitrary break silently picks a wrong order."""
    items = {it["id"]: it for it in _wi_parse()}
    live = {i for i, it in items.items() if it.get("status") not in WI_TERMINAL}
    claims = _coord_list("claims")
    # WI-0259: an item another dispatch is mid-spawn has no claim yet — the child writes
    # that at its own startup — so without this the plan surface prints `will spawn` for
    # an item it cannot honour. Sweep first so a guard whose child HAS since claimed is
    # gone before it is read as a live spawn.
    _dispatch_item_sweep()
    spawning = _coord_list(DISPATCH_ITEM_KIND)
    sel = [i for i in ids if i in items]

    held: dict[str, list[str]] = {}
    skipped: dict[str, str] = {}

    # Pass 1 — what this dispatch will not spawn at all.
    for wid in sel:
        it = items[wid]
        if it.get("status") in WI_TERMINAL:
            skipped[wid] = f"already {it.get('status')}"
        elif wid in claims:
            rec = claims[wid]
            skipped[wid] = f"claimed by {rec.get('branch') or rec.get('session_id', '?')}"
        elif wid in spawning:
            # `_dispatch_order` runs once, at dispatch creation, BEFORE this dispatch has
            # drawn any guard of its own — so every guard seen here belongs to someone
            # else and there is no self-skip to exclude.
            skipped[wid] = (f"being spawned by dispatch "
                            f"{spawning[wid].get('dispatch_id') or '?'}")
        else:
            # WI-0288 R3 (4): the readiness gate. LAST of the four, deliberately — the
            # three above are facts about this dispatch (already done, someone else has
            # it), and reporting "no acceptance criteria" for an item that is simply
            # already claimed would send the operator to edit an item that needs nothing.
            # A SKIP, not a refusal of the whole wave: it lands in the same bucket the
            # plan surface already prints, so one unready item never costs the other nine
            # their run.
            unready = _wi_readiness(it)
            if unready:
                skipped[wid] = unready

    # Pass 1b (WI-0376) — two states pass 1 cannot see, both of which end with two lanes
    # writing the same lines. LAST again, and for pass 1's reason: an item already claimed
    # or already done needs no report about the files it declares.
    #
    # THE COLLISION RULE IS FIRST-DECLARED-WINS, in the operator's given order. It has to
    # be some rule and it has to be stable; picking by "importance" would need a priority
    # field the store deliberately does not have, and picking by id would silently reorder
    # a range the operator wrote deliberately. The loser is SKIPPED rather than reordered
    # within the wave, because the queue drains head-first up to the cap and an item merely
    # placed later can still be spawned alongside the one it collides with — deferring it
    # to a later dispatch is the only placement that actually holds them apart.
    unlanded = _wi_unlanded_builders()
    claimed_paths: list[tuple[str, set[str]]] = []
    for wid in [w for w in sel if w not in skipped]:
        if wid in unlanded:
            skipped[wid] = (f"BUILT BUT NOT LANDED — commits naming it sit on "
                            f"{', '.join(unlanded[wid])}, unlanded. Land or discard that "
                            f"work; dispatching it again writes it twice")
            continue
        mine, _prose = _wi_declared_paths(items[wid])
        shared, earlier = set(), ""
        for prev, theirs in claimed_paths:
            shared = _wi_path_collisions(mine, theirs)
            if shared:
                earlier = prev
                break
        if shared:
            skipped[wid] = (f"collides with {earlier} on {', '.join(sorted(shared))} — "
                            f"two lanes editing one file is a merge they both lose; "
                            f"re-run dispatch for it once {earlier} has landed")
        else:
            claimed_paths.append((wid, mine))
    candidates = [w for w in sel if w not in skipped]

    # Pass 2 — a live blocker this dispatch will not itself spawn HOLDS the dependent.
    # The blocker set is `candidates`, not `sel`: an in-range blocker that was skipped
    # because a live lane already claimed it is still unfinished work, so releasing its
    # dependent here would start the dependent ahead of the dependency it names.
    runnable: list[str] = []
    for wid in candidates:
        blockers = [b for b in items[wid].get("blocked_by") or [] if b in live]
        unmet = [b for b in blockers if b not in candidates]
        if unmet:
            held[wid] = unmet
        else:
            runnable.append(wid)

    # Kahn over the in-range edges only; whatever cannot be emitted is a cycle.
    pending = {w: [b for b in (items[w].get("blocked_by") or [])
                   if b in runnable and b != w] for w in runnable}
    ordered: list[str] = []
    while True:
        free = [w for w in runnable if w not in ordered and not
                [b for b in pending[w] if b not in ordered]]
        if not free:
            break
        # Preserve the operator's given order among equally-free items.
        ordered.extend(free)
    for w in runnable:
        if w not in ordered:
            held[w] = [b for b in pending[w] if b not in ordered] or ["dependency cycle"]
    return ordered, held, skipped


def _lane_names_in_use() -> set[str]:
    """Every poga lane that currently exists — worktree dir OR un-landed lane branch.

    A crashed-but-unlanded lane is still in use: its branch holds work nobody has
    landed, and `_lane_taken` refuses to reissue the slot for exactly that reason."""
    seen: set[str] = set()
    root = _shared_work_root()
    wt = root / ".claude" / "worktrees"
    if wt.is_dir():
        for p in wt.iterdir():
            if p.is_dir() and p.name.startswith("poga-"):
                seen.add(p.name)
    r = sh(["git", "for-each-ref", "--format=%(refname:short)",
            "refs/heads/worktree-poga-*"], check=False)
    for ref in (r.stdout or "").split():
        seen.add(ref.replace("worktree-", "", 1))
    return seen


def _dispatch_item_title(wid: str) -> str:
    """This tree's title for `wid`, or `""` when it has none.

    One reader for a lookup two callers need (the spawner recording it on the slot, and a
    brief falling back to its own tree), and fail-quiet: a store that cannot be read costs
    a brief its title, never its brief."""
    try:
        for it in _wi_parse():
            if it["id"] == wid:
                return it["title"]
    except Exception:
        return ""
    return ""


def _dispatch_brief_state(item: str, block: str | None = None) -> tuple[str, str]:
    """Did this lane's session start actually carry its dispatch brief?

    `("briefed" | "unbriefed" | "unknown", detail)` — THREE states, never two
    ([`declare-what-a-check-assumes`]). "Could not tell" must not be folded into either
    verdict: reporting a healthy lane as unbriefed would strand it worse than the bug this
    detector exists to find, and reporting an unreadable one as briefed restores the bug.

    WI-0390 MOVED THE QUESTION, because it moved the channel. This used to scan the
    RUNTIME PROCESS'S argv for the item id, which was the right witness while the brief
    was the runtime's trailing argument. It no longer is — and a detector still asking the
    old question would answer `unbriefed` for every correctly-briefed lane in the fleet
    and send `_dispatch_confirm_briefs` to type a duplicate brief into each one. A guard
    that fires on correct code gets deleted; one that fires on correct code AND acts on it
    does damage first. The witness now is the orientation block itself: the same string
    the receipt is written about is the string appended to what the lane is given, so this
    is a claim about the delivery that happened, not an inference from a process tree.

    `block` is passed by the caller that holds it. Recomputing it here (the default) is
    the same pure function over the same coord-store records, so the two agree by
    construction rather than by timing."""
    if not item:
        return "unknown", "no POGA_DISPATCH_ITEM in the environment"
    if block is None:
        try:
            block = _dispatch_brief_block(wid=item)
        except Exception as e:
            return "unknown", f"could not resolve this lane's brief ({e})"
    if (block or "").strip():
        return "briefed", "the session-start orientation carries the brief"
    # Resolvable-to-nothing is a MEASUREMENT, not a read failure: the environment named a
    # dispatched item and the brief for it came back empty. That is the state a re-brief
    # exists for.
    return "unbriefed", f"no brief could be built for {item}"


def _dispatch_item_sweep() -> int:
    """Release every cross-dispatch item guard whose item is now CLAIMED (WI-0259).

    The guard's whole job is to bridge spawn → self-claim. Once the claim exists the claim
    IS the exclusion — `_dispatch_order` has skipped claimed items since it was written —
    so the guard has nothing left to protect and can go immediately rather than sitting out
    its clock in front of a fast re-dispatch.

    A FAST PATH, NOT THE MECHANISM. This runs on the two paths that care (planning and
    spawning) and on no schedule of its own, so it fires only if some dispatch happens to
    run while the claim is live — which is likely over a lane's hours-long life, and
    promised by nothing. `DISPATCH_ITEM_TTL_SECONDS` is what actually bounds the guard;
    read this as the guarantee and the 15 minutes stops looking load-bearing exactly when
    it is. Never raises — a sweep that fails must not break a dispatch."""
    n = 0
    try:
        claims = _coord_list("claims")
        for wid, rec in _coord_list(DISPATCH_ITEM_KIND).items():
            if wid in claims and _coord_release(
                    DISPATCH_ITEM_KIND, wid, rec.get("session_id") or "",
                    force=True, reason="claimed"):
                n += 1
    except Exception:
        pass
    return n


def _dispatch_item_guard(wid: str, did: str, identity: str) -> tuple[bool, dict]:
    """Draw the machine-wide right to spawn `wid`, across ALL dispatches (WI-0259).

    Returns (drawn, blocking_holder). Two halves, and they are not equally strong — say
    so rather than let the weaker one pass for the stronger
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)):

      • ACROSS SESSIONS the draw is atomic. `_coord_try_acquire` is an exclusive-create,
        so two lanes landing at the same instant cannot both take it. This is the case
        that produced the defect — a dispatch drained by a landing lane racing a fresh
        `poga dispatch` — and it is fully closed.
      • WITHIN ONE SESSION the check is read-then-acquire, and therefore not atomic.
        `_coord_mine` matches on session_id OR journal, so a second dispatch from the
        same session RECLAIMS its own guard however the name is keyed; the holder's
        `dispatch_id` is the only thing that can tell the two apart, and reading it means
        reading before acquiring. The residual race is the microseconds between the read
        and the create — against the minutes-wide window this closes — and it needs two
        `poga dispatch` processes running concurrently in one session, which a terminal
        serialises. Bounded and named, not hidden."""
    holder = None
    try:
        d = _coord_dir(DISPATCH_ITEM_KIND)
        if d is not None:
            rec = _coord_read(d / f"{wid}.json")
            if rec is not None and not _coord_expired(rec):
                holder = rec
    except Exception:
        holder = None
    if holder is not None and str(holder.get("dispatch_id") or "") != did:
        return False, holder
    ok, blocker = _coord_try_acquire(
        DISPATCH_ITEM_KIND, wid, identity, DISPATCH_ITEM_TTL_SECONDS,
        dispatch_id=did, item=wid)
    return (True, {}) if ok else (False, blocker)


def _dispatch_slot_path(did: str, wid: str) -> Path | None:
    d = _coord_dir(DISPATCH_SPAWN_KIND)
    if d is None:
        return None
    return d / f"{did}__{wid}.json"


def _dispatch_write_receipt(block: str | None = None) -> None:
    """WI-0248: the lane records, on the dispatch's own slot, whether it was briefed.

    This is the receipt half of "a spawn receipt, not a process launch". It is written by
    the LANE — the only party that can see what the runtime actually received — onto the
    record the spawner already created for it, so the two halves meet without a
    coordinator.

    Fail-open in every direction. A receipt problem must never be the thing that breaks a
    session start; a missing receipt is a state the reader handles (`pending`), not an
    error."""
    try:
        did = os.environ.get("POGA_DISPATCH", "").strip()
        wid = os.environ.get("POGA_DISPATCH_ITEM", "").strip()
        if not did or not wid:
            return
        path = _dispatch_slot_path(did, wid)
        if path is None or not path.is_file():
            return
        rec = _coord_read(path)
        if rec is None:
            return
        # WI-0390: `block` is the orientation the caller is about to hand the lane. Passed
        # in rather than re-derived so the receipt is about THIS start's delivery.
        state, detail = _dispatch_brief_state(wid, block)
        rec["brief"] = state
        rec["brief_detail"] = detail
        rec["brief_at"] = _coord_iso(time.time())
        rec["brief_lane"] = _current_branch().replace("worktree-", "", 1)
        atomic_write(path, json.dumps(rec, ensure_ascii=False, indent=2) + "\n")
    except Exception:
        return


def _dispatch_lane_for(did: str, wid: str) -> str:
    """The lane name this dispatch item drew, from the lane-alloc record it already
    writes. No new bookkeeping: `_lane_alloc_reserve` has stamped `dispatch_id` and
    `dispatch_item` onto the reservation since WI-0156.

    INCLUDE_EXPIRED IS LOAD-BEARING, and the bug it fixes hides in the failure case.
    The reservation carries a 5-minute TTL refreshed by heartbeats, and heartbeats ride on
    tool calls — so AN UNBRIEFED LANE NEVER REFRESHES IT. Five minutes after a lost brief
    the record expires, a live-only listing stops returning it, and the lane becomes
    unfindable exactly when something wants to name or repair it: `_dispatch_lane_working`
    degrades from `False` (idle) to `None` (cannot tell), and the unbriefed report goes
    silent about the one lane it exists for. A lane that goes hours without a heartbeat
    goes from resolving its slot name (e.g. `poga-4`) to resolving nothing.

    The TTL governs whether the SLOT may be reissued, never whether the lane exists — that
    question is answered by the worktree and the branch, which outlive any reservation."""
    try:
        for lane, rec in (_coord_list(LANE_ALLOC_KIND, include_expired=True) or {}).items():
            if (str(rec.get("dispatch_id") or "").strip() == did
                    and str(rec.get("dispatch_item") or "").strip() == wid):
                return lane
    except Exception:
        pass
    return ""


def _dispatch_lane_working(lane: str) -> bool | None:
    """Has this lane actually STARTED WORKING? True / False / None (cannot tell).

    Ground truth, and deliberately independent of the argv receipt: the ADR-0055 lazy-start
    marker is written by the SessionStart hook and CONSUMED BY THE FIRST HEARTBEAT, and
    heartbeats are driven by tool calls. So a lane that was never told to do anything keeps
    its `.pending-start` forever — *"a phantom preload never beats."*

    This answers even when no receipt exists at all (the hook never ran), which is why both
    signals are kept rather than collapsed into one."""
    if not lane:
        return None
    try:
        sd = _shared_work_root() / ".claude" / "worktrees" / lane / ".session-state"
        if not sd.is_dir():
            return None
        pend = list(sd.glob("*.pending-start"))
        if not pend:
            return True
        # A marker with a LIVE sibling that has since beaten is a session that started
        # normally; only an unconsumed marker means no tool call ever happened.
        return False
    except Exception:
        return None


#: Every brief state that means "this lane was told what to do". ONE DEFINITION, because
#: the count is derived in two places (the record's own `briefed`, and the per-wave line
#: `dispatch --go` prints) and a state added to one tuple and not the other reports a
#: numerator that disagrees with itself in front of an operator deciding whether to trust
#: it. The nudge states belong here: a lane that was briefed, went idle and was nudged WAS
#: briefed — that is precisely what distinguishes it from one that never received a prompt.
DISPATCH_BRIEFED_STATES = ("briefed", "re-briefed", "nudged", "nudge-unconfirmed")

#: What a lane that was briefed and then stopped gets sent. DELIBERATELY NOT THE BRIEF.
#: `_dispatch_rebrief_tmux` re-types the whole prompt, which is right for a lane that never
#: received one and wrong for this case: the lane HAS read its brief, claimed its item and
#: announced the assignment, so re-typing it invites a second orientation pass and a second
#: claim attempt on work already claimed. What is missing is the beat, not the instruction.
DISPATCH_RESUME_PROMPT = (
    "Proceed with your claimed item now — you were briefed, claimed it, and then went idle "
    "without starting the work. Do not re-read the brief or re-claim: continue from where "
    "you stopped, decide any mechanical question yourself and record the reasoning under "
    "'### Decisions I made without you, for review', and land when green.")


def _dispatch_lane_awaiting_input(wid: str) -> bool | None:
    """Is the lane working `wid` sitting idle, waiting for a human to type at it?

    True / False / None (cannot tell) — three outcomes, because "the attention store could
    not be read" is a different fact from "nobody is waiting", and collapsing the two is a
    recurring failure.

    WHY THIS EXISTS ALONGSIDE `_dispatch_lane_working`, which looks like it already answers
    this and does not. That probe reads the ADR-0055 `.pending-start` marker, which the
    FIRST HEARTBEAT consumes — and a heartbeat is driven by any tool call. A dispatched lane
    runs its session-start, claims its item and announces the assignment, all of which are
    tool calls, so the marker is gone before the lane has executed one step of the work.
    From that moment `_dispatch_lane_working` answers True for a lane that is briefed,
    claimed, announced and completely idle. That is exactly the state both lanes of dispatch
    D-4d6df1 sat in for nineteen minutes on 2026-09-19 while every signal read healthy.

    THE JOIN IS ON THE ITEM, NOT ON THE LANE NAME. The attention record already carries the
    item id, and it is the same id the dispatcher is holding — whereas the record's KEY is a
    coordination identity (`worktree-poga-1`) that does not match the lane slug the dispatch
    machinery passes around (`poga-1`). Matching the field that is already equal beats
    maintaining a translation between two spellings of the same lane.

    A record with no item cannot be attributed to this dispatch's lane, so it does not make
    this True — an unattributable record is not evidence about `wid`."""
    try:
        state, recs = _attention_state()
    except Exception:
        return None
    if state == "unknown":
        return None
    for rec in (recs or {}).values():
        if str((rec or {}).get("item") or "").strip() == str(wid):
            return True
    return False


def _dispatch_lane_keys() -> set[str]:
    """WHICH lanes this machine's dispatches currently hold — the identity, not the count.

    Identity rather than a number because of WI-0238: the cap must be checked against a
    set the caller can ADD to (the lanes it spawned moments ago, which have not registered
    themselves yet) without double-counting the ones that have since appeared. A count
    cannot be unioned; a set can. `_dispatch_live_lane_count` is this set's size, and stays
    the seam everything else reads.

    The key is `<dispatch-id>::<item>`, both fields written by `_lane_reserve` at the draw.
    A record carrying a dispatch id but no item predates that field (or was hand-edited):
    it keys on its own lane name instead, so two such records never collapse into one and
    silently undercount the cap.

    EXPIRY IS PART OF THE QUESTION (WI-0249). Reading each record with `_coord_read` hands
    back a record whatever its TTL says, so a reservation nobody had refreshed for hours
    still held a key — and "which lanes do my dispatches hold" answered with lanes that
    held none. `_coord_list` is the one place that decides what LIVE means for a
    coordination record; going through it means this set cannot drift from every other
    reader of the same store ([P16](principles/master.md#p16--avoid-duplication)). It
    matters most exactly when the cap binds, which is the case WI-0238 exists for: a
    finished lane that has not yet let go of its name is the difference between a dispatch
    that drains and one that stalls.

    Fail-open to the empty set, like every other coordination read."""
    keys: set[str] = set()
    try:
        in_use = _lane_names_in_use()
        live = _coord_list(LANE_ALLOC_KIND)          # live only — expiry excluded
        for lane in in_use:
            rec = live.get(lane)
            if not rec:
                continue
            did = str(rec.get("dispatch_id") or "").strip()
            if not did:
                continue
            item = str(rec.get("dispatch_item") or "").strip()
            # WI-0248 (c): an UNBRIEFED lane must not consume dispatch capacity. It is
            # alive and holds a worktree, but it was never told what to do and never will
            # be by itself — counting it lets one lost prompt block the whole queue.
            #
            # Only a MEASURED `unbriefed` is excluded. `pending`, `unknown` and a missing
            # slot all still count, which is the conservative direction: under-spawning
            # costs a wave that drains slower, over-spawning costs real money and a
            # machine full of sessions nobody asked for.
            if item:
                slot = _dispatch_slot_path(did, item)
                srec = _coord_read(slot) if (slot and slot.is_file()) else None
                if srec and str(srec.get("brief") or "").strip() == "unbriefed":
                    continue
            keys.add(f"{did}::{item}" if item else f"lane::{lane}")
    except Exception:
        return set()
    return keys


def _dispatch_live_lane_count(pending: set[str] | None = None) -> int:
    """How many lanes THIS MACHINE'S DISPATCHES currently hold. (WI-0156.)

    `pending` — the `<dispatch-id>::<item>` keys of lanes the caller has ALREADY SPAWNED
    but which have not yet registered themselves. Unioned in, never added, so a lane that
    registers mid-wave is counted once.

    WHY IT EXISTS (WI-0238, measured 2026-09-03 by causing it). The lane-alloc record this
    counts is written by the CHILD, in `_lane_reserve`, seconds after `tmux new-session`
    returns — see the note there on why the fact cannot be captured anywhere else. So a
    caller that re-read this number in a loop saw a value that could not have moved yet:
    `poga dispatch <15 ids> --cap 5 --run all --go` read ~0 on all fifteen iterations and
    opened fifteen concurrent lanes against a cap of five. THE CAP IS THE ONLY THING
    BOUNDING A FAN-OUT and `--run all` removes the other bound, so the two together are
    exactly where it has to hold. Observed: fifteen `poga-D-382d74-*` tmux sessions inside
    two seconds. The fix is not a faster read — no read can see a row the other process has
    not written — it is for the spawner to remember what it just spawned.

    NOT the number of live lanes. the operator's ruling, 2026-08-22, after a dispatch spawned
    nothing and then reported itself as draining: sessions the command did not launch do
    not count toward its cap; it ignores them and runs its own. A lane opened by hand is
    the operator's own work, not dispatch load, and must not consume dispatch capacity.

    WHY THIS SHAPE RATHER THAN A DEADLOCK DETECTOR. The bug it closes was a disagreement
    between two counts, not a missing check: the cap counted ALL live lanes while the
    drain baton passes only between DISPATCHED ones (`_dispatch_after_land`, via
    `POGA_DISPATCH`). A dispatch issued into a cap already full of hand-launched lanes
    therefore spawned zero, and with zero spawned there was no lane carrying the baton and
    never would be — it sat `[draining]` forever. Observed live: D-4d41da, 2026-08-22,
    cap 2 against 2 hand-opened lanes, six hours. Counting only our own removes the
    disagreement instead of reconciling it: a dispatch now ALWAYS spawns at least one
    lane, so a lane exists to pass the baton to and the deadlock is unreachable — no
    detector, no refusal path, no special case ([P15](principles/master.md#p15--code-for-mechanism-not-judgment)).

    THE CONSEQUENCE IS DELIBERATE AND MUST NOT BE QUIETLY UNDONE: total concurrency on the
    machine is now hand-launched lanes PLUS the dispatch cap, so `--cap 5` alongside two
    hand sessions means seven live sessions. That is what was asked for. The number that
    bounds SPEND is the dispatch cap alone, not the machine total — so any future
    load-based guard belongs beside this count, never inside it, or it silently
    re-introduces the all-lanes reading this exists to remove.

    Fail-open like every other coordination read: a cap that cannot be computed must not be
    the thing that stops a dispatch. Note what that now means — an unreadable coord store
    degrades to `len(pending)`, so the IN-WAVE bound still holds even when the shared view
    is gone. Failing open used to mean failing unbounded; it no longer does."""
    return len(_dispatch_lane_keys() | (pending or set()))


def _lane_close_marker_path(did: str, wid: str) -> Path | None:
    """Mint the path of the sanctioned-close marker for one spawn. None when the shared
    coordination directory cannot be resolved — the caller then degrades to the pre-WI-0249
    wrapper, which holds every non-zero exit open.

    A FRESH path per call, by construction: the random component means a lane relaunched
    into the same slot cannot read its predecessor's leftover marker and silently swallow a
    real crash. Called exactly once per spawn."""
    d = _coord_dir(LANE_CLOSE_KIND, create=True)
    if d is None:
        return None
    safe = re.sub(r"[^A-Za-z0-9_.-]", "", f"{did}-{wid}") or "lane"
    return d / f"{safe}-{secrets.token_hex(3)}.marker"


def _dispatch_runtime_pid() -> int | None:
    """The pid of the RUNTIME this dispatched lane is running inside, or None.

    Identified by its parent, not by its own name. The spawn wrapper's shell command line
    literally contains `POGA_DISPATCH=<our id>` (see `_dispatch_spawn_command`), so the
    runtime is the ancestor whose parent is that shell — an exact, self-identifying match
    tied to THIS dispatch. Matching on the command name instead would mean hardcoding
    `claude` into a substrate that ADR-0082 deliberately made runtime-agnostic, and would
    misfire the moment a lane runs codex or anything else.

    Returns None for every case that is not an unambiguous match: not dispatched, no
    ancestry readable, no wrapper found. None means "leave the process alone", which is the
    safe direction — a lane that fails to close is visible and sweepable; a wrong pid
    killed is not recoverable."""
    # ADR-0119 D4. None is already this function's answer for "no ancestry readable", and
    # it already means LEAVE THE PROCESS ALONE — which is exactly right under a gate: the
    # suite is running inside somebody's real runtime, and the one thing a land's test run
    # must never do is identify a live process as killable. Surfaced by the completeness
    # detector, not by the hand-written list.
    if _under_gate():
        return None
    did = os.environ.get("POGA_DISPATCH", "").strip()
    if not did:
        return None
    needle = f"POGA_DISPATCH={did}"
    try:
        pid, depth = os.getpid(), 0
        while pid > 1 and depth < 24:
            r = sh(["ps", "-o", "ppid=,command=", "-p", str(pid)], check=False)
            line = (r.stdout or "").strip()
            if not line:
                return None
            head, _, parent_cmd = line.partition(" ")
            try:
                parent = int(head)
            except ValueError:
                return None
            # The wrapper shell is the parent; WE are the runtime it launched. Never
            # return our own pid — `end` runs as a child of the runtime, and killing the
            # process that is doing the killing loses the close it is in the middle of.
            if needle in parent_cmd and pid != os.getpid():
                return pid
            pid, depth = parent, depth + 1
    except Exception:
        pass
    return None


def _dispatch_tmux_session() -> str:
    """This dispatched lane's own tmux session name, or "" when it cannot be named.

    THE HANDLE THE PID TURNED OUT NOT TO BE (WI-0354). `_dispatch_runtime_pid` reads
    process ancestry off the machine, and a read of the machine can come back empty for
    reasons that have nothing to do with whether the lane is finished — at which point the
    close had no second way to act, said so, and left the lane up. This handle is computed
    from the two environment values the spawn line set. It cannot come back empty for a
    dispatched lane, and it cannot name anything but the session that lane runs in:
    `_dispatch_open_tmux` created that session under exactly this name, and tmux refuses a
    duplicate, so the name identifies one session or none.

    EMPTY FOR A HAND-OPENED LANE, by the discriminator the rest of this file uses — no
    `POGA_DISPATCH`, no name, nothing for a close to kill. Empty under the gate too:
    `tmux` is a `GATE_FORBIDDEN_PROGRAM` and a suite has no business reading, let alone
    ending, anything on the operator's real machine (ADR-0119 D4)."""
    if _under_gate():
        return ""
    did = os.environ.get("POGA_DISPATCH", "").strip()
    wid = os.environ.get("POGA_DISPATCH_ITEM", "").strip()
    if not did or not wid:
        return ""
    return _tmux_session_name(did, wid)


def _lane_launch_path(lane: str) -> Path | None:
    """Where the wrapper writes down the pid it is about to become (WI-0399).

    One file per lane SLOT, overwritten by the next launch into that slot, because the
    question it answers is "what is running in poga-7 right now" and a slot holds one
    session at a time. A fresh-per-launch name would leave the close hunting through
    predecessors with no way to tell which is current.

    In the shared coordination dir rather than the lane's `.session-state`, for two
    reasons that both bite: the native Claude launch path creates the worktree AFTER the
    wrapper execs, so at write time there is no lane directory to write into; and the
    worktree is REMOVED at teardown, which is exactly when a close record is still being
    read."""
    d = _coord_dir(LANE_LAUNCH_KIND, create=True)
    if d is None:
        return None
    safe = re.sub(r"[^A-Za-z0-9_.-]", "-", (lane or "").strip()) or "lane"
    return d / f"{safe}.json"


def cmd_lane_launch(args: argparse.Namespace) -> None:
    """Record the launch the wrapper is about to perform (WI-0399).

    Called by `poga` immediately before every `exec`, and `$$` is the whole point: `exec`
    REPLACES the wrapper's process image while KEEPING its pid, so the number written here
    is the runtime's pid from the instant the exec succeeds. That is the same property
    `prep_and_supervise` already relies on for the liveness watcher; this writes it down
    instead of handing it to a watcher, because the reader is a close that happens hours
    later in a different process.

    WHY THE WRAPPER AND NOT A HOOK. A Claude-only exit path would have to be rebuilt for
    Codex and for Antigravity, and the substrate floor is a set of runtime-agnostic
    obligations with per-runtime bindings (ADR-0041). `poga` is the one actor present at
    every launch of every runtime, so the handle is recorded once, in one place, for all
    of them.

    `--attended` is the wrapper's honest read of whether a human can see this terminal
    (`[ -t 1 ]`), and it decides only one thing: whether the close pauses so its summary
    can be read. A detached pane gets no pause -- nobody is there, and the summary is read
    off the board.

    Fail-open and silent on success: a launch that cannot be recorded degrades to exactly
    today's behaviour, which is a session that sits at its prompt until someone closes the
    window. That is worth no noise at all on the launch path."""
    lane = str(getattr(args, "lane", "") or "").strip()
    pid = int(getattr(args, "pid", 0) or 0)
    if not lane or pid <= 1:
        sys.exit(0)
    path = _lane_launch_path(lane)
    if path is None:
        sys.exit(0)
    with contextlib.suppress(Exception):
        atomic_write(path, json.dumps({
            "lane": lane,
            "pid": pid,
            "runtime": str(getattr(args, "runtime", "") or ""),
            "attended": bool(getattr(args, "attended", False)),
            "launched": _now_iso(),
            "machine": detect_machine() if CFG else "",
        }, ensure_ascii=False, indent=2) + "\n")
    sys.exit(0)


def _lane_launch_record() -> dict:
    """This lane's launch receipt, or {} when there is none.

    {} is the ordinary answer for a session nobody launched through `poga` -- an app
    session in the main checkout, a lane entered by hand, a suite. Every caller treats it
    as "no handle, leave the process alone", which is the safe direction."""
    try:
        path = _lane_launch_path(ROOT.name)
        if path is None or not path.is_file():
            return {}
        rec = json.loads(path.read_text(encoding="utf-8"))
        return rec if isinstance(rec, dict) else {}
    except Exception:
        return {}


def _pid_is_ancestor(pid: int) -> bool:
    """Is `pid` an ancestor of this process?

    THIS IS THE AUTHORIZATION, not a sanity check, so it is worth saying what it proves.
    A launch receipt is a number in a file, and a number in a file can be stale: a slot
    relaunched, a wrapper that died before its exec, a pid the OS has since recycled onto
    something else entirely. Signalling on the strength of the file alone would mean a
    close could kill an unrelated process that happens to hold a recycled number.

    Walking our own ancestry answers a different and much stronger question -- is the
    process named here the one I am running INSIDE -- and that cannot be faked by a stale
    file, because a stale file names a process this session is not descended from. It is
    the runtime-agnostic form of the proof `_dispatch_runtime_pid` gets from matching
    `POGA_DISPATCH=<id>` in an ancestor's command line, and it needs no environment
    variable, so it holds for a Codex or Antigravity lane exactly as it does for Claude.

    False on any doubt: unreadable ancestry, a loop, our own pid, or a walk that runs out
    of depth. False means leave the process alone.

    REFUSES UNDER THE GATE, and the completeness detector is what said so rather than a
    reviewer (ADR-0119 D4, `test_gate_snapshot.CompletenessTest`). This reads the process
    table with `ps`, a machine-scoped program: a suite that reaches it makes the land's
    verdict a function of whatever else happens to be running on the operator's box. False
    is already this function's answer for "cannot tell", and under the gate it is also the
    only safe one -- the suite is running INSIDE somebody's real runtime, so a True here
    would identify a live session as killable."""
    if _under_gate():
        return False
    if pid <= 1 or pid == os.getpid():
        return False
    try:
        cur, depth = os.getpid(), 0
        while cur > 1 and depth < 24:
            r = sh(["ps", "-o", "ppid=", "-p", str(cur)], check=False)
            head = (r.stdout or "").strip()
            if not head:
                return False
            parent = int(head.split()[0])
            if parent == pid:
                return True
            if parent == cur:
                return False
            cur, depth = parent, depth + 1
    except Exception:
        return False
    return False


def _lane_exit_spawn(pid: int | None, tmux_session: str, read_pause: float = 0.0) -> None:
    """Start the detached reaper that ends this session's runtime.

    ONE IMPLEMENTATION FOR BOTH ARMS. The dispatched close and the attended close differ
    in how they are AUTHORIZED and in whether they pause; they do not differ in how a
    process is ended, and two copies of a fork-and-signal would be two places for the
    escalation to drift ([P16](principles/master.md#p16--avoid-duplication)).

    Detached because the thing being ended is our own ancestor: signalling from here would
    tear down the process tree this call is standing in, and whatever `end` still had to
    print would go with it."""
    argv = [sys.executable, str(Path(__file__).resolve()), "lane-exit",
            "--grace", str(LANE_EXIT_GRACE_SECONDS), "--detach"]
    if read_pause > 0:
        argv += ["--read-pause", str(read_pause)]
    if pid is not None:
        argv += ["--pid", str(pid)]
    if tmux_session:
        argv += ["--tmux-session", tmux_session]
    sh(argv, check=False)


def _attended_close_runtime(landed: bool, closing_did: str = "") -> None:
    """End a HAND-OPENED session's runtime once its record is closed (WI-0399).

    THE HALF `_dispatch_close_runtime` COULD NOT REACH. That function ends a dispatched
    lane, and its whole ability to name a process is `_dispatch_runtime_pid`, which finds
    the runtime by matching `POGA_DISPATCH=<id>` in an ancestor's command line. A session
    operator opened himself carries no such variable and so had no handle at all: it closed
    its journal, printed its banner, and then sat at the runtime's exit prompt until the
    terminal was closed by hand. That is a chore handed to a person by a machine that
    could do it itself -- the same family as the 2026-08-19 "sessions hand operator chores"
    brief -- and it is what operator ruled should end (2026-09-18).

    THREE FACTS MUST ALL HOLD, and each one rules out a distinct way of killing the wrong
    thing:

      1. A launch receipt exists for THIS lane slot. Without it there is no candidate at
         all, which is every session `poga` did not launch.
      2. Its pid is an ancestor of this process (`_pid_is_ancestor`). This is the
         authorization: it proves the recorded number is the runtime we are running
         inside, and it survives a stale receipt and a recycled pid, neither of which the
         file alone can distinguish.
      3. The journal that just closed is the one this lane holds. `end --session-id
         <other>` closes a SIBLING's journal, and a sibling's close is no reason to end
         this runtime -- without this, closing a neighbour's record from here would
         destroy a live session mid-work.

    ONLY AFTER A SUCCESSFUL LAND, the same condition and the same argument as the
    dispatched arm: a lane whose gate failed still has real work on its branch and needs a
    session alive to finish it. Killing that lane converts a recoverable failure into
    stranded work with no owner. So a lane that did not land stays up and says why.

    THE PAUSE IS NOT COSMETIC. An attended session prints its close summary to a terminal
    someone is looking at, and a window that closes the instant the summary appears has
    communicated nothing. The wrapper recorded whether anyone can see this terminal;
    `read_pause` is that answer turned into seconds, and it is zero when nobody is there.

    Fail-open and never raises: a session that cannot end itself is a window to close,
    which is the state we were already in. Turning a completed session into a failed one
    to save a keystroke would be a bad trade."""
    if os.environ.get("POGA_DISPATCH", "").strip():
        return                      # dispatched — `_dispatch_close_runtime` owns this
    if _running_against_fixture() or _under_gate():
        return                      # WI-0035 / ADR-0119 D4 — never signal from a suite
    rec = _lane_launch_record()
    pid = int(rec.get("pid") or 0)
    if not pid or not _process_alive(pid) or not _pid_is_ancestor(pid):
        return                      # no handle we can prove is ours
    held = _find_holder_journal()
    mine = str((held[1].get("session-id") if held else "") or "").strip()
    if not mine or not closing_did or mine != closing_did:
        return                      # a journal that is not this lane's own
    if not landed:
        print("close: this session did NOT land, so it is being left open — its work is "
              "committed on the lane and needs a session to run `session.py merge`. "
              "Close the window once that is done.")
        return
    try:
        pause = CLOSE_READ_PAUSE_SECONDS if rec.get("attended") else 0.0
        _lane_exit_spawn(pid, "", pause)
        if pause > 0:
            print(f"close: this session is complete. The window closes itself in "
                  f"{int(pause)}s — the full summary is on the board.")
        else:
            print("close: this session is complete and is closing itself — the summary "
                  "is on the board.")
    except Exception as e:
        print(f"close: could not end this session's runtime ({e}) — it is still running; "
              f"close the window by hand.", file=sys.stderr)


def _dispatch_close_runtime(landed: bool, closing_csid: str = "") -> None:
    """End a DISPATCHED lane's process, now that its record is closed and its work landed.

    THE AUTHORIZATION IS THE DISPATCH. A lane opened by hand belongs to the person who
    opened it and is never touched here; `POGA_DISPATCH` is the whole discriminator.

    IT MUST BE *OUR* SESSION THAT CLOSED, and this is a correctness property before it is
    a test guard. `end --session-id <other>` closes a sibling's journal; `cmd_end` in a
    fixture closes a fabricated one. Neither is grounds for killing THIS runtime, and the
    consequence of getting it wrong is not a failed assertion — it is a live session
    destroyed mid-work. The land gate runs the suite from inside a dispatched lane, where
    `POGA_DISPATCH` is set and the process ancestry is real, so "the tests set no dispatch
    variables" is hygiene we should keep but must not RELY on. Requiring the closed
    journal to be the one this runtime is actually living in is the fact that cannot be
    faked by an inherited environment.

    ONLY AFTER A SUCCESSFUL LAND, and that is not a detail. A lane whose gate failed, whose
    CAS lost three times, or whose renumber refused still has its work committed on its own
    branch and needs a session alive to fix it and re-run `merge`. Killing that lane would
    convert a recoverable failure into stranded work with no owner — the exact harm WI-0172
    describes, manufactured deliberately. So a lane that did not land stays up and says so.

    Fail-open and never raises: a lane that cannot close itself is a pane to sweep, which is
    the state we are already in. Turning a landed session into a failed one to save a sweep
    would be a bad trade."""
    if not os.environ.get("POGA_DISPATCH", "").strip():
        return                      # hand-opened lane — the operator owns its session
    if _running_against_fixture():
        return                      # WI-0035 — never act on the real machine from a fixture
    live = _claude_session_id() or ""
    if not live or not closing_csid or closing_csid != live:
        return                      # a journal that is not this runtime's own
    if not landed:
        print("dispatch: this lane did NOT land, so its session is being left up — its "
              "work is committed on the branch and needs a session to run `session.py "
              "merge`. Close it by hand once that is done.")
        return
    try:
        pid = _dispatch_runtime_pid()
        tmux_session = _dispatch_tmux_session()
        # TWO HANDLES, AND EITHER IS ENOUGH (WI-0354). This used to return here whenever
        # the ancestry read came back empty, which is the one branch that leaves a
        # finished lane running — and `poga-D-2659c6-WI-0350` reached it on 2026-09-13.
        # A dispatched lane on the tmux surface is still nameable when its pid is not, so
        # "could not identify" now means neither handle resolved, not just the harder one.
        if pid is None and not tmux_session:
            print("dispatch: could not identify this lane's runtime process or its tmux "
                  "session, so it is being left running — close the pane by hand "
                  "(WI-0249).")
            return
        marker = (os.environ.get("POGA_LANE_CLOSE") or "").strip()
        if marker:
            # Written BEFORE the signal, so the wrapper shell cannot lose the race and
            # read a missing marker as a crash.
            with contextlib.suppress(Exception):
                Path(marker).parent.mkdir(parents=True, exist_ok=True)
                atomic_write(Path(marker), json.dumps(
                    {"closed": _now_iso(), "pid": pid, "tmux_session": tmux_session,
                     "dispatch_id": os.environ.get("POGA_DISPATCH", ""),
                     "item": os.environ.get("POGA_DISPATCH_ITEM", "")},
                    ensure_ascii=False, indent=2) + "\n")
        else:
            print("dispatch: no POGA_LANE_CLOSE marker in this lane's environment (spawned "
                  "before WI-0249) — the pane will be held open after exit; press Enter.")
        # A DETACHED reaper, because the thing being killed is our own parent: signalling
        # from here would tear down the process tree this call is standing in, and whatever
        # `end` still had to print would go with it. The child outlives us by design.
        #
        # No read pause: this pane is detached and nobody is reading it (WI-0399). The
        # attended arm passes one; the shared spawn is the only place either of them
        # describes how a runtime is actually ended.
        _lane_exit_spawn(pid, tmux_session, 0.0)
        handles = (f"pid {pid}" if pid is not None else "no pid resolved")
        if tmux_session:
            handles += f", tmux session '{tmux_session}'"
        print(f"dispatch: item complete and landed — closing this lane's runtime "
              f"({handles}). The pane closes on exit; nothing is left to sweep.")
    except Exception as e:
        print(f"dispatch: could not close this lane's runtime ({e}) — it is still running; "
              f"close the pane by hand.", file=sys.stderr)


def _dispatch_close_after_land() -> None:
    """Close a DISPATCHED lane that landed through `merge --continue` (WI-0354).

    THE CLOSE WAS BOLTED TO THE VERB INSTEAD OF TO THE FACT. `cmd_end` frees this
    session's claims and ends its runtime only when the land it ran itself came back
    landed — and `--continue` is the verb for exactly the case where that land did NOT.
    A lane blocked at the gate closes its journal, fails to land, is told its session is
    being left up, and then lands minutes later through a route with no close in it at
    all. Both lanes the item was filed over took it, and so did `poga-D-2659c6-WI-0350`,
    observed: journal closed, `exit: 1 — nothing landed (gate)`, landed minutes later
    through `--continue`, runtime still alive long afterwards with its pane at a prompt.

    THE CLOSED JOURNAL IS THE WHOLE GUARD, and it is read rather than assumed.
    `--continue` is also the ordinary mid-session land — the deferred land after
    `end --no-merge`, the genuine second package — and a lane that lands with its journal
    still open is mid-work. Ending it there would destroy a live session to save a sweep,
    which is the trade `_dispatch_close_runtime` refuses in the other direction and must
    refuse in this one. No journal of ours, or one with no `ended` stamp, and nothing
    happens.

    NOT A SECOND IMPLEMENTATION OF THE CLOSE. It calls the same one lane exit and the same
    runtime close `cmd_end` calls; what it adds is the fact those two need and this route
    does not otherwise carry — that this session is over. Fail-open in every direction: a
    land that has already succeeded must never be turned into a failure by its own
    cleanup."""
    if not os.environ.get("POGA_DISPATCH", "").strip():
        return                      # hand-opened lane — the operator owns its session
    if _running_against_fixture():
        return                      # WI-0035 — never act on the real machine from a fixture
    try:
        found = _find_holder_journal()
        if found is None:
            return                  # no journal of ours to prove anything with
        fm = found[1]
        if not str(fm.get("ended") or "").strip():
            return                  # still open — this land is mid-session, not a close
        for line in _lane_exit_report(f"journal {fm.get('session-id', '')} closed"):
            print(line)
        _dispatch_close_runtime(True, str(fm.get("claude-session-id") or "").strip())
    except Exception as e:
        print(f"dispatch: could not close this lane after its land ({e}) — the land "
              f"stands and nothing is lost; close the pane by hand.", file=sys.stderr)


def _lane_exit_kill_tmux(name: str) -> None:
    """Destroy a dispatched lane's tmux session — the LAST act of its exit (WI-0354).

    WHY AT ALL, when the runtime has already been signalled. The wrapper shell is the tmux
    session's command, so ending the runtime only makes that shell reach its own last line
    — which it does only if the signal landed and the shell is in a state to run. Every
    step of that is a thing that can fail to be true, and when one is not, what remains is
    a named session sitting at a prompt holding a slot. `kill-session` needs none of it to
    be true: it ends the pane, the wrapper and the runtime together.

    LAST, NEVER FIRST. A runtime that handles SIGTERM writes what it writes on the way
    out, and destroying its terminal before that would take the writing with it. By the
    time this runs the pid escalation has already finished, or there was no pid to
    escalate.

    IDEMPOTENT BY THE SAME ARGUMENT AS THE REST OF THE EXIT: a session tmux has already
    reaped is simply not there, `kill-session` says so on stderr, and we ignore it.

    Never raises — this is the tail of a detached reaper with no one to tell — and never
    runs under the gate, where `tmux` is a forbidden program (ADR-0119 D4)."""
    if not name or _under_gate():
        return
    tmux = _tmux_bin()
    if not tmux:
        return
    with contextlib.suppress(Exception):
        subprocess.run([tmux, "kill-session", "-t", name], capture_output=True,
                       text=True, check=False, timeout=DISPATCH_SPAWN_TIMEOUT_SECONDS)


def cmd_lane_exit(args: argparse.Namespace) -> None:
    """Terminate a dispatched lane's runtime (WI-0249). Detached, so it can outlive the
    `end` that started it — which is running inside the very process being ended.

    SIGTERM, then SIGKILL after the grace. The escalation is the point: it makes the
    mechanism independent of how a given runtime handles SIGTERM, which is exactly the
    fact we could not measure (the signal probe was refused by the sandbox) and therefore
    must not assume. A runtime that exits cleanly on SIGTERM never sees the second signal.

    TWO HANDLES, EITHER OR BOTH (WI-0354). `--pid` signals the runtime; `--tmux-session`
    destroys the whole pane it is running in. The pid is the gentler instrument and goes
    first, but it is resolved by reading process ancestry and that read can come back
    empty, so it is no longer required — a lane whose ancestry is unreadable is still
    nameable, and a close with no way to act is how a finished lane goes on holding a slot.

    Fail-open everywhere, and refuses a pid that is not alive rather than guessing at a
    recycled one."""
    pid = int(getattr(args, "pid", 0) or 0)
    tmux_session = str(getattr(args, "tmux_session", "") or "").strip()
    grace = float(getattr(args, "grace", LANE_EXIT_GRACE_SECONDS) or LANE_EXIT_GRACE_SECONDS)
    signalable = pid > 1 and pid != os.getpid() and _process_alive(pid)
    if not signalable and not tmux_session:
        sys.exit(0)
    if getattr(args, "detach", False):
        try:
            if os.fork() > 0:
                sys.exit(0)          # parent returns to `end` immediately
            os.setsid()
            devnull = os.open(os.devnull, os.O_RDWR)
            for fd in (0, 1, 2):
                os.dup2(devnull, fd)
        except Exception:
            sys.exit(0)              # cannot detach → never signal from the caller's tree
    # WI-0399: hold the terminal open long enough for the close summary already printed
    # in it to be read. AFTER the detach, so `end` returns immediately and the pause is
    # the operator's to watch rather than the harness's to block on; BEFORE the signal,
    # because a pause after it would be a pause on a dead window. Zero for a detached
    # pane, which is every dispatched lane.
    pause = float(getattr(args, "read_pause", 0.0) or 0.0)
    if pause > 0:
        time.sleep(pause)
        # A runtime can exit on its own while its summary is being read, and the number it
        # held can be handed to something else. Only the SIGNAL is dropped -- the pane
        # teardown below still runs, because a session that left on its own can still have
        # a wrapper shell sitting at a prompt in a named tmux session holding a slot. An
        # early return here skipped that, and `test_lane_close_after_land` caught it.
        if signalable and not _process_alive(pid):
            signalable = False
    if signalable:
        with contextlib.suppress(Exception):
            os.kill(pid, signal.SIGTERM)
        deadline = time.time() + grace
        while time.time() < deadline:
            if not _process_alive(pid):
                break
            time.sleep(0.25)
        else:
            with contextlib.suppress(Exception):
                os.kill(pid, signal.SIGKILL)
    _lane_exit_kill_tmux(tmux_session)
    sys.exit(0)


def _dispatch_spawn_command(root: Path, did: str, wid: str,
                            turn_budget: int | None = None,
                            runtime: str | None = None) -> str:
    """The shell line the new terminal tab runs. Uses the repo's OWN `poga` by absolute
    path rather than relying on a `poga install` symlink being on PATH — a dispatch that
    silently opens a tab printing 'command not found' is the silent-strand failure this
    whole design exists to prevent.

    NO POSITIONAL PROMPT — WI-0390 layer 2, and this is the load-bearing line. `poga`
    classifies a bare positional token as the OPERATOR'S own prompt (`has_operator_prompt`,
    poga:379-395) purely by argv POSITION, never by authorship. A dispatch brief passed
    there is therefore read as something operator typed, `POGA_PROMPT_IS_OURS` stays 0, and
    `deliver_the_context` refuses to splice the session-start payload into it — so every
    dispatched lane ran with its canon, principles and standard rituals SUPPRESSED, and
    the only notice was a stderr line the model never sees. Measured, not reasoned about:
    the function lifted out of `poga` and run on the four argv shapes reports DELIVERED
    for `[]` and `[--model sonnet]`, SUPPRESSED for a dispatch brief — and SUPPRESSED for
    poga's OWN default prompt passed positionally, which is the negative control that
    proves the mechanism is position and not content.

    Spawning with no positional leaves `has_operator_prompt` false, so `poga` appends its
    own opening prompt IN THE SHAPE THE RUNTIME TAKES (positional for claude-code and
    codex, `-i` for antigravity — `argv_shape` in the registry) and delivery proceeds.
    That shape knowledge belongs to the launcher, which already has it; dispatch never
    acquires a second copy of it (P16). The brief itself is not lost: it rides the
    session-start orientation instead (`_dispatch_brief_block`), which both delivery
    channels carry — the SessionStart hook's additionalContext on the native path, and
    the `--prep` session-context payload on every other runtime.

    `--runtime=<id>`, NOT `-r <id>` — WI-0390 layer 3, found while building this and
    measured the same way. `-r`/`--runtime` are absent from poga's `POGA_VALUE_FLAGS`,
    and `cmd_session` calls `has_operator_prompt` on the RAW argv (poga:719) before
    `parse_runtime_flag`'s output exists — so the separated spelling leaves `codex` as a
    bare token and classifies it as an operator prompt, re-breaking delivery in the act
    of selecting the runtime. The `=` form is a single `-*` token and cannot. Probed:
    `[-r codex]` and `[--runtime codex]` SUPPRESSED, `[--runtime=codex]` DELIVERED. The
    real repair is in `poga` and belongs to the sibling item's file set; this is the
    spelling that works against `poga` exactly as it stands today.

    `POGA_DISPATCH*` ride in the environment so the lane's eventual `session.py end`
    knows which queue to advance without any coordinator telling it (see
    `_dispatch_after_land`). The `&&` is inside the spawned tab's own command line, not
    a compound in OUR shell, so `no-compound-bash` does not apply.

    `POGA_LANE_CLOSE` (WI-0249) names the file the lane's own `end` writes when it has
    landed and is about to terminate its runtime on purpose. The wrapper below consults
    that file rather than the exit code, because the exit code cannot answer the question:
    a runtime killed by a signal exits non-zero whether it was a crash or a sanctioned
    close, and inferring "this 143 was deliberate" would hold a pane open after every
    successful dispatch or close one after a real kill. The marker is written by the
    closing code itself — the receipt, not a guess about it
    ([`a-close-is-the-banner-not-the-sentence`](habits/master.md#a-close-is-the-banner-not-the-sentence))."""
    marker = _lane_close_marker_path(did, wid)
    q_marker = shlex.quote(str(marker)) if marker else ""
    # Canonicalised at dispatch time, never here: an unknown id must refuse ONCE, in front
    # of the operator, not open a wave of tabs that each fail the same way (WI-0105's
    # litter shape). An empty/absent runtime emits no flag at all, so the default spawn
    # line is byte-identical to what it was before the flag existed.
    rt = (runtime or "").strip()
    inner = (f"cd {shlex.quote(str(root))} && "
             f"POGA_DISPATCH={shlex.quote(did)} POGA_DISPATCH_ITEM={shlex.quote(wid)} "
             + (f"POGA_LANE_CLOSE={q_marker} " if marker else "")
             # WI-0288 R2 (2): the lane's turn budget. It rides in the environment for
             # the same reason the dispatch handles do — the lane must be able to bound
             # itself with nothing attached to it and no coordinator to ask.
             #
             # NOT A `claude` FLAG, and this was verified rather than assumed: the
             # installed CLI has no `--max-turns` at all (`--max-budget-usd` exists and
             # is `--print`-only), while these lanes launch as interactive TUI sessions
             # through `poga`. So the budget is ours to enforce, at the only event that
             # fires once per turn — the `Stop` hook. See `_turn_budget_count`.
             #
             # OMITTED WHEN THERE IS NO BUDGET, never sent as 0: absence and a budget of
             # zero are different states and a lane must be able to tell them apart
             # (`declare-what-a-check-assumes`).
             + (f"POGA_TURN_BUDGET={int(turn_budget)} "
                if turn_budget and int(turn_budget) > 0 else "")
             + f"{shlex.quote(str(root / 'poga'))}"
             + (f" {shlex.quote('--runtime=' + rt)}" if rt else ""))
    # WI-0185 defect 3: A FAILURE WHOSE EVIDENCE IS DESTROYED BY THE FAILURE. A tmux
    # session ends when its command exits, so a lane that died at launch took with it
    # whatever it printed about why — the hardest kind to fix, and the kind this substrate
    # keeps producing (WI-0105, WI-0156). On a NON-ZERO exit the pane is held open instead,
    # so the error is still on screen when the operator attaches. A clean exit is a lane
    # that finished; it closes as before, and nothing accumulates.
    #
    # WI-0249 adds the second way to finish. A dispatched lane that has landed kills its
    # own runtime, which is a non-zero exit and would otherwise be held open as a failure —
    # so a fan-out of 15 would leave 15 dead panes to sweep by hand, which is the errand
    # this whole item exists to delete. The marker distinguishes them; absent it (a lane
    # spawned before this shipped, or a marker path that could not be resolved) the
    # behaviour is exactly what it was, which is the safe direction to degrade in.
    guard = f"[ \"$rc\" -ne 0 ]" + (f" && [ ! -f {q_marker} ]" if marker else "")
    tail = f"; rm -f {q_marker}" if marker else ""
    return (f"{inner}; rc=$?; if {guard}; then "
            f"printf '\\n\\033[31m── lane exited %s ──\\033[0m\\n' \"$rc\"; "
            f"echo 'The output above is why. This pane is held open so it survives; "
            f"press Enter to close it.'; read _; fi{tail}")


def _dispatch_prompt(wid: str, did: str, snapshot_id: str | None,
                     title: str | None = None, goal: str | None = None) -> str:
    """The brief a dispatched lane starts on. It self-claims (the operator's ruling)
    and STOPS on a lost race rather than working an item another lane owns.

    It also DECIDES rather than asking, and PARKS rather than blocking (R3 of the
    2026-09-04 consultant brief, ruled by operator in session ~208; WI-0274 item (1)).

    This prompt used to end "Ask me questions exactly as you would in a session I had
    opened by hand." That sentence was wrong in a way that cost whole fan-outs: a
    dispatched lane has no one to ask. It was opened by a dispatch, not by a person, so a
    question does not reach anybody — it holds a lane slot that nothing is coming to
    release. The predictable result is most lanes of a fan-out idle at once, many relayed
    messages to keep them moving, and answers given only to keep the lanes moving, not
    considered. A
    rubber-stamped answer then lands in the record as the operator's considered decision, which is
    false provenance of exactly the kind ADR-0112 exists to prevent.

    Delivering this by hand to each lane AFTER it had already stopped is the errand shape
    the a-verb-is-still-an-errand habit names. It belongs in the opening prompt, which is
    the only place that reaches a lane before it stalls.

    WI-0390: this is no longer the argv the lane is launched with — it is rendered into
    the lane's own session-start orientation by `_dispatch_brief_block`. The text is
    unchanged; only the channel moved, because the argv channel was the thing suppressing
    canon. It remains the exact string `_dispatch_rebrief_tmux` types into a lane that
    came up without one, so the two routes cannot drift apart (P16).

    `title` is supplied by the spawner where it has one (recorded on the spawn slot), and
    falls back to this tree's store. The fallback matters because a lane reads a work-item
    store frozen at its own base commit: rendering the brief inside the lane would
    otherwise be a second, differently-stale read of a title the spawner already knew."""
    if title is None:
        title = _dispatch_item_title(wid)
    return (
        f"You have been dispatched on {wid} — {title} "
        f"(dispatch {did}, snapshot {snapshot_id or 'n/a'}). "
        "Run your startup and tell me who you are. Then claim your item with "
        f"`poga work claim {wid}` BEFORE doing any work on it. If the claim is refused, "
        "say so plainly and stop — another lane owns it; do not work it anyway. "
        f"Once claimed, work {wid}. "
        "DECIDE — do not ask. A design trade-off you have a defensible recommendation on "
        "is the work, not an escalation: make the call, and record it with its reasoning "
        "and the alternative you rejected under `### Decisions I made without you, for "
        "review` in your journal, so operator audits a batch afterwards. ESCALATE ONLY WHEN one "
        "of these holds: the question needs something only operator has — his knowledge, his "
        "credentials, or a physical act by him; or it changes exposure, money or PII; or "
        "it changes his operating model; or the act is genuinely irreversible or very "
        "costly to undo, or contradicts something operator has actually said. A "
        "RECOMMENDATION YOU ALREADY BELIEVE IS NOT A QUESTION — act on it, and record "
        "the reason. The test that settles everything else: if he cannot tell the two "
        "outcomes apart from where he sits, it is not his decision. "
        "NEVER BLOCK — you have no one to ask. This lane was opened by a dispatch, not by "
        "a person, so a question holds a slot nobody is coming to release. When you truly "
        f"must escalate: write the question on the item — put the prose in a file and "
        f"pass `poga work edit {wid} --append-notes-file <path>`, never an inline quoted "
        "string, because a shell eats backticks and dollar-parens out of one silently "
        f"(WI-0289) — set it aside (`poga work status {wid} --status held`), "
        "close honestly with `session.py end`, and let the slot go. operator answers from the "
        "board and re-dispatches. "
        "NEVER PUT A DIALOG IN FRONT OF operator — this is a prohibition, not a preference "
        "(the operator's ruling, session ~185: no poga session may ever put a modal dialog in "
        "front of him). "
        "This pane is DETACHED and nobody is watching it, so anything that waits for a "
        "keystroke stops the lane silently: it goes on reporting live while doing nothing, "
        "and only a human sitting at this pane can clear it. Three surfaces on this runtime "
        "can render one, and all three are already shut off or denied for you — do not "
        "reach around any of them. (1) The feedback/bug-report tool `SendFeedback`, off via "
        "`feedbackDrafts: \"off\"`; do not re-enable it and do not use `/bug` or `/feedback` "
        "— its queued draft is what held a lane on 2026-09-03. (2) The goal-proposal tool "
        "`ProposeGoal`, off via `modelProposedGoals: \"disabled\"`; its approval is one "
        "keypress nobody is here to press. (3) The question picker `AskUserQuestion`, "
        "denied fleet-wide by the `check-question` guard (P17). Do not enter plan mode "
        "either — its approval step is the same trap. If a dialog appears anyway that is a "
        "substrate DEFECT, not your cue to wait: record it on the item and park it by the "
        "NEVER BLOCK path above."
        # WI-0401. Appended rather than woven in, so a dispatch that names no goal
        # produces the byte-identical brief it produced before this shipped — the
        # property `_dispatch_rebrief_tmux` and the brief-state check both rest on.
        + (f" YOUR GOAL — what DONE looks like for this lane: {goal.strip()} It was "
           "checked at authoring time for a clause gated on something you might never be "
           "able to settle. `session.py goal` numbers its clauses for you. As each one "
           "resolves, say so "
           "with `session.py goal-dispose <n> <state>`; a clause an instruction took away "
           "is `moot` and one you cannot satisfy without a person is `blocked`, and both "
           "need the words that did it (`--because`). `end` prints the result, so the "
           "record of why this lane closed where it did is readable rather than absent "
           "(WI-0401)." if (goal or "").strip() else "")
    )


#: The heading the brief is rendered under inside the session-start orientation. Named
#: rather than inlined because three parties key on it — the renderer, the receipt that
#: says whether it was rendered, and the tests that assert the brief reached the lane.
DISPATCH_BRIEF_HEADING = "=== YOUR DISPATCH BRIEF ==="


def _dispatch_brief_block(did: str = "", wid: str = "") -> str:
    """This lane's dispatch brief, ready to append to the session-start orientation —
    or `""` when this session is not a dispatched lane.

    WI-0390 layer 2. The brief used to travel as `poga`'s trailing argument, which
    `has_operator_prompt` reads as the operator's own prompt and which therefore cost the
    lane its canon (see `_dispatch_spawn_command`). It travels here instead, on the one
    channel every runtime already has: the orientation `session.py start` builds, which
    reaches a native lane as the SessionStart hook's `additionalContext` and every other
    runtime as the `--prep` session-context payload.

    DERIVED, NOT TRANSMITTED. Nothing new rides the spawn line: `POGA_DISPATCH` and
    `POGA_DISPATCH_ITEM` are already exported there, the dispatch record and the spawn
    slot already exist in the shared coord store, and the brief is a pure function of
    them. A brief copied into the environment or into a sidecar file would be a second
    copy to keep in step with `_dispatch_prompt` and a second way to arrive stale (P16).

    EMPTY IS A REAL ANSWER, not a failure: a hand-launched lane has no dispatch in its
    environment and must get exactly the orientation it got before this shipped. The
    guard that fires on correct code gets deleted."""
    did = (did or os.environ.get("POGA_DISPATCH", "")).strip()
    wid = (wid or os.environ.get("POGA_DISPATCH_ITEM", "")).strip()
    # The ITEM is what makes a brief; the dispatch id only decorates it. A lane spawned by
    # an older dispatch, or one whose record has since been swept, still gets told what to
    # work on rather than nothing at all.
    if not wid:
        return ""
    slot = _dispatch_slot_path(did, wid) if did else None
    srec = _coord_read(slot) if (slot and slot.is_file()) else None
    snapshot_id = (srec or {}).get("snapshot_id")
    title = (srec or {}).get("title")
    # WI-0401: the goal is a property of the DISPATCH, not of the per-item slot — one
    # wave, one statement of what done looks like — so it is read from the record rather
    # than the slot, and read even when the slot answered everything else.
    goal = ""
    rec = _dispatch_read(did) if did else None
    if rec:
        goal = (rec.get("goal") or "").strip()
        if snapshot_id is None:
            snapshot_id = rec.get("snapshot_id")
    try:
        brief = _dispatch_prompt(wid, did, snapshot_id, title=title, goal=goal)
    except Exception:
        return ""
    return (f"{DISPATCH_BRIEF_HEADING}\n"
            "This session was opened by a dispatch, not by a person. The brief below is "
            "your assignment and it OUTRANKS the generic opening prompt you were launched "
            "with — run the session-start steps above, then do what it says.\n\n"
            f"{brief}")


def _dispatch_session_manager() -> str:
    """The launchd session type this process runs in — `Aqua` inside the user's GUI login,
    `Background` / `System` for an SSH login, a LaunchAgent, or a daemon. Empty when it
    cannot be determined (non-macOS, `launchctl` missing).

    This is the entire GUI detection, and it is cheap and synchronous. The alternative —
    probing with a real Apple Event — is the ~120 s block that made this necessary in the
    first place: a detector must not reproduce the failure it detects."""
    try:
        r = subprocess.run(["launchctl", "managername"], text=True,
                           capture_output=True, check=False, timeout=5)
    except Exception:
        return ""
    return (r.stdout or "").strip()


def _dispatch_apple_events_available() -> bool:
    """Whether an Apple Event from THIS session can reach a GUI app.

    Only `Aqua` qualifies, and the allowlist direction is deliberate: an unrecognised
    manager name resolves to False, which routes the spawn to tmux — a surface that works
    everywhere. Guessing wrong therefore costs a detached session instead of a 20 s block
    on a lane that never opens ([P19](principles/master.md), fail toward the safe side).

    Automation permission cannot substitute for this. The grant is scoped to apps inside
    the GUI login session, so a `Background` session (every SSH login — a common way to
    drive a fleet from another machine) has nothing to grant."""
    return _dispatch_session_manager() == "Aqua"


def _dispatch_surface() -> str:
    """The spawn surface, validated and — by default — DETECTED.

    `spawn_surface` in session.config.json may name a surface explicitly; its default,
    `auto`, picks the one that can actually work from this session: a GUI tab when we are
    inside the Aqua login, tmux otherwise. An UNLISTED value is still refused by name
    rather than tried, and a chosen-but-unusable surface is refused with the specific
    reason and its fix — never degraded silently into a different one
    ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes))."""
    want = (CFG or {}).get("spawn_surface") or "auto"
    if want != "auto" and want not in SPAWN_SURFACES:
        raise ValueError(
            f"spawn_surface '{want}' is not a supported surface "
            f"({', '.join(SPAWN_SURFACES)}, or 'auto'). Dispatch refuses an unlisted "
            "surface rather than degrading — fix `spawn_surface` in session.config.json.")

    if want == "auto":
        if _dispatch_apple_events_available():
            return "Terminal"
        if not _tmux_bin():
            mgr = _dispatch_session_manager() or "unknown"
            raise ValueError(
                f"no usable spawn surface. This session's launchd manager is '{mgr}', not "
                "'Aqua', so an Apple Event cannot reach Terminal or iTerm2 from here (an "
                "SSH login is the usual cause, and macOS Automation permission does not "
                "apply to it). The surface that does work from here is tmux, and tmux is "
                "not installed: `brew install tmux`. Or dispatch from a Terminal tab in "
                "the Runner's own GUI session.")
        return "tmux"

    if want == "tmux" and not _tmux_bin():
        raise ValueError(
            "spawn_surface is 'tmux' but tmux is not installed: `brew install tmux`.")
    return want


def _dispatch_surface_mismatch(surface: str) -> str | None:
    """A one-line warning when an EXPLICIT GUI surface cannot work from this session.

    Reported up front rather than after the spawn, because the failure it predicts costs
    20 s per item and reads like a hung launcher. The configured value is still honoured —
    an explicit declaration is not overridden by a detector — so this warns, never
    rewrites."""
    if surface in GUI_SPAWN_SURFACES and not _dispatch_apple_events_available():
        mgr = _dispatch_session_manager() or "unknown"
        return (f"WARNING: spawn_surface is '{surface}', but this session's launchd manager "
                f"is '{mgr}', not 'Aqua' — an Apple Event cannot reach a GUI app from here, "
                f"and Automation permission does not change that (it is scoped to the GUI "
                f"login). Each spawn will block {DISPATCH_SPAWN_TIMEOUT_SECONDS}s and fail. "
                f"Set `spawn_surface` to 'tmux' or 'auto', or dispatch from a Terminal tab "
                f"in the GUI session.")
    return None


def _dispatch_open_tmux(cmd: str, name: str) -> tuple[bool, str]:
    """Start a dispatched lane in a detached, named tmux session. (ok, detail).

    This is the surface that works from ANY session — a GUI tab, an SSH login, a
    LaunchAgent — because it is a plain child process rather than a request to a GUI app.
    The cost is honest and named in the detail: no window appears, so the attach command IS
    the deliverable. A lane running where nobody is told to look is the silent strand this
    design exists to prevent, so the caller reports the attach line to the operator.

    NOT gate-guarded (ADR-0119 D4). `SpawnedMeansObservedTest` is this function's own
    hermetic unit test — it mocks `_tmux_bin` AND `subprocess.run` and pins all three
    outcomes — and the unmocked reach WI-0271 measured was `_dispatch_rebrief_tmux`, which
    is guarded, not this. The guard goes where the reach is."""
    tmux = _tmux_bin()
    if not tmux:
        return False, "tmux is not installed: `brew install tmux`"
    try:
        r = subprocess.run([tmux, "new-session", "-d", "-s", name, cmd],
                           cwd=ROOT, text=True, capture_output=True, check=False,
                           timeout=DISPATCH_SPAWN_TIMEOUT_SECONDS)
    except subprocess.TimeoutExpired:
        return False, f"tmux blocked for {DISPATCH_SPAWN_TIMEOUT_SECONDS}s starting '{name}'"
    except Exception as e:
        return False, f"could not run tmux ({e})"
    if r.returncode != 0:
        detail = (r.stderr or r.stdout or "tmux failed").strip()
        if "duplicate session" in detail.lower():
            detail += (f" — a lane for this item is already running; attach with "
                       f"`tmux attach -t {name}` or kill it with `tmux kill-session -t {name}`")
        return False, detail
    # WI-0185: CONFIRM, do not assume. `spawned` counted launches ATTEMPTED, not lanes
    # alive, so the record asserted a lane that did not exist and every reader downstream
    # believed it — dispatch-status showed 2, attach opened a tab for it, the operator
    # counted two. `tmux new-session` exiting 0 only says tmux accepted the request; a
    # command that dies immediately (the lost worktree race) takes its session with it.
    # One cheap `has-session` turns a silent loss into a named one.
    try:
        h = subprocess.run([tmux, "has-session", "-t", name], capture_output=True,
                           text=True, check=False, timeout=DISPATCH_SPAWN_TIMEOUT_SECONDS)
    except Exception:
        # Could not look. NOT a failure — reporting a live lane as dead would strand it
        # worse than the bug being fixed. Say so and let the observed-set check in
        # `attach` (WI-0186) be the second line of defence.
        return True, (f"in tmux session '{name}' (could not confirm it is up) — "
                      f"attach with `tmux attach -t {name}`")
    if h.returncode != 0:
        return False, (f"tmux accepted the launch but session '{name}' is already gone — "
                       f"the lane's command exited immediately. Its output died with it; "
                       f"`poga dispatch {name.split('-')[-1]} --go` alone to see the error.")
    return True, f"in tmux session '{name}' — attach with `tmux attach -t {name}`"


def _dispatch_open_tab(cmd: str, surface: str, name: str = "") -> tuple[bool, str]:
    """Open a new lane running `cmd` on `surface`. (ok, detail) — and on SUCCESS the detail
    may carry operator-facing instructions (tmux's attach line), not just failure text.

    Bounded by DISPATCH_SPAWN_TIMEOUT_SECONDS — see the note above; a blocked Apple Event
    is reported as a named, actionable failure rather than waited out."""
    if surface == "tmux":
        return _dispatch_open_tmux(cmd, name or "poga-lane")
    if surface == "iTerm2":
        script = (f'tell application "iTerm2"\n'
                  f'  activate\n'
                  f'  tell current window to create tab with default profile\n'
                  f'  tell current session of current window to write text {_applescript_str(cmd)}\n'
                  f'end tell')
    else:
        script = (f'tell application "Terminal"\n'
                  f'  activate\n'
                  f'  do script {_applescript_str(cmd)}\n'
                  f'end tell')
    try:
        r = subprocess.run(["osascript", "-e", script], cwd=ROOT, text=True,
                           capture_output=True, check=False,
                           timeout=DISPATCH_SPAWN_TIMEOUT_SECONDS)
    except subprocess.TimeoutExpired:
        return False, (f"osascript blocked for {DISPATCH_SPAWN_TIMEOUT_SECONDS}s "
                       f"opening {surface}. {_APPLE_EVENT_PERMISSION_HINT}")
    except Exception as e:                       # osascript absent (non-macOS), etc.
        return False, f"could not run osascript ({e})"
    if r.returncode != 0:
        detail = (r.stderr or r.stdout or "osascript failed").strip()
        if "-1712" in detail or "timed out" in detail.lower():
            detail += f" — {_APPLE_EVENT_PERMISSION_HINT}"
        return False, detail
    return True, ""


def _dispatch_try_spawn(rec: dict, wid: str, identity: str,
                        dry_run: bool = False) -> tuple[bool, str]:
    """Draw the exclusive right to spawn `wid` for this dispatch, then open its tab.

    The slot is an atomic exclusive-create in the shared coord store, so two lanes
    landing simultaneously cannot both spawn the same item — the spawn right is DRAWN,
    never computed from what looks free (`numbers-are-drawn-never-picked`). The slot is
    also the item's provenance record: it exists before the tab does, so nothing
    dispatch-spawned can ever be an anonymous phantom."""
    did = rec["dispatch_id"]
    slot = f"{did}__{wid}"
    # WI-0390: the item's TITLE is recorded on the slot at spawn time. The lane renders
    # its own brief now, and a lane reads a work-item store frozen at its base commit —
    # so without this the title would be a second, differently-stale read of something
    # the spawner already had in hand.
    ok, holder = _coord_try_acquire(
        DISPATCH_SPAWN_KIND, slot, identity, DISPATCH_SPAWN_TTL_SECONDS,
        dispatch_id=did, item=wid, snapshot_id=rec.get("snapshot_id"),
        title=_dispatch_item_title(wid),
        dispatched_by=rec.get("created_by"), spawned_by=identity)
    if not ok:
        who = holder.get("session_id", "?")
        return False, f"{wid}: spawn slot already drawn by {who}"
    # WI-0259 — the cross-dispatch half. Drawn AFTER the per-dispatch slot, deliberately:
    # the slot is this item's provenance record and must still exist before any tab is
    # asked for, and taking it first means a same-dispatch retry is refused by the slot
    # (its own case) before it can ever reach a guard it would wrongly reclaim.
    _dispatch_item_sweep()
    gok, gholder = _dispatch_item_guard(wid, did, identity)
    if not gok:
        _coord_release(DISPATCH_SPAWN_KIND, slot, identity, force=True,
                       reason="cross-dispatch item guard")
        other = gholder.get("dispatch_id") or gholder.get("session_id") or "?"
        return False, (f"{wid}: already being spawned by dispatch {other} — "
                       f"not spawning a second lane for it")
    root = _shared_work_root()
    # WI-0288 R2 (2): the lane is launched WITH its budget. Read off the dispatch record
    # rather than the environment, so every lane in a wave carries the number that
    # dispatch actually recorded — and an older record with no `turn_budget` key spawns
    # exactly as it did before rather than inheriting today's default retroactively.
    #
    # WI-0390: no brief is passed here any more — see `_dispatch_spawn_command`. The
    # runtime comes off the record for the same reason the budget does: every lane in a
    # wave gets what dispatch recorded, and a record predating the flag spawns exactly as
    # it did before rather than inheriting a default retroactively.
    cmd = _dispatch_spawn_command(root, did, wid,
                                  turn_budget=rec.get("turn_budget"),
                                  runtime=rec.get("runtime"))
    surface = rec.get("surface") or "Terminal"
    name = _tmux_session_name(did, wid)
    if dry_run:
        where = f"tmux session '{name}'" if surface == "tmux" else f"{surface} tab"
        return True, f"{wid}: would open a {where}"
    ok2, detail = _dispatch_open_tab(cmd, surface, name)
    if not ok2:
        # Release the slot so a retry (or another lander) can take the item; a held slot
        # over a tab that never opened is exactly a silent strand.
        _coord_release(DISPATCH_SPAWN_KIND, slot, identity, force=True)
        _coord_release(DISPATCH_ITEM_KIND, wid, identity, force=True,
                       reason="spawn failed")
        return False, f"{wid}: spawn FAILED — {detail}"
    # A tmux lane opens no window, so its attach line is not decoration — it is the only
    # thing that makes the lane reachable. Carry the success detail through.
    return True, f"{wid}: lane opening" + (f" {detail}" if detail else "")


def _dispatch_rebrief_tmux(name: str, prompt: str) -> tuple[bool, str]:
    """Type the brief into a lane that came up without one.

    TWO send-keys calls, and that is not a style choice: combined into one, the TUI
    swallows the Enter and the text sits at the prompt unsent (measured in a peer lane,
    session ~185). `-l` sends the text literally, so a brief containing `;` or a key name
    cannot be re-interpreted as tmux key syntax.

    ADR-0119 D4. WI-0271 caught `CapBindsOnTheFirstWaveTest` issuing a real
    `tmux send-keys -t poga-D-wave01-WI-0001` at the operator's LIVE tmux server during a
    land — keystrokes typed into somebody's actual session by a test run."""
    if _under_gate():
        return False, "not re-briefed — this suite is the land gate (ADR-0119 D4)"
    tmux = _tmux_bin()
    if not tmux:
        return False, "tmux is not installed here"
    try:
        for argv in ([tmux, "send-keys", "-t", name, "-l", prompt],
                     [tmux, "send-keys", "-t", name, "Enter"]):
            r = subprocess.run(argv, capture_output=True, text=True, check=False,
                               timeout=DISPATCH_SPAWN_TIMEOUT_SECONDS)
            if r.returncode != 0:
                return False, (r.stderr or r.stdout or "send-keys failed").strip()
    except Exception as e:
        return False, f"could not run tmux send-keys ({e})"
    return True, ""


def _dispatch_confirm_briefs(rec: dict, items: list[str] | None = None,
                             grace: int | None = None) -> list[str]:
    """Turn `spawned` from a claim about processes into a claim about BRIEFED lanes.

    WI-0248 (b). Runs once per wave, not once per lane: it polls every unresolved slot
    together and returns the moment they all resolve, so a healthy five-lane wave costs
    about one poll and only a genuinely broken one pays the full grace.

    Where a lane is both not-briefed AND not-working, it re-briefs it and waits for the
    lane's own `.pending-start` to be consumed — the receipt is the artifact the lane's own
    machinery produces, never a self-report and never our say-so
    ([`a-close-is-the-banner-not-the-sentence`]).

    BOTH signals are required before typing into a session. Not-briefed alone is not
    enough: the argv probe can answer `unknown`, and a lane that is merely thinking hard
    must never have text injected into it."""
    lines: list[str] = []
    did = rec.get("dispatch_id") or ""
    # Only THIS wave's lanes. The log accumulates across waves, and re-confirming an
    # already-settled lane would re-type a brief into a session that has been working for
    # an hour — the one thing this must never do.
    if items is None:
        items = [e.get("item") for e in (rec.get("log") or []) if e.get("item")]
    items = [str(w) for w in items if w]
    if not did or not items:
        return lines
    deadline = time.time() + (DISPATCH_BRIEF_GRACE_SECONDS if grace is None else grace)
    pending = list(items)
    states: dict[str, str] = {}
    # ALWAYS READ ONCE, THEN CHECK THE CLOCK. A `while … < deadline` never enters its body
    # at grace 0 and would report every slot `no-receipt` — including receipts already
    # sitting on disk. The grace bounds how long we WAIT, never whether we LOOK.
    first = True
    while pending and (first or time.time() < deadline):
        first = False
        still: list[str] = []
        for wid in pending:
            slot = _dispatch_slot_path(did, str(wid))
            srec = _coord_read(slot) if (slot and slot.is_file()) else None
            state = str((srec or {}).get("brief") or "").strip()
            if state in ("briefed", "unbriefed", "unknown"):
                states[str(wid)] = state
            else:
                still.append(wid)
        pending = still
        # Don't sleep on the way out — at grace 0 that would cost a poll interval to learn
        # nothing, and on the last iteration it delays the report by a wait already spent.
        if pending and time.time() + DISPATCH_BRIEF_POLL_SECONDS <= deadline:
            time.sleep(DISPATCH_BRIEF_POLL_SECONDS)
    # A slot that never reported is NOT evidence of a healthy lane. It is the case where
    # the hook did not run at all, which is exactly how the D-d9202c lanes looked.
    for wid in pending:
        states[str(wid)] = "no-receipt"

    # Merge into the record rather than replace it: a later wave must not erase what an
    # earlier one established, or `briefed` would count only the most recent lanes.
    merged = dict(rec.get("brief_states") or {})
    merged.update(states)
    rec["brief_states"] = merged
    rec["briefed"] = sum(1 for s in merged.values() if s in DISPATCH_BRIEFED_STATES)

    surface = rec.get("surface") or "Terminal"
    for wid, state in sorted(states.items()):
        # WI-0409. ASKED OF EVERY LANE, INCLUDING THE BRIEFED ONES, because "briefed" was
        # the state both wedged lanes of D-4d6df1 reported while doing nothing. The old
        # `if state == "briefed": continue` treated delivery as completion, and delivery is
        # the one thing that had genuinely succeeded.
        idle = _dispatch_lane_awaiting_input(wid)
        if state == "briefed" and idle is not True:
            continue
        lane = _dispatch_lane_for(did, wid)
        working = _dispatch_lane_working(lane)
        if working is True and idle is not True:
            # Not briefed on the command line, but demonstrably working — a lane someone
            # briefed by hand, or a receipt we could not read. Leave it alone.
            lines.append(f"  {wid}: brief {state}, but the lane is working — left alone")
            continue
        if idle is True:
            # Briefed or not, this lane is registering that it wants input. `working` is
            # True here almost by construction (the startup turn consumed the marker), so
            # the branch above would have called it healthy — which is the whole defect.
            # A SHORT NUDGE, never the brief again: it already has the brief.
            if surface != "tmux":
                lines.append(f"  {wid}: BRIEFED BUT IDLE — waiting for input, and surface "
                             f"{surface!r} cannot be nudged automatically; send it a "
                             f"message with SendMessage")
                continue
            ok, detail = _dispatch_rebrief_tmux(_tmux_session_name(did, str(wid)),
                                                DISPATCH_RESUME_PROMPT)
            if not ok:
                lines.append(f"  {wid}: BRIEFED BUT IDLE — nudge FAILED: {detail}")
                continue
            end = time.time() + DISPATCH_REBRIEF_CONFIRM_SECONDS
            moved = False
            while time.time() < end:
                if _dispatch_lane_awaiting_input(wid) is not True:
                    moved = True
                    break
                time.sleep(DISPATCH_BRIEF_POLL_SECONDS)
            merged[wid] = "nudged" if moved else "nudge-unconfirmed"
            lines.append(
                f"  {wid}: was BRIEFED BUT IDLE — nudged, lane is now working" if moved else
                f"  {wid}: was BRIEFED BUT IDLE — nudge sent but it is still waiting; "
                f"reach it with SendMessage (`ListAgents` has the address)")
            continue
        if state == "unknown":
            lines.append(f"  {wid}: brief UNKNOWN and lane not working — "
                         f"cannot tell; inspect `tmux attach -t {_tmux_session_name(did, wid)}`")
            continue
        if surface != "tmux":
            lines.append(f"  {wid}: NOT BRIEFED and idle — surface {surface!r} cannot be "
                         f"re-briefed automatically; re-send the brief in that window")
            continue
        ok, detail = _dispatch_rebrief_tmux(_tmux_session_name(did, str(wid)),
                                            _dispatch_prompt(str(wid), did,
                                                             rec.get("snapshot_id")))
        if not ok:
            lines.append(f"  {wid}: NOT BRIEFED and re-brief FAILED — {detail}")
            continue
        end = time.time() + DISPATCH_REBRIEF_CONFIRM_SECONDS
        started = False
        while time.time() < end:
            if _dispatch_lane_working(lane) is True:
                started = True
                break
            time.sleep(DISPATCH_BRIEF_POLL_SECONDS)
        if started:
            rec["briefed"] = int(rec.get("briefed", 0)) + 1
            merged[wid] = "re-briefed"
            lines.append(f"  {wid}: was NOT BRIEFED — re-briefed, lane is now working")
        else:
            merged[wid] = "rebrief-unconfirmed"
            lines.append(f"  {wid}: was NOT BRIEFED — re-brief sent but the lane has not "
                         f"started; `tmux attach -t {_tmux_session_name(did, wid)}`")
    rec["brief_states"] = merged
    return lines


def _dispatch_brief_view(rec: dict) -> dict[str, str]:
    """What each of this dispatch's lanes reports about its brief, RIGHT NOW.

    Derived at read time from the slots themselves, with the record's stored `brief_states`
    as the fallback — so a receipt that landed after the confirm pass (or a dispatch whose
    wave predates it) is still reflected, and the count is never a stale cache of a
    question the store can answer directly.

    The stored value wins only where the slot is silent: `re-briefed` and
    `rebrief-unconfirmed` are conclusions the confirm pass drew, and no slot records them."""
    view = dict(rec.get("brief_states") or {})
    did = rec.get("dispatch_id") or ""
    if not did:
        return view
    for entry in (rec.get("log") or []):
        wid = str(entry.get("item") or "")
        if not wid:
            continue
        if view.get(wid) in ("re-briefed", "rebrief-unconfirmed"):
            continue
        slot = _dispatch_slot_path(did, wid)
        srec = _coord_read(slot) if (slot and slot.is_file()) else None
        state = str((srec or {}).get("brief") or "").strip()
        if state:
            view[wid] = state
        else:
            view.setdefault(wid, "no-receipt")
    return view


def _dispatch_print_unbriefed(rec: dict, indent: str = "  ") -> None:
    """Name every lane that is running without a brief, on every surface that reports a
    dispatch. Printed WITHOUT `-v`, for the same reason the stall reason is: a lane that
    only explains itself under a flag is a lane nobody reads the explanation of."""
    states = _dispatch_brief_view(rec)
    did = rec.get("dispatch_id") or ""
    if not did:
        return
    for wid in sorted(states):
        state = states[wid]
        if state in ("briefed", "re-briefed", "unknown"):
            continue
        # THE SAME TWO-SIGNAL RULE THE RE-BRIEF USES, applied to reporting — and it is here
        # because running this against real records without it printed "the lane is alive
        # but was never told what to do" over every lane of every dispatch that predates
        # the receipt. `no-receipt` is ABSENCE OF A MECHANISM, not evidence of a stranded
        # lane: dispatches older than this feature have no receipts, and finished lanes are
        # gone. A silent-slot lane is only worth naming when the lane still exists AND is
        # demonstrably not working. `unbriefed` is a MEASUREMENT and stands on its own.
        lane = _dispatch_lane_for(did, wid)
        idle = _dispatch_lane_working(lane) is False
        if state != "unbriefed" and not idle:
            continue
        # Say only what was measured. "The lane is alive" is a claim about a process this
        # function never looked at, and an `unbriefed` receipt from an hour ago says
        # nothing about now ([`no-fabricated-data`]).
        where = "and it is idle" if idle else "current state not checked"
        print(f"{indent}UNBRIEFED — {wid} ({state}): this lane never received its brief "
              f"({where}).")
        print(f"{indent}  attach: `tmux attach -t {_tmux_session_name(did, wid)}`")


def _dispatch_state(rec: dict) -> str:
    """`complete` | `draining` | `stalled`.

    STALLED is the state this vocabulary was missing: a queue that nothing will advance,
    because advancement rides on a landing lane from this dispatch and none exists. It must
    not share a word with a healthy wave still working — the whole failure of the original
    was that `[draining]` covered both."""
    if not rec.get("queue"):
        return "complete"
    if int(rec.get("spawned", 0)) <= 0:
        return "stalled"
    return "draining"


def _dispatch_advance(rec: dict, identity: str, want: int,
                      dry_run: bool = False, confirm: bool = True) -> list[str]:
    """Spawn up to `want` more lanes for this dispatch, respecting cap and budget.
    Mutates and persists `rec`. Returns human-readable report lines.

    `confirm` runs the WI-0248 brief confirmation over the lanes THIS call spawned, so the
    wave reports briefed lanes rather than launched processes. Off for dry runs and for
    callers that must not block."""
    lines: list[str] = []
    spawned_now: list[str] = []
    cap = int(rec.get("cap") or DISPATCH_CAP_DEFAULT)
    budget = int(rec.get("budget") or 0)
    did = str(rec.get("dispatch_id") or "")
    # WI-0238. The lanes THIS call has spawned, which no coordination read can see yet —
    # their lane-alloc record is written by the child, seconds from now. Carried across
    # iterations so the cap is checked against what will exist rather than what has
    # registered; without it the first wave is unbounded, which is the one place the cap
    # is the only bound there is. Per-call by design: a fresh `_dispatch_after_land`
    # process starts empty and spawns one, so there is nothing for it to remember.
    pending: set[str] = set()
    for _ in range(max(0, want)):
        if not rec.get("queue"):
            break
        if rec.get("spawned", 0) >= budget:
            reason = (f"budget reached ({budget} spawned) — stopping; "
                      f"{len(rec['queue'])} item(s) left. Re-run `poga dispatch` to continue.")
            _dispatch_note_block(rec, "budget", reason)
            lines.append(reason)
            break
        live = _dispatch_live_lane_count(pending)
        if live >= cap:
            reason = (f"cap reached ({live}/{cap} DISPATCHED lanes) — holding "
                      f"{len(rec['queue'])} item(s)")
            # The self-draining promise is TRUE ONLY IF a lane from THIS dispatch is
            # actually running. The queue is advanced by a landing session that carries
            # `POGA_DISPATCH` (`_dispatch_after_land`) and by nothing else — so with zero
            # spawned there is no such session, will never be one, and the cheerful
            # "the next lane to LAND spawns the next one" is a false promise printed over
            # a permanent deadlock. Observed live: D-4d41da, 2026-08-22, cap 2 against 2
            # existing lanes — spawned 0, sat `[draining]` for six hours (WI-0156).
            #
            # KEPT AFTER the cap was narrowed to dispatched lanes, which makes reaching
            # this branch with zero spawned no longer possible by the route that produced
            # D-4d41da. It stays because the honest message costs nothing and the
            # unreachable case is only unreachable while the count stays narrow: a future
            # load guard that re-widens it would restore the deadlock and delete its own
            # explanation in the same edit. A message that survives its cause is cheaper
            # than one that has to be rediscovered.
            #
            # The remedy is spelled `python3 session.py dispatch-retry`, NOT `poga
            # dispatch-retry`: retry is a session.py subcommand and has never been a poga
            # verb, so the old text answered a stalled operator with a command poga refuses
            # — "'dispatch-retry' is not a poga verb" — from the one message whose entire
            # job is to get a permanently stuck queue moving again. A remedy the reader
            # cannot run is a second dead end printed over the first (WI-0158).
            if int(rec.get("spawned", 0)) > 0:
                reason += "; the next lane to LAND spawns the next one."
            else:
                reason += (f"; NOTHING will advance this queue — no lane from this dispatch "
                           f"is running, and only a lane carrying POGA_DISPATCH advances it. "
                           f"Free a lane or raise --cap, then "
                           f"`python3 session.py dispatch-retry "
                           f"{rec.get('dispatch_id', '<id>')}`.")
            _dispatch_note_block(rec, "cap", reason)
            lines.append(reason)
            break
        wid = rec["queue"][0]
        ok, detail = _dispatch_try_spawn(rec, wid, identity, dry_run=dry_run)
        lines.append(f"  {detail}")
        rec["queue"] = rec["queue"][1:]
        if ok:
            rec["spawned"] = int(rec.get("spawned", 0)) + 1
            pending.add(f"{did}::{wid}")
            spawned_now.append(wid)
            _dispatch_clear_block(rec)
            rec.setdefault("log", []).append(
                {"item": wid, "at": _coord_iso(time.time()), "by": identity})
        else:
            # A refused slot means someone else took it; a failed spawn is reported by
            # name. Either way the item leaves this lander's queue view rather than
            # spinning — but a FAILED one is re-queued at the back so it is not lost.
            if "FAILED" in detail:
                rec["queue"] = rec["queue"] + [wid]
                _dispatch_note_block(rec, "spawn-failed", detail)
                break
            _dispatch_note_block(rec, "slot-taken", detail)
    # WI-0248 (b): a lane is not "spawned" until it confirms it was told what to do. This
    # runs AFTER the whole wave, so the grace is paid once rather than once per lane, and
    # BEFORE the write, so the record persists the confirmed count and not the optimistic
    # one. Fail-open: a confirmation that itself breaks must not turn a wave that actually
    # spawned lanes into a failed dispatch.
    if confirm and not dry_run and spawned_now:
        try:
            conf = _dispatch_confirm_briefs(rec, items=spawned_now)
        except Exception as e:
            conf = [f"  brief confirmation could not run ({e}) — lanes may be unbriefed; "
                    f"`poga dispatched -v` re-checks"]
        if conf:
            # BOTH HALVES MUST DESCRIBE THIS WAVE. `rec["briefed"]` accumulates across
            # every wave, so pairing it with a this-wave denominator prints things like
            # `2/1 confirmed briefed this wave` — a numerator larger than its denominator,
            # arriving at exactly the moment an operator is looking at a real strand and
            # deciding whether to trust the counter.
            view = _dispatch_brief_view(rec)
            here = sum(1 for w in spawned_now
                       if view.get(w) in DISPATCH_BRIEFED_STATES)
            lines.append(f"  brief check: {here}/{len(spawned_now)} "
                         f"confirmed briefed this wave")
            lines.extend(conf)
    if not dry_run:
        _dispatch_write(rec)
    return lines


def _dispatch_after_land() -> None:
    """No master: the session that just LANDED pulls the next queued item and spawns it.

    Reads its dispatch id from the environment the spawning tab set, so a hand-opened
    lane never advances someone else's queue and a dispatched one needs no coordinator
    to tell it what comes next. Fail-open in every direction — a dispatch problem must
    never turn a successful land into a failed one."""
    did = os.environ.get("POGA_DISPATCH", "").strip()
    if not did:
        return
    try:
        rec = _dispatch_read(did)
        if not rec or not rec.get("queue"):
            return
        identity = _coord_identity()
        lines = _dispatch_advance(rec, identity, want=1)
        if lines:
            print(f"dispatch: {did} — " + "; ".join(x.strip() for x in lines))
    except Exception as e:
        print(f"dispatch: could not advance {did} ({e}) — "
              f"re-run `poga dispatch` to continue the queue.", file=sys.stderr)


def _dispatch_render_plan(rec: dict, ids: list[str], held: dict, skipped: dict,
                          bad: list[str], subagents: list[str],
                          why: dict[str, str] | None = None) -> list[str]:
    """The ONE approval surface — every item, its disposition, and what will NOT run."""
    items = {it["id"]: it for it in _wi_parse()}
    titles = {i: it["title"] for i, it in items.items()}
    cap, budget = rec["cap"], rec["budget"]
    first = ids[:budget]
    later = ids[budget:]
    # The surface belongs on the approval surface: since it is DETECTED, "10 tabs open" and
    # "10 detached tmux sessions you must attach to" are materially different things to
    # approve, and the operator should not have to infer which one they agreed to.
    surface = rec.get("surface") or "Terminal"
    where = ("detached tmux sessions — each prints its attach command"
             if surface == "tmux" else f"{surface} tabs")
    out = [f"Dispatch plan {rec['dispatch_id']} (snapshot {rec.get('snapshot_id') or 'n/a'}) "
           f"— cap {cap}, budget {budget}",
           f"  lanes open as: {where}"]
    # WI-0390: which AGENT the wave runs on belongs on the approval surface for the same
    # reason the surface does — "10 Claude lanes" and "10 Codex lanes" are materially
    # different things to approve, and the runtime's guard posture differs between them
    # (ADR-0082 D6: only claude-code declares `native`).
    _rt = _runtime_row(rec.get("runtime") or RUNTIME_DEFAULT)
    if _rt:
        out.append(f"  runtime: {_rt['id']} ({_rt['command']}), guards {_rt['guards']}"
                   + ("" if rec.get("runtime") else " — registry default, none requested"))
    if subagents:
        out.append("  subagents (run in THIS session):")
        out += [f"    {w:8} {titles.get(w, '')}" for w in subagents]
    if first:
        # WI-0238. This line used to read `min(len(first), cap)` — the cap as though it
        # were empty — and was printed by a wave that then ignored the cap entirely, so a
        # 15-item dispatch promised "5 now" and opened 15. With the cap now binding, the
        # remaining way to overstate is to ignore the lanes OTHER live dispatches already
        # hold, so the room is measured rather than assumed. An approval surface that
        # cannot be honoured is worse than none: it is what got approved.
        held_now = _dispatch_live_lane_count()
        room = max(0, cap - held_now)
        now = min(len(first), room)
        note = f"{now} now"
        if held_now:
            note += (f" — {held_now} of the cap {cap} is already held by live "
                     f"dispatched lane(s)")
        out.append(f"  lanes ({note}, rest as lanes land):")
        out += [f"    {w:8} {titles.get(w, '')}" for w in first]
        if now == 0:
            # The D-4d41da shape, caught at the only moment the operator is certainly
            # reading rather than hours later on the record (`declare-what-a-check-assumes`).
            out.append("    ⚠ NOTHING will spawn — the cap is already full. Raise --cap, "
                       "or wait for a dispatched lane to land.")
    if later:
        out.append(f"  beyond budget ({len(later)} — re-run dispatch to continue):")
        out += [f"    {w:8} {titles.get(w, '')}" for w in later]
    # WI-0376 clause 2. Silence about an item nobody could assess is not a clean bill:
    # everything above this line was planned as disjoint, and for 52 of the store's 55
    # live items that disjointness rests on no evidence whatsoever. The check names what
    # it could not reach rather than folding "couldn't tell" into "checked and it's fine"
    # ([`declare-what-a-check-assumes`](habits/master.md#declare-what-a-check-assumes)).
    # Printed ONLY for the items this dispatch will actually run — an unassessed item that
    # was skipped or held is not being planned as disjoint and does not need the warning.
    unassessed = []
    for w in list(first) + list(later):
        it = items.get(w)
        if not it:
            continue
        paths, prose = _wi_declared_paths(it)
        if not paths:
            unassessed.append((w, "no FILES: declaration"
                                  + (f"; `FILES:` names only {', '.join(prose)}" if prose
                                     else "")))
        elif prose:
            unassessed.append((w, f"partly assessed — {len(paths)} path(s) read, but "
                                  f"{', '.join(prose)} is not a path"))
    if unassessed:
        out.append(f"  NOT assessed for file overlap ({len(unassessed)} of "
                   f"{len(first) + len(later)} — planned as disjoint on no evidence):")
        out += [f"    {w:8} {why_not}" for w, why_not in unassessed]
    if held:
        out.append("  held (blocked by work outside this range):")
        out += [f"    {w:8} blocked by {', '.join(b)}" for w, b in sorted(held.items())]
    if skipped:
        out.append("  skipped:")
        out += [f"    {w:8} {why}" for w, why in sorted(skipped.items())]
    if bad:
        out.append(f"  UNRESOLVED (not in the snapshot or the store): {', '.join(bad)}")
        for t in bad:
            if (why or {}).get(t):
                out.append(f"    {t} — {why[t]}")
    if not first and not subagents:
        out.append("  nothing to dispatch.")
    return out




def cmd_dispatch(args: argparse.Namespace) -> None:
    """Fan a work-item range out to peer lanes. Plans by default; `--go` executes."""
    # WI-0401. THE FIRST THING THIS FUNCTION DOES, and the position is the point: a goal
    # carrying a clause the lane can never settle is refused before a snapshot is read,
    # before an ordinal range is resolved and before a dispatch id is drawn, so a refusal
    # costs the author one rewrite and nothing else (`validate before you draw an id`).
    #
    # REFUSED HERE RATHER THAN WARNED, because of where the cost lands otherwise: on a
    # lane that has already finished its work and cannot leave. On 2026-09-18 that was 34
    # turns after the journal was closed, with nobody attached to the pane to release it.
    # The author, at this moment, can still put the condition in the brief body — which is
    # where it informs the work without becoming a stop condition.
    goal = " ".join((getattr(args, "goal", "") or "").split())
    if goal:
        refusal = goal_conditional_refusal(goal, "dispatch")
        if refusal:
            print(refusal)
            sys.exit(2)
    # WI-0390 layer 1. Before this, dispatch had no runtime flag at all and its spawn line
    # carried no runtime selection, so every dispatched lane fell through to the registry
    # default — a dispatched Codex lane was not expressible, and an item asking for a
    # reading "at the first Codex dispatch" named a path that could not exist.
    #
    # RESOLVED HERE, ONCE, AND BY NAME. `_runtime_row` takes the id or the short alias
    # (D2: `-r cx` and `-r codex` are the same request) and the canonical id is what goes
    # on the record, so the spawn line is never an operator's abbreviation. An unknown id
    # refuses in front of the operator with the roster; the alternative is a wave of tabs
    # that each fail the same way with nobody attached to read it.
    runtime = (getattr(args, "runtime", "") or "").strip()
    if runtime:
        row = _runtime_row(runtime)
        if row is None:
            print(f"dispatch: unknown runtime {runtime!r}.\n{_runtime_roster()}")
            sys.exit(2)
        if not row.get("command"):
            print(f"dispatch: runtime {row['id']!r} has no launch command configured — "
                  f"nothing to spawn.\n{_runtime_roster()}")
            sys.exit(2)
        runtime = row["id"]
    snapshot_id, mapping = _dispatch_snapshot()
    if mapping is None or not mapping:
        print("dispatch: no work-item snapshot is pinned for this session, so an ordinal "
              "range cannot be resolved.\n"
              "          Run `poga work list` first — that pins the ordinal→id snapshot "
              "this command resolves against.\n"
              "          (Explicit WI-NNNN ids work with no snapshot.)")
        if not any(t.lower().startswith("wi-") for t in _dispatch_parse_range(args.items)):
            sys.exit(2)

    tokens = _dispatch_parse_range(args.items)
    if not tokens:
        print("dispatch: nothing selected — give a range like `1-10`, `1,3,5`, or WI ids.")
        sys.exit(2)
    ids, bad, why = _dispatch_resolve(tokens, mapping)
    subagents = [s.upper() if s.lower().startswith("wi-") else
                 mapping.get(s, s) for s in
                 (args.subagent.split(",") if args.subagent else []) if s]
    subagents = [s for s in subagents if s in ids]
    lane_ids = [i for i in ids if i not in subagents]

    ordered, held, skipped = _dispatch_order(lane_ids)

    cap = int(args.cap or DISPATCH_CAP_DEFAULT)
    # DEFAULT = one wave then stop (the operator's ruling). `--run X` gives the chain
    # a budget of X lanes to work through on its own; `--run all` means the whole range.
    if args.run is None:
        budget = cap
    elif str(args.run).lower() == "all":
        budget = len(ordered)
    else:
        budget = int(args.run)
    # WI-0288 R2 (2): the per-lane TURN budget, distinct from the spawn budget above.
    turn_budget = getattr(args, "max_turns", None)
    if turn_budget is None:
        turn_budget = DISPATCH_TURN_BUDGET_DEFAULT

    try:
        surface = _dispatch_surface()
    except ValueError as e:
        print(f"dispatch: {e}")
        sys.exit(2)
    mismatch = _dispatch_surface_mismatch(surface)

    rec = {
        "dispatch_id": f"D-{secrets.token_hex(3)}",
        "snapshot_id": snapshot_id,
        "created_at": _coord_iso(time.time()),
        "created_by": _coord_identity(),
        "surface": surface,
        "cap": cap,
        "budget": budget,
        # WI-0288 R2 (2). A THIRD bound, and the name is deliberate: `cap` is how many
        # lanes run at once, `budget` is how many are ever opened, and neither says
        # anything about how long ONE lane runs — which is the cost R2 was ruled on.
        # Never folded into `budget`: that key is the spawn count, `CapAndBudgetTest`
        # asserts on it, and conflating the two would silently re-scope both.
        "turn_budget": turn_budget,
        # WI-0390. Empty = the registry default, and stored empty rather than filled in
        # with `RUNTIME_DEFAULT`: "nobody asked" and "someone asked for claude-code" are
        # different states, and a record that cannot tell them apart cannot spawn a
        # byte-identical default line ([`declare-what-a-check-assumes`]).
        "runtime": runtime,
        # WI-0401. What DONE looks like for every lane in this wave, checked above and
        # therefore free of the clause shape that strands one. Empty is the ordinary
        # case: a dispatch that names no goal is unchanged by this.
        "goal": goal,
        "spawned": 0,
        "queue": list(ordered),
        "held": held,
        "subagents": subagents,
        "log": [],
    }

    for line in _dispatch_render_plan(rec, ordered, held, skipped, bad, subagents, why):
        print(line)
    if mismatch:
        print(f"\n{mismatch}")

    if not args.go:
        print("\n(plan only — nothing spawned. Re-run with `--go` to dispatch.)")
        return
    if bad and not args.force:
        print("\ndispatch: refusing to spawn with unresolved items above — fix the "
              "range (or land the lane, where one is named above), or re-run with "
              "--force to dispatch the resolved ones only.")
        sys.exit(2)
    if not ordered:
        print("\ndispatch: no lane items to spawn.")
        return

    _dispatch_write(rec)
    print(f"\ndispatch {rec['dispatch_id']}: spawning (surface {surface}) …")
    for line in _dispatch_advance(rec, rec["created_by"], want=budget):
        print(line)
    # WI-0248: `spawned` alone was the sentence three unbriefed lanes hid behind. Say both
    # numbers, always — a gap between them IS the finding, and a reader who sees only the
    # launch count has no way to notice it.
    print(f"dispatch {rec['dispatch_id']}: {rec['spawned']} lane(s) spawned, "
          f"{rec.get('briefed', 0)} confirmed briefed, {len(rec['queue'])} queued.")
    _dispatch_print_unbriefed(rec)
    state = _dispatch_state(rec)
    if state == "stalled":
        # A wave that spawned NOTHING is not a dispatch in progress, and must not be
        # reported as one. There is no landing lane to advance the queue, so this record
        # cannot move on its own — say that here, at the only moment the operator is
        # certainly reading, rather than leaving it to be discovered hours later.
        stall = (rec.get("stall") or {}).get("detail") or "no reason recorded"
        print(f"\n⚠ dispatch {rec['dispatch_id']} is STALLED — nothing spawned, "
              f"{len(rec['queue'])} item(s) queued and nothing will advance them.")
        print(f"  why: {stall}")
        # `python3 session.py …`, not `poga …`: both verbs are session.py subcommands and
        # neither is in poga's dispatch table, so the pair printed here — the two commands
        # an operator staring at a STALLED wave is likeliest to paste verbatim — both came
        # back "is not a poga verb" (WI-0158).
        print(f"  retry: `python3 session.py dispatch-retry {rec['dispatch_id']}`  ·  "
              f"give up: `python3 session.py dispatch-cancel {rec['dispatch_id']}`")
    elif rec["queue"]:
        print("Each lane spawns the next as it LANDS — no supervisor is running.")
    if subagents:
        print(f"Subagent items stay with you: {', '.join(subagents)}.")


def _dispatch_age_str(rec: dict) -> str:
    """How long this dispatch has existed, human-readable. An age is what turns `stalled`
    from a state into an alarm — six hours stalled and six seconds stalled are the same
    word and very different facts."""
    mins = _iso_age_min(rec.get("created_at"))
    if mins is None:
        return ""
    mins = int(round(mins))
    return f"{mins}m" if mins < 60 else f"{mins // 60}h {mins % 60:02d}m"


def cmd_dispatch_retry(args: argparse.Namespace) -> None:
    """Re-run a stalled dispatch's wave from the operator's side.

    ADR-0075's advancement model has no base case when the FIRST wave spawns nothing:
    the trigger is a landing lane carrying `POGA_DISPATCH`, and a dispatch that spawned
    zero has no such lane and never will. This verb IS that base case. It deliberately
    does not run automatically — the thing that blocked the wave (a full cap, a dead
    launcher) is usually still true a second later, and a self-retrying dispatch would
    spin instead of reporting."""
    rec = _dispatch_read(args.dispatch_id)
    if rec is None:
        print(f"dispatch-retry: no dispatch {args.dispatch_id} in the store.")
        raise SystemExit(2)
    if rec.get("cancelled"):
        print(f"dispatch-retry: {args.dispatch_id} was cancelled — nothing to retry.")
        raise SystemExit(2)
    if not rec.get("queue"):
        print(f"dispatch-retry: {args.dispatch_id} has an empty queue — nothing to retry.")
        return
    if args.cap is not None:
        rec["cap"] = int(args.cap)
    if args.run is not None:
        rec["budget"] = int(rec.get("spawned", 0)) + int(args.run)
    want = max(0, int(rec.get("budget", 0)) - int(rec.get("spawned", 0)))
    before = int(rec.get("spawned", 0))
    print(f"dispatch-retry {args.dispatch_id}: {len(rec['queue'])} queued, "
          f"cap {rec.get('cap')}, {_dispatch_live_lane_count()} dispatched lane(s) live …")
    for line in _dispatch_advance(rec, _coord_identity(), want=want, dry_run=args.dry_run):
        print(line)
    gained = int(rec.get("spawned", 0)) - before
    print(f"dispatch-retry {args.dispatch_id}: {gained} lane(s) spawned this pass, "
          f"{len(rec['queue'])} still queued, state {_dispatch_state(rec)}.")


def cmd_dispatch_cancel(args: argparse.Namespace) -> None:
    """Retire a dispatch nobody intends to finish.

    Before this existed the only way to clear a dead dispatch was to hand-edit JSON under
    `.git/` — state with a writer, and exactly the hand-repair class ADR-0099 exists to
    stop. The record is KEPT and marked, not deleted: it is the provenance for every lane
    the dispatch did spawn, and deleting it would orphan them."""
    rec = _dispatch_read(args.dispatch_id)
    if rec is None:
        print(f"dispatch-cancel: no dispatch {args.dispatch_id} in the store.")
        raise SystemExit(2)
    if rec.get("cancelled"):
        print(f"dispatch-cancel: {args.dispatch_id} was already cancelled "
              f"at {str(rec.get('cancelled', {}).get('at'))[:19]}.")
        return
    dropped = list(rec.get("queue") or [])
    rec["cancelled"] = {"at": _coord_iso(time.time()), "by": _coord_identity(),
                        "dropped": dropped, "reason": args.reason or ""}
    rec["queue"] = []
    _dispatch_write(rec)
    print(f"dispatch-cancel {args.dispatch_id}: cancelled. "
          f"{len(dropped)} queued item(s) released — they are unclaimed work items again, "
          f"not lost.")
    if dropped:
        # Naming them is the point: a silent release is how work disappears.
        print("  released: " + ", ".join(dropped))


def cmd_dispatch_status(args: argparse.Namespace) -> None:
    """Show open dispatches and their queues. Read-only."""
    d = _dispatch_dir()
    if d is None or not d.is_dir():
        print("dispatch: no dispatch store here.")
        return
    recs = []
    for p in sorted(d.glob("D-*.json")):
        r = _coord_read(p)
        if r:
            recs.append(r)
    if not recs:
        print("dispatch: none recorded.")
        return
    for r in recs:
        done = len(r.get("log") or [])
        state = _dispatch_state(r)
        if r.get("cancelled"):
            state = "cancelled"
        age = _dispatch_age_str(r)
        print(f"{r['dispatch_id']}  [{state}]  snapshot {r.get('snapshot_id') or 'n/a'}  "
              f"cap {r.get('cap')}  budget {r.get('budget')}  "
              f"spawned {r.get('spawned', 0)}  "
              f"briefed {sum(1 for s in _dispatch_brief_view(r).values() if s in ('briefed', 're-briefed'))}  "
              f"queued {len(r.get('queue') or [])}"
              + (f"  age {age}" if age else ""))
        _dispatch_print_unbriefed(r, indent="    ")
        # The stall reason is printed WITHOUT -v. A stalled dispatch that only explains
        # itself under a flag is a stalled dispatch nobody reads the explanation of.
        if state == "stalled":
            stall = (r.get("stall") or {}).get("detail")
            print(f"    STALLED — {stall or 'no reason recorded (record predates WI-0171)'}")
            # Same WI-0158 correction as the stall banner in `cmd_dispatch`: retry and
            # cancel live on session.py, never on poga, and this surface is the one a
            # reader comes BACK to hours later — the copy most likely to be pasted cold.
            print(f"    retry: `python3 session.py dispatch-retry {r['dispatch_id']}`  ·  "
                  f"give up: `python3 session.py dispatch-cancel {r['dispatch_id']}`")
        if args.verbose:
            for entry in (r.get("log") or []):
                print(f"    spawned {entry.get('item')} at {str(entry.get('at'))[:19]} "
                      f"by {entry.get('by')}")
            for w in (r.get("queue") or []):
                print(f"    queued  {w}")


def _notify_payload_path() -> Path:
    d = _shared_work_root() / ".session-state"
    d.mkdir(exist_ok=True)
    return d / "notify-payloads.jsonl"


def _notify_record_payload(hook: dict, matched: str) -> None:
    """Keep the raw `Notification` payload so its shape is OBSERVED, not guessed (WI-0162).

    The key the message is read from was a guess that survives being wrong — the record is
    still written, just without text — and every test fed it synthetically, so the only way
    to confirm it was for someone to be watching at the exact moment a real session blocked.
    That is a person as an execution surface (ADR-0099) for a fact the machine can capture
    on its own.

    UNTRACKED and capped. Never raises: a hook that can fail the session it reports on is
    worse than no hook."""
    try:
        rec = {"at": _coord_iso(time.time()),
               "matched_key": matched,
               "keys": sorted(k for k in hook if isinstance(k, str)),
               "payload": hook}
        p = _notify_payload_path()
        lines = []
        with contextlib.suppress(Exception):
            lines = p.read_text(encoding="utf-8").splitlines()
        lines.append(json.dumps(rec, ensure_ascii=False))
        atomic_write(p, "\n".join(lines[-NOTIFY_PAYLOAD_KEEP:]) + "\n")
    except Exception:
        pass


def _notify_payloads() -> list[dict]:
    """Every captured payload, oldest first. [] if none — which is the honest answer
    before the hook has ever fired for real."""
    out = []
    try:
        for line in _notify_payload_path().read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if not line:
                continue
            with contextlib.suppress(Exception):
                out.append(json.loads(line))
    except Exception:
        pass
    return out


def _notify_key_verdict() -> str:
    """One line on whether the text key is CONFIRMED, still a guess, or WRONG.

    Three outcomes, never two. "No payload captured yet" is not "the guess is fine"."""
    payloads = _notify_payloads()
    if not payloads:
        return ("notify: the Notification payload shape is still a GUESS — the hook has "
                "not been captured firing for real yet. Nothing to confirm from.")
    matched = [p for p in payloads if p.get("matched_key")]
    if matched:
        keys = sorted({p["matched_key"] for p in matched})
        return (f"notify: CONFIRMED — the message text arrives under "
                f"{', '.join(repr(k) for k in keys)} "
                f"({len(matched)} of {len(payloads)} captured payload(s)).")
    seen = sorted({k for p in payloads for k in (p.get("keys") or [])})
    return (f"notify: the text key is WRONG — {len(payloads)} payload(s) captured and none "
            f"carried any of {NOTIFY_TEXT_KEYS}. Keys actually present: "
            f"{', '.join(seen) or '(none)'}. The record is still written; it has no text.")


def cmd_notify(_args: argparse.Namespace) -> None:
    """`Notification` hook: the lane needs the user, so say so where it can be counted.

    Structural rather than disciplinary on purpose — a rule that a blocked lane *should*
    announce itself fails exactly when the lane is stuck, which is the only moment it
    matters. Fails open in every direction: this must never be able to break the session
    it is reporting on."""
    try:
        hook = _read_hook_stdin()
    except Exception:
        sys.exit(0)
    msg = ""
    matched = ""
    for k in NOTIFY_TEXT_KEYS:
        v = hook.get(k)
        if isinstance(v, str) and v.strip():
            msg = v.strip()
            matched = k
            break
    _notify_record_payload(hook, matched)
    _attention_write(msg)
    sys.exit(0)


def _attach_state_path(did: str) -> Path:
    """Which lanes this machine has already opened a window for. Local to the OPERATOR's
    machine, because 'have I opened this window' is a fact about this desk, not about the
    dispatch — the same dispatch attached from two machines should open windows on both."""
    d = _shared_work_root() / ".session-state"
    d.mkdir(exist_ok=True)
    return d / f"attach-{re.sub(r'[^A-Za-z0-9_-]', '-', did)}.json"


def _attach_seen(did: str) -> set[str]:
    try:
        return set(json.loads(_attach_state_path(did).read_text(encoding="utf-8")) or [])
    except Exception:
        return set()


def _attach_mark(did: str, names: set[str]) -> None:
    with contextlib.suppress(Exception):
        atomic_write(_attach_state_path(did),
                     json.dumps(sorted(names), ensure_ascii=False, indent=2) + "\n")


def _attach_resolve_terminal(want: str = "") -> str:
    """Which terminal opens the windows — DETECTED by default, refused by name when it
    cannot work.

    The old spawn code hardcoded Terminal and iTerm2. Ghostty is a third
    answer, and the next terminal is a fourth — so an unrecognised value is treated as a
    TEMPLATE rather than an error, and adding a terminal is a config line. What is still
    refused, loudly, is having no way at all: a silent no-op here is a fan-out the operator
    believes is watched and is not."""
    want = (want or (CFG or {}).get("attach_terminal") or "auto").strip()
    if want != "auto":
        return want
    prog = (os.environ.get("TERM_PROGRAM") or "").strip().lower()
    if prog == "ghostty" or shutil.which("ghostty"):
        return "ghostty"
    if prog == "iterm.app":
        return "iTerm2"
    if _dispatch_apple_events_available():
        return "Terminal"
    if os.environ.get("TMUX") and _tmux_bin():
        return "tmux-window"
    mgr = _dispatch_session_manager() or "unknown"
    raise ValueError(
        f"no way to open a window from here. This session's launchd manager is '{mgr}' "
        f"(not 'Aqua'), no Ghostty binary is on PATH, and we are not inside a tmux to add "
        f"a window to. `poga attach` has to run on the machine you are SITTING AT — that "
        f"is the whole point of the split. If you are already remote, run it in your local "
        f"terminal instead, or set `attach_terminal` to a launch template containing "
        f"'{{cmd}}'.")


def _attach_bin(name: str) -> str:
    """Absolute path to a binary the OPENED TAB will have to run, or "" if this machine
    does not have it (WI-0187).

    THE TAB'S SHELL HAS NO PROFILE. Ghostty launches its command as
    `/usr/bin/login -flp <user> /bin/bash --noprofile --norc -c exec -l <cmd>` — no
    profile, no rc, so a package manager's bin directory is never on PATH and every binary
    installed there is unreachable by bare name. At the first live drill three tabs opened and all three
    printed `bash: line 0: exec: mosh: not found`; `ssh` worked only by the luck of living
    in `/usr/bin`. Whether mosh was installed was beside the point — that shell could not
    have found it either way.

    Resolution happens HERE, on the operator's machine, because that is where the tab
    opens. The work machine's PATH is irrelevant to it.

    Read the wrapper, do not reason about it: this exact `login -flp` line was read earlier
    in that same session and reported as meaning PATH would be fully set up — backwards,
    and stated confidently from reading rather than running."""
    return shutil.which(name) or ""


def _attach_transport_check(host: str, transport: str) -> str:
    """"" if the tab can run this attach, else why not — checked ONCE, BEFORE any tab
    opens (WI-0187).

    attach knew the transport at startup and opened three tabs that were each guaranteed
    to fail. One named refusal beats N identical failures the operator reads one tab at a
    time. `_attach_resolve_terminal` already refuses by name when it has no way to open a
    window; the transport deserves the same check and did not have it."""
    if not _attach_bin("tmux"):
        return ("tmux is not on this machine, and the attach command runs it — "
                "`brew install tmux`")
    if not host:
        return ""
    if not _attach_bin(transport):
        other = "ssh" if transport == "mosh" else "mosh"
        alt = (f" or use `--transport {other}`" if _attach_bin(other) else "")
        return f"{transport} is not on this machine — install it{alt}"
    return ""


def _attach_terminal_check(terminal: str) -> str:
    """"" if this machine can open a window with `terminal`, else why not — checked ONCE,
    BEFORE any window opens (WI-0167).

    `_attach_transport_check`'s sibling, and for its argument: one named refusal beats N
    identical failures the operator reads one window at a time. Ghostty had neither half of
    that — nothing checked it up front, and the per-window failure it did produce was exit
    127 rather than a name.

    The AppleScript openers pass trivially: they drive an app through its dictionary and
    interpolate no path, so there is no binary for this machine to be missing. Only the
    launch templates can fail here."""
    if terminal == "ghostty" or terminal in ATTACH_APPLESCRIPT:
        return ""
    _, why = _attach_template_bins(ATTACH_TEMPLATES.get(terminal, terminal))
    return why


def _attach_command(name: str, host: str, transport: str) -> str:
    """The command a freshly-opened window runs: attach to one lane's tmux session.

    Local is the degenerate case (ADR-0100 D5) — no transport wrapper at all — and it is
    also the only configuration an Architect can self-test, since every Architect session
    runs `Background`.

    EVERY BINARY IS ABSOLUTE (WI-0187). The tab's shell reads no profile, so a bare name
    resolves against a stripped PATH — see `_attach_bin`. Falls back to the bare name when
    resolution fails so the command is still readable in `--dry-run`; the caller has
    already refused by name via `_attach_transport_check` before any real tab opens."""
    tmux = _attach_bin("tmux") or "tmux"
    inner = f"{shlex.quote(tmux)} attach -t {shlex.quote(name)}"
    if not host:
        return inner
    # The REMOTE side runs `inner`, so its tmux is resolved by the remote login shell —
    # an ssh/mosh login DOES read a profile, unlike the local tab. Only the near side of
    # the hop needs an absolute path here.
    remote_inner = f"tmux attach -t {shlex.quote(name)}"
    if transport == "ssh":
        # `-t` forces a pty: without it tmux refuses ("open terminal failed").
        ssh = _attach_bin("ssh") or "ssh"
        return f"{shlex.quote(ssh)} -t {shlex.quote(host)} {shlex.quote(remote_inner)}"
    mosh = _attach_bin("mosh") or "mosh"
    return f"{shlex.quote(mosh)} {shlex.quote(host)} -- {remote_inner}"


def _is_drill_item(name: str) -> bool:
    """Is this claim id a drill's synthetic item rather than a real one? (WI-0174)

    The drill claims through the PRODUCTION claim path on purpose — that is the whole
    point of the rehearsal, and the reason WI-0189 caught what a fake path would not.
    The cost is that every reader that joins on claims inherited the `DRILL-` namespace
    without being asked. The line is the surface's lifetime, not the reader's identity:
    an EPHEMERAL surface showing a drill claim is correct and wanted (the start banner
    and `poga work claims` are how an operator sees a rehearsal is live), while a
    DURABLE one — a tracked journal's frontmatter, a published feed — must not carry an
    id that names nothing and will outlive the drill that made it. Every durable reader
    goes through this predicate so the next one added has an obvious thing to call.
    """
    return name.startswith(DRILL_ITEM_PREFIX)


def _drill_items_dir(create: bool = False) -> Path:
    """Where drill work items live: UNTRACKED, beside the drill's other residue.

    NOT `work-items/`. the operator's rule after the first drill claimed two real backlog items —
    test runs use no real work items and record no permanent data — and a file in the tracked store is permanent data the moment anything commits. Under
    `.session-state/` (gitignored) nothing can reach git even by accident, and `--clean`
    removes them.

    They are otherwise ORDINARY ITEMS: same `_wi_parse_text`, same fields, same ids in the
    same shape. The point of a drill is to be as close to the real thing as it can be
    without being it, so the parser, the claim, the coordination record and the release are
    all the production ones — only the storage location and the id prefix differ."""
    d = _shared_work_root() / ".session-state" / "drill-items"
    if create:
        d.mkdir(parents=True, exist_ok=True)
    return d


def _drill_items() -> list[dict]:
    """Every drill item currently on disk, parsed exactly as a real one is."""
    d = _drill_items_dir()
    out: list[dict] = []
    try:
        paths = sorted(d.glob(f"{DRILL_ITEM_PREFIX}*.md"))
    except Exception:
        return out
    for f in paths:
        try:
            out.append(_wi_parse_text(f.stem, f.read_text(encoding="utf-8")))
        except Exception:
            continue
    return out


def _drill_item_write(wid: str, title: str) -> Path:
    """Create one drill item. Same on-disk shape as a real work item, so a reader that
    can parse the store can parse this without a special case."""
    d = _drill_items_dir(create=True)
    f = d / f"{wid}.md"
    f.write_text(
        f"# {wid}: {title}\n\n"
        f"- status: open\n"
        f"- section: next\n"
        f"- blocked-by: \n"
        f"- group: drill\n"
        f"- source: \n"
        f"- impact: fix\n"
        f"- version: \n\n"
        f"SYNTHETIC. Created by `poga drill` to exercise claim/release against the real\n"
        f"coordination store without touching the backlog. Lives outside `work-items/` and\n"
        f"outside git; removed by `poga drill --clean`. If you are reading this in a real\n"
        f"checkout, a drill did not clean up after itself.\n",
        encoding="utf-8")
    return f


def _drill_items_clear() -> tuple[int, int]:
    """Delete every drill item and release any claim held on one. (items, claims)."""
    released = 0
    for wid in list(_coord_list("claims")):
        if wid.startswith(DRILL_ITEM_PREFIX):
            if _coord_release("claims", wid, _coord_identity(), force=True):
                released += 1
    d = _drill_items_dir()
    removed = 0
    try:
        for f in sorted(d.glob(f"{DRILL_ITEM_PREFIX}*.md")):
            f.unlink()
            removed += 1
        with contextlib.suppress(Exception):
            d.rmdir()
    except Exception:
        pass
    return removed, released


def _drill_script_path() -> Path:
    d = _shared_work_root() / ".session-state"
    d.mkdir(exist_ok=True)
    p = d / "drill-lane.sh"
    if not p.exists() or p.read_text(encoding="utf-8") != DRILL_SCRIPT:
        p.write_text(DRILL_SCRIPT, encoding="utf-8")
        p.chmod(0o755)
    return p


def _drill_records() -> list[dict]:
    d = _dispatch_dir()
    if d is None or not d.is_dir():
        return []
    out = []
    for p in sorted(d.glob("D-*.json")):
        r = _coord_read(p)
        if r and r.get("drill"):
            out.append(r)
    return out


def cmd_drill(args: argparse.Namespace) -> None:
    """Exercise dispatch -> attach with lanes that are not real (the operator's ruling, session
    ~172: test runs use no real work items, record no permanent data, consume no real
    session numbers and touch no journals or history).

    WHY THIS EXISTS. WI-0160's acceptance criteria said *"dispatch two items on devbox"*,
    so the drill as specified could only be run by putting live autonomous agents on real
    backlog items. Doing exactly that at the first drill claimed two items, spawned two
    Claude sessions, drew two session numbers, wrote two journals and left two branches —
    all to answer a question about whether a window opens. The test was more dangerous than
    the thing it tested.

    A drill lane therefore does NOT run the agent. It runs a trivial interactive script, and
    that is not a shortcut: everything the attach drill actually exercises — the tmux session
    name, the dispatch record, discovery, the terminal, the transport, attach and detach —
    is upstream of what runs *inside* the lane. Substituting the payload tests the whole path
    and none of the risk.

    What it deliberately does NOT cover: the agent-side behaviours. The live `Notification`
    payload behind the attention record needs a real session and stays a separate, attended
    exercise. A drill that claimed to cover it would be worse than one that says it does not.

    The only residue is a dispatch record under `.git/poga-coord` and the script under
    `.session-state` — both untracked, both TTL'd, both removed by `--clean`. Nothing enters
    git, the work store, or the journals."""
    if args.clean:
        recs = _drill_records()
        if not recs and not _drill_items():
            print("drill: nothing to clean — no drill dispatches recorded.")
            return
        tmux = _tmux_bin()
        d = _dispatch_dir()
        for rec in recs:
            did = rec["dispatch_id"]
            for entry in (rec.get("log") or []):
                name = _tmux_session_name(did, str(entry.get("item")))
                if tmux:
                    subprocess.run([tmux, "kill-session", "-t", name],
                                   capture_output=True, text=True, check=False)
                print(f"  killed {name}")
            with contextlib.suppress(Exception):
                (d / f"{did}.json").unlink()
            print(f"drill {did}: cleaned.")
        with contextlib.suppress(Exception):
            _drill_script_path().unlink()
        items, released = _drill_items_clear()
        if items or released:
            print(f"  {items} drill item(s) deleted, {released} claim(s) released")
        print("drill: clean. Nothing was ever written to git, the backlog, or a journal.")
        return

    lanes = max(1, int(args.lanes or 2))
    script = _drill_script_path()
    did = f"D-{secrets.token_hex(3)}"
    now = _coord_iso(time.time())
    rec = {"dispatch_id": did, "snapshot_id": None, "created_at": now,
           "created_by": os.environ.get("CLAUDE_CODE_SESSION_ID", "drill"),
           "surface": "tmux", "cap": lanes, "budget": lanes, "spawned": 0,
           "queue": [], "held": {}, "subagents": [], "log": [],
           "drill": True}
    print(f"drill {did}: starting {lanes} FAKE lane(s). No backlog item, no journal, "
          f"no branch.")
    # The claim is REAL, so the item it claims has to exist for the production code path
    # to accept it — a claim forced past `--force` would rehearse a different function
    # from the one a dispatched lane runs.
    poga_bin = _shared_work_root() / "poga"
    for i in range(1, lanes + 1):
        item = f"{DRILL_ITEM_PREFIX}{i}"
        _drill_item_write(item, f"Drill lane {i} — synthetic, claim/release rehearsal")
        name = _tmux_session_name(did, item)
        ok, detail = _dispatch_open_tmux(
            f"{shlex.quote(str(script))} {shlex.quote(item)} {shlex.quote(str(poga_bin))}",
            name)
        if not ok:
            print(f"  {item}: FAILED to start — {detail}")
            continue
        rec["log"].append({"item": item, "at": _coord_iso(time.time()), "by": "drill"})
        rec["spawned"] += 1
        print(f"  {item}: lane up — {name}")
    _dispatch_write(rec)
    print(f"\ndrill {did}: {rec['spawned']} lane(s) running.")
    print("On the machine you are SITTING AT:")
    print(f"  poga attach --host {os.uname().nodename.split('.')[0]} --transport ssh")
    print("Then: type in a tab, close a tab (the lane should SURVIVE), reattach.")
    print("Each lane has CLAIMED its synthetic item for real — `poga work claims` shows")
    print("them, and typing `quit` in a tab releases one. That round trip is the half the")
    print("drill used to skip.")
    print("When done, here:  poga drill --clean")


def _attach_window_path() -> Path:
    """The Ghostty window this desk is putting lane tabs into. Local to the OPERATOR's
    machine for the same reason `_attach_state_path` is: which window is on this screen is
    a fact about this desk, not about the dispatch."""
    d = _shared_work_root() / ".session-state"
    d.mkdir(exist_ok=True)
    return d / "attach-ghostty-window.json"


def _attach_window_id() -> str:
    try:
        return str(json.loads(_attach_window_path().read_text(encoding="utf-8")) or "")
    except Exception:
        return ""


def _attach_set_window_id(wid: str) -> None:
    with contextlib.suppress(Exception):
        atomic_write(_attach_window_path(), json.dumps(wid, ensure_ascii=False) + "\n")


def _attach_ghostty_script(cmd: str, wid: str) -> str:
    """One tab in ONE window, via Ghostty's AppleScript dictionary (verified against
    Ghostty's `Ghostty.sdef`, session ~172).

    The design calls for tabs in one window, and Ghostty's CLI cannot do it: `+new-window` is a
    GTK action that refuses on macOS, and native NSWindow tabbing does not apply either —
    setting "Prefer tabs when opening documents" to Always still produced a window. The
    dictionary is the only route, and it is a real API rather than synthesized keystrokes:
    `new tab in <window> with configuration <surface configuration>`, where the record
    carries `command`.

    ONE round trip decides and reports, because the window may have been closed between
    waves: it looks for the window by its stable `id`, opens a new one if that is gone, and
    returns whichever id it ended up using. Looking first and acting second would race the
    operator's own hands on a window that is right there on screen.

    `wait after command` is true so a lane whose transport dies leaves its tab up carrying
    the error. Without it the tab closes on exit and the failure is a window that flickered
    — the silent-strand shape this whole command exists to prevent."""
    cfg = ("{command:" + _applescript_str(cmd) + ", wait after command:true}")
    # Returns "<window id>\t<tab id>". The TAB id is what WI-0183 needs and what the first
    # cut threw away: `new tab` yields a tab and `new window` yields a window whose
    # `selected tab` is the one just made (verified against Ghostty's sdef — `tab`
    # carries a stable `id` and responds to `select tab`). Without it a lane can be known to
    # be waiting and still have no way to point at itself.
    return (
        'tell application "Ghostty"\n'
        f'  set cfg to {cfg}\n'
        '  set target to missing value\n'
        '  repeat with w in windows\n'
        f'    if (id of w) is {_applescript_str(wid)} then set target to w\n'
        '  end repeat\n'
        '  if target is missing value then\n'
        '    set made to new window with configuration cfg\n'
        '    return (id of made) & tab & (id of (selected tab of made))\n'
        '  else\n'
        '    set t to new tab in target with configuration cfg\n'
        f'    return {_applescript_str(wid)} & tab & (id of t)\n'
        '  end if\n'
        'end tell')


def _attach_raise_script(tab_id: str, mode: str) -> str:
    """The AppleScript for one raise. "" for `off` or an unknown mode."""
    t = f'(first tab of windows whose id is {_applescript_str(tab_id)})'
    # `tabs of windows` is the flat search: a tab is addressed by its own stable id, and
    # which window currently holds it is not something this code should have to track.
    t = (f'set tgt to missing value\n'
         f'  repeat with w in windows\n'
         f'    repeat with tb in tabs of w\n'
         f'      if (id of tb) is {_applescript_str(tab_id)} then\n'
         f'        set tgt to tb\n'
         f'        set tgtw to w\n'
         f'      end if\n'
         f'    end repeat\n'
         f'  end repeat\n'
         f'  if tgt is missing value then return "gone"\n')
    if mode == "select":
        act = '  select tab tgt\n'
    elif mode == "activate":
        act = '  select tab tgt\n  activate window tgtw\n'
    elif mode == "focus":
        act = '  select tab tgt\n  focus (focused terminal of tgt)\n'
    else:
        return ""
    return ('tell application "Ghostty"\n  ' + t + act + '  return "ok"\nend tell')


def _attach_raise(tab_id: str, mode: str) -> tuple[bool, str]:
    """Raise one lane's tab. (ok, detail). BEST-EFFORT BY CONSTRUCTION — the attention
    record is the truth and the raise is decoration on top of it (ADR-0101's D-record
    split). A raise that fails must never make a waiting lane less visible than it was."""
    script = _attach_raise_script(tab_id, mode)
    if not script:
        return False, "raising is off"
    try:
        r = subprocess.run(["osascript", "-e", script], cwd=ROOT, text=True,
                           capture_output=True, check=False,
                           timeout=DISPATCH_SPAWN_TIMEOUT_SECONDS)
    except Exception as e:
        return False, f"could not run osascript ({e})"
    if r.returncode != 0:
        return False, (r.stderr or r.stdout or "osascript failed").strip()
    if (r.stdout or "").strip() == "gone":
        return False, "that tab has been closed"
    return True, ""


def _attach_fetch_attention(host: str) -> tuple[dict | None, str]:
    """Every attention record on the WORK machine. (records, why-not).

    The records live in the work machine's coordination store — a lane writes one when it
    blocks — while the tabs live here. Same split as the dispatch record, so same read:
    locally it is a plain list, remotely one ssh that flattens each JSON file onto its own
    line. Flattening is safe because `json.dumps` escapes newlines inside strings, so a
    real newline in the file is always structural.

    Three outcomes, never two. `None` is could-not-look, and a caller must not render it as
    "nobody is waiting"."""
    if not host:
        try:
            return _coord_list(ATTENTION_KIND), ""
        except Exception as e:
            return None, f"unreadable ({type(e).__name__})"
    d = _coord_dir(ATTENTION_KIND)
    remote = f".git/poga-coord/{ATTENTION_KIND}"
    if d is not None:
        with contextlib.suppress(Exception):
            remote = str(Path(*d.parts[-3:]))
    cmd = (f'for f in {shlex.quote(remote)}/*.json; do '
           f'[ -f "$f" ] && tr -d "\n" < "$f" && echo; done')
    try:
        r = subprocess.run(["ssh", host, cmd], text=True, capture_output=True,
                           check=False, timeout=20)
    except Exception as e:
        return None, f"could not reach {host} ({e})"
    if r.returncode != 0:
        return None, (r.stderr or "").strip() or f"ssh {host} exited {r.returncode}"
    out: dict = {}
    for line in (r.stdout or "").splitlines():
        line = line.strip()
        if not line:
            continue
        try:
            rec = json.loads(line)
        except Exception:
            continue                      # one bad record must not blind the rest
        if _coord_expired(rec):
            continue
        out[str(rec.get("name") or rec.get("session_id") or len(out))] = rec
    return out, ""


def _attach_open_ghostty(cmd: str, window: dict | None,
                         name: str = "") -> tuple[bool, str]:
    """Open one Ghostty TAB for a lane. (ok, detail).

    `window` is this run's in-memory handle; the on-disk copy lets a re-run rejoin the same
    window rather than starting a second one beside it. `name` is the lane's tmux session
    name, which is how the tab id gets filed (WI-0183) — a lane that is waiting can only
    raise itself if something remembered which tab it went into."""
    holder = window if window is not None else {}
    wid = holder.get("id") or _attach_window_id()
    script = _attach_ghostty_script(cmd, wid)
    try:
        r = subprocess.run(["osascript", "-e", script], cwd=ROOT, text=True,
                           capture_output=True, check=False,
                           timeout=DISPATCH_SPAWN_TIMEOUT_SECONDS)
    except subprocess.TimeoutExpired:
        return False, (f"osascript blocked for {DISPATCH_SPAWN_TIMEOUT_SECONDS}s opening a "
                       f"Ghostty tab. {_APPLE_EVENT_PERMISSION_HINT}")
    except Exception as e:
        return False, f"could not run osascript ({e})"
    if r.returncode != 0:
        detail = (r.stderr or r.stdout or "osascript failed").strip()
        if "-1712" in detail or "timed out" in detail.lower():
            detail += f" — {_APPLE_EVENT_PERMISSION_HINT}"
        return False, detail
    got = (r.stdout or "").strip()
    # "<window id>\t<tab id>". Older Ghostty, or a script that somehow returned one field,
    # degrades to window-only — the tab id is what WI-0183's raise needs, and a lane with
    # no tab id simply cannot be raised. That is a missing decoration, not a broken attach.
    wid_got, _, tab_got = got.partition("\t")
    if wid_got:
        holder["id"] = wid_got
        _attach_set_window_id(wid_got)
    if tab_got and name:
        holder.setdefault("tabs", {})[name] = tab_got
    return True, ""


def _attach_template_bins(template: str) -> tuple[dict[str, str], str]:
    """The binaries a launch template interpolates, resolved. ({placeholder: quoted
    absolute path}, why-not).

    RESOLVED, NEVER GUESSED (WI-0167). This was `shutil.which("ghostty") or "ghostty"`, and
    the `or` is the whole defect: on a machine where Ghostty is installed at
    `GHOSTTY_APP_BIN` and nothing puts it on PATH, so `which` answered None and the
    template shelled a BARE NAME under `shell=True`. The window died `command not found`,
    exit 127, reaching the operator as a generic template failure — from the one subsystem
    whose entire design is to refuse by name (`_attach_resolve_terminal`,
    `_attach_transport_check`). A guess that fails toward a confusing error is the shape
    `declare-what-a-check-assumes` exists to prevent, and a fallback to a name that is not
    there is not a fallback at all: there is no configuration in which running it helps.

    Per PLACEHOLDER, never per terminal. A template needs only the binaries it actually
    interpolates, so a machine with no Ghostty must still open a `tmux-window` — scoping
    the refusal to the terminal instead would trade one wrong answer for another."""
    subs: dict[str, str] = {}
    if "{ghostty}" in template:
        found = _ghostty_bin()
        if not found:
            return {}, (
                "this launch template runs Ghostty's own binary and this machine has "
                "none: `ghostty` is not on PATH, and nothing runnable sits at "
                f"{GHOSTTY_APP_BIN} either. Installing Ghostty.app does NOT put `ghostty` "
                "on PATH — symlink that path onto yours, or set `attach_terminal` to "
                "'ghostty', which drives the app through its AppleScript dictionary and "
                "needs no binary at all (and gets you tabs in one window rather than a "
                "window per lane). Nothing was run: a bare `ghostty` under a shell could "
                "only have exited 127")
        subs["ghostty"] = shlex.quote(found)
    if "{tmux}" in template:
        found = _tmux_bin()
        if not found:
            return {}, ("this launch template runs tmux and this machine has none — "
                        "`brew install tmux`. Nothing was run")
        subs["tmux"] = shlex.quote(found)
    return subs, ""


def _attach_open(cmd: str, terminal: str, name: str,
                 window: dict | None = None) -> tuple[bool, str]:
    """Open ONE surface running `cmd`. (ok, detail).

    NOT gate-guarded, and the first cut of ADR-0119 D4 guarded it. This function resolves
    `_tmux_bin()` only to INTERPOLATE a path into a launch template — it never spawns tmux —
    so it is not one of the reaches D4 is about, and the guard here sat ABOVE the point
    where `test_attach`'s hermetic tests mock `subprocess.run`. Those tests never touched
    the machine; they assert the SHAPE of an argv that is never run. Guarding a dispatcher
    whose spawn is already mocked removes coverage and buys nothing, which is why the
    detector's second shape now requires the resolved binary to be argv[0]."""
    if terminal == "ghostty":
        return _attach_open_ghostty(cmd, window, name)
    if terminal in ATTACH_APPLESCRIPT:
        return _dispatch_open_tab(cmd, terminal, name)
    template = ATTACH_TEMPLATES.get(terminal, terminal)
    if "{cmd}" not in template and "{argv}" not in template:
        return False, (f"`attach_terminal` is '{terminal}', which is neither a known "
                       f"terminal ({', '.join(list(ATTACH_TEMPLATES) + list(ATTACH_APPLESCRIPT))}) "
                       f"nor a launch template — a template must contain '{{cmd}}' (one "
                       f"quoted argument) or '{{argv}}' (separate arguments).")
    subs, why = _attach_template_bins(template)
    if why:
        return False, why
    line = template.format(cmd=shlex.quote(cmd), argv=cmd, name=shlex.quote(name), **subs)
    try:
        r = subprocess.run(line, shell=True, cwd=ROOT, text=True, capture_output=True,
                           check=False, timeout=DISPATCH_SPAWN_TIMEOUT_SECONDS)
    except subprocess.TimeoutExpired:
        return False, f"'{terminal}' blocked for {DISPATCH_SPAWN_TIMEOUT_SECONDS}s"
    except Exception as e:
        return False, f"could not run the launch template ({e})"
    if r.returncode != 0:
        return False, (r.stderr or r.stdout or f"'{terminal}' exited {r.returncode}").strip()
    return True, ""


def _attach_fetch_record(did: str, host: str) -> tuple[dict | None, str]:
    """The dispatch record, read locally or over the wire. (record, why-not).

    Three outcomes, never two (`declare-what-a-check-assumes`): a record, a definite
    absence, or an unreachable store. 'I could not look' must never render as 'there is
    nothing there' — that collapse is how a fan-out reads as finished."""
    if not host:
        rec = _dispatch_read(did)
        return (rec, "") if rec else (None, f"no dispatch {did} in this machine's store")
    d = _dispatch_dir()
    remote_path = f".git/poga-coord/dispatch/{did}.json"
    if d is not None:
        with contextlib.suppress(Exception):
            remote_path = str(Path(*d.parts[-4:]) / f"{did}.json")
    try:
        r = subprocess.run(["ssh", host, f"cat {shlex.quote(remote_path)}"],
                           text=True, capture_output=True, check=False, timeout=20)
    except Exception as e:
        return None, f"could not reach {host} ({e})"
    if r.returncode != 0:
        return None, (r.stderr or "").strip() or f"ssh {host} exited {r.returncode}"
    try:
        return json.loads(r.stdout), ""
    except Exception as e:
        return None, f"unreadable record from {host} ({type(e).__name__})"


def _attach_live_dispatch_ids(host: str) -> tuple[list[str] | None, str]:
    """Which dispatches have lanes running RIGHT NOW, asked of tmux. (ids, why-not).

    The operator is sitting at a different machine from the one that dispatched, so
    requiring them to carry a `D-xxxxxx` across the gap makes them the transport for a
    token neither machine ever showed them — the [ADR-0099](adr/0099-the-user-is-not-an-execution-surface.md)
    class, arriving through the fix for it.

    `_tmux_session_name` already stamps the dispatch id INTO the session name for exactly
    this reason ("what is running and why, without consulting the record"), so the live
    set is a property of the work machine we can read directly. That also makes the answer
    the right one rather than merely the newest: a dispatch whose lanes have all exited has
    nothing to attach to, however recently it ran.

    Three outcomes, never two (`declare-what-a-check-assumes`): the ids, a definite empty
    list, or `None` for could-not-look. No tmux server at all is a DEFINITE EMPTY — tmux
    exits 1 with "no server running" — and must not read as unreachable, or the common
    idle case would render as a fault."""
    names, why = _attach_live_sessions(host)
    if names is None:
        return None, why
    ids: list[str] = []
    for line in names:
        m = re.match(r"^poga-(D-[0-9a-fA-F]+)-", line)
        if m and m.group(1) not in ids:
            ids.append(m.group(1))
    return ids, ""


def _attach_live_sessions(host: str) -> tuple[list[str] | None, str]:
    """Every tmux session name running on the work machine RIGHT NOW. (names, why-not).

    Split out of `_attach_live_dispatch_ids` for WI-0186. Discovery was already asking this
    question and already holding the answer — then throwing the names away and keeping only
    the dispatch ids, while the open loop iterated the RECORD's log instead. Two sources of
    truth about the same question, one observed and one asserted, and it used the asserted
    one: at the first drill three tabs opened for two live lanes, the third attaching a lane
    that had died at spawn and printing `no such session`.

    NOT gate-guarded. `ReadsWhatIsRunningFromTmuxTest` is this function's own hermetic
    unit test — it mocks `subprocess.run` and pins all three outcomes — and no unmocked
    reach to this function was ever measured. A guard here would sit above that mock and
    delete ten tests to prevent nothing (ADR-0119 D4).

    Same three-outcome contract as its caller: the names, a definite empty list, or `None`
    for could-not-look. No tmux server at all is a DEFINITE EMPTY."""
    argv = ["tmux", "ls", "-F", "#{session_name}"]
    if host:
        argv = ["ssh", host, "tmux ls -F '#{session_name}'"]
    elif not _tmux_bin():
        return None, "no tmux on this machine"
    try:
        r = subprocess.run(argv, text=True, capture_output=True, check=False, timeout=20)
    except Exception as e:
        return None, f"could not ask {host or 'this machine'} what is running ({e})"
    if r.returncode != 0:
        err = ((r.stderr or "") + (r.stdout or "")).lower()
        if "no server running" in err or "no sessions" in err:
            return [], ""
        return None, (r.stderr or "").strip() or f"tmux exited {r.returncode}"
    return [ln.strip() for ln in (r.stdout or "").splitlines() if ln.strip()], ""


def _attach_checkout_staleness(fetch: bool = True) -> str:
    """One line about how current THIS checkout is, or "" when it is up to date (WI-0188).

    ADR-0100 makes the operator's machine a REQUIRED PARTICIPANT, and nothing kept its copy
    current or warned when it was not. In one hour of the first drill the same fact —
    "your checkout predates the fix" — arrived three times wearing three different masks:
    `not a poga verb`, then twice `is not a git repository`. Each read as a separate bug.

    IT REPORTS, IT NEVER PULLS. Pulling under an operator mid-fan-out is a surprise, and
    the whole point of the split is that this machine is where the human is. The fetch is
    read-only and bounded; a failure is reported as CANNOT TELL rather than as up-to-date,
    because "I could not look" collapsing into "nothing is wrong" is the failure this
    neighbourhood keeps producing.

    THE PROBE IS SHARED, THE WORDING IS NOT (WI-0222). The mechanism now lives in
    `_checkout_staleness`, because this was the first of three surfaces of one fact and a
    second copy of it would drift from the first — `single-source-and-deliver`. What stays
    here is what is genuinely attach's: `ttl=0` (always look, never cache — attach runs
    rarely and deliberately, and would rather pay the second than be wrong, where
    `poga work` is typed constantly and made the opposite trade), `ref="HEAD"` (attach asks
    about the operator's OWN checkout on whatever branch they are on, not about the
    trunk), and this phrasing, which speaks to an operator mid-fan-out."""
    behind, upstream, why, _age = _checkout_staleness(ttl=0, ref="HEAD", fetch=fetch,
                                                      timeout=30)
    if behind is None:
        # Keyed on the REASON, not on whether `upstream` came back empty: the exception
        # path also has no upstream, and collapsing the two would tell an operator whose
        # git just crashed that they have no tracking branch — a confident wrong diagnosis
        # in place of an honest "could not look".
        if why.startswith("no upstream"):
            return ("attach: CANNOT TELL whether this checkout is current — no upstream "
                    "is tracked for this branch. `poga attach` runs your own code; if a "
                    "fix landed on the work machine, pull before trusting a failure here.")
        return f"attach: CANNOT TELL whether this checkout is current — {why}."
    if behind <= 0:
        return ""
    return (f"attach: THIS CHECKOUT IS {behind} COMMIT(S) BEHIND {upstream}. You are "
            f"running old code — a failure below may already be fixed. `git pull` here, "
            f"then re-run. (Reporting only; attach never pulls under you.)")


def _attach_resolve_dispatch(host: str) -> list[str]:
    """The dispatches to attach to when the operator named none. Every one that is running."""
    where = host or "this machine"
    ids, why = _attach_live_dispatch_ids(host)
    if ids is None:
        print(f"attach: CANNOT TELL what is running on {where} — {why}.")
        print(f"  Name the dispatch explicitly (`attach D-xxxxxx`), or run "
              f"`poga dispatched` on {where} to see the ids.")
        raise SystemExit(2)
    if not ids:
        print(f"attach: no dispatched lanes are running on {where}.")
        print("  Nothing to open a window onto. `poga dispatched` lists past dispatches.")
        raise SystemExit(2)
    if len(ids) > 1:
        # ATTACH THEM ALL (the operator's ruling, session ~172: several dispatches attach each). The
        # first cut refused here and made the operator name one, borrowing `dispatch`'s
        # never-guess rule — but that rule is about SPAWNING, where picking wrong starts
        # real work in the wrong place. This command opens views and nothing else, so the
        # cost of an unwanted one is a window you close. Refusing was the expensive option:
        # it left the second fan-out running headless, which is the exact failure the
        # watcher exists to prevent.
        print(f"attach: {len(ids)} dispatches have lanes running on {where} — "
              f"attaching all of them: {', '.join(ids)}.")
        return ids
    print(f"attach: one dispatch running on {where} — {ids[0]}.")
    return ids


def _attach_raise_pass(did: str, host: str, window: dict, mode: str,
                       after_min: int, raised: set) -> None:
    """Raise the tab of every lane of `did` that is waiting on the user (WI-0183).

    ADR-0101's attention records are countable but PASSIVE — a lane that blocks on a
    question is a number on a board someone has to go and look at. Ghostty's dictionary
    turns the pull surface into a push one with no new channel, no daemon and no poll of
    its own: attach is already polling, and the record is already the truth. The raise is
    best-effort decoration on top of it, which is exactly the split ADR-0101's D-record
    insists on — so every failure here is reported and none of them stops anything.

    ESCALATION. `after_min` promotes any mode to `focus` once a question has gone
    unanswered that long. Stealing focus mid-sentence is worse than a quiet badge when the
    question is fresh, and better than silence when it is an hour old."""
    tabs = (window or {}).get("tabs") or {}
    if not tabs:
        return
    recs, why = _attach_fetch_attention(host)
    if recs is None:
        # Could not look. Never rendered as "nobody is waiting" — but also never fatal,
        # and said once per run rather than once per poll.
        if "attention" not in raised:
            raised.add("attention")
            print(f"attach {did}: CANNOT TELL whether any lane is waiting on you — {why}. "
                  f"Tabs are open; they just will not raise themselves.")
        return
    for key, rec in sorted(recs.items()):
        item = (rec.get("item") or "").strip()
        if not item:
            continue
        name = _tmux_session_name(did, item)
        tab = tabs.get(name)
        if not tab:
            continue
        stamp = str(rec.get("created_at") or "")
        if (name, stamp) in raised:
            continue
        use = mode
        mins = _iso_age_min(stamp)
        if after_min and mins is not None and mins >= after_min:
            use = "focus"
        ok, detail = _attach_raise(tab, use)
        raised.add((name, stamp))
        msg = (rec.get("message") or "").strip()
        if ok:
            print(f"  {item}: WAITING ON YOU — raised its tab ({use})"
                  + (f" — {msg}" if msg else ""))
        else:
            # The record is the truth, so a failed raise still reports the question.
            print(f"  {item}: WAITING ON YOU (could not raise its tab — {detail})"
                  + (f" — {msg}" if msg else ""))


def cmd_attach(args: argparse.Namespace) -> None:
    """Open a window per dispatched lane, and keep opening them as later waves spawn.

    A WATCHER, not a script, and that is not a detail: ADR-0075's wave trigger is the
    landing session, so past the cap lanes spawn LATER. A one-shot attacher covers the
    first wave and leaves the rest running headless — the silent-strand failure arriving
    through the fix for it.

    It opens views and nothing else. It never spawns a lane, draws a spawn slot, holds a
    claim, or advances the queue; every one of those would rebuild the coordinator
    ADR-0051 retired, wearing a local process instead of a session."""
    host = (args.host or (CFG or {}).get("attach_host") or "").strip()
    # Resolve the terminal BEFORE discovery: there is no point asking the work machine what
    # is running if this machine could not open a window for the answer anyway.
    transport = (args.transport or (CFG or {}).get("attach_transport") or "mosh").strip()
    if transport not in ("mosh", "ssh"):
        print(f"attach: transport '{transport}' is not supported (mosh | ssh).")
        raise SystemExit(2)
    try:
        terminal = _attach_resolve_terminal(args.terminal or "")
    except ValueError as e:
        print(f"attach: {e}")
        raise SystemExit(2)
    # WI-0187: the tab's shell reads no profile, so check the binaries it will have to run
    # BEFORE opening anything. N identical failures the operator reads one tab at a time
    # is the shape this refusal replaces.
    why_transport = _attach_transport_check(host, transport)
    if why_transport and not args.dry_run:
        print(f"attach: {why_transport}.")
        print("  Nothing opened — every tab would have failed identically.")
        raise SystemExit(2)
    # WI-0167: and the binary that opens the window, for the same reason. A template that
    # names a binary this machine does not have fails identically for every lane.
    why_terminal = _attach_terminal_check(terminal)
    if why_terminal and not args.dry_run:
        print(f"attach: {why_terminal}.")
        print("  Nothing opened — every window would have failed identically.")
        raise SystemExit(2)
    # WI-0188: report-only, before any tab, so an old checkout is named once instead of
    # arriving three times wearing three different errors.
    if not args.no_fetch:
        stale = _attach_checkout_staleness()
        if stale:
            print(stale)

    # WI-0183: how loudly a waiting lane may interrupt. Refused by name rather than
    # silently downgraded — a mode operator set and did not get is the kind of quiet
    # disagreement that only shows up when he is waiting on a lane that never spoke up.
    raise_mode = (args.raise_mode or (CFG or {}).get("attach_raise")
                  or ATTACH_RAISE_DEFAULT).strip()
    if raise_mode not in ATTACH_RAISE_MODES:
        print(f"attach: raise mode '{raise_mode}' is not one of "
              f"{' | '.join(ATTACH_RAISE_MODES)}.")
        raise SystemExit(2)
    raise_after = args.raise_after
    if raise_after is None:
        raise_after = int((CFG or {}).get("attach_raise_after") or 0)
    if raise_mode != "off" and terminal != "ghostty":
        # SAY IT, do not just skip it. Raising rides entirely on Ghostty's dictionary;
        # every other surface here is a launch template with no handle on what it opened.
        print(f"attach: raising is '{raise_mode}' but the terminal is '{terminal}' — "
              f"only ghostty can raise a tab, so waiting lanes will be counted and "
              f"reported, never raised.")
        raise_mode = "off"

    named = args.dispatch_id
    if isinstance(named, str):
        named = [named] if named else []
    dids = list(named or []) or _attach_resolve_dispatch(host)

    where = f"{host} over {transport}" if host else "this machine"
    print(f"attach {', '.join(dids)}: lanes on {where}, windows via {terminal}.")

    # Several dispatches are watched TOGETHER, one pass over all of them, not one after
    # another. Draining them in sequence would leave the second fan-out headless for as
    # long as the first took to finish — the strand this command exists to prevent, moved
    # rather than fixed. State is per-dispatch because `_attach_seen` is keyed that way:
    # 'have I opened this window' is a fact about one dispatch at one desk.
    seen = {did: (set() if args.forget else _attach_seen(did)) for did in dids}
    opened_here = {did: 0 for did in dids}
    # ONE window for the whole run, every lane a tab in it (the attach design:
    # one window, multiple tabs) — shared across dispatches too, so attaching two
    # fan-outs does not produce two windows.
    window: dict = {}
    active = list(dids)
    unreadable: list[str] = []
    # WI-0186 bookkeeping: say each thing once. A watcher that re-prints "not running"
    # every poll trains the operator to ignore the one poll where it mattered.
    reported_dead: set[str] = set()
    warned_live = False
    # WI-0183: which (lane, question) pairs have already been raised. Keyed on the
    # record's creation stamp so a NEW question on the same lane raises again, while one
    # unanswered question does not re-raise every twenty seconds — a tab that jumps at you
    # on a loop is one you learn to ignore, which is the opposite of the point.
    raised: set[tuple[str, str]] = set()
    polls = 0
    while active:
        polls += 1
        for did in list(active):
            rec, why = _attach_fetch_record(did, host)
            if rec is None:
                # One unreadable record must not kill the dispatches that ARE readable —
                # but it is never silent, and if it leaves nothing to watch the command
                # still exits non-zero rather than reporting a quiet success.
                print(f"attach {did}: CANNOT READ the dispatch record — {why}.")
                unreadable.append(did)
                active.remove(did)
                continue
            names = [(e.get("item"), _tmux_session_name(did, str(e.get("item"))))
                     for e in (rec.get("log") or []) if e.get("item")]
            # WI-0186: the record ASSERTS what was spawned; tmux SHOWS what is running.
            # Prefer the observation. RE-READ EVERY POLL, never once: attach is a watcher
            # and later waves spawn lanes that did not exist at discovery time — filtering
            # forever against a first-pass snapshot would trade a cosmetic bug for the
            # silent-strand bug this command exists to prevent. `None` (could not look)
            # does NOT filter: refusing to open on an unanswered question is the collapse,
            # not the fix.
            live, why_live = _attach_live_sessions(host)
            if live is None and not warned_live:
                print(f"attach {did}: CANNOT TELL what is running on "
                      f"{host or 'this machine'} — {why_live}. Opening what the record "
                      f"claims; a tab may land on a dead lane.")
                warned_live = True
            fresh = [(item, name) for item, name in names if name not in seen[did]]
            if live is not None:
                alive = set(live)
                kept = []
                for item, name in fresh:
                    if name in alive:
                        kept.append((item, name))
                    elif name not in reported_dead:
                        # NAMED, not silently skipped. A lane in the log with no session is
                        # either still starting (next poll takes it) or dead (WI-0185) —
                        # and a dead one the operator never hears about is the strand.
                        reported_dead.add(name)
                        print(f"  {item}: NOT RUNNING on {host or 'this machine'} — the "
                              f"record says it spawned, tmux has no `{name}`. No tab "
                              f"opened; still watching in case it is mid-start.")
                fresh = kept
            for item, name in fresh:
                cmd = _attach_command(name, host, transport)
                if args.dry_run:
                    print(f"  {item}: would open a {terminal} window running: {cmd}")
                    seen[did].add(name)
                    continue
                ok, detail = _attach_open(cmd, terminal, name, window)
                if ok:
                    opened_here[did] += 1
                    seen[did].add(name)
                    print(f"  {item}: window open — {name}")
                else:
                    # Named, not swallowed. A window that failed to open is the one thing
                    # this command exists to prevent going unnoticed.
                    print(f"  {item}: WINDOW FAILED — {detail}")
            if not args.dry_run:
                _attach_mark(did, seen[did])

            if raise_mode != "off":
                _attach_raise_pass(did, host, window, raise_mode, raise_after, raised)

            state = _dispatch_state(rec)
            if rec.get("cancelled"):
                print(f"attach {did}: dispatch was cancelled — nothing further will spawn.")
                active.remove(did)
            elif state == "stalled":
                stall = (rec.get("stall") or {}).get("detail") or "no reason recorded"
                print(f"attach {did}: dispatch is STALLED — {stall}")
                active.remove(did)
            elif state == "complete":
                print(f"attach {did}: dispatch complete — {len(seen[did])} lane(s) "
                      f"attached ({opened_here[did]} opened by this run).")
                active.remove(did)
            elif args.once:
                print(f"attach {did}: {len(rec.get('queue') or [])} item(s) still queued; "
                      f"--once, so not waiting for them.")
                active.remove(did)
            elif args.max_polls and polls >= args.max_polls:
                print(f"attach {did}: stopped after {polls} poll(s); "
                      f"{len(rec.get('queue') or [])} item(s) still queued.")
                active.remove(did)
        if active:
            time.sleep(max(1, int(args.interval or ATTACH_POLL_SECONDS)))
    if unreadable and len(unreadable) == len(dids):
        raise SystemExit(2)
